(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pausanias-3-e", [{"sp": "HDR", "t": "Ἑλλάδος Περιήγησις"}, {"sp": "HDR", "t": "Βιβλίον Εʹ — Ἠλιακῶν Αʹ", "st": "5"}, {"sp": "N", "t": "ὅσοι δὲ Ἑλλήνων Πελοποννήσου πέντε εἶναι μοίρας καὶ οὐ πλείονάς φασιν, ἀνάγκη σφᾶς ὁμολογεῖν ὡς ἐν τῇ Ἀρκάδων οἰκοῦσιν Ἠλεῖοι καὶ Ἀρκάδες, δευτέρα δὲ Ἀχαιῶν, τρεῖς δὲ ἐπὶ ταύταις αἱ Δωριέων. γένη δὲ οἰκεῖ Πελοπόννησον Ἀρκάδες μὲν αὐτόχθονες καὶ Ἀχαιοί· καὶ οἱ μὲν ὑπὸ Δωριέων ἐκ τῆς σφετέρας ἀνέστησαν, οὐ μέντοι Πελοποννήσου γε ἐξεχώρησαν, ἀλλὰ ἐκβαλόντες Ἴωνας νέμονται τὸν Αἰγιαλὸν τὸ ἀρχαῖον, νῦν δὲ ἀπὸ τῶν Ἀχαιῶν τούτων καλούμενον·", "st": "5.1"}, {"sp": "N", "t": "οἱ δὲ Ἀρκάδες διατελοῦσιν ἐξ ἀρχῆς καὶ ἐς τόδε τὴν ἑαυτῶν ἔχοντες. τὰ δὲ λοιπὰ ἐπηλύδων ἐστὶν ἀνθρώπων. Κορίνθιοι μὲν γὰρ οἱ νῦν νεώτατοι Πελοποννησίων εἰσί, καί σφισιν, ἀφ’ οὗ τὴν γῆν παρὰ βασιλέως ἔχουσιν, εἴκοσιν ἔτη καὶ διακόσια τριῶν δέοντα ἦν ἐς ἐμέ· Δρύοπες δὲ καὶ Δωριεῖς, οἱ μὲν ἐκ Παρνασσοῦ, Δωριεῖς δὲ ἐκ τῆς Οἴτης ἐς Πελοπόννησόν εἰσιν ἀφιγμένοι.", "st": "5.1"}, {"sp": "N", "t": "τοὺς Ἠλείους ἴσμεν ἐκ Καλυδῶνος διαβεβηκότας καὶ Αἰτωλίας τῆς ἄλλης· τὰ δὲ ἔτι παλαιότερα ἐς αὐτοὺς τοιάδε εὕρισκον. βασιλεῦσαι πρῶτον ἐν τῇ γῇ ταύτῃ λέγουσιν Ἀέθλιον, παῖδα δὲ αὐτὸν Διός τε εἶναι καὶ Πρωτογενείας τῆς Δευκαλίωνος, Ἀεθλίου δὲ Ἐνδυμίωνα γενέσθαι·", "st": "5.1"}, {"sp": "N", "t": "τούτου τοῦ Ἐνδυμίωνος Σελήνην φασὶν ἐρασθῆναι, καὶ ὡς θυγατέρες αὐτῷ γένοιντο ἐκ τῆς θεοῦ πεντήκοντα. οἱ δὲ δὴ μᾶλλόν τι εἰκότα λέγοντες Ἐνδυμίωνι λαβόντι Ἀστεροδίαν γυναῖκα—οἱ δὲ τὴν Ἰτώνου τοῦ Ἀμφικτύονος Χρομίαν, ἄλλοι δὲ Ὑπερίππην τὴν Ἀρκάδος—, γενέσθαι δ’ οὖν φασιν αὐτῷ Παίονα καὶ Ἐπειόν τε καὶ Αἰτωλὸν καὶ θυγατέρα ἐπ’ αὐτοῖς Εὐρυκύδαν. ἔθηκε δὲ καὶ ἐν Ὀλυμπίᾳ δρόμου τοῖς παισὶν ἀγῶνα Ἐνδυμίων ὑπὲρ τῆς ἀρχῆς, καὶ ἐνίκησε καὶ ἔσχε τὴν βασιλείαν Ἐπειός· καὶ Ἐπειοὶ πρῶτον τότε ὧν ἦρχεν ὠνομάσθησαν.", "st": "5.1"}, {"sp": "N", "t": "τῶν δὲ ἀδελφῶν οἱ τὸν μὲν καταμεῖναί φασιν αὐτοῦ, Παίονα δὲ ἀχθόμενον τῇ ἥσσῃ φυγεῖν ὡς πορρωτάτω, καὶ τὴν ὑπὲρ Ἀξιοῦ ποταμοῦ χώραν ἀπ’ αὐτοῦ Παιονίαν ὀνομασθῆναι. τὰ δὲ ἐς τὴν Ἐνδυμίωνος τελευτὴν οὐ κατὰ τὰ αὐτὰ Ἡρακλεῶταί τε οἱ πρὸς Μιλήτῳ καὶ Ἠλεῖοι λέγουσιν, ἀλλὰ Ἠλεῖοι μὲν ἀποφαίνουσιν Ἐνδυμίωνος μνῆμα, Ἡρακλεῶται δὲ ἐς Λάτμον τὸ ὄρος ἀποχωρῆσαί φασιν αὐτὸν ⟨καὶ τιμὴν αὐτῷ νέ⟩μουσι, καὶ ἄδυτον Ἐνδυμίωνός ἐστιν ἐν τῷ Λάτμῳ.", "st": "5.1"}, {"sp": "N", "t": "Ἐπειῷ δὲ γήμαντι Ἀναξιρόην τὴν Κορώνου θυγάτηρ μὲν Ὑρμίνα, ἄρσεν δὲ οὐκ ἐγένετο αὐτῷ γένος· καὶ τάδε ἄλλα συνέβη κατ’ Ἐπειὸν βασιλεύοντα. Οἰνόμαος ὁ Ἀλξίωνος, Ἄρεως δὲ καθὰ ποιηταί τε ἐπεφήμισαν καὶ τῶν πολλῶν ἐστιν ἐς αὐτὸν λόγος, οὗτος δυναστεύων περὶ τὴν Πισαίαν καλουμένην ὁ Οἰνόμαος ἐπαύθη τῆς ἀρχῆς διαβάντος Πέλοπος τοῦ Λυδοῦ ἐκ τῆς Ἀσίας.", "st": "5.1"}, {"sp": "N", "t": "Πέλοψ δὲ ἀποθανόντος Οἰνομάου τήν τε Πισαίαν ἔσχε καὶ Ὀλυμπίαν, ἀποτεμόμενος τῆς Ἐπειοῦ χώρας ὅμορον οὖσαν τῇ Πισαίᾳ· Ἑρμοῦ τε ἐν Πελοποννήσῳ ναὸν ἱδρύσασθαι καὶ θῦσαι τῷ θεῷ Πέλοπα ἔλεγον οἱ Ἠλεῖοι πρῶτον, ἀποτρεπόμενον τὸ ἐπὶ τῷ Μυρτίλου θανάτῳ μήνιμα ἐκ τοῦ θεοῦ.", "st": "5.1"}, {"sp": "N", "t": "Αἰτωλῷ δὲ μετὰ Ἐπειὸν βασιλεύσαντι συνέπεσεν ἐκ Πελοποννήσου φυγεῖν, ὅτι αὐτὸν οἱ Ἄπιδος παῖδες ἐφ’ αἵματι ἀκουσίῳ δίκην εἷλον· Ἆπιν γὰρ τὸν Ἰάσονος ἐκ Παλλαντίου τοῦ Ἀρκάδων ἀπέκτεινεν Αἰτωλὸς ἐπελάσας τὸ ἅρμα τεθέντων ἐπὶ Ἀζᾶνι ἄθλων. ἀπὸ μὲν Αἰτωλοῦ τοῦ Ἐνδυμίωνος οἱ περὶ τὸν Ἀχελῷον οἰκοῦντες ἐκλήθησαν φυγόντος ἐς ταύτην τὴν ἤπειρον, τὴν δὲ Ἐπειῶν ἔσχεν ἀρχὴν Ἠλεῖος, Εὐρυκύδας τε τῆς Ἐνδυμίωνος καὶ—ὅτῳ πιστὰ—πατρὸς ὢν Ποσειδῶνος· καὶ τὸ ὄνομα οἱ ἄνθρωποι τὸ νῦν ἀντὶ Ἐπειῶν ἀπὸ τοῦ Ἠλείου μεταβεβλήκασιν.", "st": "5.1"}, {"sp": "N", "t": "Ἠλείου δὲ ἦν Αὐγέας· οἱ δὲ ἀποσεμνύνοντες τὰ ἐς αὐτόν, παρατρέψαντες τοῦ Ἠλείου τὸ ὄνομα, Ἡλίου φασὶν Αὐγέαν παῖδα εἶναι. τούτῳ βοῦς τῷ Αὐγέᾳ καὶ αἰπόλια τοσαῦτα ἐγένετο ὡς καὶ τῆς χώρας αὐτῷ τὰ πολλὰ ἤδη διατελεῖν ἀργὰ ὄντα ὑπὸ τῶν βοσκημάτων τῆς κόπρου· Ἡρακλέα οὖν εἴτε ἐπὶ μοίρᾳ τῆς Ἠλείας εἴτε ἐφ’ ὅτῳ δὴ καὶ ἄλλῳ μισθῷ πείθει οἱ καθῆραι τῆς κόπρου τὴν γῆν.", "st": "5.1"}, {"sp": "N", "t": "καὶ ὁ μὲν καὶ τοῦτο ἐξειργάσατο ἐκτρέψας τοῦ Μηνίου τὸ ῥεῦμα ἐς τὴν κόπρον· Αὐγέας δέ, ὅτι τῷ Ἡρακλεῖ σοφίᾳ πλέον καὶ οὐ σὺν πόνῳ τὸ ἔργον ἤνυστο, αὐτός τε ἀποδοῦναί οἱ τὸν μισθὸν ἀπηξίου καὶ τῶν παίδων τῶν ἀρσένων τὸν πρεσβύτερον Φυλέα ἐξέβαλεν ἀντειπόντα ὡς οὐ δίκαια ποιοῖτο πρὸς ἄνδρα εὐεργέτην. αὐτὸς δὲ τά τε ἄλλα παρεσκευάζετο ὡς τὸν Ἡρακλέα ἀμυνούμενος, ἢν ἐπὶ τὴν Ἦλιν στρατεύηται, καὶ τοὺς παῖδας τοὺς Ἄκτορος καὶ Ἀμαρυγκέα ἐπηγάγετο ἐς φιλίαν·", "st": "5.1"}, {"sp": "N", "t": "ἦν δὲ ὁ Ἀμαρυγκεὺς ἄλλως μὲν ἀγαθὸς τὰ ἐς τὸν πόλεμον, ὁ δέ οἱ πατὴρ Πυττίος Θεσσαλὸς τὰ ἄνωθεν ἦν καὶ ἐς τὴν Ἠλείαν ἀφίκετο ἐκ Θεσσαλίας. Ἀμαρυγκεῖ μὲν δὴ καὶ ἀρχῆς ἐν Ἠλείᾳ μετέδωκεν ὁ Αὐγέας, Ἄκτορι δὲ καὶ τοῖς παισὶ γένος τε ἦν ἐπιχώριον βασιλείας τε μετῆν σφισιν· Ἄκτωρ γὰρ πατρὸς μὲν Φόρβαντος ἦν τοῦ Λαπίθου, μητρὸς δὲ Ὑρμίνης τῆς Ἐπειοῦ, καὶ ᾤκισεν ἀπ’ αὐτῆς Ἄκτωρ πόλιν Ὑρμίναν ἐν τῇ Ἠλείᾳ.", "st": "5.1"}, {"sp": "N", "t": "τῷ δὲ Ἡρακλεῖ πρὸς τὸν Αὐγέαν πολεμοῦντι οὐδὲν ὑπῆρχεν ἀποδείκνυσθαι λαμπρόν· ἅτε γὰρ καὶ τόλμῃ καὶ ταῖς ἡλικίαις τοῦ Ἄκτορος τῶν παίδων ἀκμαζόντων, ἐτρέπετο ὑπ’ αὐτῶν ἀεὶ τὸ συμμαχικὸν τοῦ Ἡρακλέους, ἐς ὃ Ἰσθμικὰς σπονδὰς Κορινθίων ἐπαγγειλάντων καὶ θεωρῶν ἐς τὸν ἀγῶνα ἐρχομένων τῶν υἱῶν τοῦ Ἄκτορος ἀπέκτεινε σφᾶς λοχήσας ὁ Ἡρακλῆς ἐν Κλεωναῖς. ἀφανοῦς δὲ ὄντος τοῦ εἰργασμένου τὸν φόνον μάλιστα ἐποιεῖτο ἡ Μολίνη σπουδὴν τῶν παίδων τὸν αὐτόχειρα ἐξευρεῖν.", "st": "5.2"}, {"sp": "N", "t": "ὡς δὲ ἔμαθεν, ἐνταῦθα οἱ Ἠλεῖοι δίκας τοῦ φόνου παρὰ Ἀργείων ἀπῄτουν· τηνικαῦτα γὰρ ἔτυχεν Ἡρακλῆς ἐν Τίρυνθι οἰκῶν. μὴ διδόντων δέ σφισι δίκας τῶν Ἀργείων, οἱ δὲ δεύτερα ἐνέκειντο Κορινθίοις ἔκσπονδον τὸ Ἀργολικὸν πᾶν τοῦ ἀγῶνος γενέσθαι τοῦ Ἰσθμικοῦ. ὡς δὲ ἡμάρτανον καὶ τούτου, Μολίνην θέσθαι φασὶν ἐπὶ τοῖς πολίταις κατάρας, ἢν Ἰσθμίων μὴ θέλωσιν εἴργεσθαι. φυλάσσουσι δὲ τῆς Μολίνης καὶ ἐς τόδε ἔτι τὰς κατάρας, καὶ ὅσοι τὰ σώματα ἀσκοῦσιν Ἠλείων, οὔ σφισιν ἐς τὸν ἀγῶνα ἐσελθεῖν καθέστηκε τὸν Ἰσθμικόν.", "st": "5.2"}, {"sp": "N", "t": "διάφοροι δὲ τῷ εἰρημένῳ δύο εἰσὶν ἄλλοι λόγοι. τούτων δὲ ὁ μὲν Κύψελον τὸν τυραννήσαντα Κορινθίων φησὶν ἄγαλμα ἀναθεῖναι τῷ Διὶ χρυσοῦν ἐς Ὀλυμπίαν, προαποθανόντος δὲ τοῦ Κυψέλου πρὶν ἐπὶ τῷ ἀναθήματι τὸ ὄνομα ἐπιγράψαι τὸ αὑτοῦ, τοὺς Κορινθίους παρὰ Ἠλείων αἰτεῖν δοῦναί σφισιν ἐπιγράψαι δημοσίᾳ τὴν πόλιν ἐπὶ τῷ ἀναθήματι, οὐ τυχόντας δὲ ὀργῇ τε ἐς τοὺς Ἠλείους χρῆσθαι καὶ προειπεῖν σφισιν Ἰσθμίων εἴργεσθαι. πῶς ἂν οὖν Κορινθίοις αὐτοῖς τοῦ ἀγῶνος μετῆν τοῦ ἐν Ὀλυμπίᾳ, εἰ δὴ ἄκοντάς γε Ἠλείους ἀπὸ τῶν Ἰσθμίων εἶργον;", "st": "5.2"}, {"sp": "N", "t": "ὁ δὲ ἕτερος ἔχει τῶν λόγων Προλάῳ παῖδας ἀνδρὶ παρὰ Ἠλείοις δοκίμῳ καὶ τῇ γυναικὶ αὐτοῦ Λυσίππῃ Φίλανθον καὶ Λάμπον γενέσθαι· τούτους ἐπὶ τὸν ἀγῶνα ἐλθόντας τῶν Ἰσθμίων παγκρατιάσοντας ἐν παισί, τὸν δὲ αὐτῶν παλαίσοντα, ὑπὸ τῶν ἀνταγωνιστῶν, πρὶν ἢ ἐς τὸν ἀγῶνα ἐσελθεῖν, ἀποπνιγῆναι σφᾶς ἢ καὶ ἄλλῳ τῷ τρόπῳ διαχρησθῆναι· καὶ οὕτω τὰς ἐπὶ τοῖς Ἠλείοις, ἢν Ἰσθμίων μὴ ἑκόντες εἴργωνται, Λυσίππης ἀρὰς εἶναι. δείκνυται δὲ καὶ ὅδε εὐήθης ὢν ὁ λόγος.", "st": "5.2"}, {"sp": "N", "t": "Τίμωνι γὰρ ἀνδρὶ Ἠλείῳ γεγόνασι πεντάθλου νῖκαι τῶν ἐν Ἕλλησιν ἀγώνων, καί οἱ καὶ εἰκών ἐστιν ἐν Ὀλυμπίᾳ καὶ ἐλεγεῖον, στεφάνους τε ὁπόσους ἀνείλετο ὁ Τίμων λέγον καὶ δὴ καὶ αἰτίαν δι’ ἥντινα Ἰσθμικῆς οὐ μέτεστιν αὐτῷ νίκης· καὶ ἔχει τὰ ἐς τοῦτο τὸ ἐλεγεῖον·<br>Σισυφίαν δὲ μολεῖν χθόν’ ἐκώλυεν ἀνέρα νείκη<br>ἀμφὶ Μολιονιδᾶν οὐλομένῳ θανάτῳ.<br>τάδε μὲν ἡμῖν ἐς τοσοῦτο ἐξητάσθω·", "st": "5.2"}, {"sp": "N", "t": "Ἡρακλῆς δὲ εἷλεν ὕστερον καὶ ἐπόρθησεν Ἦλιν, στρατιὰν παρά τε Ἀργείων καὶ ἐκ Θηβῶν ἀθροίσας καὶ Ἀρκάδας· ἤμυναν δὲ καὶ Ἠλείοις οἱ ἐκ Πύλου τοῦ ἐν τῇ Ἠλείᾳ καὶ οἱ Πισαῖοι. καὶ τοὺς μὲν ἐτιμωρήσατο αὐτῶν ὁ Ἡρακλῆς, τῆς δὲ ἐπὶ τοὺς Πισαίους στρατείας αὐτὸν χρησμὸς ἐπέσχεν ἐκ Δελφῶν ἔχων οὕτω·<br>πατρὶ μέλει Πίσης, Πυθοῦς δέ μοι ἐν γυάλοισι.<br>τοῦτο μὲν δὴ σωτηρία Πισαίοις τὸ μάντευμα ἐγένετο· Φυλεῖ δὲ Ἡρακλῆς τήν τε χώραν ἀνέδωκε τὴν Ἠλείαν καὶ τἄλλα, αἰδοῖ τοῦ Φυλέως μᾶλλον ἢ αὐτὸς ἑκουσίως· τά τε γὰρ αἰχμάλωτα ἐφίησιν ἔχειν αὐτῷ καὶ Αὐγέαν μὴ ὑποσχεῖν δίκην.", "st": "5.3"}, {"sp": "N", "t": "τῶν δὲ Ἠλείων αἱ γυναῖκες, ἅτε τῶν ἐν ἡλικίᾳ σφίσιν ἠρημωμένης τῆς χώρας, εὔξασθαι τῇ Ἀθηνᾷ λέγονται κυῆσαι παραυτίκα, ἐπειδὰν μιχθῶσι τοῖς ἀνδράσι· καὶ ἥ τε εὐχή σφισιν ἐτελέσθη καὶ Ἀθηνᾶς ἱερὸν ἐπίκλησιν Μητρὸς ἱδρύσαντο. ὑπερησθέντες δὲ ἀμφότεροι τῇ μίξει καὶ αἱ γυναῖκες καὶ οἱ ἄνδρες, ἔνθα συνεγένοντο ἀλλήλοις πρῶτον, αὐτό τε τὸ χωρίον Βαδὺ ὀνομάζουσι καὶ ποταμὸν τὸν ῥέοντα ἐνταῦθα ὕδωρ Βαδὺ ἐπιχωρίῳ φωνῇ.", "st": "5.3"}, {"sp": "N", "t": "Φυλέως δέ, ὡς τὰ ἐν τῇ Ἤλιδι κατεστήσατο, αὖθις ἐς Δουλίχιον ἀποχωρήσαντος, Αὐγέαν μὲν τὸ χρεὼν ἐπέλαβε προήκοντα ἐς γῆρας, βασιλείαν δὲ τὴν Ἠλείων Ἀγασθένης ἔσχεν ὁ Αὐγέου καὶ Ἀμφίμαχός τε καὶ Θάλπιος· Ἄκτορος γὰρ τοῖς παισὶν ἀδελφὰς ἐσαγαγομένοις διδύμας ἐς τὸν οἶκον, Δεξαμενοῦ θυγατέρας ἐν Ὠλένῳ βασιλεύοντος, τῷ μὲν ἐκ Θηρονίκης Ἀμφίμαχος, Εὐρύτῳ δὲ ἐκ Θηραιφόνης ἐγεγόνει Θάλπιος.", "st": "5.3"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ Ἀμαρυγκεὺς οὔτε αὐτὸς διέμεινεν ἰδιωτεύων οὔτε Διώρης ὁ Ἀμαρυγκέως. ἃ δὴ καὶ Ὅμηρος παρεδήλωσεν ἐν καταλόγῳ τῶν Ἠλείων, τὸν μὲν σύμπαντα αὐτῶν στόλον ποιήσας τεσσαράκοντα εἶναι νεῶν, τούτων δὲ τὰς ἡμισείας ὑπὸ Ἀμφιμάχῳ τετάχθαι καὶ Θαλπίῳ, τῶν λοιπῶν δὲ εἴκοσι δέκα μὲν ναυσὶ Διώρην τὸν Ἀμαρυγκέως ἡγεῖσθαι, τοσαύταις δὲ ἑτέραις Πολύξενον τὸν Ἀγασθένους. Πολυξένῳ δὲ ἀνασωθέντι ἐκ Τροίας ἐγένετο υἱὸς Ἀμφίμαχος—τὸ δὲ ὄνομα τῷ παιδὶ ἔθετο ὁ Πολύξενος κατὰ φιλίαν ἐμοὶ δοκεῖν πρὸς Ἀμφίμαχον τὸν Κτεάτου τελευτήσαντα ἐν Ἰλίῳ—, Ἀμφιμάχου δὲ Ἠλεῖος·", "st": "5.3"}, {"sp": "N", "t": "καὶ ἐπὶ Ἠλείου βασιλεύοντος ἐν Ἤλιδι, τηνικαῦτα ὁ Δωριέων στόλος σὺν τοῖς Ἀριστομάχου παισὶν ἠθροίζετο ἐπὶ καθόδῳ τῇ ἐς Πελοπόννησον. γίνεται δὲ τοῖς βασιλεῦσιν αὐτῶν λόγιον τόδε, ἡγεμόνα τῆς καθόδου ποιεῖσθαι τὸν τριόφθαλμον. ἀποροῦσι δέ σφισιν ὅ τι ὁ χρησμὸς ἐθέλοι συνέτυχεν ἐλαύνων ἀνὴρ ἡμίονον, ὁ δὲ ἕτερος διέφθαρτο τῷ ἡμιόνῳ τῶν ὀφθαλμῶν·", "st": "5.3"}, {"sp": "N", "t": "Κρεσφόντου δὲ συμφρονήσαντος ὡς ἐς τοῦτον τὸν ἄνδρα ἔχοι τὸ μάντευμα, οὕτως ᾠκειώσαντο αὐτὸν οἱ Δωριεῖς. ὁ δὲ σφᾶς ναυσὶν ἐκέλευεν ἐς Πελοπόννησον κατιέναι μηδὲ στρατῷ πεζῷ διὰ τοῦ ἰσθμοῦ πειρᾶσθαι. ταῦτά τε δὴ παρῄνεσε καὶ ἅμα τὸν ἐς Μολύκριον ἐκ Ναυπάκτου πλοῦν καθηγήσατο αὐτοῖς· οἱ δὲ ἀντὶ τούτου δεηθέντι τὴν Ἠλείαν γῆν συνέθεντο αὐτῷ δώσειν. ὁ δὲ ἀνὴρ ἦν Ὄξυλος Αἵμονος τοῦ Θόαντος· Θόας δὲ ἦν οὗτος ὃς καὶ τοῖς Ἀτρέως παισὶν ἀρχὴν συγκαθεῖλε τὴν Πριάμου, γενεαὶ δὲ ἀπὸ Θόαντος ἀνήκουσιν ἓξ ἐς Αἰτωλὸν τὸν Ἐνδυμίωνος.", "st": "5.3"}, {"sp": "N", "t": "ἦσαν δὲ οἱ Ἡρακλεῖδαι συγγενεῖς καὶ ἄλλως τοῖς ἐν Αἰτωλίᾳ βασιλεῦσι, καὶ ἀδελφαὶ Θόαντι τῷ Ἀνδραίμονος καὶ Ὕλλου τοῦ Ἡρακλέους ἦσαν αἱ μητέρες. συνεπεπτώκει δὲ τῷ Ὀξύλῳ φυγάδι ἐξ Αἰτωλίας εἶναι· δισκεύοντα γάρ φασιν ἁμαρτεῖν αὐτὸν καὶ ἐξεργάσασθαι φόνον ἀκούσιον, τὸν δὲ ἀποθανόντα ὑπὸ τοῦ δίσκου τὸν ἀδελφὸν εἶναι τοῦ Ὀξύλου Θέρμιον, οἱ δὲ Ἀλκιδόκον τὸν Σκοπίου.", "st": "5.3"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἄλλο ἐπὶ τῷ Ὀξύλῳ τοιόνδε, ὡς τοὺς παῖδας ὑποπτεύσειε τοῦ Ἀριστομάχου, μὴ τὴν Ἠλείαν τε ἰδόντες ἀγαθὴν οὖσαν καὶ ἐξειργασμένην διὰ πάσης οὐκ ἐθελήσωσιν ἔτι αὐτῷ διδόναι τὴν γῆν, καὶ τοῦδε ἕνεκα διὰ τῶν Ἀρκάδων καὶ οὐ διὰ τῆς Ἠλείας τοῖς Δωριεῦσιν ἡγήσατο. Ὀξύλῳ δὲ σπεύσαντι ἀμαχεὶ λαβεῖν τὴν Ἠλείων ἀρχὴν Δῖος οὐκ εἶκε, πρόκλησιν δὲ ἐποιεῖτο μὴ σφᾶς παρασκευῇ τῇ πάσῃ διακινδυνεῦσαι, προκριθῆναι δὲ ἀφ’ ἑκατέρων στρατιώτην ἕνα ἐς τὴν μάχην·", "st": "5.4"}, {"sp": "N", "t": "καί πως συνήρεσε ταῦτα ἀμφοτέροις, οἱ δὲ ἐς τὸ ἔργον προταχθέντες Δέγμενός τε Ἠλεῖος ἦν τοξότης καὶ παρὰ τῶν Αἰτωλῶν Πυραίχμης σφενδόνην δεδιδαγμένος. κρατήσαντος δὲ τοῦ Πυραίχμου τήν τε βασιλείαν ἔσχεν Ὄξυλος καὶ Ἐπειοὺς τοὺς ἀρχαίους τὰ μὲν ἄλλα εἴασεν ἐπὶ τοῖς αὑτῶν μένειν, συνοίκους δέ σφισι τοὺς Αἰτωλοὺς ἐπὶ ἀναδασμῷ τῆς χώρας ἐπεισήγαγε. καὶ Δίῳ τε ἀπένειμε γέρα καὶ ἥρωσι τοῖς τε ἄλλοις κατὰ τὰ ἀρχαῖα ἐφύλαξε τὰς τιμὰς καὶ Αὐγέᾳ τὰ ἐς τὸν ἐναγισμὸν ἔτι καὶ ἐς ἡμᾶς αὐτῷ καθεστηκότα.", "st": "5.4"}, {"sp": "N", "t": "λέγεται δὲ ὡς καὶ τοὺς ἀνθρώπους ἐκ τῶν κωμῶν, ὅσοι τοῦ τείχους οὐ πολὺ ἀφεστήκεσαν, κατελθεῖν ἔπεισεν ἐς τὴν πόλιν καὶ πλήθει τε οἰκητόρων [καὶ] μείζονα καὶ εὐδαιμονεστέραν ἐς τὰ ἄλλα ἀπέφηνε τὴν Ἦλιν. ἀφίκετο δὲ αὐτῷ καὶ ἐκ Δελφῶν χρησμός, τὸν Πελοπίδην ἐπάγεσθαι συνοικιστήν· Ὄξυλος δὲ τὴν ζήτησιν ἐποιεῖτο σπουδῇ καὶ ἀναζητῶν εὗρεν Ἀγώριον τὸν Δαμασίου τοῦ Πενθίλου τοῦ Ὀρέστου, καὶ αὐτόν τε ἐξ Ἑλίκης τῆς Ἀχαιῶν καὶ σὺν τῷ Ἀγωρίῳ μοῖραν τῶν Ἀχαιῶν ἐπηγάγετο οὐ πολλήν.", "st": "5.4"}, {"sp": "N", "t": "τῷ δὲ Ὀξύλῳ Πιερίαν μὲν τῇ γυναικὶ ὄνομα εἶναι λέγουσι, πέρα δὲ τὰ ἐς αὐτὴν οὐ μνημονεύουσιν. Ὀξύλου δὲ γενέσθαι παῖδάς φασιν Αἰτωλὸν καὶ Λαΐαν· προαποθανόντος δὲ Αἰτωλοῦ θάπτουσιν αὐτὸν οἱ γονεῖς ἐν αὐτῇ ποιησάμενοι τῇ πύλῃ τὸ μνῆμα, ἥτις ἐπ’ Ὀλυμπίαν καὶ τὸ ἱερὸν ἄγει τοῦ Διός· ἔθαψαν δὲ αὐτὸν οὕτω κατὰ μαντείαν, ὡς μήτε ἐκτὸς τῆς πόλεως μήτε ἐντὸς γένοιτο ὁ νεκρός. ἐναγίζει δὲ ὁ γυμνασίαρχος ἔτι καὶ ἐς ἐμὲ καθ’ ἕκαστον ἔτος τῷ Αἰτωλῷ.", "st": "5.4"}, {"sp": "N", "t": "μετὰ δὲ Ὄξυλον Λαΐας ἔσχεν ὁ Ὀξύλου τὴν ἀρχήν. οὐ μὴν τούς γε ἀπογόνους αὐτοῦ βασιλεύοντας εὕρισκον, καὶ σφᾶς ἐπιστάμενος ὅμως παρίημι· οὐ γάρ τί μοι καταβῆναι τὸν λόγον ἠθέλησα ἐς ἄνδρας ἰδιώτας. χρόνῳ δὲ ὕστερον Ἴφιτος, γένος μὲν ὢν ἀπὸ Ὀξύλου, ἡλικίαν δὲ κατὰ Λυκοῦργον τὸν γράψαντα Λακεδαιμονίοις τοὺς νόμους, τὸν ἀγῶνα διέθηκεν ἐν Ὀλυμπίᾳ πανήγυρίν τε Ὀλυμπικὴν αὖθις ἐξ ἀρχῆς καὶ ἐκεχειρίαν κατεστήσατο, ἐκλιπόντα ἐπὶ χρόνον ὁπόσος δὴ οὗτος ἦν· αἰτίαν δὲ δι’ ἥντινα ἐξέλιπε τὰ Ὀλύμπια, ἐν τοῖς ἔχουσιν ἐς Ὀλυμπίαν τοῦ λόγου δηλώσω.", "st": "5.4"}, {"sp": "N", "t": "τῷ δὲ Ἰφίτῳ, φθειρομένης τότε δὴ μάλιστα τῆς Ἑλλάδος ὑπὸ ἐμφυλίων στάσεων καὶ ὑπὸ νόσου λοιμώδους, ἐπῆλθεν αἰτῆσαι τὸν ἐν Δελφοῖς θεὸν λύσιν τῶν κακῶν· καί οἱ προσταχθῆναί φασιν ὑπὸ τῆς Πυθίας ὡς αὐτόν τε Ἴφιτον δέοι καὶ Ἠλείους τὸν Ὀλυμπικὸν ἀγῶνα ἀνανεώσασθαι. ἔπεισε δὲ Ἠλείους Ἴφιτος καὶ Ἡρακλεῖ θύειν, τὸ πρὸ τούτου πολέμιόν σφισιν Ἡρακλέα εἶναι νομίζοντας. τὸν δὲ Ἴφιτον τὸ ἐπίγραμμα τὸ ἐν Ὀλυμπίᾳ φησὶν Αἴμονος παῖδα εἶναι, Ἑλλήνων δὲ οἱ πολλοὶ Πραξωνίδου καὶ οὐχ Αἴμονος εἶναί φασι· τὰ δὲ Ἠλείων γράμματα ἀρχαῖα ἐς πατέρα ὁμώνυμον ἀνῆγε τὸν Ἴφιτον.", "st": "5.4"}, {"sp": "N", "t": "Ἠλείοις δὲ μέτεστι μὲν πολέμου τοῦ πρὸς Ἰλίῳ, μέτεστι δὲ καὶ ἔργων ⟨τῶν⟩ κατὰ τὴν Μήδων ἐς τὴν Ἑλλάδα ἔφοδον. ὑπερβάντων δὲ ὅσοι σφίσιν ἐγένοντο κίνδυνοι πρὸς Πισαίους τε καὶ Ἀρκάδας ὑπὲρ τῆς διαθέσεως τοῦ ἀγῶνος τοῦ ἐν Ὀλυμπίᾳ, συν⟨εσ⟩έβαλον μὲν Λακεδαιμονίοις ἀκουσίως ἐς τὴν Ἀθηναίων, συνέστησαν δὲ μετὰ οὐ πολὺν χρόνον ἐπὶ Λακεδαιμονίους Μαντινεῦσιν ὁμοῦ καὶ Ἀργείοις, ἐπαγόμενοι καὶ τὸ Ἀττικὸν ἐς τὴν συμμαχίαν.", "st": "5.4"}, {"sp": "N", "t": "κατὰ δὲ τὴν Ἄγιδος ἐπιστρατείαν ἐς τὴν γῆν καὶ τὴν προδοσίαν τὴν Ξενίου μάχῃ μὲν περὶ Ὀλυμπίαν νικῶσιν οἱ Ἠλεῖοι καὶ τροπὴν ἐργασάμενοι τῶν Λακεδαιμονίων ἐκ τοῦ περιβόλου σφᾶς ἐξήλασαν τοῦ ἱεροῦ· χρόνῳ δὲ ὕστερον ἐπαύθη σφίσιν ὁ πόλεμος κατὰ τὰς συνθήκας ἃς ἐγὼ πρότερον ἔτι ἐν τῷ λόγῳ τῷ ἐς Λακεδαιμονίους ἐδήλωσα.", "st": "5.4"}, {"sp": "N", "t": "Φιλίππου δὲ τοῦ Ἀμύντου οὐκ ἐθέλοντος ἀποσχέσθαι τῆς Ἑλλάδος, προσεχώρησαν μὲν ἐς τὴν συμμαχίαν τῶν Μακεδόνων οἱ Ἠλεῖοι στάσει κακωθέντες ὑπὸ ἀλλήλων, μαχεσθῆναι δὲ οὐχ ὑπέμειναν τοῖς Ἕλλησιν ἐναντία ἐν Χαιρωνείᾳ· τῆς δὲ ἐφόδου Φιλίππῳ τῆς ἐπὶ Λακεδαιμονίους μετέσχον κατὰ ἔχθος ἐς αὐτοὺς τὸ ἀρχαῖον, ἀποθανόντος δὲ Ἀλεξάνδρου Μακεδόσι καὶ Ἀντιπάτρῳ μετὰ Ἑλλήνων ἐπολέμησαν.", "st": "5.4"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον Ἀριστότιμος ὁ Δαμαρέτου τοῦ Ἐτύμονος τυραννίδα ἔσχεν ἐν Ἠλείᾳ, συμπαρασκευάσαντος αὐτῷ τὰ ἐς τὴν ἐπίθεσιν Ἀντιγόνου τοῦ Δημητρίου βασιλεύοντος ἐν Μακεδονίᾳ· τὸν δὲ Ἀριστότιμον μῆνας τυραννήσαντα ἓξ καταλύουσιν ἐπαναστάντες Χίλων καὶ Ἑλλάνικος καὶ Λάμπις τε καὶ Κύλων, οὗτος δὲ καὶ αὐτοχειρίᾳ τὸν τύραννον ἀπέκτεινεν ὁ Κύλων ἐπὶ Διὸς Σωτῆρος βωμὸν καταφυγόντα ἱκέτην. τὰ μὲν δὴ ἐς πόλεμον τοιαῦτα ὑπῆρχεν Ἠλείοις, ὡς περὶ αὐτῶν ἡμῖν ἐν τῷ παρόντι ἀπαριθμῆσαι μετρίως·", "st": "5.5"}, {"sp": "N", "t": "θαυμάσαι δ’ ἄν τις ἐν τῇ γῇ τῇ Ἠλείᾳ τήν τε βύσσον, ὅτι ἐνταῦθα μόνον, ἑτέρωθι δὲ οὐδαμοῦ τῆς Ἑλλάδος φύεται, καὶ ὅτι ἐν τῇ ὑπερορίᾳ καὶ οὐκ ἐντὸς τῆς χώρας αἱ ἵπποι σφίσιν ἐκύισκον ἐκ τῶν ὄνων. καὶ τούτου μὲν κατάραν τινὰ ἐλέγετο γενέσθαι τὸ αἴτιον· ἡ δὲ βύσσος ἡ ἐν τῇ Ἠλείᾳ λεπτότητος μὲν ἕνεκα οὐκ ἀποδεῖ τῆς Ἑβραίων, ἔστι δὲ οὐχ ὁμοίως ξανθή.", "st": "5.5"}, {"sp": "N", "t": "ἰόντι δὲ ἀπὸ τῆς Ἠλείας χωρίον ἐστὶν ἐπὶ θάλασσαν καθῆκον, ὃ ὀνομάζεται μὲν Σαμικόν, ἐν δεξιᾷ δὲ ὑπὲρ αὐτὸ ἥ τε Τριφυλία καλουμένη καὶ πόλις ἐστὶν ἐν τῇ Τριφυλίᾳ Λέπρεος. ἐθέλουσι μὲν δὴ οἱ Λεπρεᾶται μοῖρα εἶναι τῶν Ἀρκάδων, φαίνονται δὲ Ἠλείων κατήκοοι τὸ ἐξ ἀρχῆς ὄντες· καὶ ὅσοι αὐτῶν Ὀλύμπια ἐνίκησαν, Ἠλείους ἐκ Λεπρέου σφᾶς ὁ κῆρυξ ἀνεῖπε. καὶ Ἀριστοφάνης ἐποίησεν ὡς Λέπρεος εἴη πόλισμα Ἠλείων. ἔστι δὲ ὁδὸς ἐς Λέπρεον ἀπὸ μὲν Σαμικοῦ τὸν Ἄνιγρον ποταμὸν ἀφέντι ἐν ἀριστερᾷ, ἑτέρα δὲ ἐξ Ὀλυμπίας, τρίτη δὲ ἐξ Ἤλιδος· ἡμερήσιος δὲ αὐτῶν ἐστιν ἡ μακροτάτη.", "st": "5.5"}, {"sp": "N", "t": "τεθῆναι δὲ τῇ πόλει τὸ ὄνομά φασιν ἀπὸ τοῦ οἰκιστοῦ Λεπρέου τοῦ Πυργέως. ἐλέγετο δὲ καὶ ὡς πρὸς Ἡρακλέα ἐρίσειεν ὁ Λεπρέος μὴ ἀποδεῖν τοῦ Ἡρακλέους ἐσθίων· ἐπεὶ δὲ ἑκάτερος βοῦν αὐτῶν ἐν ἴσῳ τῷ καιρῷ κατέσφαξε καὶ εὐτρέπισεν ἐς τὸ δεῖπνον, καὶ ἦν ὥσπερ καὶ ὑφίστατο ὁ Λεπρέος φαγεῖν οὐκ ἀδυνατώτερος τοῦ Ἡρακλέους, ἐτόλμησε τὸ μετὰ τοῦτο προ[σ]καλέσασθαι καὶ ἐς ἀγῶνα ὅπλων αὐτόν. καὶ ἀποθανεῖν τε Λεπρέον κρατηθέντα τῇ μάχῃ καὶ ἐν τῇ Φιγαλέων ταφῆναι λέγουσιν· οὐ μὴν εἶχόν γε οἱ Φιγαλεῖς ἀποφῆναι Λεπρέου μνῆμα.", "st": "5.5"}, {"sp": "N", "t": "ἤδη δὲ ἤκουσα θυγατρὶ τοῦ Πυργέως Λεπρέᾳ προσποιούντων τὸν οἰκισμόν· οἱ δὲ τοῖς πρῶτον οἰκήσασιν ἐν τῇ γῇ νόσον φασὶν ἐπιγενέσθαι λέπραν καὶ οὕτω τὸ ὄνομα λαβεῖν τὴν πόλιν ἐπὶ τῶν οἰκητόρων τῇ συμφορᾷ. γενέσθαι δὲ οἱ Λεπρεῖταί σφισιν ἔλεγον ἐν τῇ πόλει Λευκαίου Διὸς ναὸν καὶ Λυκούργου τάφον τοῦ Ἀλέου καὶ ἄλλον Καύκωνος· τούτῳ δὲ καὶ ἐπίθημα ἄνδρα ἐπεῖναι λύραν ἔχοντα.", "st": "5.5"}, {"sp": "N", "t": "κατὰ δὲ ἐμὲ οὔτε μνῆμα ἐπίσημον οὔτε ἱερὸν ἦν θεῶν σφισιν οὐδενὸς πλήν γε Δήμητρος· πλίνθου δὲ καὶ τοῦτο ἐπεποίητο ὠμῆς καὶ οὐδὲν παρείχετο ἄγαλμα. Λεπρεατῶν δέ ἐστιν οὐ πόρρω τῆς πόλεως Ἀρήνη καλουμένη πηγή, καὶ τὸ ὄνομα ἀπὸ τῆς Ἀφαρέως γυναικὸς τεθῆναι λέγουσι τῇ πηγῇ.", "st": "5.5"}, {"sp": "N", "t": "ἀναστρέψαντι δὲ αὖθις ἐπὶ τὸ Σαμικὸν καὶ διοδεύοντι τὸ χωρίον, Ἄνιγρος ποταμὸς ἐκδίδωσιν ἐς θάλασσαν. τούτου τὸ ῥεῦμα τοῦ ποταμοῦ πολλάκις ἀνείργουσιν οἱ ἄνεμοι βίαιοι πνέοντες· φοροῦντες γὰρ κατ’ αὐτὸν τὴν θῖνα ἐκ τοῦ πελάγους ἐπέχουσι τοῦ πρόσω τὸ ὕδωρ. ὁπότε οὖν ἀμφοτέρωθεν ἡ ψάμμος ὑπό τε τῆς θαλάσσης καὶ τὰ ἐντὸς ὑπὸ τοῦ ποταμοῦ διάβροχος γένοιτο, ἐνταῦθα καὶ ὑποζυγίοις καὶ ἀνδρὶ ἔτι μᾶλλον εὐζώνῳ καταδῦναι κίνδυνός ἐστιν ἐς αὐτήν.", "st": "5.5"}, {"sp": "N", "t": "ὁ δὲ Ἄνιγρος οὗτος ἐξ Ἀρκαδικοῦ μὲν κάτεισιν ὄρους Λαπίθου, παρέχεται δὲ εὐθὺς ἀπὸ τῶν πηγῶν ὕδωρ οὐκ εὐῶδες, ἀλλὰ καὶ δύσοσμον δεινῶς. πρὶν δὲ ἢ καταδέξασθαι τὸν Ἀκίδαντα καλούμενον δῆλός ἐστιν οὐδὲ ἀρχὴν τρέφων ἰχθῦς· μετὰ δὲ τοῦτον ἐσβαλόντα ὅσοι τῶν ἰχθύων ὁμοῦ τῷ ὕδατι αὐτοῦ κατίασιν ἐς τὸν Ἄνιγρον, οὐ σφᾶς ἔτι ἐδωδίμους ἔχουσιν ἄνθρωποι, τὰ πρότερα, ἢν ἐντὸς ἁλῶσι τοῦ Ἀκίδαντος, ἐδωδίμους ὄντας.", "st": "5.5"}, {"sp": "N", "t": "ὅτι δὲ τῷ Ἀκίδαντι ὄνομα Ἰάρδανος ἦν τὸ ἀρχαῖον, αὐτὸς μὲν οὐδαμόθεν συνεβαλόμην, ἀκούσας δὲ ἀνδρὸς Ἐφεσίου λέγω τὸν λόγον. τῷ δὲ Ἀνίγρῳ τὸ ἄτοπον εἶναι τῆς ὀσμῆς ἀπὸ τῆς γῆς πείθομαι δι’ ἧς ἄνεισι τὸ ὕδωρ, καθὰ δὴ καὶ τοῖς ὑπὲρ Ἰωνίας ἐστὶν ὕδασι τὸ αὐτὸ αἴτιον, ὁπόσων ἡ ἀτμὶς ὀλέθριός ἐστιν ἀνθρώπῳ.", "st": "5.5"}, {"sp": "N", "t": "Ἑλλήνων δὲ οἱ μὲν Χίρωνα, οἱ δὲ ἄλλον Κένταυρον Πυλήνορα τοξευθέντα ὑπὸ Ἡρακλέους καὶ φυγόντα τραυματίαν φασὶν ἐν τῷ ὕδατι ἀπολοῦσαι τούτῳ τὸ ἕλκος, καὶ ἀπὸ τῆς ὕδρας τοῦ ἰοῦ γενέσθαι δυσχερῆ τῷ Ἀνίγρῳ τὴν ὀσμήν· οἱ δὲ ἐς Μελάμποδα τὸν Ἀμυθάονος καὶ ἐς τῶν Προίτου θυγατέρων τὰ καθάρσια ἐμβληθέντα ἐνταῦθα ἀνάγουσι τὴν αἰτίαν τοῦ ἐπὶ τῷ ποταμῷ παθήματος.", "st": "5.5"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῷ Σαμικῷ σπήλαιον οὐκ ἄπωθεν τοῦ ποταμοῦ, καλούμενον Ἀνιγρίδων νυμφῶν. ὃς δ’ ἂν ἔχων ἀλφὸν ἢ λεύκην ἐς αὐτὸ ἐσέλθῃ, πρῶτα μὲν ταῖς νύμφαις εὔξασθαι καθέστηκεν αὐτῷ καὶ ὑποσχέσθαι θυσίαν ὁποίαν δή τινα, μετὰ δὲ ἀποσμήχει τὰ νοσοῦντα τοῦ σώματος· διανηξάμενος δὲ τὸν ποταμὸν ὄνειδος μὲν ἐκεῖνο κατέλιπεν ἐν τῷ ὕδατι αὐτοῦ, ὁ δὲ ὑγιής τε ἄνεισι καὶ ὁμόχρως.", "st": "5.5"}, {"sp": "N", "t": "κατὰ δὲ τὴν ὁδὸν τὴν εὐθεῖαν διαβάντι τὸν Ἄνιγρον καὶ ἰόντι ἐς Ὀλυμπίαν, ἔστιν οὐ μετὰ πολὺ ἐν δεξιᾷ τῆς ὁδοῦ χωρίον τε ὑψηλὸν καὶ πόλις Σαμία ἐπ’ αὐτοῦ [Σαμικοῦ]. ταύτῃ [τῇ Σαμικῷ] Πολυσπέρχοντά φασιν ἄνδρα Αἰτωλὸν ἐπιτειχίσματι ἐπὶ τοὺς Ἀρκάδας χρήσασθαι.", "st": "5.6"}, {"sp": "N", "t": "τὰ δὲ ἐρείπια τὰ Ἀρήνης σαφῶς μὲν οὔτε Μεσσηνίων εἶχεν οὐδεὶς οὔτε Ἠλείων ἀποφῆναί μοι· διάφορα δὲ ὑπὲρ αὐτῆς καὶ οὐ κατὰ ταὐτὰ πάρεστι τοῖς ἐθέλουσιν εἰκάζειν, πιθανώτατα δὲ ἐφαίνοντό μοι λέγειν οἱ τὸ Σαμικὸν τὰ παλαιότερα ἔτι καὶ τὰ ἐπὶ τῶν ἡρώων Ἀρήνην καλεῖσθαι νομίζοντες. οὗτοι δὲ καὶ ἔπη τῶν ἐν Ἰλιάδι ἔλεγον·<br>ἔστι δέ τις ποταμὸς Μινυήιος εἰς ἅλα βάλλων<br>ἐγγύθεν Ἀρήνης.", "st": "5.6"}, {"sp": "N", "t": "τὰ δὲ ἐρείπια ταῦτα πλησιαίτατά ἐστι τοῦ Ἀνίγρου. καὶ Ἀρήνην μὲν ἀμφισβητοίης ἂν μὴ ὀνομασθῆναι τὸ Σαμικόν, τῷ δὲ ποταμῷ Ἀνίγρῳ Μινυήιον τὸ ὄνομα εἶναι τὸ ἀρχαῖον ὡμολογήκασιν οἱ Ἀρκάδες. ὅρον δὲ Ἠλείοις πρὸς τὴν Μεσσηνίαν τῆς Νέδας τὰ ἐπὶ θαλάσσῃ γενέσθαι τις πείθοιτο ἂν ὁμοῦ τῇ ἐς Πελοπόννησον Ἡρακλειδῶν καθόδῳ.", "st": "5.6"}, {"sp": "N", "t": "μετὰ δὲ τὸν Ἄνιγρον ὁδεύσαντι ἐπὶ μακρότερον διὰ χωρίου τὰ πλείονα ὑποψάμμου καὶ ἔχοντος δένδρα πίτυς ἀγρίας, ὀπίσω ἐς ἀριστερὰ Σκιλλοῦντος ὄψει ἐρείπια. τῶν μὲν δὴ πόλεων ἦν τῶν ἐν τῇ Τριφυλίᾳ καὶ Σκιλλοῦς· ἐπὶ δὲ τοῦ πολέμου τοῦ Πισαίων πρὸς Ἠλείους ἐπίκουροί τε Πισαίων οἱ Σκιλλούντιοι καὶ διάφοροι τοῖς Ἠλείοις ἦσαν ἐκ τοῦ φανεροῦ, καὶ σφᾶς οἱ Ἠλεῖοι τούτων ἕνεκα ἐποίησαν ἀναστάτους.", "st": "5.6"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ ὕστερον Σκιλλοῦντα ἀποτεμόμενοι τῆς Ἠλείας Ξενοφῶντι ἔδοσαν τῷ Γρύλου, φυγάδι ἤδη γεγονότι ἐξ Ἀθηνῶν. ἐδιώχθη δὲ ὁ Ξενοφῶν ὑπὸ Ἀθηναίων ὡς ἐπὶ βασιλέα τῶν Περσῶν σφίσιν εὔνουν ὄντα στρατείας μετασχὼν Κύρῳ πολεμιωτάτῳ τοῦ δήμου· καθήμενος γὰρ ἐν Σάρδεσιν ὁ Κῦρος Λυσάνδρῳ τῷ Ἀριστοκρίτου καὶ Λακεδαιμονίοις χρήματα ἀνήλισκεν ἐς τὰς ναῦς. ἀντὶ τούτων μὲν Ξενοφῶντι ἐγένετο φυγή, κατοικήσας δὲ ἐν Σκιλλοῦντι τέμενός τε καὶ ἱερὸν καὶ ναὸν Ἀρτέμιδι ᾠκοδομήσατο Ἐφεσίᾳ.", "st": "5.6"}, {"sp": "N", "t": "παρέχεται δὲ ὁ Σκιλλοῦς καὶ ἄγρας θηρίων, ὑῶν τε ἀγρίων καὶ ἐλάφων· καὶ τὴν γῆν τὴν Σκιλλουντίαν Σελινοῦς ποταμὸς διέξεισιν. οἱ δὲ Ἠλείων ἐξηγηταὶ κομίσασθαί τε αὖθις Σκιλλοῦντα Ἠλείους ἔλεγον, καὶ Ξενοφῶντα, ὅτι ἔλαβε παρὰ Λακεδαιμονίων τὴν γῆν, κριθῆναι μὲν ἐν τῇ Ὀλυμπικῇ βουλῇ, τυχόντα δὲ παρὰ Ἠλείων συγγνώμης ἀδεῶς ἐν Σκιλλοῦντι οἰκῆσαι. καὶ δὴ καὶ ὀλίγον ἀπωτέρω τοῦ ἱεροῦ μνῆμά τε ἐδείκνυτο καὶ τῆς Πεντελῆσίν ἐστι λιθοτομίας εἰκὼν ἐπὶ τῷ τάφῳ· εἶναι δὲ αὐτὸ Ξενοφῶντος λέγουσιν οἱ προσοικοῦντες.", "st": "5.6"}, {"sp": "N", "t": "κατὰ δὲ τὴν ἐς Ὀλυμπίαν ὁδόν, πρὶν ἢ διαβῆναι τὸν Ἀλφειόν, ἔστιν ὄρος ἐκ Σκιλλοῦντος ἐρχομένῳ πέτραις ὑψηλαῖς ἀπότομον· ὀνομάζεται δὲ Τυπαῖον τὸ ὄρος. κατὰ τούτου τὰς γυναῖκας Ἠλείοις ἐστὶν ὠθεῖν νόμος, ἢν φωραθῶσιν ἐς τὸν ἀγῶνα ἐλθοῦσαι τὸν Ὀλυμπικὸν ἢ καὶ ὅλως ἐν ταῖς ἀπειρημέναις σφίσιν ἡμέραις διαβᾶσαι τὸν Ἀλφειόν. οὐ μὴν οὐδὲ ἁλῶναι λέγουσιν οὐδεμίαν, ὅτι μὴ Καλλιπάτειραν μόνην· εἰσὶ δὲ οἳ τὴν αὐτὴν ταύτην Φερενίκην καὶ οὐ Καλλιπάτειραν καλοῦσιν.", "st": "5.6"}, {"sp": "N", "t": "αὕτη προαποθανόντος αὐτῇ τοῦ ἀνδρός, ἐξεικάσασα αὑτὴν τὰ πάντα ἀνδρὶ γυμναστῇ, ἤγαγεν ἐς Ὀλυμπίαν τὸν υἱὸν μαχούμενον· νικῶντος δὲ τοῦ Πεισιρόδου, τὸ ἔρυμα ἐν ᾧ τοὺς γυμναστὰς ἔχουσιν ἀπειλημμένους, τοῦτο ὑπερπηδῶσα ἡ Καλλιπάτειρα ἐγυμνώθη. φωραθείσης δὲ ὅτι εἴη γυνή, ταύτην ἀφιᾶσιν ἀζήμιον καὶ τῷ πατρὶ καὶ ἀδελφοῖς αὐτῆς καὶ τῷ παιδὶ αἰδῶ νέμοντες—ὑπῆρχον δὴ ἅπασιν αὐτοῖς Ὀλυμπικαὶ νῖκαι—, ἐποίησαν δὲ νόμον ἐς τὸ ἔπειτα ἐπὶ τοῖς γυμνασταῖς γυμνοὺς σφᾶς ἐς τὸν ἀγῶνα ἐσέρχεσθαι.", "st": "5.6"}, {"sp": "N", "t": "ἀφικομένῳ δὲ ἐς Ὀλυμπίαν ἐνταῦθα ἤδη τὸ ὕδωρ ἐστὶ τοῦ Ἀλφειοῦ πλήθει τε πολὺ ἰδόντι καὶ ἥδιστον, ἅτε ποταμῶν καὶ ἄλλων καὶ λόγου μάλιστα ἀξίων ἑπτὰ ἐς αὐτὸν ῥεόντων. διὰ Μεγάλης μέν γε πόλεως Ἑλισσὼν ἐρχόμενος ἐκδίδωσιν ἐς τὸν Ἀλφειόν, Βρενθεάτης δὲ ἐκ τῆς Μεγαλοπολιτῶν γῆς, παρὰ δὲ Γόρτυναν ἔνθα ἱερὸν Ἀσκληπιοῦ, παρὰ δὴ ταῦτα Γορτύνιος ῥέων, ἐκ ⟨δὲ⟩ Μελαινεῶν Βουφάγος τῆς Μεγαλοπολίτιδος μεταξὺ καὶ Ἡραιίτιδος χώρας, ἐκ δὲ τῆς Κλειτορίων Λάδων, ἐκ δὲ Ἐρυμάνθου τοῦ ὄρους ὁμώνυμος τῷ ὄρει. οὗτοι μὲν ἐξ Ἀρκαδίας κατίασιν ἐς τὸν Ἀλφειόν, Κλάδεος δὲ ἐρχόμενος ἐκ τῆς Ἠλείας συμμίσγει οἱ τὸ ῥεῦμα· αὐτῷ δὲ ἐν τῇ Ἀρκάδων τῷ Ἀλφειῷ καὶ οὐχὶ ἐκ τῆς Ἠλείας εἰσὶν αἱ πηγαί.", "st": "5.7"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἄλλα τοιάδε ἐς τὸν Ἀλφειόν, ὡς ἀνὴρ εἴη θηρευτής, ἐρασθῆναι δὲ αὐτὸν Ἀρεθούσης, κυνηγετεῖν δὲ καὶ ταύτην. καὶ Ἀρέθουσαν μὲν οὐκ ἀρεσκομένην γήμασθαι περαιωθῆναί φασιν ἐς νῆσον τὴν κατὰ Συρακούσας, καλουμένην δὲ Ὀρτυγίαν, καὶ ἐνταῦθα ἐξ ἀνθρώπου γενέσθαι πηγήν· συμβῆναι δὲ ὑπὸ τοῦ ἔρωτος καὶ Ἀλφειῷ τὴν ἀλλαγὴν ἐς τὸν ποταμόν.", "st": "5.7"}, {"sp": "N", "t": "ταῦτα μὲν λόγου τοῦ ἐς Ἀλφειὸν †ἐς τὴν Ὀρτυγίαν †· τὸ δὲ διὰ τῆς θαλάσσης ἰόντα ἐνταῦθα ἀνακοινοῦσθαι τὸ ὕδωρ πρὸς τὴν πηγὴν οὐκ ἔστιν ὅπως ἀπιστήσω, τὸν θεὸν ἐπιστάμενος τὸν ἐν Δελφοῖς ὁμολογοῦντά σφισιν, ὃς Ἀρχίαν τὸν Κορίνθιον ἐς τὸν Συρακουσῶν ἀποστέλλων οἰκισμὸν καὶ τάδε εἶπε τὰ ἔπη·<br>Ὀρτυγίη τις κεῖται ἐν ἠεροειδέι πόντῳ,<br>Θρινακίης καθύπερθεν, ἵν’ Ἀλφειοῦ στόμα βλύζει.<br>μισγόμενον πηγαῖσιν ἐυρρείτης Ἀρεθούσης.<br>κατὰ τοῦτο οὖν, ὅτι τῇ Ἀρεθούσῃ τοῦ Ἀλφειοῦ τὸ ὕδωρ μίσγεται, καὶ τοῦ ἔρωτος τὴν φήμην τῷ ποταμῷ πείθομαι γενέσθαι.", "st": "5.7"}, {"sp": "N", "t": "ὅσοι δὲ Ἑλλήνων ἢ Αἰγυπτίων ἐς Αἰθιοπίαν ⟨τὴν⟩ ὑπὲρ Συήνης καὶ ἐς Μερόην Αἰθιόπων πόλιν ἀναβεβήκασι, λέγουσιν οὗτοι τὸν Νεῖλον, ἐσιόντα ἐς λίμνην καὶ δι’ αὐτῆς διεξιόντα ὥσπερ ἐκ χέρσου, μετὰ τοῦτο ἤδη δι’ Αἰθιοπίας τῆς κάτω καὶ ἐς Αἴγυπτον ῥεύσαντα ἐπὶ Φάρον καὶ τὴν ταύτῃ θάλασσαν κατέρχεσθαι. ἐν δὲ τῇ γῇ ποταμὸν τῇ Ἑβραίων Ἰάρδανον καὶ αὐτὸς οἶδα λίμνην Τιβεριάδα ὀνομαζομένην διοδεύοντα, ἐς δὲ λίμνην ἑτέραν καλουμένην θάλασσαν Νεκράν, ἐς ταύτην ἐσιόντα καὶ ὑπὸ τῆς λίμνης αὐτὸν ἀναλούμενον.", "st": "5.7"}, {"sp": "N", "t": "ἡ δὲ θάλασσα ἡ Νεκρὰ πάσχει παντὶ ὕδατι ἄλλῳ τὰ ἐναντία· ἐν ᾗ γε τὰ μὲν ζῶντα πέφυκεν οὐ νηχόμενα ἐποχεῖσθαι, τὰ δὲ θνήσκοντα ἐς βυθὸν χωρεῖν. ταύτῃ ἄκαρπος καὶ ἰχθύων ἡ λίμνη· ἅτε ἀπὸ τοῦ φανερωτάτου κινδύνου ἐπὶ τὸ ὕδωρ ἀναφεύγουσιν ὀπίσω τὸ οἰκεῖον. τῷ δὲ Ἀλφειῷ τὸ αὐτὸ πάσχει καὶ ὕδωρ ἄλλο ἐν Ἰωνίᾳ· τούτου δὲ τοῦ ὕδατος πηγὴ μέν ἐστιν ἐν Μυκάλῃ τῷ ὄρει, διεξελθὸν δὲ θάλασσαν τὴν μεταξὺ ἄνεισιν αὖθις κατὰ Βραγχίδας πρὸς λιμένι ὀνομαζομένῳ Πανόρμῳ.", "st": "5.7"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἔχει τρόπον τὸν εἰρημένον· ἐς δὲ τὸν ἀγῶνα τὸν Ὀλυμπικὸν λέγουσιν Ἠλείων οἱ τὰ ἀρχαιότατα μνημονεύοντες Κρόνον τὴν ἐν οὐρανῷ σχεῖν βασιλείαν πρῶτον καὶ ἐν Ὀλυμπίᾳ ποιηθῆναι Κρόνῳ ναὸν ὑπὸ τῶν τότε ἀνθρώπων, οἳ ὠνομάζοντο χρυσοῦν γένος· Διὸς δὲ τεχθέντος ἐπιτρέψαι Ῥέαν τοῦ παιδὸς τὴν φρουρὰν τοῖς Ἰδαίοις Δακτύλοις, καλουμένοις δὲ τοῖς αὐτοῖς τούτοις καὶ Κούρησιν· ἀφικέσθαι δὲ αὐτοὺς ἐξ Ἴδης τῆς Κρητικῆς, [πρὸς] Ἡρακλέα καὶ Παιωναῖον καὶ Ἐπιμήδην καὶ Ἰάσιόν τε καὶ Ἴδαν·", "st": "5.7"}, {"sp": "N", "t": "τὸν δὲ Ἡρακλέα παίζοντα—εἶναι γὰρ δὴ αὐτὸν πρεσβύτατον ἡλικίᾳ—συμβαλεῖν τοὺς ἀδελφοὺς ἐς ἅμιλλαν δρόμου καὶ τὸν νικήσαντα ἐξ αὐτῶν κλάδῳ στεφανῶσαι κοτίνου· παρεῖναι δὲ αὐτοῖς πολὺν δή τι οὕτω τὸν κότινον ὡς τὰ χλωρὰ ἔτι τῶν φύλλων ὑπεστρῶσθαι σφᾶς καθεύδοντας. κομισθῆναι δὲ ἐκ τῆς Ὑπερβορέων γῆς τὸν κότινόν φασιν ὑπὸ τοῦ Ἡρακλέους ἐς Ἕλληνας, εἶναι δὲ ἀνθρώπους οἳ ὑπὲρ τὸν ἄνεμον οἰκοῦσι τὸν Βορέαν.", "st": "5.7"}, {"sp": "N", "t": "πρῶτος μὲν ἐν ὕμνῳ τῷ ἐς Ἀχαιίαν ἐποίησεν Ὠλὴν Λύκιος ἀφικέσθαι τὴν Ἀχαιίαν ἐς Δῆλον ἐκ τῶν Ὑπερβορέων τούτων· ἔπειτα δὲ ᾠδὴν Μελάνωπος Κυμαῖος ἐς Ὦπιν καὶ Ἑκαέργην ᾖσεν, ὡς ἐκ τῶν Ὑπερβορέων καὶ αὗται πρότερον ἔτι τῆς Ἀχαιίας ἀφίκοντο [καὶ] ἐς Δῆλον·", "st": "5.7"}, {"sp": "N", "t": "Ἀριστέας ⟨δὲ⟩ [γὰρ] ὁ Προκοννήσιος—μνήμην ⟨γὰρ⟩ ἐποιήσατο Ὑπερβορέων καὶ οὗτος—τάχα τι καὶ πλέον περὶ αὐτῶν πεπυσμένος ⟨ἂν⟩ εἴη παρὰ Ἰσσηδόνων, ἐς οὓς ἀφικέσθαι φησὶν ἐν τοῖς ἔπεσιν. Ἡρακλεῖ οὖν πρόσεστι τῷ Ἰδαίῳ δόξα τὸν τότε ἀγῶνα διαθεῖναι πρώτῳ καὶ Ὀλύμπια ὄνομα θέσθαι· διὰ πέμπτου οὖν ἔτους αὐτὸν κατεστήσατο ἄγεσθαι, ὅτι αὐτός τε καὶ οἱ ἀδελφοὶ πέντε ἦσαν ἀριθμόν.", "st": "5.7"}, {"sp": "N", "t": "Δία δὴ οἱ μὲν ἐνταῦθα παλαῖσαι καὶ αὐτῷ Κρόνῳ περὶ τῆς ἀρχῆς, οἱ δὲ ἐπὶ κατειργασμένῳ ἀγωνοθετῆσαί φασιν αὐτόν· νικῆσαι δὲ ἄλλοι τε λέγονται καὶ ὅτι Ἀπόλλων παραδράμοι μὲν ἐρίζοντα Ἑρμῆν, κρατήσαι δὲ Ἄρεως πυγμῇ. τούτου δὲ ἕνεκα καὶ τὸ αὔλημα τὸ Πυθικόν φασι τῷ πηδήματι ἐπεισαχθῆναι τῶν πεντάθλων, ὡς τὸ μὲν ἱερὸν τοῦ Ἀπόλλωνος τὸ αὔλημα ὄν, τὸν Ἀπόλλωνα δὲ ἀνῃρημένον Ὀλυμπικὰς νίκας.", "st": "5.7"}, {"sp": "N", "t": "τούτων δὲ ὕστερον Κλύμενον τὸν Κάρδυος, πεντηκοστῷ μάλιστα ἔτει μετὰ τὴν συμβᾶσαν ἐπὶ Δευκαλίωνος ἐν Ἕλλησιν ἐπομβρίαν ἐλθόντα ἐκ Κρήτης, γένος ἀπὸ Ἡρακλέους ὄντα τοῦ Ἰδαίου, τόν τε ἀγῶνα ἐν Ὀλυμπίᾳ θεῖναι καὶ Κούρησι τοῖς τε ἄλλοις καὶ Ἡρακλεῖ τῷ προγόνῳ λέγουσιν ἱδρύσασθαι βωμόν, Παραστάτην ἐπωνυμίαν τῷ Ἡρακλεῖ θέμενον. Ἐνδυμίων δὲ ὁ Ἀεθλίου Κλύμενόν τε ἔπαυσε τῆς ἀρχῆς καὶ δρόμου τοῖς υἱοῖς ἆθλα ἐν Ὀλυμπίᾳ τὴν βασιλείαν ἔθηκε.", "st": "5.8"}, {"sp": "N", "t": "Πέλοψ δὲ ὕστερον γενεᾷ μάλιστα μετὰ Ἐνδυμίωνα τὸν ἀγῶνα τῷ Ὀλυμπίῳ Διὶ ἐποίησεν ἀξιολογώτατα ἀνθρώπων τῶν πρὸ αὐτοῦ. Πέλοπος δὲ τῶν παίδων σκεδασθέντων ἐξ Ἤλιδος ἀνὰ πᾶσαν τὴν ἄλλην Πελοπόννησον, Ἀμυθάων ὁ Κρηθέως Ἐνδυμίωνι ἀνεψιὸς πρὸς πατρός—εἶναι γάρ φασι καὶ Ἀέθλιον Αἰόλου, Διὸς δὲ ἐπίκλησιν—, ἔθηκεν ὁ Ἀμυθάων τὰ Ὀλύμπια, μετὰ δὲ αὐτὸν Πελίας τε καὶ Νηλεὺς ἐν κοινῷ.", "st": "5.8"}, {"sp": "N", "t": "ἔθηκε δὲ καὶ Αὐγέας καὶ Ἡρακλῆς ὁ Ἀμφιτρύωνος ἑλὼν Ἦλιν· ὁπόσους δὲ ἐστεφάνωσεν οὗτος νικῶντας, ἔστιν Ἰόλαος ταῖς Ἡρακλέους δραμὼν ἵπποις. ἦν δὲ ἄρα ἐκ παλαιοῦ καθεστηκὸς ἀγωνίζεσθαι καὶ ἀλλοτρίαις ἵπποις· Ὅμηρος γοῦν ἐν ἄθλοις τεθεῖσιν ἐπὶ Πατρόκλῳ πεποίηκεν ὡς Μενέλαος Αἴθῃ τῇ Ἀγαμέμνονος, τῷ δὲ ἑτέρῳ χρήσαιτο τῶν ἵππων οἰκείῳ.", "st": "5.8"}, {"sp": "N", "t": "ἡνιόχει δὲ καὶ ἄλλως ὁ Ἰόλαος Ἡρακλεῖ τὰς ἵππους· αὐτός τε οὖν ἅρματι καὶ Ἰάσιος ἀνὴρ Ἀρκὰς κέλητος ἐνίκησεν ἵππου δρόμῳ, Τυνδάρεω δὲ οἱ παῖδες ὁ μὲν δρόμῳ, Πολυδεύκης δὲ πυκτεύων. λέγεται δὲ καὶ ἐς αὐτὸν Ἡρακλέα ὡς πάλης τε ἀνέλοιτο καὶ παγκρατίου νίκας.", "st": "5.8"}, {"sp": "N", "t": "μετὰ δὲ Ὄξυλον—διέθηκε γὰρ τὸν ἀγῶνα καὶ Ὄξυλος—, μετὰ τοῦτον βασιλεύσαντα ἐξέλιπεν ἄχρι Ἰφίτου τὰ Ὀλύμπια. Ἰφίτου δὲ τὸν ἀγῶνα ἀνανεωσαμένου κατὰ τὰ ἤδη μοι λελεγμένα, τοῖς ἀνθρώποις ἔτι ὑπῆρχε τῶν ἀρχαίων λήθη· καὶ κατ’ ὀλίγον ἐς ὑπόμνησιν ἤρχοντο αὐτῶν, καὶ ὁπότε τι ἀναμνησθεῖεν, ἐποιοῦντο τῷ ἀγῶνι προσθήκην.", "st": "5.8"}, {"sp": "N", "t": "δῆλον δέ· ἐξ οὗ γὰρ τὸ συνεχὲς ταῖς μνήμαις ἐπὶ ταῖς Ὀλυμπιάσιν ἐστί, δρόμου μὲν ἆθλα ἐτέθη πρῶτον, καὶ Ἠλεῖος Κόροιβος ἐνίκα· εἰκὼν μὲν δὴ οὐκ ἔστιν ἐν Ὀλυμπίᾳ τοῦ Κοροίβου, τάφος δὲ ἐπὶ τοῖς πέρασι τῆς Ἠλείας. Ὀλυμπιάδι δὲ ὕστερον τετάρτῃ καὶ δεκάτῃ προσετέθη σφίσι δίαυλος· Ὕπηνος δὲ ἀνὴρ Πισαῖος ἀνείλετο ἐπὶ τῷ διαύλῳ τὸν κότινον, τῇ δὲ ἑξῆς ⟨ἐπὶ τῷ δολίχῳ⟩ Ἄκανθος ⟨Λακεδαιμόνιος⟩.", "st": "5.8"}, {"sp": "N", "t": "ἐπὶ δὲ τῆς ὀγδόης καὶ δεκάτης Ὀλυμπιάδος πεντάθλου καὶ πάλης ἀφίκοντο ἐς μνήμην· καὶ τοῦ μὲν Λάμπιδι ὑπῆρξεν, Εὐρυβάτῳ δὲ ἡ νίκη τῆς πάλης, Λακεδαιμονίοις καὶ τούτοις. τρίτῃ δὲ Ὀλυμπιάδι καὶ εἰκοστῇ πυγμῆς ἆθλα ἀπέδοσαν· Ὀνόμαστος δὲ ἐνίκησεν ἐκ Σμύρνης συντελούσης ἤδη τηνικαῦτα ἐς Ἴωνας. πέμπτῃ δὲ ἐπὶ ταῖς εἴκοσι κατεδέξαντο ἵππων τελείων δρόμον, καὶ ἀνηγορεύθη Θηβαῖος Παγώνδας κρατῶν ἅρματι.", "st": "5.8"}, {"sp": "N", "t": "ὀγδόῃ δὲ ἀπὸ ταύτης Ὀλυμπιάδι ἐδέξαντο παγκρατιαστήν τε ἄνδρα καὶ ἵππον κέλητα· ἵππος μὲν δὴ Κραννωνίου Κραυξίδα παρέφθη, τοὺς δὲ ἐσελθόντας ἐπὶ τὸ παγκράτιον ὁ Λύγδαμις κατειργάσατο Συρακούσιος. τούτῳ πρὸς ταῖς λιθοτομίαις ἐστὶν ἐν Συρακούσαις μνῆμα· εἰ δὲ καὶ Ἡρακλεῖ τῷ Θηβαίῳ μέγεθος παρισοῦτο ὁ Λύγδαμις, ἐγὼ μὲν οὐκ οἶδα, λεγόμενον δὲ ὑπὸ Συρακουσίων ἐστί.", "st": "5.8"}, {"sp": "N", "t": "τὰ δὲ ἐπὶ τοῖς παισὶν ἐς μὲν τῶν παλαιοτέρων οὐδεμίαν ἥκει μνήμην, αὐτοὶ δὲ ἀρέσαν σφίσι κατεστήσαντο Ἠλεῖοι. δρόμου μὲν δὴ καὶ πάλης ἐτέθη παισὶν ἆθλα ἐπὶ τῆς ἑβδόμης καὶ τριακοστῆς Ὀλυμπιάδος, καὶ Ἱπποσθένης Λακεδαιμόνιος πάλην, Πολυνείκης δὲ τὸν δρόμον ἐνίκησεν Ἠλεῖος. πρώτῃ δὲ ἐπὶ ταῖς τεσσαράκοντα Ὀλυμπιάδι πύκτας ἐσεκάλεσαν παῖδας, καὶ περιῆν τῶν ἐσελθόντων Συβαρίτης Φιλύτας.", "st": "5.8"}, {"sp": "N", "t": "τῶν δὲ ὁπλιτῶν ὁ δρόμος ἐδοκιμάσθη μὲν ἐπὶ τῆς πέμπτης Ὀλυμπιάδος καὶ ἑξηκοστῆς, μελέτης ἐμοὶ δοκεῖν ἕνεκα τῆς ἐς τὰ πολεμικά· τοὺς δὲ δραμόντας ἀσπίσιν ὁμοῦ πρῶτος Δαμάρετος ἐκράτησεν Ἡραιεύς. δρόμος δὲ δύο ἵππων τελείων συνωρὶς κληθεῖσα τρίτῃ μὲν Ὀλυμπιάδι ἐτέθη πρὸς ταῖς ἐνενήκοντα, Εὐαγόρας δὲ ἐνίκησεν Ἠλεῖος. ἐνάτῃ δὲ ἤρεσεν Ὀλυμπιάδι καὶ ἐνενηκοστῇ καὶ πώλων ἅρμασιν ἀγωνίζεσθαι· Λακεδαιμόνιος δὲ Συβαριάδης τὸν στέφανον τῶν πώλων ἔσχε τοῦ ἅρματος.", "st": "5.8"}, {"sp": "N", "t": "προσέθεσαν δὲ ὕστερον καὶ συνωρίδα πώλων καὶ πῶλον κέλητα· ἐπὶ μὲν δὴ τῇ συνωρίδι Βελιστίχην ἐκ Μακεδονίας τῆς ἐπὶ θαλάσσῃ γυναῖκα, Τληπόλεμον δὲ Λύκιον ἀναγορευθῆναι λέγουσιν ἐπὶ τῷ κέλητι, τοῦτον μὲν ἐπὶ τῆς πρώτης καὶ τριακοστῆς τε καὶ ἑκατοστῆς Ὀλυμπιάδος, τῆς δὲ Βελιστίχης τὴν συνωρίδα Ὀλυμπιάδι πρὸ ταύτης τρίτῃ. πέμπτῃ δὲ ἐπὶ ταῖς τεσσαράκοντα καὶ ἑκατὸν ἆθλα ἐτέθη παγκρατίου παισί, καὶ ἐνίκα Φαίδιμος Αἰολεὺς ἐκ πόλεως Τρῳάδος.", "st": "5.8"}, {"sp": "N", "t": "κατελύθη δὲ ἐν Ὀλυμπίᾳ καὶ ἀγωνίσματα, μεταδόξαν μηκέτι ἄγειν αὐτὰ Ἠλείοις. πένταθλόν τε γὰρ παίδων ἐπὶ τῆς ὀγδόης Ὀλυμπιάδος καὶ τριακοστῆς ἐτέθη, καὶ ἐπ’ αὐτῷ τὸν κότινον Εὐτελίδα Λακεδαιμονίου λαβόντος οὐκέτι ἀρεστὰ Ἠλείοις ἦν πεντάθλους ἐσέρχεσθαι παῖδας. τῆς δὲ ἀπήνης καὶ κάλπης τὸν δρόμον, τὸν μὲν Ὀλυμπιάδι νομισθέντα ἑβδομηκοστῇ, τὸν δὲ τῆς κάλπης τῇ ἐφεξῆς ταύτῃ, κήρυγμα ὑπὲρ ἀμφοτέρων ἐποιήσαντο ἐπὶ τῆς τετάρτης Ὀλυμπιάδος καὶ ὀγδοηκοστῆς μήτε κάλπης τοῦ λοιποῦ μήτε ἀπήνης ἔσεσθαι δρόμον. ὅτε δὲ ἐτέθη πρῶτον, Θερσίου μὲν ἀπήνη Θεσσαλοῦ, Παταίκου δὲ Ἀχαιοῦ τῶν ἐκ Δύμης ἐνίκησεν ἡ κάλπη.", "st": "5.9"}, {"sp": "N", "t": "ἦν δὲ ἡ μὲν θήλεια ἵππος, καὶ ἀπ’ αὐτῶν ἀποπηδῶντες ἐπὶ τῷ ἐσχάτῳ δρόμῳ συνέθεον [οἱ ἀναβάται] ταῖς ἵπποις εἰλημμένοι τῶν χαλινῶν, καθὰ καὶ ἐς ἐμὲ ἔτι οἱ ἀναβάται καλούμενοι· διάφορα δὲ τοῖς ἀναβάταις ἐς τῆς κάλπης τὸν δρόμον τά τε σημεῖά ἐστι καὶ ἄρσενές σφισιν ὄντες οἱ ἵπποι. ἀπήνῃ δὲ οὔτε τῷ ἀνευρήματι οὐδὲν ἀρχαῖον οὔτε εὐπρέπεια αὐτῇ προσῆν, ἐπάρατόν τε Ἠλείοις ἐκ παλαιοῦ καὶ ἀρχὴν γενέσθαι σφίσιν ἐν τῇ χώρᾳ τὸ ζῷον· ἦν γὰρ δὴ ἀπήνη κατὰ τὴν συνωρίδα ἡμιόνους ἀντὶ ἵππων ἔχουσα.", "st": "5.9"}, {"sp": "N", "t": "ὁ δὲ κόσμος ὁ περὶ τὸν ἀγῶνα ἐφ’ ἡμῶν, ὡς θύεσθαι τῷ θεῷ τὰ ἱερεῖα πεντάθλου μὲν καὶ δρόμου τῶν ἵππων ὕστερα⟨, τῶν δὲ λοιπῶν πρότερα⟩ ἀγωνισμάτων, οὗτος κατέστη σφίσιν ὁ κόσμος Ὀλυμπιάδι ἑβδόμῃ πρὸς ταῖς ἑβδομήκοντα· τὰ πρὸ τούτων δὲ ἐπὶ ἡμέρας ἦγον τῆς αὐτῆς ὁμοίως καὶ ἀνθρώπων καὶ ἵππων ἀγῶνα. τότε δὲ προήχθησαν ἐς νύκτα οἱ παγκρατιάζοντες ἅτε οὐ κατὰ καιρὸν ἐσκληθέντες, αἴτιοι δὲ ἐγένοντο οἵ τε ἵπποι καὶ ἐς πλέον ἔτι ἡ τῶν πεντάθλων ἅμιλλα· καὶ ἐκράτει μὲν Ἀθηναῖος Καλλίας τοὺς παγκρατιάσαντας, ἐμπόδιον δὲ οὐκ ἔμελλε παγκρατίῳ τοῦ λοιποῦ τὸ πένταθλον οὐδὲ οἱ ἵπποι γενήσεσθαι.", "st": "5.9"}, {"sp": "N", "t": "τὰ δὲ ἐπὶ τοῖς ἀγωνοθετοῦσιν οὐ κατὰ τὰ αὐτὰ ἃ καθεστηκότα ἦν ἐξ ἀρχῆς καὶ ἐφ’ ἡμῶν ἐς αὐτοὺς νομίζουσιν, ἀλλὰ Ἴφιτος μὲν τὸν ἀγῶνα ἔθηκεν αὐτὸς μόνος, καὶ μετὰ Ἴφιτον ἐτίθεσαν ὡσαύτως οἱ ἀπὸ Ὀξύλου· πεντηκοστῇ δὲ Ὀλυμπιάδι ἀνδράσι δύο ἐξ ἁπάντων λαχοῦσιν Ἠλείων ἐπετράπη ποιῆσαι τὰ Ὀλύμπια, καὶ ἐπὶ πλεῖστον ἀπὸ ἐκείνου διέμεινε τῶν ἀγωνοθετῶν ὁ ἀριθμὸς τῶν δύο.", "st": "5.9"}, {"sp": "N", "t": "πέμπτῃ δὲ Ὀλυμπιάδι καὶ ἐνενηκοστῇ ἐννέα ἑλλανοδίκας κατέστησαν· τρισὶ μὲν δὴ ἐπετέτραπτο ἐξ αὐτῶν ὁ δρόμος τῶν ἵππων, τοσούτοις δὲ ἑτέροις ἐπόπταις εἶναι τοῦ πεντάθλου, τοῖς δὲ ὑπολειπομένοις τὰ λοιπὰ ἔμελε τῶν ἀγωνισμάτων. δευτέρᾳ δὲ ἀπὸ ταύτης Ὀλυμπιάδι προσετέθη καὶ ὁ δέκατος ἀθλοθέτης. ἐπὶ δὲ τῆς τρίτης καὶ ἑκατοστῆς φυλαί τε Ἠλείοις δώδεκα καὶ εἷς ἀπὸ φυλῆς ἑκάστης ἐγένετο Ἑλλανοδίκης.", "st": "5.9"}, {"sp": "N", "t": "πιεσθέντες δὲ ὑπὸ Ἀρκάδων πολέμῳ μοῖράν τε ἀπέβαλον τῆς γῆς καὶ ὅσοι τῶν δήμων ἦσαν ἐν τῇ ἀποτμηθείσῃ χώρᾳ, καὶ οὕτως ἐς ὀκτώ τε ἀριθμὸν φυλῶν ἐπὶ τῆς τετάρτης συνεστάλησαν Ὀλυμπιάδος καὶ ἑκατοστῆς καὶ Ἑλλανοδίκαι σφίσιν ἴσοι ταῖς φυλαῖς ᾑρέθησαν. ὀγδόῃ δὲ ἐπὶ ταῖς ἑκατὸν Ὀλυμπιάδι ἐπανῆλθον αὖθις ἐς ἀνδρῶν δέκα ἀριθμόν, καὶ ἤδη τὸ ἀπὸ τούτου διαμεμένηκεν ἐς ἡμᾶς.", "st": "5.9"}, {"sp": "N", "t": "πολλὰ μὲν δὴ καὶ ἄλλα ἴδοι τις ἂν ἐν Ἕλλησι, τὰ δὲ καὶ ἀκούσαι θαύματος ἄξια· μάλιστα δὲ τοῖς Ἐλευσῖνι δρωμένοις καὶ ἀγῶνι τῷ ἐν Ὀλυμπίᾳ μέτεστιν ἐκ θεοῦ φροντίδος. τὸ δὲ ἄλσος τὸ ἱερὸν τοῦ Διὸς παραποιήσαντες τὸ ὄνομα Ἄλτιν ἐκ παλαιοῦ καλοῦσι· καὶ δὴ καὶ Πινδάρῳ ποιήσαντι ἐς ἄνδρα Ὀλυμπιονίκην ᾆσμα Ἄλτις ἐπωνόμασται τὸ χωρίον.", "st": "5.10"}, {"sp": "N", "t": "ἐποιήθη δὲ ὁ ναὸς καὶ τὸ ἄγαλμα τῷ Διὶ ἀπὸ λαφύρων, ἡνίκα Πίσαν οἱ Ἠλεῖοι καὶ ὅσον τῶν περιοίκων ἄλλο συναπέστη Πισαίοις πολέμῳ καθεῖλον. Φειδίαν δὲ τὸν ἐργασάμενον τὸ ἄγαλμα εἶναι καὶ ἐπίγραμμά ἐστιν ἐς μαρτυρίαν ὑπὸ τοῦ Διὸς γεγραμμένον τοῖς ποσί·<br>Φειδίας Χαρμίδου υἱὸς Ἀθηναῖός μ’ ἐποίησε.<br>τοῦ ναοῦ δὲ Δώριος μέν ἐστιν ἡ ἐργασία, τὰ δὲ ἐκτὸς περίστυλός ἐστι·", "st": "5.10"}, {"sp": "N", "t": "πεποίηται δὲ ἐπιχωρίου πώρου. ὕψος μὲν δὴ αὐτοῦ ⟨τὸ⟩ ἐς τὸν ἀετὸν ἀνῆκον, εἰσίν οἱ ὀκτὼ πόδες καὶ ἑξήκοντα, εὖρος δὲ πέντε καὶ ἐνενήκοντα, τὰ δὲ ἐς μῆκος τριάκοντά τε καὶ διακόσιοι· τέκτων δὲ ἐγένετο αὐτοῦ Λίβων ἐπιχώριος. κέραμος δὲ οὐ γῆς ὀπτῆς ἐστιν, ἀλλὰ κεράμου τρόπον λίθος ὁ Πεντελῆσιν εἰργασμένος· τὸ δὲ εὕρημα ἀνδρὸς Ναξίου λέγουσιν εἶναι Βύζου, οὗ φασιν ἐν Νάξῳ τὰ ἀγάλματα ἐφ’ ὧν ἐπίγραμμα εἶναι<br>Νάξιος Εὔεργός με γένει Λητοῦς πόρε, Βύζεω<br>παῖς, ὃς πρώτιστος τεῦξε λίθου κέραμον.<br>ἡλικίαν δὲ ὁ Βύζης οὗτος κατὰ Ἀλυάττην ⟨ἦν⟩ τὸν Λυδὸν καὶ Ἀστυάγην τὸν Κυαξάρου βασιλεύοντα ἐν Μήδοις.", "st": "5.10"}, {"sp": "N", "t": "ἐν δὲ Ὀλυμπίᾳ λέβης ἐπίχρυσος ἐπὶ ἑκάστῳ τοῦ ὀρόφου τῷ πέρατι ἐπίκειται καὶ Νίκη κατὰ μέσον μάλιστα ἕστηκε τὸν ἀετόν, ἐπίχρυσος καὶ αὕτη. ὑπὸ δὲ τῆς Νίκης τὸ ἄγαλμα ἀσπὶς ἀνάκειται χρυσῆ, Μέδουσαν τὴν Γοργόνα ἔχουσα ἐπειργασμένην. τὸ ἐπίγραμμα δὲ τὸ ἐπὶ τῇ ἀσπίδι τούς τε ἀναθέντας δηλοῖ καὶ καθ’ ἥντινα αἰτίαν ἀνέθεσαν· λέγει γὰρ δὴ οὕτω·<br>ναὸς μὲν φιάλαν χρυσέαν ἔχει, ἐκ δὲ Τανάγρας<br>τοὶ Λακεδαιμόνιοι συμμαχία τ’ ἀν⟨έ⟩θεν<br>δῶρον ἀπ’ Ἀργείων καὶ Ἀθαναίων καὶ Ἰώνων,<br>τὰν δεκάταν νίκας εἵνεκα τῶ πολέμω.<br>ταύτης τῆς μάχης μνήμην καὶ ἐν τῇ Ἀτθίδι ἐποιησάμην συγγραφῇ, τὰ Ἀθήνῃσιν ἐπεξιὼν μνήματα.", "st": "5.10"}, {"sp": "N", "t": "τοῦ δὲ ἐν Ὀλυμπίᾳ ναοῦ τῆς ὑπὲρ τῶν κιόνων περιθεούσης ζώνης κατὰ τὸ ἐκτὸς ἀσπίδες εἰσὶν ἐπίχρυσοι μία καὶ εἴκοσιν ἀριθμόν, ἀνάθημα στρατηγοῦ Ῥωμαίων Μομμίου κρατήσαντος Ἀχαιῶν πολέμῳ καὶ Κόρινθόν τε ἑλόντος καὶ Κορινθίους τοὺς Δωριέας ποιήσαντος ἀναστάτους.", "st": "5.10"}, {"sp": "N", "t": "τὰ δὲ ἐν τοῖς ἀετοῖς, ἔστιν ἔμπροσθεν Πέλοπος ἡ πρὸς Οἰνόμαον τῶν ἵππων ἅμιλλα ἔτι μέλλουσα καὶ τὸ ἔργον τοῦ δρόμου παρὰ ἀμφοτέρων ἐν παρασκευῇ. Διὸς δὲ ἀγάλματος κατὰ μέσον πεποιημένου μάλιστα τὸν ἀετόν, ἔστιν Οἰνόμαος ἐν δεξιᾷ τοῦ Διὸς ἐπικείμενος κράνος τῇ κεφαλῇ, παρὰ δὲ αὐτὸν γυνὴ Στερόπη, θυγατέρων καὶ αὕτη τῶν Ἄτλαντος· Μυρτίλος δέ, ὃς ἤλαυνε τῷ Οἰνομάῳ τὸ ἅρμα, κάθηται πρὸ τῶν ἵππων, οἱ δέ εἰσιν ἀριθμὸν οἱ ἵπποι τέσσαρες. μετὰ δὲ αὐτόν εἰσιν ἄνδρες δύο· ὀνόματα μέν σφισιν οὐκ ἔστι, θεραπεύειν δὲ ἄρα τοὺς ἵππους καὶ τούτοις προσετέτακτο ὑπὸ τοῦ Οἰνομάου.", "st": "5.10"}, {"sp": "N", "t": "πρὸς αὐτῷ δὲ κατάκειται τῷ πέρατι Κλάδεος· ἔχει δὲ καὶ ἐς τὰ ἄλλα παρ’ Ἠλείων τιμὰς ποταμῶν μάλιστα μετά γε Ἀλφειόν. τὰ δὲ ἐς ἀριστερὰ ἀπὸ τοῦ Διὸς ὁ Πέλοψ καὶ Ἱπποδάμεια καὶ ὅ τε ἡνίοχός ἐστι τοῦ Πέλοπος καὶ ἵπποι δύο τε ἄνδρες, ἱπποκόμοι δὴ καὶ οὗτοι τῷ Πέλοπι. καὶ αὖθις ὁ ἀετὸς κάτεισιν ἐς στενόν, καὶ κατὰ τοῦτο Ἀλφειὸς ἐπ’ αὐτοῦ πεποίηται. τῷ δὲ ἀνδρὶ ὃς ἡνιοχεῖ τῷ Πέλοπι λόγῳ μὲν τῷ Τροιζηνίων ἐστὶν ὄνομα Σφαῖρος, ὁ δὲ ἐξηγητὴς ἔφασκεν ὁ ἐν Ὀλυμπίᾳ Κίλλαν εἶναι.", "st": "5.10"}, {"sp": "N", "t": "τὰ μὲν δὴ ἔμπροσθεν ⟨ἐν⟩ τοῖς ἀετοῖς ἐστι Παιωνίου, γένος ἐκ Μένδης τῆς Θρᾳκίας, τὰ δὲ ὄπισθεν αὐτῶν Ἀλκαμένους, ἀνδρὸς ἡλικίαν τε κατὰ Φειδίαν καὶ δευτερεῖα ἐνεγκαμένου σοφίας ἐς ποίησιν ἀγαλμάτων. τὰ δὲ ἐν τοῖς ἀετοῖς ἐστιν αὐτῷ Λαπιθῶν ἐν τῷ Πειρίθου γάμῳ πρὸς Κενταύρους ἡ μάχη. κατὰ μὲν δὴ τοῦ ἀετοῦ τὸ μέσον Πειρίθους ἐστίν· παρὰ δὲ αὐτὸν τῇ μὲν Εὐρυτίων ἡρπακὼς τὴν γυναῖκά ἐστι τοῦ Πειρίθου καὶ ἀμύνων Καινεὺς τῷ Πειρίθῳ, τῇ δὲ Θησεὺς ἀμυνόμενος πελέκει τοὺς Κενταύρους· Κένταυρος δὲ ὁ μὲν παρθένον, ὁ δὲ παῖδα ἡρπακώς ἐστιν ὡραῖον. ἐποίησε δὲ ἐμοὶ δοκεῖν ταῦτα ὁ Ἀλκαμένης, Πειρίθουν τε εἶναι Διὸς ἐν ἔπεσι τοῖς Ὁμήρου δεδιδαγμένος καὶ Θησέα ἐπιστάμενος ὡς εἴη τέταρτος ⟨ἀπὸ⟩ Πέλοπος.", "st": "5.10"}, {"sp": "N", "t": "ἔστι δὲ ἐν Ὀλυμπίᾳ καὶ Ἡρακλέους τὰ πολλὰ τῶν ἔργων. ὑπὲρ μὲν τοῦ ναοῦ πεποίηται τῶν θυρῶν ἡ ἐξ Ἀρκαδίας ἄγρα τοῦ ὑὸς καὶ τὰ πρὸς Διομήδην τὸν Θρᾷκα καὶ ἐν Ἐρυθείᾳ πρὸς Γηρυόνην, καὶ Ἄτλαντός τε τὸ φόρημα ἐκδέχεσθαι μέλλων καὶ τῆς κόπρου καθαίρων τὴν γῆν ἐστιν Ἠλείοις· ὑπὲρ δὲ τοῦ ὀπισθοδόμου τῶν θυρῶν [ὁ] τοῦ ζωστῆρος τὴν Ἀμαζόνα ἐστὶν ἀφαιρούμενος καὶ τὰ ἐς τὴν ἔλαφον καὶ τὸν ἐν Κνωσσῷ ταῦρον καὶ ὄρνιθας τὰς ἐπὶ Στυμφήλῳ καὶ ἐς ὕδραν τε καὶ τὸν ἐν τῇ γῇ τῇ Ἀργείᾳ λέοντα.", "st": "5.10"}, {"sp": "N", "t": "τὰς θύρας δὲ ἐσιόντι τὰς χαλκᾶς, ἔστιν ἐν δεξιᾷ πρὸ τοῦ κίονος Ἴφιτος ὑπὸ γυναικὸς στεφανούμενος Ἐκεχειρίας, ὡς τὸ ἐλεγεῖον τὸ ἐπ’ αὐτοῖς φησιν. ἑστήκασι δὲ καὶ ἐντὸς τοῦ ναοῦ κίονες, καὶ στοαί τε ἔνδον ὑπερῷοι καὶ πρόσοδος δι’ αὐτῶν ἐπὶ τὸ ἄγαλμά ἐστι. πεποίηται δὲ καὶ ἄνοδος ἐπὶ τὸν ὄροφον σκολιά.", "st": "5.10"}, {"sp": "N", "t": "καθέζεται μὲν δὴ ὁ θεὸς ἐν θρόνῳ χρυσοῦ πεποιημένος καὶ ἐλέφαντος· στέφανος δὲ ἐπίκειταί οἱ τῇ κεφαλῇ μεμιμημένος ἐλαίας κλῶνας. ἐν μὲν δὴ τῇ δεξιᾷ φέρει Νίκην ἐξ ἐλέφαντος καὶ ταύτην καὶ χρυσοῦ, ταινίαν τε ἔχουσαν καὶ ἐπὶ τῇ κεφαλῇ στέφανον· τῇ δὲ ἀριστερᾷ τοῦ θεοῦ χειρὶ ἔνεστι σκῆπτρον μετάλλοις τοῖς πᾶσιν ἠνθισμένον, ὁ δὲ ὄρνις ὁ ἐπὶ τῷ σκήπτρῳ καθήμενός ἐστιν ὁ ἀετός. χρυσοῦ δὲ καὶ τὰ ὑποδήματα τῷ θεῷ καὶ ἱμάτιον ὡσαύτως ἐστί· τῷ δὲ ἱματίῳ ζῴδιά τε καὶ τῶν ἀνθῶν τὰ κρίνα ἐστὶν ἐμπεποιημένα.", "st": "5.11"}, {"sp": "N", "t": "ὁ δὲ θρόνος ποικίλος μὲν χρυσῷ καὶ λίθοις, ποικίλος δὲ καὶ ἐβένῳ τε καὶ ἐλέφαντί ἐστι· καὶ ζῷά τε ἐπ’ αὐτοῦ γραφῇ μεμιμημένα καὶ ἀγάλματά ἐστιν εἰργασμένα. Νῖκαι μὲν δὴ τέσσαρες χορευουσῶν παρεχόμεναι σχῆμα κατὰ ἕκαστον τοῦ θρόνου τὸν πόδα, δύο δέ εἰσιν ἄλλαι πρὸς ἑκάστου πέζῃ ποδός. τῶν ποδῶν δὲ ἑκατέρῳ τῶν ἔμπροσθεν παῖδές τε ἐπίκεινται Θηβαίων ὑπὸ σφιγγῶν ἡρπασμένοι καὶ ὑπὸ τὰς σφίγγας Νιόβης τοὺς παῖδας Ἀπόλλων κατατοξεύουσι καὶ Ἄρτεμις.", "st": "5.11"}, {"sp": "N", "t": "τῶν δὲ [ἐκ] τοῦ θρόνου μεταξὺ ποδῶν τέσσαρες κανόνες εἰσίν, ⟨ἐκ⟩ ποδὸς ἐς πόδα ἕτερον διήκων ἕκαστος. τῷ μὲν δὴ κατ’ εὐθὺ τῆς ἐσόδου κανόνι, ἑπτά ἐστιν ἀγάλματα ἐπ’ αὐτῷ, τὸ γὰρ ὄγδοον ἐξ αὐτῶν οὐκ ἴσασι τρόπον ὅντινα ἐγένετο ἀφανές· εἴη δ’ ἂν ἀγωνισμάτων ἀρχαίων ταῦτα μιμήματα, οὐ γάρ πω τὰ ἐς τοὺς παῖδας ἐπὶ ἡλικίας ἤδη καθειστήκει τῆς Φειδίου. τὸν δὲ αὑτὸν ταινίᾳ τὴν κεφαλὴν ἀναδούμενον ἐοικέναι τὸ εἶδος Παντάρκει λέγουσι, μειράκιον δὲ Ἠλεῖον τὸν Παντάρκη παιδικὰ εἶναι τοῦ Φειδίου· ἀνείλετο δὲ καὶ ἐν παισὶν ὁ Παντάρκης πάλης νίκην Ὀλυμπιάδι ἕκτῃ πρὸς ταῖς ὀγδοήκοντα.", "st": "5.11"}, {"sp": "N", "t": "ἐπὶ δὲ τῶν κανόνων τοῖς λοιποῖς ὁ λόχος ἐστὶν ὁ σὺν Ἡρακλεῖ μαχόμενος πρὸς Ἀμαζόνας· ἀριθμὸς μὲν δὴ συναμφοτέρων ἐς ἐννέα ἐστὶ καὶ εἴκοσι, τέτακται δὲ καὶ Θησεὺς ἐν τοῖς συμμάχοις τῷ Ἡρακλεῖ. ἀνέχουσι δὲ οὐχ οἱ πόδες μόνοι τὸν θρόνον, ἀλλὰ καὶ κίονες ἴσοι τοῖς ποσὶ μεταξὺ ἑστηκότες τῶν ποδῶν. ὑπελθεῖν δὲ οὐχ οἷόν τέ ἐστιν ὑπὸ τὸν θρόνον, ὥσπερ γε καὶ ἐν Ἀμύκλαις ἐς τὰ ἐντὸς τοῦ θρόνου παρερχόμεθα· ἐν Ὀλυμπίᾳ δὲ ἐρύματα τρόπον τοίχων πεποιημένα τὰ [δὲ] ἀπείργοντά ἐστι.", "st": "5.11"}, {"sp": "N", "t": "τούτων τῶν ἐρυμάτων ὅσον μὲν ἀπαντικρὺ τῶν θυρῶν ἐστιν, ἀλήλιπται κυανῷ μόνον, τὰ δὲ λοιπὰ αὐτῶν παρέχεται Παναίνου γραφάς. ἐν δὲ αὐταῖς ἔστι μὲν οὐρανὸν καὶ γῆν Ἄτλας ἀνέχων, παρέστηκε δὲ καὶ Ἡρακλῆς ἐκδέξασθαι τὸ ἄχθος ἐθέλων τοῦ Ἄτλαντος, ἔτι δὲ Θησεύς τε καὶ Πειρίθους καὶ Ἑλλάς τε καὶ Σαλαμὶς ἔχουσα ἐν τῇ χειρὶ τὸν ἐπὶ ταῖς ναυσὶν ἄκραις ποιούμενον κόσμον, Ἡρακλέους τε τῶν ἀγωνισμάτων τὸ ἐς τὸν λέοντα τὸν ἐν Νεμέᾳ καὶ τὸ ἐς Κασσάνδραν παρανόμημα Αἴαντος,", "st": "5.11"}, {"sp": "N", "t": "Ἱπποδάμειά τε ἡ Οἰνομάου σὺν τῇ μητρὶ καὶ Προμηθεὺς ἔτι ἐχόμενος μὲν ὑπὸ τῶν δεσμῶν, Ἡρακλῆς δὲ ἐς αὐτὸν ἦρται· λέγεται γὰρ δὴ καὶ τόδε ἐς τὸν Ἡρακλέα, ὡς ἀποκτείναι μὲν τὸν ἀετὸν ὃς ἐν τῷ Καυκάσῳ τὸν Προμηθέα ἐλύπει, ἐξέλοιτο δὲ καὶ αὐτὸν Προμηθέα ἐκ τῶν δεσμῶν. τελευταῖα δὲ ἐν τῇ γραφῇ Πενθεσίλειά τε ἀφιεῖσα τὴν ψυχὴν καὶ Ἀχιλλεὺς ἀνέχων ἐστὶν αὐτήν· καὶ Ἑσπερίδες δύο φέρουσι τὰ μῆλα ὧν ἐπιτετράφθαι λέγονται τὴν φρουράν. Πάναινος μὲν δὴ οὗτος ἀδελφός τε ἦν Φειδίου καὶ αὐτοῦ καὶ Ἀθήνῃσιν ἐν Ποικίλῃ τὸ Μαραθῶνι ἔργον ἐστὶ γεγραμμένον.", "st": "5.11"}, {"sp": "N", "t": "ἐπὶ δὲ τοῖς ἀνωτάτω τοῦ θρόνου πεποίηκεν ὁ Φειδίας ὑπὲρ τὴν κεφαλὴν τοῦ ἀγάλματος τοῦτο μὲν Χάριτας, τοῦτο δὲ Ὥρας, τρεῖς ἑκατέρας. εἶναι γὰρ θυγατέρας Διὸς καὶ ταύτας ἐν ἔπεσίν ἐστιν εἰρημένα· Ὅμηρος δὲ ἐν Ἰλιάδι ἐποίησε τὰς Ὥρας καὶ ἐπιτετράφθαι τὸν οὐρανὸν καθάπερ τινὰς φύλακας βασιλέως αὐλῆς. τὸ ὑπόθημα δὲ τὸ ὑπὸ τοῦ Διὸς τοῖς ποσίν, ὑπὸ τῶν ἐν τῇ Ἀττικῇ καλούμενον θρανίον, λέοντάς τε χρυσοῦς καὶ Θησέως ἐπειργασμένην ἔχει μάχην τὴν πρὸς Ἀμαζόνας, τὸ Ἀθηναίων πρῶτον ἀνδραγάθημα ἐς οὐχ ὁμοφύλους.", "st": "5.11"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ βάθρου ⟨τοῦ⟩ τὸν θρόνον τε ἀνέχοντος καὶ ὅσος ἄλλος κόσμος περὶ τὸν Δία, ἐπὶ τούτου τοῦ βάθρου χρυσᾶ ποιήματα, ἀναβεβηκὼς ἐπὶ ἅρμα Ἤλιος καὶ Ζεύς τέ ἐστι καὶ Ἥρα, ⟨ἔτι δὲ Ἥφαιστος,⟩ παρὰ δὲ αὐτὸν Χάρις· ταύτης δὲ Ἑρμῆς ἔχεται, τοῦ Ἑρμοῦ δὲ Ἑστία· μετὰ δὲ τὴν Ἑστίαν Ἔρως ἐστὶν ἐκ θαλάσσης Ἀφροδίτην ἀνιοῦσαν ὑποδεχόμενος, τὴν δὲ Ἀφροδίτην στεφανοῖ Πειθώ· ἐπείργασται δὲ καὶ Ἀπόλλων σὺν Ἀρτέμιδι Ἀθηνᾶ τε καὶ Ἡρακλῆς, καὶ ἤδη τοῦ βάθρου πρὸς τῷ πέρατι Ἀμφιτρίτη καὶ Ποσειδῶν Σελήνη τε ἵππον ἐμοὶ δοκεῖν ἐλαύνουσα. τοῖς δέ ἐστιν εἰρημένα ἐφ’ ἡμιόνου τὴν θεὸν ὀχεῖσθαι καὶ οὐχ ἵππου, καὶ λόγον γέ τινα ἐπὶ τῷ ἡμιόνῳ λέγουσιν εὐήθη.", "st": "5.11"}, {"sp": "N", "t": "μέτρα δὲ τοῦ ἐν Ὀλυμπίᾳ Διὸς ἐς ὕψος τε καὶ εὖρος ἐπιστάμενος γεγραμμένα οὐκ ἐν ἐπαίνῳ θήσομαι τοὺς μετρήσαντας, ἐπεὶ καὶ τὰ εἰρημένα αὐτοῖς μέτρα πολύ τι ἀποδέοντά ἐστιν ἢ τοῖς ἰδοῦσι παρέστηκεν ἐς τὸ ἄγαλμα δόξα, ὅπου γε καὶ αὐτὸν τὸν θεὸν μάρτυρα ἐς τοῦ Φειδίου τὴν τέχνην γενέσθαι λέγουσιν. ὡς γὰρ δὴ ἐκτετελεσμένον ἤδη τὸ ἄγαλμα ἦν, ηὔξατο ὁ Φειδίας ἐπισημῆναι τὸν θεὸν εἰ τὸ ἔργον ἐστὶν αὐτῷ κατὰ γνώμην· αὐτίκα δ’ ἐς τοῦτο τοῦ ἐδάφους κατασκῆψαι κεραυνόν φασιν, ἔνθα ὑδρία καὶ ἐς ἐμὲ ἐπίθημα ἦν ἡ χαλκῆ.", "st": "5.11"}, {"sp": "N", "t": "ὅσον δὲ τοῦ ἐδάφους ἐστὶν ἔμπροσθεν τοῦ ἀγάλματος, τοῦτο οὐ λευκῷ, μέλανι δὲ κατεσκεύασται τῷ λίθῳ· περιθεῖ δὲ ἐν κύκλῳ τὸν μέλανα λίθου Παρίου κρηπίς, ἔρυμα εἶναι τῷ ἐλαίῳ τῷ ἐκχεομένῳ. ἔλαιον γὰρ τῷ ἀγάλματί ἐστιν ἐν Ὀλυμπίᾳ συμφέρον, καὶ ἔλαιόν ἐστι τὸ ἀπεῖργον μὴ γίνεσθαι τῷ ἐλέφαντι βλάβος διὰ τὸ ἑλῶδες τῆς Ἄλτεως. ἐν ἀκροπόλει δὲ τῇ Ἀθηναίων τὴν καλουμένην Παρθένον οὐκ ἔλαιον, ὕδωρ δὲ τὸ ἐς τὸν ἐλέφαντα ὠφελοῦν ἐστιν· ἅτε γὰρ αὐχμηρᾶς τῆς ἀκροπόλεως οὔσης διὰ τὸ ἄγαν ὑψηλόν, τὸ ἄγαλμα ἐλέφαντος πεποιημένον ὕδωρ καὶ δρόσον τὴν ἀπὸ τοῦ ὕδατος ποθεῖ.", "st": "5.11"}, {"sp": "N", "t": "ἐν Ἐπιδαύρῳ δὲ ἐρομένου μου καθ’ ἥντινα αἰτίαν οὔτε ὕδωρ τῷ Ἀσκληπιῷ σφισιν οὔτε ἔλαιόν ἐστιν ἐγχεόμενον, ἐδίδασκόν με οἱ περὶ τὸ ἱερὸν ὡς καὶ τὸ ἄγαλμα τοῦ θεοῦ καὶ ὁ θρόνος ἐπὶ φρέατι εἴη πεποιημένα.", "st": "5.11"}, {"sp": "N", "t": "ὅσοι δὲ ἀνθρώπων τὰ διὰ τοῦ στόματος ἐς τὸ ἐκτὸς ἐλέφασιν ἐξίσχοντα ὀδόντας τῶν θηρίων εἶναι καὶ οὐ κέρατα ἥγηνται, τούτοις ἔστιν ἀπιδεῖν μὲν ἐς τὰς ἄλκας, τὸ ἐν Κελτικῇ θηρίον, ἀπιδεῖν δὲ ἐς τοὺς Αἰθιοπικοὺς ταύρους· ἄλκαι μὲν γὰρ κέρατα ἐπὶ ταῖς ὀφρύσιν ἔχουσιν οἱ ἄρρενες, τὸ δὲ θῆλυ οὐ φύει τὸ παράπαν· οἱ δὲ Αἰθιοπικοὶ ταῦροι τὰ κέρατα φύουσιν ἐπὶ τῇ ῥινί. τίς ἂν οὖν ποιήσαιτο ἔτι ἐν μεγάλῳ θαύματι διὰ στόματος ζῴῳ κέρατα ἐκφῦναι;", "st": "5.12"}, {"sp": "N", "t": "πάρεστι δὲ ἀναδιδάσκεσθαι καὶ τοῖσδε ἔτι· κέρατα γὰρ κατὰ ἐτῶν περίοδον ἀπογίνεται καὶ αὖθις ἐκβλαστάνει ζῴοις, καὶ τοῦτο ἔλαφοί τε καὶ δορκάδες, ὡσαύτως δὲ καὶ οἱ ἐλέφαντες πεπόνθασιν. ὀδοὺς δὲ οὐκ ἔστιν ὅτῳ δεύτερα παρέσται ζῴῳ τῶν γε ἤδη τελείων· εἰ δὲ ὀδόντες τὰ διὰ στόματος ἐξίσχοντα καὶ μὴ κέρατα ἦσαν, πῶς ἂν καὶ ἀνεφύοντο αὖθις; οὐ μὴν οὐδὲ εἴκειν πυρὶ ἔχουσιν ὀδόντες φύσιν· κέρατα δὲ καὶ βοῶν καὶ ἐλεφάντων ἐς ὁμαλές τε ἐκ περιφεροῦς καὶ ἐς ἄλλα ὑπὸ πυρὸς ἄγεται σχήματα. ποταμίοις γε μὴν ἵπποις καὶ ὑσὶν ἡ κάτωθεν γένυς τοὺς χαυλιόδοντας φέρει, κέρατα δὲ ἀναφυόμενα ⟨οὐχ⟩ ὁρῶμεν ἐκ γενύων·", "st": "5.12"}, {"sp": "N", "t": "ἐλέφαντι οὖν τὰ κέρατα ἴστω τις διὰ κροτάφων κατερχόμενα ἄνωθεν καὶ οὕτως ἐς τὸ ἐκτὸς ἐπιστρέφοντα. τοῦτο οὐκ ἀκοὴν γράφω, θεασάμενος δὲ ἐλέφαντος ἐν γῇ τῇ Καμπανῶν κρανίον ἐν Ἀρτέμιδος ἱερῷ· σταδίους δὲ ὡς τριάκοντα ἀπέχει μάλιστα Καπύης τὸ ἱερόν, αὕτη δὲ ἡ μητρόπολίς ἐστιν ἡ Καπύη τῶν Καμπανῶν. ὁ μὲν δὴ ἐλέφας παρὰ τὰ λοιπὰ ζῷα διάφορον καὶ τὴν ἔκφυσιν παρέχεται τῶν κεράτων, ὥσπερ γε καὶ τὸ μέγεθός ἐστιν αὐτῷ καὶ εἶδος οὐδὲν ἐοικότα ἑτέρῳ θηρίῳ· φιλότιμοι δὲ ἐς τὰ μάλιστά μοι καὶ ἐς θεῶν τιμὴν οὐ φειδωλοὶ χρημάτων γενέσθαι δοκοῦσιν οἱ Ἕλληνες, οἷς γε παρὰ Ἰνδῶν ἤγετο καὶ ἐξ Αἰθιοπίας ἐλέφας ἐς ποίησιν ἀγαλμάτων.", "st": "5.12"}, {"sp": "N", "t": "ἐν δὲ Ὀλυμπίᾳ παραπέτασμα ἐρεοῦν κεκοσμημένον ὑφάσμασιν Ἀσσυρίοις καὶ βαφῇ πορφύρας τῆς Φοινίκων ἀνέθηκεν Ἀντίοχος, οὗ δὴ καὶ ὑπὲρ τοῦ θεάτρου τοῦ Ἀθήνῃσιν ἡ αἰγὶς ἡ χρυσῆ καὶ ἐπ’ αὐτῆς ἡ Γοργώ ἐστιν ἀναθήματα. τοῦτο οὐκ ἐς τὸ ἄνω τὸ παραπέτασμα πρὸς τὸν ὄροφον ὥσπερ γε ἐν Ἀρτέμιδος τῆς Ἐφεσίας ἀνέλκουσι, καλῳδίοις δὲ ἐπιχαλῶντες καθιᾶσιν ἐς τὸ ἔδαφος.", "st": "5.12"}, {"sp": "N", "t": "ἀναθήματα δὲ ὁπόσα ἔνδον ἢ ἐν τῷ προνάῳ κεῖται, θρόνος ἐστὶν Ἀριμνήστου βασιλεύσαντος ἐν Τυρσηνοῖς, ὃς πρῶτος βαρβάρων ἀναθήματι τὸν ἐν Ὀλυμπίᾳ Δία ἐδωρήσατο, καὶ ἵπποι Κυνίσκας χαλκοῖ, σημεῖα Ὀλυμπικῆς νίκης· οὗτοι μέγεθος μὲν ἀποδέουσιν ἵππων, ἑστήκασι δὲ ἐν τῷ προνάῳ τοῖς ἐσιοῦσιν ἐν δεξιᾷ. κεῖται δὲ καὶ τρίπους ἐπίχαλκος, ἐφ’ οὗ πρὶν ἢ τὴν τράπεζαν ποιηθῆναι προετίθεντο τοῖς νικῶσιν οἱ στέφανοι.", "st": "5.12"}, {"sp": "N", "t": "βασιλέων δὲ ἀνδριάντας, Ἀδριανοῦ μὲν αἱ ἐς τὸ Ἀχαϊκὸν τελοῦσαι πόλεις ἀνέθεσαν Παρίου λίθου, Τραϊανοῦ δὲ οἱ πάντες Ἕλληνες. οὗτος προσεκτήσατο ὁ βασιλεὺς Γέτας τοὺς ὑπὲρ Θρᾴκης Ὀσρόῃ τε τῷ ἀπογόνῳ τῷ Ἀρσάκου καὶ Πάρθοις ἐπολέμησεν· ὁπόσα δὲ ἐς ἔργων ἔχει οἱ κατασκευήν, ἀξιολογώτατά ἐστι λουτρὰ ἐπώνυμα αὐτοῦ καὶ θέατρον μέγα κυκλοτερὲς πανταχόθεν καὶ οἰκοδόμημα ἐς ἵππων δρόμους προῆκον καὶ ἐς δύο σταδίων μῆκος, καὶ ἡ Ῥωμαίων ἀγορὰ κόσμου τε ἕνεκα τοῦ λοιποῦ θέας ἀξία καὶ μάλιστα ἐς τὸν ὄροφον χαλκοῦ πεποιημένον.", "st": "5.12"}, {"sp": "N", "t": "αἱ δὲ εἰκόνες αἱ τοῖς κατασκευάσμασι τοῖς περιφερέσιν ἐγκείμεναι, ἡ μὲν τοῦ ἠλέκτρου βασιλέως Ῥωμαίων ἐστὶν Αὐγούστου, ἡ δὲ τοῦ ἐλέφαντος βασιλέως Νικομήδους ἐλέγετο εἶναι Βιθυνῶν. ἀπὸ τούτου δὲ καὶ τῇ μεγίστῃ τῶν ἐν Βιθυνίᾳ πόλεων μετεβλήθη τὸ ὄνομα, Ἀστακῷ τὰ πρὸ τούτου καλουμένῃ· τὰ δὲ ἐξ ἀρχῆς αὐτῇ Ζυποίτης ἐγένετο οἰκιστής, Θρᾷξ γένος εἰκάζοντί γε ἀπὸ τοῦ ὀνόματος. τὸ δὲ ἤλεκτρον τοῦτο οὗ τῷ Αὐγούστῳ πεποίηνται τὴν εἰκόνα, ὅσον μὲν αὐτόματον ἐν τοῦ Ἠριδανοῦ ταῖς ψάμμοις εὑρίσκεται, σπανίζεται τὰ μάλιστα καὶ ἀνθρώπῳ τίμιον πολλῶν ἐστιν ἕνεκα· τὸ δὲ ἄλλο ἤλεκτρον ἀναμεμιγμένος ἐστὶν ἀργύρῳ χρυσός.", "st": "5.12"}, {"sp": "N", "t": "ἐν δὲ τῷ ἐν Ὀλυμπίᾳ ναῷ Νέρωνος ἀναθήματα τρεῖς μὲν ἐς κοτίνου φύλλα στέφανοι, τέταρτος δὲ ἐς δρυός ἐστι μεμιμημένος· κεῖνται δὲ αὐτόθι καὶ ἀσπίδες χαλκαῖ πέντε καὶ εἴκοσι, τοῖς ὁπλιτεύουσιν εἶναι φορήματα ἐς τὸν δρόμον. στῆλαι δὲ ἄλλαι τε ἑστήκασι καὶ ἡ πρὸς Ἀθηναίους καὶ Ἀργείους τε καὶ Μαντινέας ἔχουσα ὅρκον παρὰ Ἠλείων ἐς συμμαχίαν ἐτῶν ἑκατόν.", "st": "5.12"}, {"sp": "N", "t": "ἔστι δὲ ἐντὸς τῆς Ἄλτεως καὶ Πέλοπι ἀποτετμημένον τέμενος· ἡρώων δὲ τῶν ἐν Ὀλυμπίᾳ τοσοῦτον προτετιμημένος ἐστὶν ὁ Πέλοψ ὑπὸ Ἠλείων ὅσον Ζεὺς θεῶν τῶν ἄλλων. ἔστιν οὖν τοῦ ναοῦ τοῦ Διὸς κατὰ δεξιὰν τῆς ἐσόδου πρὸς ἄνεμον Βορέαν τὸ Πελόπιον, ἀφεστηκὸς μὲν τοῦ ναοῦ τοσοῦτον ὡς μεταξὺ καὶ ἀνδριάντας καὶ ἀναθήματα ἄλλα ἀνακεῖσθαι, παρήκει δὲ ὡς ἐπὶ τὸν ὀπισθόδομον ἀπὸ μέσου μάλιστα ἀρξάμενον τοῦ ναοῦ· καὶ λίθων τε θριγκῷ περιέχεται καὶ δένδρα ἐντὸς πεφυκότα καὶ ἀνδριάντες εἰσὶν ἀνακείμενοι,", "st": "5.13"}, {"sp": "N", "t": "ἔσοδος δὲ ἐς αὐτὸ πρὸς δυσμῶν ἐστιν ἡλίου. τοῦτο ἀπονεῖμαι τῷ Πέλοπι Ἡρακλῆς ὁ Ἀμφιτρύωνος λέγεται· τέταρτος γὰρ δὴ ἀπόγονος καὶ οὗτος ἦν Πέλοπος, λέγεται δὲ καὶ ὡς ἔθυσεν ἐς τὸν βόθρον τῷ Πέλοπι. θύουσι δὲ αὐτῷ καὶ νῦν ἔτι οἱ κατὰ ἔτος τὰς ἀρχὰς ἔχοντες· τὸ δὲ ἱερεῖόν ἐστι κριὸς μέλας. ἀπὸ ταύτης οὐ γίνεται τῷ μάντει μοῖρα τῆς θυσίας, τράχηλον δὲ μόνον δίδοσθαι τοῦ κριοῦ καθέστηκε τῷ ὀνομαζομένῳ ξυλεῖ.", "st": "5.13"}, {"sp": "N", "t": "ἔστι δὲ ὁ ξυλεὺς ἐκ τῶν οἰκετῶν τοῦ Διός, ἔργον δὲ αὐτῷ πρόσκειται τὰ ἐς τὰς θυσίας ξύλα τεταγμένου λήμματος καὶ πόλεσι παρέχειν καὶ ἀνδρὶ ἰδιώτῃ· τὰ δὲ λεύκης μόνης ξύλα καὶ ἄλλου δένδρου ἐστὶν οὐδενός· ὃς δ’ ἂν ἢ αὐτῶν Ἠλείων ἢ ξένων τοῦ θυομένου τῷ Πέλοπι ἱερείου φάγῃ τῶν κρεῶν, οὐκ ἔστιν οἱ ἐσελθεῖν παρὰ τὸν Δία. τὸ δὲ αὐτὸ καὶ ἐν τῇ Περγάμῳ τῇ ὑπὲρ ποταμοῦ Καΐκου πεπόνθασιν οἱ τῷ Τηλέφῳ θύοντες· ἔστι γὰρ δὴ οὐδὲ τούτοις ἀναβῆναι πρὸ λουτροῦ παρὰ τὸν Ἀσκληπιόν.", "st": "5.13"}, {"sp": "N", "t": "λέγεται δὲ καὶ τοιοῦτον· μηκυνομένου τοῦ πρὸς Ἰλίῳ πολέμου ⟨τοῖς Ἕλλησιν,⟩ προαγορεῦσαι [δὲ] αὐτοῖς τοὺς μάντεις ὡς αἱρήσουσιν οὐ πρότερον τὴν πόλιν, πρὶν ἂν τὰ Ἡρακλέους τόξα καὶ ὀστοῦν ἐπαγάγωνται Πέλοπος. οὕτω δὴ μεταπέμψασθαι μὲν Φιλοκτήτην φασὶν αὐτοὺς ἐς τὸ στρατόπεδον, ἀχθῆναι δὲ καὶ τῶν ὀστῶν ὠμοπλάτην σφίσιν ἐκ Πίσης τῶν Πέλοπος· ὡς δὲ οἴκαδε ἐκομίζοντο, ἀπόλλυται περὶ Εὔβοιαν καὶ ἡ ναῦς ὑπὸ τοῦ χειμῶνος ἡ τὸ ὀστοῦν φέρουσα τὸ Πέλοπος.", "st": "5.13"}, {"sp": "N", "t": "ἔτεσι δὲ ὕστερον πολλοῖς μετὰ ἅλωσιν Ἰλίου Δαμάρμενον ἁλιέα ἐξ Ἐρετρίας ἀφέντα δίκτυον ἐς θάλασσαν τὸ ὀστοῦν ἑλκύσαι, θαυμάσαντα δὲ αὐτοῦ τὸ μέγεθος ἔχειν ἀποκρύψαντα ὑπὸ τὴν ψάμμον. τέλος δὲ αὐτὸν ἀφικέσθαι καὶ ἐς Δελφούς, ὅτου τε ἀνδρὸς τὸ ὀστοῦν εἴη καὶ ὅ τι χρηστέον αὐτῷ διδαχθῆναι δεησόμενον.", "st": "5.13"}, {"sp": "N", "t": "καί πως κατὰ πρόνοιαν τοῦ θεοῦ τηνικαῦτα ⟨πρεσβεία⟩ παρῆν Ἠλείων ἐπανόρθωμα αἰτούντων νόσου λοιμώδους· ἀνεῖπεν οὖν σφισιν ἡ Πυθία, τοῖς μὲν ἀνασώσασθαι Πέλοπος τὰ ὀστᾶ, Δαμαρμένῳ δὲ ἀποδοῦναι τὰ εὑρημένα αὐτῷ Ἠλείοις. καί οἱ ταῦτα ποιήσαντι ἄλλα τε ἀντέδοσαν Ἠλεῖοι καὶ Δαμάρμενόν τε αὐτὸν καὶ ἀπογόνους τοὺς ἐκείνου φύλακας σφᾶς εἶναι τοῦ ὀστοῦ. ἡ δὲ ὠμοπλάτη τοῦ Πέλοπος ἠφάνιστο ἤδη κατ’ ἐμέ, ὅτι ἐμοὶ δοκεῖν ἐκέκρυπτο ἐπὶ πολὺ κατὰ τοῦ βυθοῦ καὶ ὁμοῦ τῷ χρόνῳ προσέκαμνεν οὐχ ἥκιστα ὑπὸ τῆς θαλάσσης.", "st": "5.13"}, {"sp": "N", "t": "Πέλοπος δὲ καὶ Ταντάλου τῆς παρ’ ἡμῖν ἐνοικήσεως σημεῖα ἔτι καὶ ἐς τόδε λείπεται, Ταντάλου μὲν λίμνη τε ἀπ’ αὐτοῦ καλουμένη καὶ οὐκ ἀφανὴς τάφος, Πέλοπος δὲ ἐν Σιπύλῳ μὲν θρόνος ἐν κορυφῇ τοῦ ὄρους ἐστὶν ὑπὲρ τῆς Πλαστήνης μητρὸς τὸ ἱερόν, διαβάντι δὲ Ἕρμον ποταμὸν Ἀφροδίτης ἄγαλμα ἐν Τήμνῳ πεποιημένον ἐκ μυρσίνης τεθηλυίας· ἀναθεῖναι δὲ Πέλοπα αὐτὸ παρειλήφαμεν μνήμῃ, προϊλασκόμενόν τε τὴν θεὸν καὶ γενέσθαι οἱ τὸν γάμον τῆς Ἱπποδαμείας αἰτούμενον.", "st": "5.13"}, {"sp": "N", "t": "ἔστι δὲ ὁ τοῦ Διὸς τοῦ Ὀλυμπίου βωμὸς ἴσον μὲν μάλιστα τοῦ Πελοπίου τε καὶ τοῦ ἱεροῦ τῆς Ἥρας ἀπέχων, προκείμενος μέντοι καὶ πρὸ ἀμφοτέρων· κατασκευασθῆναι δὲ αὐτὸν οἱ μὲν ὑπὸ Ἡρακλέους τοῦ Ἰδαίου λέγουσιν, οἱ δὲ ὑπὸ ἡρώων τῶν ἐπιχωρίων γενεαῖς δύο ὕστερον τοῦ Ἡρακλέους. πεποίηται δὲ ἱερείων τῶν θυομένων τῷ Διὶ ἀπὸ τῆς τέφρας τῶν μηρῶν, καθάπερ γε καὶ ἐν Περγάμῳ· τέφρας γὰρ δή ἐστι καὶ τῇ Ἥρᾳ τῇ Σαμίᾳ βωμὸς οὐδέν τι ἐπιφανέστερος ἢ ἐν τῇ χώρᾳ τῇ Ἀττικῇ ἃς αὐτοσχεδίας Ἀθηναῖοι καλοῦσιν ἐσχάρας.", "st": "5.13"}, {"sp": "N", "t": "τοῦ βωμοῦ δὲ τοῦ ἐν Ὀλυμπίᾳ κρηπῖδος μὲν τῆς πρώτης, προθύσεως καλουμένης, πόδες πέντε καὶ εἴκοσι καὶ ἑκατόν ἐστι περίοδος, τοῦ δὲ ἐπὶ τῇ προθύσει περίμετρος ἐπακτοῦ πόδες δύο καὶ τριάκοντα· τὸ δὲ ὕψος τοῦ βωμοῦ τὸ σύμπαν ἐς δύο καὶ εἴκοσιν ἀνήκει πόδας. αὐτὰ μὲν δὴ τὰ ἱερεῖα ἐν μέρει τῷ κάτω, τῇ προθύσει, καθέστηκεν αὐτοῖς θύειν· τοὺς μηροὺς δὲ ἀναφέροντες ⟨ἐς⟩ τοῦ βωμοῦ τὸ ὑψηλέστατον καθαγίζουσιν ἐνταῦθα.", "st": "5.13"}, {"sp": "N", "t": "ἀναβασμοὶ δὲ ἐς μὲν τὴν πρόθυσιν ἀνάγουσιν ἐξ ἑκατέρας τῆς πλευρᾶς λίθου πεποιημένοι· τὸ δὲ ἀπὸ τῆς προθύσεως ἐς τὸ ἄνω τοῦ βωμοῦ τέφρας παρέχεται ⟨καὶ⟩ ἀναβασμούς. ἄχρι μὲν δὴ τῆς προθύσεως ἔστιν ἀναβῆναι καὶ παρθένοις καὶ ὡσαύτως γυναιξίν, ἐπειδὰν τῆς Ὀλυμπίας μὴ ἐξείργωνται· ἀπὸ τούτου δὲ ἐς τὸ ἀνωτάτω τοῦ βωμοῦ μόνοις ἔστιν ἀνδράσιν ἀνελθεῖν. θύεται δὲ τῷ Διὶ καὶ ἄνευ τῆς πανηγύρεως ὑπό τε ἰδιωτῶν καὶ ἀνὰ πᾶσαν ἡμέραν ὑπὸ Ἠλείων.", "st": "5.13"}, {"sp": "N", "t": "κατ’ ἔτος δὲ ἕκαστον φυλάξαντες οἱ μάντεις τὴν ἐνάτην ἐπὶ δέκα τοῦ Ἐλαφίου μηνὸς κομίζουσιν ἐκ τοῦ πρυτανείου τὴν τέφραν, φυράσαντες δὲ τῷ ὕδατι τοῦ Ἀλφειοῦ κονιῶσιν οὕτω τὸν βωμόν. ὑπὸ δὲ ἄλλου τὴν τέφραν ὕδατος ποιηθῆναι πηλὸν οὐ μή ποτε ἐγγένηται· καὶ τοῦδε ἕνεκα ὁ Ἀλφειὸς νενόμισται τῷ Ὀλυμπίῳ Διὶ ποταμῶν ⟨δὴ⟩ μάλιστα εἶναι φίλος. ἔστι δὲ καὶ ἐν Διδύμοις τῶν Μιλησίων βωμός, ἐποιήθη δὲ ὑπὸ Ἡρακλέους τοῦ Θηβαίου, καθὰ οἱ Μιλήσιοι λέγουσιν, ἀπὸ τῶν ἱερείων τοῦ αἵματος· ἐς δὲ τὰ ὕστερα τὸ αἷμα τῶν θυμάτων οὐκ ἐς ὑπέρογκον ηὔξηκεν αὐτὸν μέγεθος.", "st": "5.13"}, {"sp": "N", "t": "ὁ δὲ ἐν Ὀλυμπίᾳ βωμὸς παρέχεται καὶ ἄλλο τοιόνδε ἐς θαῦμα· οἱ γὰρ ἰκτῖνες πεφυκότες ἁρπάζειν μάλιστα ὀρνίθων ἀδικοῦσιν οὐδὲν ἐν Ὀλυμπίᾳ τοὺς θύοντας· ἢν δὲ ἁρπάσῃ ποτὲ ἰκτῖνος ἤτοι σπλάγχνα ἢ τῶν κρεῶν, νενόμισται τῷ θύοντι οὐκ αἴσιον εἶναι τὸ σημεῖον. φασὶ δὲ Ἡρακλεῖ τῷ Ἀλκμήνης θύοντι ἐν Ὀλυμπίᾳ δι’ ὄχλου μάλιστα γενέσθαι τὰς μυίας· ἐξευρόντα οὖν αὐτὸν ἢ καὶ ὑπ’ ἄλλου διδαχθέντα Ἀπομυίῳ θῦσαι Διί, καὶ οὕτως ἀποτραπῆναι τὰς μυίας πέραν τοῦ Ἀλφειοῦ. λέγονται δὲ κατὰ ταὐτὰ καὶ Ἠλεῖοι θύειν τῷ Ἀπομυίῳ Διί, ἐξελαύνοντες τῆς [Ἠλείας] Ὀλυμπίας τὰς μυίας.", "st": "5.14"}, {"sp": "N", "t": "τῆς δὲ λεύκης μόνης τοῖς ξύλοις ἐς τοῦ Διὸς τὰς θυσίας καὶ ἀπ’ οὐδενὸς δένδρου τῶν ἄλλων οἱ Ἠλεῖοι χρῆσθαι νομίζουσι, κατ’ ἄλλο μὲν οὐδὲν προτιμῶντες ἐμοὶ δοκεῖν τὴν λεύκην, ὅτι δὲ Ἡρακλῆς ἐκόμισεν αὐτὴν ἐς Ἕλληνας ἐκ τῆς Θεσπρωτίδος χώρας. καί μοι καὶ αὐτὸς ὁ Ἡρακλῆς ἐφαίνετο, ἡνίκα τῷ Διὶ ἔθυεν ἐν Ὀλυμπίᾳ, τῶν ἱερείων τὰ μηρία ἐπὶ λεύκης καῦσαι ξύλων· τὴν δὲ λεύκην ὁ Ἡρακλῆς πεφυκυῖαν παρὰ τὸν Ἀχέροντα εὗρε τὸν ἐν Θεσπρωτίᾳ ποταμόν, καὶ τοῦδε ἕνεκά φασιν αὐτὴν Ἀχερωίδα ὑπὸ Ὁμήρου καλεῖσθαι.", "st": "5.14"}, {"sp": "N", "t": "εἶχον δὲ ἄρα καὶ ἐξ ἀρχῆς οἱ ποταμοὶ καὶ ἐς τόδε ἔχουσιν οὐ κατὰ τὰ αὐτὰ ἐπιτηδείως πρὸς γένεσιν πόας τε καὶ δένδρων· ἀλλὰ πλεῖσται μὲν ὑπὸ Μαιάνδρου μυρῖκαι καὶ μάλιστα αὔξονται, Ἀσωπὸς δὲ ὁ Βοιώτιος βαθυτάτας πέφυκεν ἐκτρέφειν τὰς σχοίνους, τὸ δένδρον δὲ ἡ περσεία μόνου χαίρει τοῦ Νείλου τῷ ὕδατι. οὕτω καὶ τὴν λεύκην θαῦμα οὐδὲν καὶ αἴγειρόν τε καὶ κότινον, τὴν μὲν ἐπὶ Ἀχέροντι ἀναφῦναι πρώτῳ, κότινον δὲ ἐπὶ τῷ Ἀλφειῷ, τὴν δὲ αἴγειρον γῆς τῆς τῶν Κελτῶν καὶ Ἠριδανοῦ τοῦ Κελτικοῦ θρέμμα εἶναι.", "st": "5.14"}, {"sp": "N", "t": "φέρε δή, ἐποιησάμεθα γὰρ βωμοῦ τοῦ μεγίστου μνήμην, ἐπέλθωμεν καὶ τὰ ἐς ἅπαντας ἐν Ὀλυμπίᾳ τοὺς βωμούς· ἐπακολουθήσει δὲ ὁ λόγος μοι τῇ ἐς αὐτοὺς τάξει, καθ’ ἥντινα Ἠλεῖοι θύειν ἐπὶ τῶν βωμῶν νομίζουσι. θύουσι δὲ Ἑστίᾳ μὲν πρώτῃ, δευτέρῳ δὲ τῷ Ὀλυμπίῳ Διὶ ἰόντες ἐπὶ τὸν βωμὸν τὸν ἐντὸς τοῦ ναοῦ, τρίτα δὲ ⟨Λαοίτᾳ Διὶ καὶ Ποσειδῶνι Λαοίτᾳ·⟩ ἐπὶ ἑνὸς βωμοῦ καὶ αὕτη καθέστηκεν ἡ θυσία.", "st": "5.14"}, {"sp": "N", "t": "⟨τέταρτα καὶ⟩ πέμπτα Ἀρτέμιδι θύουσι καὶ Ληίτιδι Ἀθηνᾷ, ἕκτα Ἐργάνῃ· ταύτῃ τῇ Ἐργάνῃ καὶ οἱ ἀπόγονοι Φειδίου, καλούμενοι δὲ φαιδρυνταί, γέρας παρὰ Ἠλείων εἰληφότες τοῦ Διὸς τὸ ἄγαλμα ἀπὸ τῶν προσιζανόντων καθαίρειν, οὗτοι θύουσιν ἐνταῦθα πρὶν ἢ λαμπρύνειν τὸ ἄγαλμα ἄρχονται. ἔστι δὲ Ἀθηνᾶς καὶ ἄλλος βωμὸς πλησίον τοῦ ναοῦ, καὶ Ἀρτέμιδος παρ’ αὐτὸν τετράγωνος ἀνήκων ἠρέμα ἐς ὕψος.", "st": "5.14"}, {"sp": "N", "t": "μετὰ δὲ τοὺς κατειλεγμένους Ἀλφειῷ καὶ Ἀρτέμιδι θύουσιν ἐπὶ ἑνὸς βωμοῦ· τὸ δὲ αἴτιον τούτου παρεδήλωσε μέν που καὶ Πίνδαρος ἐν ᾠδῇ, γράφομεν δὲ καὶ ἡμεῖς ἐν τοῖς λόγοις τοῖς Λετριναίοις. τούτου δὲ οὐ πόρρω καὶ ἄλλος τῷ Ἀλφειῷ βωμὸς πεποίηται, παρὰ δὲ αὐτόν ἐστιν Ἡφαίστου· τοῦ δὲ Ἡφαίστου τὸν βωμόν εἰσιν Ἠλείων οἳ ὀνομάζουσιν Ἀρείου Διός· λέγουσι δὲ οἱ αὐτοὶ οὗτοι καὶ ὡς Οἰνόμαος ἐπὶ τοῦ βωμοῦ τούτου θύοι τῷ Ἀρείῳ Διί, ὁπότε τῶν Ἱπποδαμείας μνηστήρων καθίστασθαι μέλλοι τινὶ ἐς ἵππων ἅμιλλαν.", "st": "5.14"}, {"sp": "N", "t": "μετὰ τοῦτον πεποίηται μὲν Ἡρακλεῖ βωμὸς ἐπίκλησιν Παραστάτῃ, πεποίηται δὲ καὶ τοῦ Ἡρακλέους τοῖς ἀδελφοῖς Ἐπιμήδει καὶ Ἴδᾳ καὶ Παιωναίῳ τε καὶ Ἰάσῳ· τὸν δὲ τοῦ Ἴδα βωμὸν Ἀκεσίδα ὑπὸ ἑτέρων οἶδα καλούμενον. ἔνθα δὲ τῆς οἰκίας τὰ θεμέλιά ἐστι τῆς Οἰνομάου, δύο ἐνταῦθά εἰσι βωμοί, Διός τε Ἑρκείου —τοῦτον ὁ Οἰνόμαος ἐφαίνετο αὐτὸς οἰκοδομήσασθαι —, τῷ δὲ Κεραυνίῳ Διὶ ὕστερον ἐποιήσαντο ἐμοὶ δοκεῖν βωμόν, ὅτ’ ἐς τοῦ Οἰνομάου τὴν οἰκίαν κατέσκηψεν ὁ κεραυνός.", "st": "5.14"}, {"sp": "N", "t": "τὰ δὲ ἐς τὸν μέγαν βωμὸν ὀλίγῳ μέν τι ἡμῖν πρότερόν ἐστιν εἰρημένα, καλεῖται δὲ Ὀλυμπίου Διός· πρὸς αὐτῷ δέ ἐστιν Ἀγνώστων θεῶν βωμὸς καὶ μετὰ τοῦτον Καθαρσίου Διὸς καὶ Νίκης καὶ αὖθις Διὸς ἐπωνυμίαν Χθονίου. εἰσὶ δὲ καὶ θεῶν πάντων βωμοὶ καὶ Ἥρας ἐπίκλησιν Ὀλυμπίας, πεποιημένος τέφρας καὶ οὗτος· Κλυμένου δέ φασιν αὐτὸν ἀνάθημα εἶναι. μετὰ δὲ τοῦτον Ἀπόλλωνος καὶ Ἑρμοῦ βωμός ἐστιν ἐν κοινῷ, διότι Ἑρμῆν λύρας, Ἀπόλλωνα δὲ εὑρέτην εἶναι κιθάρας Ἑλλήνων ἐστὶν ἐς αὐτοὺς λόγος.", "st": "5.14"}, {"sp": "N", "t": "ἐφεξῆς δὲ Ὁμονοίας βωμὸς καὶ αὖθις Ἀθηνᾶς, ὁ δὲ Μητρὸς θεῶν. τῆς ἐσόδου δὲ τῆς ἐς τὸ στάδιόν εἰσιν ἐγγύτατα βωμοὶ δύο· τὸν μὲν αὐτῶν Ἑρμοῦ καλοῦσιν Ἐναγωνίου, τὸν δὲ ἕτερον Καιροῦ. Ἴωνι δὲ οἶδα τῷ Χίῳ καὶ ὕμνον πεποιημένον Καιροῦ· γενεαλογεῖ δὲ ἐν τῷ ὕμνῳ νεώτατον παίδων Διὸς Καιρὸν εἶναι. πλησίον δὲ τοῦ Σικυωνίων θησαυροῦ ἤτοι Κουρήτων ἢ τοῦ Ἀλκμήνης ἐστὶν Ἡρακλέους· λέγεται γὰρ καὶ ἀμφότερα.", "st": "5.14"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ Γαίῳ καλουμένῳ, βωμός ἐστιν ἐπ’ αὐτῷ Γῆς, τέφρας καὶ οὗτος· τὰ δὲ ἔτι ἀρχαιότερα καὶ μαντεῖον τῆς Γῆς αὐτόθι εἶναι λέγουσιν. ἐπὶ δὲ τοῦ ὀνομαζομένου Στομίου Θέμιδι ὁ βωμὸς πεποίηται. τοῦ δὲ Καταιβάτου Διὸς προβέβληται μὲν πανταχόθεν πρὸ τοῦ βωμοῦ φράγμα, ἔστι δὲ πρὸς τῷ βωμῷ τῷ ἀπὸ τῆς τέφρας τῷ μεγάλῳ. μεμνήσθω δέ τις οὐ κατὰ στοῖχον τῆς ἱδρύσεως ἀριθμουμένους τοὺς βωμούς, τῇ δὲ τάξει τῇ Ἠλείων ἐς τὰς θυσίας συμπερινοστοῦντα ἡμῖν τὸν λόγον. πρὸς δὲ τῷ τεμένει τοῦ Πέλοπος Διονύσου μὲν καὶ Χαρίτων ἐν κοινῷ, μεταξὺ δὲ αὐτῶν Μουσῶν καὶ ἐφεξῆς τούτων Νυμφῶν ἐστι βωμός.", "st": "5.14"}, {"sp": "N", "t": "ἔστι δὲ οἴκημα ἐκτὸς τῆς Ἄλτεως, καλεῖται δὲ ἐργαστήριον Φειδίου, καὶ ὁ Φειδίας καθ’ ἕκαστον τοῦ ἀγάλματος ἐνταῦθα εἰργάζετο· ἔστιν οὖν βωμὸς ἐν τῷ οἰκήματι θεοῖς πᾶσιν ἐν κοινῷ. ὀπίσω δὲ ἀναστρέψαντι αὖθις ἐς τὴν Ἄλτιν ἐστὶν ἀπαντικρὺ τοῦ Λεωνιδαίου—", "st": "5.15"}, {"sp": "N", "t": "τὸ δὲ ἐκτὸς μὲν τοῦ περιβόλου τοῦ ἱεροῦ τὸ Λεωνίδαιον, τῶν δὲ ἐσόδων πεποίηται τῶν ἐς τὴν Ἄλτιν κατὰ τὴν πομπικήν, ἣ μόνη τοῖς πομπεύουσίν ἐστιν ὁδός· τοῦτο δὲ ἀνδρὸς μὲν τῶν ἐπιχωρίων ἐστὶν ἀνάθημα Λεωνίδου, κατ’ ἐμὲ δὲ ἐς αὐτὸ Ῥωμαίων ἐσῳκίζοντο οἱ τὴν Ἑλλάδα ἐπιτροπεύοντες· διέστηκε δὲ ἀγυιὰν ἀπὸ τῆς ἐσόδου τῆς πομπικῆς, τοὺς γὰρ δὴ ὑπὸ Ἀθηναίων καλουμένους στενωποὺς ἀγυιὰς ὀνομάζουσιν οἱ Ἠλεῖοι—", "st": "5.15"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ Ἄλτει τοῦ Λεωνιδαίου περᾶν μέλλοντι ἐς ἀριστερὰν Ἀφροδίτης βωμὸς καὶ Ὡρῶν μετ’ αὐτόν. κατὰ δὲ τὸν ὀπισθόδομον μάλιστά ἐστιν ἐν δεξιᾷ πεφυκὼς κότινος· καλεῖται δὲ ἐλαία Καλλιστέφανος, καὶ τοῖς νικῶσι τὰ Ὀλύμπια καθέστηκεν ἀπ’ αὐτῆς δίδοσθαι τοὺς στεφάνους. τούτου πλησίον τοῦ κοτίνου πεποίηται Νύμφαις βωμός·", "st": "5.15"}, {"sp": "N", "t": "Καλλιστεφάνους ὀνομάζουσι καὶ ταύτας. ἔστι δὲ [τοῖς] ἐκτὸς τῆς Ἄλτεως μὲν Ἀρτέμιδος Ἀγοραίας βωμός, ἐν δεξιᾷ δὲ τοῦ Λεωνιδαίου, πεποίηται δὲ καὶ Δεσποίναις —τὰ δὲ ἐς τὴν θεὸν ἥντινα ὀνομάζουσι Δέσποιναν διδάξει μοι τοῦ λόγου τὰ ἐς Ἀρκάδας—, μετὰ δὲ τοῦτον ἔστιν Ἀγοραίου Διὸς βωμός, πρὸ δὲ τῆς καλουμένης Προεδρίας Ἀπόλλωνος ἐπωνυμίαν Πυθίου καὶ μετ’ αὐτὸν Διονύσου· τοῦτον οὔτε πάλαι τὸν βωμὸν καὶ ὑπὸ ἀνδρῶν ἰδιωτῶν ἀνατεθῆναι λέγουσιν.", "st": "5.15"}, {"sp": "N", "t": "ἰόντι δὲ ἐπὶ τὴν ἄφεσιν τῶν ἵππων ἔστι βωμός, ἐπίγραμμα δὲ ἐπ’ αὐτῷ Μοιραγέτα· δῆλα οὖν ἐστιν ἐπίκλησιν εἶναι Διὸς ὃς τὰ ἀνθρώπων οἶδεν, ὅσα διδόασιν αἱ Μοῖραι καὶ ὅσα μὴ πέπρωταί σφισι. πλησίον δὲ καὶ Μοιρῶν βωμός ἐστιν ἐπιμήκης, μετὰ δὲ αὐτὸν Ἑρμοῦ καὶ δύο ἐφεξῆς Διὸς Ὑψίστου· ἐν δὲ τῶν ἵππων τῇ ἀφέσει ἐν μὲν τῷ ὑπαίθρῳ, τῆς ἀφέσεως κατὰ μέσον που μάλιστα, Ποσειδῶνος Ἱππίου καὶ Ἥρας εἰσὶν Ἱππίας βωμοί, πρὸς δὲ τῷ κίονι Διοσκούρων.", "st": "5.15"}, {"sp": "N", "t": "τῆς δὲ πρὸς τὸν Ἔμβολον καλούμενον ἐσόδου τῇ μὲν Ἄρεως Ἱππίου, τῇ δὲ Ἀθηνᾶς Ἱππίας βωμός, ἐς δὲ αὐτὸν τὸν Ἔμβολον ἐσελθόντων Τύχης ἐστὶν ἀγαθῆς βωμὸς καὶ Πανός τε καὶ Ἀφροδίτης, ἐνδοτάτω δὲ τοῦ Ἐμβόλου Νυμφῶν ἃς Ἀκμηνὰς καλοῦσιν. ἀπὸ δὲ τῆς στοᾶς ἣν οἱ Ἠλεῖοι καλοῦσιν Ἀγνάπτου, τὸν ἀρχιτέκτονα ἐπονομάζοντες τῷ οἰκοδομήματι, ἀπὸ ταύτης ἐπανιόντι ἐστὶν ἐν δεξιᾷ βωμὸς Ἀρτέμιδος.", "st": "5.15"}, {"sp": "N", "t": "ἐσελθόντων δὲ αὖθις διὰ τῆς πομπικῆς ἐς τὴν Ἄλτιν, εἰσὶν ὄπισθεν τοῦ Ἡραίου Κλαδέου τε τοῦ ποταμοῦ καὶ Ἀρτέμιδος βωμοί, ὁ δὲ μετ’ αὐτοὺς Ἀπόλλωνος, τέταρτος δὲ Ἀρτέμιδος ἐπίκλησιν Κοκκώκας, καὶ Ἀπόλλωνος πέμπτος Θερμίου. τὸν μὲν δὴ παρὰ Ἠλείοις Θέρμιον καὶ αὐτῷ μοι παρίστατο εἰκάζειν ὡς κατὰ Ἀτθίδα γλῶσσαν εἴη θέσμιος· ἀνθ’ ὅτου δὲ Ἄρτεμιν ἐπονομάζουσι Κοκκώκαν, οὐχ οἷά τε ἦν μοι διδαχθῆναι.", "st": "5.15"}, {"sp": "N", "t": "ἔστι δὲ πρὸ τοῦ καλουμένου Θεηκολεῶνος οἴκημα· τούτου δὲ ἐν γωνίᾳ τοῦ οἰκήματος Πανὸς ἵδρυται βωμός. τὸ πρυτανεῖον δὲ Ἠλείοις ἔστι μὲν τῆς Ἄλτεως ἐντός, πεποίηται δὲ παρὰ τὴν ἔξοδον ἥ ἐστι τοῦ γυμνασίου πέραν· ἐν τούτῳ δὲ οἵ τε δρόμοι τῷ γυμνασίῳ καὶ τοῖς ἀθληταῖς εἰσιν αἱ παλαῖστραι. ⟨τοῦ⟩ πρυτανείου δὲ πρὸ μὲν τῶν θυρῶν βωμός ἐστιν Ἀρτέμιδος Ἀγροτέρας·", "st": "5.15"}, {"sp": "N", "t": "ἐν δὲ αὐτῷ τῷ πρυτανείῳ παριόντων ἐς τὸ οἴκημα, ἔνθα σφίσιν ἡ ἑστία, Πανός ἐστιν ἐν δεξιᾷ τῆς ἐσόδου βωμός. ἔστι δὲ ἡ ἑστία τέφρας καὶ αὕτη πεποιημένη, καὶ ἐπ’ αὐτῆς πῦρ ἀνὰ πᾶσάν τε ἡμέραν καὶ ἐν πάσῃ νυκτὶ ὡσαύτως καίεται· ἀπὸ ταύτης τῆς ἑστίας τὴν τέφραν κατὰ τὰ εἰρημένα ἤδη μοι κομίζουσιν ἐπὶ τὸν τοῦ Ὀλυμπίου βωμόν, καὶ οὐχ ἥκιστα ἐς μέγεθος συντελεῖ τῷ βωμῷ τὸ ἀπὸ τῆς ἑστίας ἐπιφορούμενον.", "st": "5.15"}, {"sp": "N", "t": "ἑκάστου δὲ ἅπαξ τοῦ μηνὸς θύουσιν ἐπὶ πάντων Ἠλεῖοι τῶν κατειλεγμένων βωμῶν. θύουσι δὲ ἀρχαῖόν τινα τρόπον· λιβανωτὸν γὰρ ὁμοῦ πυροῖς μεμαγμένοις μέλιτι θυμιῶσιν ἐπὶ τῶν βωμῶν, τιθέασι δὲ καὶ κλῶνας ἐλαίας ἐπ’ αὐτῶν καὶ οἴνῳ χρῶνται σπονδῇ. μόναις δὲ ταῖς Νύμφαις οὐ νομίζουσιν οἶνον οὐδὲ ταῖς Δεσποίναις σπένδειν οὐδὲ ἐπὶ τῷ βωμῷ τῷ κοινῷ πάντων θεῶν. μέλει δὲ τὰ ἐς θυσίας θεηκόλῳ τε, ὃς ἐπὶ μηνὶ ἑκάστῳ τὴν τιμὴν ἔχει, καὶ μάντεσι καὶ σπονδοφόροις, ἔτι δὲ ἐξηγητῇ τε καὶ αὐλητῇ καὶ τῷ ξυλεῖ·", "st": "5.15"}, {"sp": "N", "t": "ὁπόσα δὲ ἐπὶ ταῖς σπονδαῖς λέγειν σφίσιν ἐν τῷ πρυτανείῳ καθέστηκεν, ἢ καὶ ὕμνους ὁποίους ᾄδουσιν, οὔ με ἦν εἰκὸς ἐπεισαγαγέσθαι καὶ ταῦτα ἐς τὸν λόγον. θεοῖς δὲ οὐ τοῖς Ἑλληνικοῖς μόνον ἀλλὰ καὶ τῷ ἐν Λιβύῃ σπένδουσι καὶ Ἥρᾳ τε Ἀμμωνίᾳ καὶ Παράμμωνι· Ἑρμοῦ δὲ ἐπίκλησίς ἐστιν ὁ Παράμμων. φαίνονται δὲ χρώμενοι ἐκ παλαιοτάτου τῷ ἐν Λιβύῃ μαντείῳ, καὶ ἀναθήματα Ἠλείων ἐν Ἄμμωνός εἰσι βωμοί· γέγραπται δὲ ἐπ’ αὐτῶν ὅσα τε ἐπυνθάνοντο οἱ Ἠλεῖοι καὶ τὰ χρησθέντα ὑπὸ τοῦ θεοῦ καὶ τὰ ὀνόματα τῶν ἀνδρῶν οἳ παρὰ τὸν Ἄμμωνα ἦλθον ἐξ Ἤλιδος. ταῦτα μὲν δή ἐστιν ἐν Ἄμμωνος·", "st": "5.15"}, {"sp": "N", "t": "Ἠλεῖοι δὲ καὶ ἥρωσι καὶ γυναιξὶ σπένδουσιν ἡρώων, ὅσοι τε ἐν τῇ χώρᾳ τῇ Ἠλείᾳ καὶ ὅσοι παρὰ Αἰτωλοῖς τιμὰς ἔχουσιν. ὁπόσα δὲ ᾄδουσιν ἐν τῷ πρυτανείῳ, φωνὴ μέν ἐστιν αὐτῶν ἡ Δώριος, ὅστις δὲ ὁ ποιήσας ἦν τὰ ᾄσματα, οὐ λέγουσιν. ἔστι δὲ καὶ ἑστιατόριον Ἠλείοις· καὶ τοῦτο ἔστι μὲν ἐντὸς τοῦ πρυτανείου, τοῦ οἰκήματος τοῦ τῆς ἑστίας ἀπαντικρύ, τοὺς δὲ τὰ Ὀλύμπια νικῶντας ἑστιῶσιν ἐν τούτῳ τῷ οἰκήματι.", "st": "5.15"}, {"sp": "N", "t": "λείπεται δὲ τὸ μετὰ τοῦτο ἡμῖν τῆς τε Ἥρας ὁ ναὸς καὶ ὁπόσα ἐστὶν ἐν τῷ ναῷ πρέποντα ἐς συγγραφήν. λέγεται δὲ ὑπὸ Ἠλείων ὡς Σκιλλούντιοι τῶν ἐν τῇ Τριφυλίᾳ πόλεών εἰσιν οἱ κατασκευασάμενοι τὸν ναὸν ὀκτὼ μάλιστα ἔτεσιν ὕστερον ἢ τὴν βασιλείαν τὴν ἐν Ἤλιδι ἐκτήσατο Ὄξυλος. ἐργασία μὲν δή ἐστι τοῦ ναοῦ Δώριος, κίονες δὲ περὶ πάντα ἑστήκασιν αὐτόν· ἐν δὲ τῷ ὀπισθοδόμῳ δρυὸς ὁ ἕτερος τῶν κιόνων ἐστί. μῆκος δέ εἰσι τοῦ ναοῦ πόδες ⟨ἐννέα καὶ ἑξήκοντα καὶ ἑκατόν, εὖρος δὲ⟩ τρεῖς καὶ ἑξήκοντα⟨, τὸ δὲ ὕψος τῶν πεντήκοντα⟩ οὐκ ἀποδεῖ· τὸν δὲ ἀρχιτέκτονα ὅστις ἐγένετο οὐ μνημονεύουσι.", "st": "5.16"}, {"sp": "N", "t": "διὰ πέμπτου δὲ ὑφαίνουσιν ἔτους τῇ Ἥρᾳ πέπλον αἱ ἓξ καὶ δέκα γυναῖκες· αἱ δὲ αὐταὶ τιθέασι καὶ ἀγῶνα Ἡραῖα. ὁ δὲ ἀγών ἐστιν ἅμιλλα δρόμου παρθένοις· οὔτι που πᾶσαι ἡλικίας τῆς αὐτῆς, ἀλλὰ πρῶται μὲν αἱ νεώταται, μετὰ ταύτας δὲ αἱ τῇ ἡλικίᾳ δεύτεραι, τελευταῖαι δὲ θέουσιν ὅσαι πρεσβύταται τῶν παρθένων εἰσί.", "st": "5.16"}, {"sp": "N", "t": "θέουσι δὲ οὕτω· καθεῖταί σφισιν ἡ κόμη, χιτὼν ὀλίγον ὑπὲρ γόνατος καθήκει, τὸν ὦμον ἄχρι τοῦ στήθους φαίνουσι τὸν δεξιόν. ἀποδεδειγμένον μὲν δὴ ἐς τὸν ἀγῶνά ἐστι καὶ ταύταις τὸ Ὀλυμπικὸν στάδιον, ἀφαιροῦσι δὲ αὐταῖς ἐς τὸν δρόμον τοῦ σταδίου τὸ ἕκτον μάλιστα· ταῖς δὲ νικώσαις ἐλαίας τε διδόασι στεφάνους καὶ βοὸς μοῖραν τεθυμένης τῇ Ἥρᾳ, καὶ δὴ ἀναθεῖναί σφισιν ἔστι γραψαμέναις εἰκόνας. εἰσὶ δὲ καὶ αἱ διακονούμεναι ταῖς ἑκκαίδεκα κατὰ ταὐτὰ ταῖς ἀγωνοθετούσαις γυναῖκες.", "st": "5.16"}, {"sp": "N", "t": "ἐπανάγουσι δὲ καὶ τῶν παρθένων τὸν ἀγῶνα ἐς τὰ ἀρχαῖα, Ἱπποδάμειαν τῇ Ἤρᾳ τῶν γάμων τῶν Πέλοπος ἐκτίνουσαν χάριν τάς τε ἑκκαίδεκα ἀθροῖσαι γυναῖκας λέγοντες καὶ σὺν αὐταῖς διαθεῖναι πρώτην τὰ Ἡραῖα· μνημονεύουσι δὲ καὶ ὅτι Χλῶρις νικήσειεν Ἀμφίονος θυγάτηρ μόνη λειφθεῖσα τοῦ οἴκου. σὺν δὲ αὐτῇ καὶ ἕνα περιγενέσθαι φασὶ τῶν ἀρσένων· ἃ δὲ ἐς τοὺς Νιόβης παῖδας παρίστατο αὐτῷ μοι γινώσκειν, ἐν τοῖς ἔχουσιν ἐς Ἀργείους ἐδήλωσα.", "st": "5.16"}, {"sp": "N", "t": "ἐς δὲ τὰς ἑκκαίδεκα γυναῖκας καὶ ἄλλον τοιόνδε λέγουσιν ἐπὶ τῷ προτέρῳ λόγον. Δαμοφῶντά φασι τυραννοῦντα ἐν Πίσῃ πολλά τε ἐργάσασθαι καὶ χαλεπὰ Ἠλείους· ὡς δὲ ἐτελεύτησεν ὁ Δαμοφῶν—οὐ γὰρ δὴ οἱ Πισαῖοι συνεχώρουν μετέχειν δημοσίᾳ τοῦ τυράννου τῶν ἁμαρτημάτων, καί πως ἀρεστὰ καὶ Ἠλείοις ἐγένετο καταλύεσθαι τὰ ἐς αὐτοὺς ἐγκλήματα—, οὕτως ἑκκαίδεκα οἰκουμένων τηνικαῦτα ἔτι ἐν τῇ Ἠλείᾳ πόλεων γυναῖκα ἀφ’ ἑκάστης εἵλοντο διαλύειν τὰ διάφορά σφισιν, ἥτις ἡλικίᾳ τε ἦν πρεσβυτάτη καὶ ἀξιώματι καὶ δόξῃ τῶν γυναικῶν προεῖχεν.", "st": "5.16"}, {"sp": "N", "t": "αἱ πόλεις δὲ ἀφ’ ὧν τὰς γυναῖκας εἵλοντο, ἦσαν Ἦλις …. ἀπὸ τούτων μὲν αἱ γυναῖκες οὖσαι τῶν πόλεων Πισαίοις διαλλαγὰς πρὸς Ἠλείους ἐποίησαν· ὕστερον δὲ καὶ τὸν ἀγῶνα ἐπετράπησαν ὑπ’ αὐτῶν θεῖναι τὰ Ἡραῖα καὶ ὑφήνασθαι τῇ Ἥρᾳ τὸν πέπλον. αἱ δὲ ἑκκαίδεκα γυναῖκες καὶ χοροὺς δύο ἱστᾶσι καὶ τὸν μὲν Φυσκόας τῶν χορῶν, τὸν δὲ Ἱπποδαμείας καλοῦσι· τὴν Φυσκόαν δὲ εἶναι ταύτην φασὶν ἐκ τῆς Ἤλιδος τῆς Κοίλης, τῷ δήμῳ δὲ ἔνθα ᾤκησεν ὄνομα [μὲν] Ὀρθίαν εἶναι.", "st": "5.16"}, {"sp": "N", "t": "ταύτῃ τῇ Φυσκόᾳ Διόνυσον συγγενέσθαι λέγουσι, Φυσκόαν δὲ ἐκ Διονύσου τεκεῖν παῖδα Ναρκαῖον· τοῦτον, ὡς ηὐξήθη, πολεμεῖν τοῖς προσοίκοις καὶ δυνάμεως ἐπὶ μέγα ἀρθῆναι, καὶ δὴ καὶ Ἀθηνᾶς ἱερὸν ἐπίκλησιν Ναρκαίας αὐτὸν ἱδρύσασθαι· Διονύσῳ τε τιμὰς λέγουσιν ὑπὸ Ναρκαίου ⟨καὶ⟩ Φυσκόας δοθῆναι πρώτων. Φυσκόας μὲν δὴ γέρα καὶ ἄλλα καὶ χορὸς ἐπώνυμος παρὰ τῶν ἑκκαίδεκα γυναικῶν, φυλάσσουσι δὲ οὐδὲν ἧσσον Ἠλεῖοι καὶ τἄλλα ⟨καταλυθεισῶν⟩ ὅμως τῶν πόλεων· νενεμημένοι γὰρ ἐς ὀκτὼ φυλὰς ἀφ’ ἑκάστης αἱροῦνται γυναῖκας δύο.", "st": "5.16"}, {"sp": "N", "t": "ὁπόσα δὲ ἢ ταῖς ἑκκαίδεκα γυναιξὶν ἢ τοῖς ἑλλανοδικοῦσιν Ἠλείων δρᾶν καθέστηκεν, οὐ πρότερον δρῶσι πρὶν ἢ χοίρῳ τε ἐπιτηδείῳ πρὸς καθαρμὸν καὶ ὕδατι ἀποκαθήρωνται. γίνεται δέ σφισιν ἐπὶ κρήνῃ Πιέρᾳ τὰ καθάρσια· ἐκ δὲ Ὀλυμπίας τὴν πεδιάδα ἐς Ἦλιν ἐρχομένῳ πρὸς τὴν πηγὴν ἀφικέσθαι τὴν Πιέραν ἔστι.", "st": "5.16"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἔχει κατὰ τὰ προειρημένα· τῆς Ἥρας δέ ἐστιν ἐν τῷ ναῷ Διός, τὸ δὲ Ἥρας ἄγαλμα καθήμενόν ἐστιν ἐπὶ θρόνῳ· παρέστηκε δὲ γένειά τε ἔχων καὶ ἐπικείμενος κυνῆν ἐπὶ τῇ κεφαλῇ, ἔργα δέ ἐστιν ἁπλᾶ. τὰς δὲ ἐφεξῆς τούτων καθημένας ἐπὶ θρόνων Ὥρας ἐποίησεν Αἰγινήτης Σμῖλις. παρὰ δὲ αὐτὰς Θέμιδος ἅτε μητρὸς τῶν Ὡρῶν ἄγαλμα ἕστηκε Δορυκλείδου τέχνη, γένος μὲν Λακεδαιμονίου, μαθητοῦ δὲ Διποίνου καὶ Σκύλλιδος.", "st": "5.17"}, {"sp": "N", "t": "τὰς δὲ Ἑσπερίδας πέντε ἀριθμὸν Θεοκλῆς ἐποίησε, Λακεδαιμόνιος μὲν καὶ οὗτος, πατρὸς Ἡγύλου, φοιτῆσαι δὲ καὶ αὐτὸς παρὰ Σκύλλιν καὶ Δίποινον λέγεται. τὴν δὲ Ἀθηνᾶν κράνος ἐπικειμένην καὶ δόρυ καὶ ἀσπίδα ἔχουσαν Λακεδαιμονίου λέγουσιν ἔργον εἶναι Μέδοντος, τοῦτον δὲ ἀδελφόν τε εἶναι Δορυκλείδου καὶ παρὰ ἀνδράσι διδαχθῆναι τοῖς αὐτοῖς.", "st": "5.17"}, {"sp": "N", "t": "Κόρη δὲ καὶ Δημήτηρ καὶ Ἀπόλλων καὶ Ἄρτεμις, αἱ μὲν ἀλλήλων εἰσὶν ἀπαντικρὺ καθήμεναι, Ἀπόλλων δὲ ἐναντίος ἑστώσῃ τῇ Ἀρτέμιδι ἕστηκεν. ἀνάκειται δὲ ἐνταῦθα καὶ Λητὼ Τύχη τε καὶ Διόνυσος καὶ ἔχουσα Νίκη πτερά· τοὺς δὲ εἰργασμένους αὐτὰ οὐκ ἔχω δηλῶσαι, φαίνεται δὲ εἶναί μοι καὶ ταῦτα ἐς τὰ μάλιστα ἀρχαῖα. τὰ μὲν δὴ κατειλεγμένα ἐστὶν ἐλέφαντος καὶ χρυσοῦ, χρόνῳ δὲ ὕστερον καὶ ἄλλα ἀνέθεσαν ἐς τὸ Ἡραῖον· Ἑρμῆν λίθου, Διόνυσον δὲ φέρει νήπιον, τέχνη δέ ἐστι Πραξιτέλους, καὶ Ἀφροδίτη χαλκῆ Κλέωνος ἔργον Σικυωνίου.", "st": "5.17"}, {"sp": "N", "t": "τούτου δὲ ὁ διδάσκαλος τοῦ Κλέωνος, ὄνομα Ἀντιφάνης, ἐκ φοιτήσεως Περικλύτου, Πολυκλείτου δὲ ἦν τοῦ Ἀργείου μαθητὴς ὁ Περίκλυτος. παιδίον δὲ ἐπίχρυσον κάθηται γυμνὸν πρὸ τῆς Ἀφροδίτης· Βοηθὸς δὲ ἐτόρευσεν αὐτὸ Καλχηδόνιος. μετεκομίσθη δὲ αὐτόσε καὶ ἐκ τοῦ καλουμένου Φιλιππείου, χρυσοῦ καὶ ταῦτα καὶ ἐλέφαντος, Εὐρυδίκη τε ἡ ⟨Ἀριδαίου γυνὴ καὶ Ὀλυμπιὰς ἡ⟩ Φιλίππου.", "st": "5.17"}, {"sp": "N", "t": "λάρναξ δὲ κέδρου μὲν πεποίηται, ζῴδια δὲ ἐλέφαντος ἐπ’ αὐτῆς, τὰ δὲ χρυσοῦ, τὰ δὲ καὶ ἐξ αὐτῆς ἐστιν εἰργασμένα τῆς κέδρου· ἐς ταύτην τὴν λάρνακα Κύψελον τὸν Κορίνθου τυραννήσαντα ἀπέκρυψεν ἡ μήτηρ, ἡνίκα τεχθέντα ἀνευρεῖν αὐτὸν σπουδὴν ἐποιοῦντο οἱ Βακχίδαι. τῆς μὲν δὴ σωτηρίας ἕνεκα τοῦ Κυψέλου τὸ ἀπ’ αὐτοῦ γένος οἱ ὀνομαζόμενοι Κυψελίδαι τὴν λάρνακα ἐς Ὀλυμπίαν ἀνέθεσαν, τὰς δὲ λάρνακας οἱ τότε ἐκάλουν Κορίνθιοι κυψέλας· ἀπὸ τούτου δὲ καὶ ὄνομα Κύψελον τῷ παιδὶ θέσθαι λέγουσι.", "st": "5.17"}, {"sp": "N", "t": "τῶν δὲ ἐπὶ τῇ λάρνακι ἐπιγράμματα ἔπεστι τοῖς πλείοσι, γράμμασι τοῖς ἀρχαίοις γεγραμμένα· καὶ τὰ μὲν ἐς εὐθὺ αὐτῶν ἔχει, σχήματα δὲ ἄλλα τῶν γραμμάτων βουστροφηδὸν καλοῦσιν Ἕλληνες. τὸ δέ ἐστι τοιόνδε· ἀπὸ τοῦ πέρατος τοῦ ἔπους ἐπιστρέφει τῶν ἐπῶν τὸ δεύτερον ὥσπερ ἐν διαύλου δρόμῳ. γέγραπται δὲ ἐπὶ τῇ λάρνακι καὶ ἄλλως τὰ ἐπιγράμματα ἑλιγμοῖς συμβαλέσθαι χαλεποῖς. ἀρξαμένῳ δὲ ἀνασκοπεῖσθαι κάτωθεν τοσάδε ἐπὶ τῆς λάρνακος ἡ πρώτη παρέχεται χώρα.", "st": "5.17"}, {"sp": "N", "t": "Οἰνόμαος διώκων Πέλοπά ἐστιν ἔχοντα Ἱπποδάμειαν· ἑκατέρῳ μὲν δὴ δύο αὐτῶν εἰσιν ἵπποι, τοῖς δὲ τοῦ Πέλοπός ἐστι πεφυκότα καὶ πτερά. ἑξῆς δὲ Ἀμφιαράου τε ἡ οἰκία πεποίηται καὶ Ἀμφίλοχον φέρει νήπιον πρεσβῦτις ἥτις δή· πρὸ δὲ τῆς οἰκίας Ἐριφύλη τὸν ὅρμον ἔχουσα ἕστηκε, παρὰ δὲ αὐτὴν αἱ θυγατέρες Εὐρυδίκη καὶ Δημώνασσα, καὶ Ἀλκμαίων παῖς γυμνός.", "st": "5.17"}, {"sp": "N", "t": "Ἄσιος δὲ ἐν τοῖς ἔπεσι καὶ Ἀλκμήνην ἐποίησε θυγατέρα Ἀμφιαράου καὶ Ἐριφύλης εἶναι. Βάτων δέ, ὃς ἡνιοχεῖ τῷ Ἀμφιαράῳ, τάς τε ἡνίας τῶν ἵππων καὶ τῇ χειρὶ ἔχει τῇ ἑτέρᾳ λόγχην. Ἀμφιαράῳ δὲ ὁ μὲν τῶν ποδῶν ἐπιβέβηκεν ἤδη τοῦ ἅρματος, τὸ ξίφος δὲ ἔχει γυμνὸν καὶ ἐς τὴν Ἐριφύλην ἐστὶν ἐπεστραμμένος ἐξαγόμενός τε ὑπὸ τοῦ θυμοῦ, ⟨ὡς μόλις⟩ ἐκείνης ἂν ἀποσχέσθαι.", "st": "5.17"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Ἀμφιαράου τὴν οἰκίαν ἔστιν ἀγὼν ὁ ἐπὶ Πελίᾳ καὶ οἱ θεώμενοι τοὺς ἀγωνιστάς. πεποίηται δὲ Ἡρακλῆς ἐν θρόνῳ καθήμενος καὶ ὄπισθεν γυνὴ αὐτοῦ· ταύτης τῆς γυναικὸς ἐπίγραμμα μὲν ἄπεστιν ἥτις ἐστί, Φρυγίοις δὲ αὐλεῖ καὶ οὐχ Ἑλληνικοῖς αὐλοῖς. ἡνιοχοῦντες δὲ συνωρίδα Πῖσός ἐστιν ὁ Περιήρους καὶ Ἀστερίων Κομήτου, πλεῦσαι καὶ οὗτος λεγόμενος ἐπὶ τῆς Ἀργοῦς, καὶ Πολυδεύκης τε καὶ Ἄδμητος, ἐπὶ δὲ αὐτοῖς Εὔφημος, Ποσειδῶνός τε ὢν κατὰ τὸν τῶν ποιητῶν λόγον καὶ Ἰάσονι ἐς Κόλχους τοῦ πλοῦ μετεσχηκώς· οὗτος δὲ καὶ τῇ συνωρίδι ὁ νικῶν ἐστιν.", "st": "5.17"}, {"sp": "N", "t": "οἱ δὲ ἀποτετολμηκότες πυκτεύειν Ἄδμητος καὶ Μόψος ἐστὶν ὁ Ἄμπυκος· ἐν μέσῳ δὲ αὐτῶν ἀνὴρ ἑστηκὼς ἐπαυλεῖ, καθότι καὶ ἐφ’ ἡμῶν ἐπὶ τῷ ἅλματι αὐλεῖν τῶν πεντάθλων νομίζουσιν. Ἰάσονι δὲ καὶ Πηλεῖ τὸ ἔργον τῆς πάλης ἐξ ἴσου καθέστηκε. πεποίηται δὲ καὶ Εὐρυβώτας ἀφιεὶς δίσκον, ὅστις δὴ οὗτός ἐστιν ἐπὶ δίσκῳ φήμην ἔχων. οἱ δ’ ἐς ἅμιλλαν δρόμου καθεστηκότες Μελανίων ἐστὶ καὶ Νεοθεὺς καὶ Φαλαρεύς, τέταρτος δὲ Ἀργεῖος καὶ Ἴφικλος πέμπτος· τούτῳ δὲ νικῶντι ὀρέγει τὸν στέφανον ὁ Ἄκαστος· εἴη δ’ ἂν ὁ Πρωτεσιλάου πατὴρ τοῦ στρατεύσαντος ἐς Ἴλιον.", "st": "5.17"}, {"sp": "N", "t": "κεῖνται δὲ καὶ τρίποδες, ἆθλα δὴ τοῖς νικῶσι, καὶ θυγατέρες εἰσὶν αἱ Πελίου· τὸ δὲ ὄνομα ἐπὶ τῇ Ἀλκήστιδι γέγραπται μόνῃ. Ἰόλαος δέ, ὃς ἐθελοντὴς μετεῖχεν Ἡρακλεῖ τῶν ἔργων, ἔστιν ἵππων ἅρματι ἀνῃρημένος νίκην. τὸ δὲ ἀπὸ τούτου ἀγὼν μὲν ὁ ἐπὶ Πελίᾳ πέπαυται, τὴν ὕδραν δέ, τὸ ἐν τῷ ποταμῷ τῇ Ἀμυμώνῃ θηρίον, Ἡρακλεῖ τοξεύοντι Ἀθηνᾶ παρέστηκεν· ἅτε δὲ τοῦ Ἡρακλέους ὄντος οὐκ ἀγνώστου τοῦ τε ἄθλου χάριν καὶ ἐπὶ τῷ σχήματι, τὸ ὄνομα οὐκ ἔστιν ἐπ’ αὐτῷ γεγραμμένον. Φινεύς τε ὁ Θρᾷξ ἐστι, καὶ οἱ παῖδες οἱ Βορέου τὰς Ἁρπυίας ἀπ’ αὐτοῦ διώκουσιν.", "st": "5.17"}, {"sp": "N", "t": "τῆς χώρας δὲ ἐπὶ τῇ λάρνακι τῆς δευτέρας ἐξ ἀριστερῶν μὲν γίνοιτο ἂν ἡ ἀρχὴ τῆς περιόδου, πεποίηται δὲ γυνὴ παῖδα λευκὸν καθεύδοντα ἀνέχουσα τῇ δεξιᾷ χειρί, τῇ δὲ ἑτέρᾳ μέλανα ἔχει παῖδα καθεύδοντι ἐοικότα, ἀμφοτέρους διεστραμμένους τοὺς πόδας. δηλοῖ μὲν δὴ καὶ τὰ ἐπιγράμματα, συνεῖναι δὲ καὶ ἄνευ τῶν ἐπιγραμμάτων ἔστι Θάνατόν τε εἶναι σφᾶς καὶ Ὕπνον καὶ ἀμφοτέροις Νύκτα αὐτοῖς τροφόν.", "st": "5.18"}, {"sp": "N", "t": "γυνὴ δὲ εὐειδὴς γυναῖκα αἰσχρὰν κολάζουσα καὶ τῇ μὲν ἀπάγχουσα αὐτήν, τῇ δὲ ῥάβδῳ παίουσα, Δίκη ταῦτα Ἀδικίαν δρῶσά ἐστι· δύο δὲ ἄλλας γυναῖκας ἐς ὅλμους καθικνουμένας ὑπέροις, φάρμακα εἰδέναι σφᾶς νομίζουσιν, ἐπεὶ ἄλλως γε οὐδὲν ἐς αὐτάς ἐστιν ἐπίγραμμα. τὰ δὲ ἐς τὸν ἄνδρα τε καὶ γυναῖκα ἑπομένην αὐτῷ τὰ ἔπη δηλοῖ τὰ ἑξάμετρα· λέγει γὰρ δὴ οὕτως·<br>Ἴδας Μάρπησσαν καλλίσφυρον, ἃν οἱ Ἀπόλλων<br>ἅρπασε, τὰν Εὐανοῦ ἄγει πάλιν οὐκ ἀέκουσαν.", "st": "5.18"}, {"sp": "N", "t": "χιτῶνα δὲ ἐνδεδυκὼς ἀνὴρ τῇ μὲν δεξιᾷ κύλικα, τῇ δὲ ἔχων ἐστὶν ὅρμον, λαμβάνεται δὲ αὐτῶν Ἀλκμήνη· πεποίηται δὲ ἐς τὸν λόγον τῶν Ἑλλήνων ὡς συγγένοιτο Ἀλκμήνῃ Ζεὺς Ἀμφιτρύωνι εἰκασθείς. Μενέλαος δὲ θώρακά τε ἐνδεδυκὼς καὶ ἔχων ξίφος ἔπεισιν Ἑλένην ἀποκτεῖναι, δῆλα ὡς ἁλισκομένης Ἰλίου. Μηδείας δὲ ἐπὶ θρόνου καθημένης Ἰάσων ἐν δεξιᾷ, τῇ δὲ Ἀφροδίτη παρέστηκε· γέγραπται δὲ καὶ ἐπίγραμμα ἐπ’ αὐτοῖς·<br>Μήδειαν Ἰάσων γαμέει, κέλεται δ’ Ἀφροδίτα.", "st": "5.18"}, {"sp": "N", "t": "πεποίηνται δὲ καὶ ᾄδουσαι Μοῦσαι καὶ Ἀπόλλων ἐξάρχων τῆς ᾠδῆς, καί σφισιν ἐπίγραμμα γέγραπται·<br>Λατοΐδας οὗτος τάχ’ ἄναξ ἑκάεργος Ἀπόλλων·<br>Μοῦσαι δ’ ἀμφ’ αὐτόν, χαρίεις χορός, αἷσι κατάρχει.<br>Ἄτλας δὲ ἐπὶ μὲν τῶν ὤμων κατὰ τὰ λεγόμενα οὐρανόν τε ἀνέχει καὶ γῆν, φέρει δὲ καὶ τὰ Ἑσπερίδων μῆλα. ὅστις δέ ἐστιν ὁ ἀνὴρ ὁ ἔχων τὸ ξίφος καὶ [ὁ] ἐπὶ τὸν Ἄτλαντα ἐρχόμενος, ἰδίᾳ μὲν ἐπ’ αὐτῷ γεγραμμένον ἐστὶν οὐδέν, δῆλα δὲ ἐς ἅπαντας Ἡρακλέα εἶναι. γέγραπται δὲ καὶ ἐπὶ τούτοις·<br>Ἄτλας οὐρανὸν οὗτος ἔχει, τὰ δὲ μᾶλα μεθήσει.", "st": "5.18"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ἄρης ὅπλα ἐνδεδυκώς, Ἀφροδίτην ἄγων· ἐπίγραμμα δὲ Ἐνυάλιός ἐστιν αὐτῷ. πεποίηται δὲ καὶ Θέτις παρθένος, λαμβάνεται δὲ αὐτῆς Πηλεύς, καὶ ἀπὸ τῆς χειρὸς τῆς Θέτιδος ὄφις ἐπὶ τὸν Πηλέα ἐστὶν ὁρμῶν. αἱ δὲ ἀδελφαὶ Μεδούσης ἔχουσαι πτερὰ πετόμενον Περσέα εἰσὶ διώκουσαι· τὸ δὲ ὄνομα ἐπὶ τῷ Περσεῖ γέγραπται μόνῳ.", "st": "5.18"}, {"sp": "N", "t": "στρατιωτικὰ δὲ ἐπὶ τῇ τρίτῃ χώρᾳ τῆς λάρνακος· τὸ μὲν πολύ εἰσιν ἐν αὐτοῖς οἱ πεζοί, πεποίηνται δὲ καὶ ἐπὶ συνωρίδων ἱππεῖς. ἐπὶ δὲ τοῖς στρατιώταις ἔστιν εἰκάζειν συνιέναι μὲν σφᾶς ἐς μάχην, συνιέναι δὲ καὶ ἀσπασομένους τε καὶ ἀναγνωριοῦντας ἀλλήλους. λέγεται δὲ καὶ ἐς ἀμφότερα ὑπὸ τῶν ἐξηγητῶν, καὶ τοῖς μέν ἐστιν εἰρημένον Αἰτωλοὺς τοὺς μετὰ Ὀξύλου καὶ Ἠλείους εἶναι τοὺς ἀρχαίους, ἀπαντᾶν δὲ σφᾶς γένους τε μνήμῃ τοῦ ἐξ ἀρχῆς καὶ εὔνοιαν ἐνδεικνυμένους ἐς ἀλλήλους· οἱ δὲ συνιέναι φασὶν ἐς ἀγῶνα τὰ στρατιωτικά, Πυλίους δὲ εἶναι καὶ Ἀρκάδας παρά τε Φειὰν πόλιν καὶ ποταμὸν μαχουμένους Ἰάρδανον.", "st": "5.18"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὐδὲ ἀρχὴν ἀποδέξαιτο ἄν τις, ὡς ὁ τοῦ Κυψέλου πρόγονος Κορίνθιός τε ὢν καὶ τὴν λάρνακα αὑτῷ ποιούμενος κτῆμα, ὁπόσα μὲν Κορινθίοις ἦν ἐπιχώρια, ἑκὼν ὑπερέβαινεν, ἃ δὲ ξενικά τε καὶ οὐδὲ ἄλλως ἥκοντα ἐς δόξαν, ἐτεχνᾶτο ἐπὶ τῇ λάρνακι· αὐτῷ μέντοι παρίστατο ἐμοὶ ταῦτα εἰκάζειν. Κυψέλῳ καὶ τοῖς προγόνοις ἐκ [τῶνδε] ⟨Γονούσσης⟩ ἦν γένος ἐξ ἀρχῆς [γονούσης] τῆς ὑπὲρ Σικυῶνος, καὶ πρόγονός σφισιν ἦν Μέλας ὁ Ἀντάσου·", "st": "5.18"}, {"sp": "N", "t": "Μέλανα δὲ καὶ τὸν σὺν αὐτῷ στρατὸν κατὰ τὰ προειρημένα μοι καὶ ἐν τῇ Κορινθίᾳ συγγραφῇ οὐκ ἤθελεν Ἀλήτης συνοίκους δέξασθαι, γεγονός οἱ μάντευμα ἐκ Δελφῶν ὑφορώμενος, ἐς ὃ θεραπείᾳ τε τῇ πάσῃ χρώμενον [καὶ] Μέλανα καὶ ὁπότε ἀπελασθείη σὺν δεήσει ἐπανιόντα αὖθις ἐδέξατο καὶ ἄκων Ἀλήτης. τοῦτο τὸ στρατιωτικὸν τεκμαίροιτο ἄν τις τοὺς ἐπὶ τῇ λάρνακι εἰργασμένους εἶναι.", "st": "5.18"}, {"sp": "N", "t": "τέταρτα δὲ ἐπὶ τῇ λάρνακι ἐξ ἀριστερᾶς περιιόντι Βορέας ἐστὶν ἡρπακὼς Ὠρείθυιαν—οὐραὶ δὲ ὄφεων ἀντὶ ποδῶν εἰσὶν αὐτῷ—καὶ Ἡρακλέους ὁ πρὸς Γηρυόνην ἀγών· τρεῖς δὲ ἄνδρες Γηρυόνης εἰσὶν ἀλλήλοις προσεχόμενοι. Θησεὺς δὲ ἔχων λύραν καὶ παρ’ αὐτὸν Ἀριάδνη κατέχουσά ἐστι στέφανον. Ἀχιλλεῖ δὲ καὶ Μέμνονι μαχομένοις παρεστήκασιν αἱ μητέρες·", "st": "5.19"}, {"sp": "N", "t": "ἔστι δὲ καὶ Μελανίων καὶ Ἀταλάντη παρ’ αὐτὸν ἔχουσα ἐλάφου νεβρόν. μονομαχοῦντος δὲ Αἴαντι Ἕκτορος κατὰ τὴν πρόκλησιν, μεταξὺ ἕστηκεν αὐτῶν Ἔρις αἰσχίστη τὸ εἶδος ἐοικυῖα· πρὸς δὲ ταύτῃ καὶ Καλλιφῶν Σάμιος ἐν Ἀρτέμιδος ἱερῷ τῆς Ἐφεσίας ἐποίησεν Ἔριν, τὴν μάχην γράψας τὴν ἐπὶ ταῖς ναυσὶν Ἑλλήνων. εἰσὶ δὲ ἐπὶ τῇ λάρνακι Διόσκουροι, ὁ ἕτερος οὐκ ἔχων πω γένεια, μέση δὲ αὐτῶν Ἑλένη·", "st": "5.19"}, {"sp": "N", "t": "Αἴθρα δὲ ἡ Πιτθέως ὑπὸ τῆς Ἑλένης τοῖς ποσὶν ἐς ἔδαφος καταβεβλημένη μέλαιναν ἔχουσά ἐστιν ἐσθῆτα, ἐπίγραμμα δὲ ἐπ’ αὐτοῖς ἔπος τε ἑξάμετρον καὶ ὀνόματός ἐστιν ἑνὸς ἐπὶ τῷ ἑξαμέτρῳ προσθήκη·<br>Τυνδαρίδα Ἑλέναν φέρετον, Αἴθραν δ’ ἕλκετον<br>Ἀθάναθεν.", "st": "5.19"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τὸ ἔπος οὕτω πεποίηται· Ἰφιδάμαντος δὲ τοῦ Ἀντήνορος κειμένου μαχόμενος πρὸς Ἀγαμέμνονα ὑπὲρ αὐτοῦ Κόων ἐστί· Φόβος δὲ ἐπὶ τοῦ … Ἀγαμέμνονος τῇ ἀσπίδι ἔπεστιν, ἔχων τὴν κεφαλὴν λέοντος. … ἐπιγράμματα δὲ ὑπὲρ μὲν τοῦ Ἰφιδάμαντος νεκροῦ,<br>Ἰφιδάμας οὗτός τε Κόων περιμάρναται αὐτοῦ·<br>τοῦ Ἀγαμέμνονος δὲ ἐπὶ τῇ ἀσπίδι,", "st": "5.19"}, {"sp": "N", "t": "οὗτος μὲν Φόβος ἐστὶ βροτῶν, ὁ δ’ ἔχων Ἀγαμέμνων.<br>ἄγει δὲ καὶ Ἑρμῆς παρ’ Ἀλέξανδρον τὸν Πριάμου τὰς θεὰς κριθησομένας ὑπὲρ τοῦ κάλλους, καὶ ἔστιν ἐπίγραμμα καὶ τούτοις·<br>Ἑρμείας ὅδ’ Ἀλεξάνδρῳ δείκνυσι διαιτῆν<br>τοῦ εἴδους Ἥραν καὶ Ἀθάναν καὶ Ἀφροδίταν.<br>Ἄρτεμις δὲ οὐκ οἶδα ἐφ’ ὅτῳ λόγῳ πτέρυγας ἔχουσά ἐστιν ἐπὶ τῶν ὤμων, καὶ τῇ μὲν δεξιᾷ κατέχει πάρδαλιν, τῇ δὲ ἑτέρᾳ τῶν χειρῶν λέοντα. πεποίηται δὲ καὶ Κασσάνδραν ἀπὸ τοῦ ἀγάλματος Αἴας τῆς Ἀθηνᾶς ἕλκων, ἐπ’ αὐτῷ δὲ καὶ ἐπίγραμμά ἐστιν·<br>Αἴας Κασσάνδραν ἀπ’ Ἀθαναίας Λοκρὸς ἕλκει.", "st": "5.19"}, {"sp": "N", "t": "τῶν δὲ Οἰδίποδος παίδων Πολυνείκει πεπτωκότι ἐς γόνυ ἔπεισιν Ἐτεοκλῆς. τοῦ Πολυνείκους δὲ ὄπισθεν ⟨γυνὴ⟩ ἕστηκεν ὀδόντας τε ἔχουσα οὐδὲν ἡμερωτέρους θηρίου καί οἱ τῶν χειρῶν εἰσιν ἐπικαμπεῖς οἱ ὄνυχες· ἐπίγραμμα δὲ ἐπ’ αὐτῇ εἶναί φησι Κῆρα, ὡς τὸν μὲν ὑπὸ τοῦ πεπρωμένου τὸν Πολυνείκην ἀπαχθέντα, Ἐτεοκλεῖ δὲ γενομένης καὶ σὺν τῷ δικαίῳ τῆς τελευτῆς. Διόνυσος δὲ ἐν ἄντρῳ κατακείμενος, γένεια ἔχων καὶ ἔκπωμα χρυσοῦν, ἐνδεδυκώς ἐστι ποδήρη χιτῶνα· δένδρα δὲ ἄμπελοι περὶ αὐτὸν καὶ μηλέαι τέ εἰσι καὶ ῥόαι.", "st": "5.19"}, {"sp": "N", "t": "ἡ δὲ ἀνωτάτω χώρα—πέντε γὰρ ἀριθμόν εἰσι— παρέχεται μὲν ἐπίγραμμα οὐδέν, λείπεται δὲ εἰκάζειν ἐς τὰ ἐπειργασμένα. εἰσὶν οὖν ἐν σπηλαίῳ γυνὴ καθεύδουσα σὺν ἀνδρὶ ἐπὶ κλίνῃ, καὶ σφᾶς Ὀδυσσέα εἶναι καὶ Κίρκην ἐδοξάζομεν ἀριθμῷ τε τῶν θεραπαινῶν, αἵ εἰσι πρὸ τοῦ σπηλαίου, καὶ τοῖς ποιουμένοις ὑπ’ αὐτῶν· τέσσαρές τε γάρ εἰσιν αἱ γυναῖκες καὶ ἐργάζονται τὰ ἔργα, ἃ ἐν τοῖς ἔπεσιν Ὅμηρος εἴρηκε. Κένταυρος δὲ οὐ τοὺς πάντας ἵππου πόδας, τοὺς δὲ ἔμπροσθεν αὐτῶν ἔχων ἀνδρός ἐστιν.", "st": "5.19"}, {"sp": "N", "t": "ἑξῆς καὶ ἵππων συνωρίδες καὶ γυναῖκες ἐπὶ τῶν συνωρίδων εἰσὶν ἑστῶσαι· πτερὰ δὲ τοῖς ἵπποις χρυσᾶ ἐστι, καὶ ἀνὴρ δίδωσιν ὅπλα μιᾷ τῶν γυναικῶν. ταῦτα ἐς τὴν Πατρόκλου τελευτὴν ἔχειν τεκμαίρονται· Νηρηίδας τε γὰρ ἐπὶ τῶν συνωρίδων εἶναι καὶ Θέτιν τὰ ὅπλα λαμβάνειν παρὰ Ἡφαίστου. καὶ δὴ καὶ ἄλλως ὁ τὰ ὅπλα διδοὺς οὔτε τοὺς πόδας ἐστὶν ἐρρωμένος καὶ ὄπισθεν οἰκέτης ἕπεταί οἱ πυράγραν ἔχων·", "st": "5.19"}, {"sp": "N", "t": "λέγεται δὲ καὶ ἐς τὸν Κένταυρον ὡς Χίρων, ἀπηλλαγμένος ἤδη παρὰ ἀνθρώπων καὶ ἠξιωμένος εἶναι σύνοικος θεοῖς, ῥᾳστώνην τινὰ ἥκοι τοῦ πένθους Ἀχιλλεῖ παρασκευάσων. παρθένους δὲ ἐπὶ ἡμιόνων τὴν μὲν ἔχουσαν τὰς ἡνίας, τὴν δὲ ἐπικειμένην κάλυμμα ἐπὶ τῇ κεφαλῇ, Ναυσικᾶν τε νομίζουσιν εἶναι τὴν Ἀλκίνου καὶ τὴν θεράπαιναν, ἐλαυνούσας ἐπὶ τοὺς πλυνούς. τοξεύοντα δὲ ἄνδρα Κενταύρους, τοὺς δὲ καὶ ἀπεκτονότα ἐξ αὐτῶν, δῆλα Ἡρακλέα τε τὸν τοξεύοντα καὶ Ἡρακλέους εἶναι τὸ ἔργον.", "st": "5.19"}, {"sp": "N", "t": "τὸν μὲν δὴ τὴν λάρνακα [κατ]εἰργασμένον ὅστις ἦν, οὐδαμῶς ἡμῖν δυνατὰ ἦν συμβαλέσθαι· τὰ ἐπιγράμματα δὲ τὰ ἐπ’ αὐτῆς τάχα μέν που καὶ ἄλλος τις ἂν εἴη πεποιηκώς, τῆς δὲ ὑπονοίας τὸ πολὺ ἐς Εὔμηλον τὸν Κορίνθιον εἶχεν ἡμῖν, ἄλλων τε ἕνεκα καὶ τοῦ προσοδίου μάλιστα ὃ ἐποίησεν ἐς Δῆλον.", "st": "5.19"}, {"sp": "N", "t": "ἔστι δὲ ἐνταῦθα καὶ ἄλλα ἀναθήματα, κλίνη τε μέγεθος οὐ μεγάλη, τὰ πολλὰ ἐλέφαντι κεκοσμημένη, καὶ ὁ Ἰφίτου δίσκος καὶ τράπεζα ἐφ’ ἧς προτίθενται τοῖς νικῶσιν οἱ στέφανοι. τὴν μὲν δὴ Ἱπποδαμείας λέγουσιν εἶναι παίγνιον· ὁ δὲ τοῦ Ἰφίτου δίσκος τὴν ἐκεχειρίαν, ἣν ἐπὶ τοῖς Ὀλυμπίοις ἐπαγγέλλουσιν Ἠλεῖοι, ταύτην οὐκ ἐς εὐθὺ ἔχει γεγραμμένην, ἀλλὰ ἐς κύκλου σχῆμα περίεισιν ἐπὶ τῷ δίσκῳ τὰ γράμματα.", "st": "5.20"}, {"sp": "N", "t": "ἡ τράπεζα δὲ ἐλέφαντος μὲν πεποίηται καὶ χρυσοῦ, Κωλώτου δέ ἐστιν ἔργον· εἶναι δέ φασιν ἐξ Ἡρακλείας τὸν Κωλώτην, οἱ δὲ πολυπραγμονήσαντες σπουδῇ τὰ ἐς τοὺς πλάστας Πάριον ἀποφαίνουσιν ὄντα αὐτόν, μαθητὴν Πασιτέλους, Πασιτέλη δὲ αὐτὸν διδαχθῆναι …. καὶ Ἥρα τε καὶ Ζεὺς καὶ θεῶν Μήτηρ καὶ Ἑρμῆς καὶ Ἀπόλλων μετὰ Ἀρτέμιδος πεποίηται· ὄπισθε δὲ ἡ διάθεσίς ἐστιν ἡ τοῦ ἀγῶνος.", "st": "5.20"}, {"sp": "N", "t": "κατὰ δὲ ἑκατέραν πλευρὰν τῇ μὲν Ἀσκληπιὸς καὶ τῶν Ἀσκληπιοῦ θυγατέρων Ὑγεία ἐστίν, ἔτι δὲ καὶ Ἄρης καὶ Ἀγὼν παρ’ αὐτόν, τῇ δὲ Πλούτων καὶ Διόνυσος Περσεφόνη τε καὶ Νύμφαι, σφαῖραν αὐτῶν ἡ ἑτέρα φέρουσα· ἐπὶ δὲ ⟨τῇ⟩ κλειδὶ —ἔχει γὰρ δὴ ὁ Πλούτων κλεῖν—, λέγουσιν ἐπ’ αὐτῇ τὸν καλούμενον Ἅιδην κεκλεῖσθαί τε ὑπὸ τοῦ Πλούτωνος καὶ ὡς ἐπάνεισιν οὐδεὶς αὖθις ἐξ αὐτοῦ.", "st": "5.20"}, {"sp": "N", "t": "λόγον δέ, ὃν Ἀρίσταρχος ἔλεγεν ὁ τῶν Ὀλυμπίασιν ἐξηγητής, οὔ με εἰκὸς ἦν παριδεῖν· ὃς ἐπὶ τῆς ἡλικίας ἔφη τῆς ἑαυτοῦ τὸν ὄροφον τοῦ Ἡραίου πεπονηκότα ἐπανορθουμένων Ἠλείων ὁπλίτου νεκρὸν τραύματα ἔχοντα μεταξὺ ἀμφοτέρων εὑρεθῆναι, τῆς τε ἐς εὐπρέπειαν στέγης καὶ τῆς ἀνεχούσης τὸν κέραμον· τοῦτον τὸν ἄνδρα μαχέσασθαι τὴν μάχην τὴν ἐντὸς Ἄλτεως πρὸς Λακεδαιμονίους Ἠλείων.", "st": "5.20"}, {"sp": "N", "t": "καὶ γὰρ ἐπὶ τῶν θεῶν τὰ ἱερὰ καὶ ἐς πάντα ὁμοίως τὰ ὑψηλὰ ἐπαναβαίνοντες ἠμύνοντο οἱ Ἠλεῖοι. οὗτος δ’ οὖν ὁ ἀνὴρ ἐφαίνετο ἡμῖν ὑποδῦναι μὲν ἐνταῦθα λιποψυχήσας ὑπὸ τραυμάτων· ὡς δὲ ἀφῆκε τὴν ψυχήν, οὐκ ἔμελλεν ἄρα οὔτε πνῖγος θέρους οὔτε ἐν χειμῶνι κρυμὸς ἔσεσθαι τῷ νεκρῷ βλάβος ἅτε ἐν σκέπῃ πάσῃ κειμένῳ. ἔλεγε δὲ καὶ τόδε ἔτι ὁ Ἀρίσταρχος, ὡς ἐκκομίσαιντο ἐς τὸ ἐκτὸς τῆς Ἄλτεως τὸν νεκρὸν καὶ ὁμοῦ τοῖς ὅπλοις γῇ κρύψαιεν.", "st": "5.20"}, {"sp": "N", "t": "ἣν δὲ καλοῦσιν Οἰνομάου κίονα [καὶ] οἱ Ἠλεῖοι [καλοῦσιν], ἔστι μὲν πρὸς τὸ ἱερὸν τοῦ Διὸς ἰόντι ἀπὸ τοῦ μεγάλου βωμοῦ· τέσσαρες δέ εἰσιν ἐν ἀριστερᾷ κίονες καὶ ἐπ’ αὐτῶν ὄροφος, πεποίηνται δὲ ἔρυμα εἶναι ξυλίνῳ κίονι πεπονηκότι ὑπὸ τοῦ χρόνου καὶ τὰ πολλὰ ὑπὸ δεσμῶν συνεχομένῳ. οὗτος ὁ κίων ἐν οἰκίᾳ τοῦ Οἰνομάου, καθὰ λέγουσιν, εἱστήκει· κεραυνώσαντος δὲ τοῦ θεοῦ τὴν μὲν ἄλλην ἠφάνισεν οἰκίαν τὸ πῦρ, ὑπελίπετο δὲ τὸν κίονα ἐξ ἁπάσης μόνον.", "st": "5.20"}, {"sp": "N", "t": "πινάκιον δὲ πρὸ αὐτοῦ χαλκοῦν ἐλεγεῖα ἔχει γεγραμμένα·<br>καὶ γὰρ ἐγὼ κεινῶν εἴμ’ ὦ ξένε λείψανον οἴκων,<br>στυλὶς ἐν Οἰνομάου πρίν ποτ’ ἐοῦσα δόμοις·<br>νῦν δὲ παρὰ Κρονίδην κεῖμαι τάδ’ ἔχουσα τὰ δεσμὰ<br>τίμιος· οὐδ’ ὀλοὴ δαίσατο φλόξ με πυρός.<br>συνέβη δὲ καὶ ἄλλο κατ’ ἐμὲ τοιόνδε.", "st": "5.20"}, {"sp": "N", "t": "ἀνὴρ βουλῆς τῆς Ῥωμαίων ἀνείλετο Ὀλυμπικὴν νίκην· ἐθέλων δὲ ὑπολιπέσθαι τῆς νίκης ὑπόμνημα χαλκῆν εἰκόνα ⟨σὺν⟩ ἐπιγράμματι, ὤρυσσεν ἐς ποίησιν βάθρου· καὶ ὡς ἐγένετο ἐγγύτατα τὸ ὄρυγμα αὐτῷ τῆς τοῦ Οἰνομάου κίονος, ἐνταῦθα εὕρισκον οἱ ὀρύσσοντες καὶ ὅπλων καὶ χαλινῶν καὶ ψαλίων θραύματα.", "st": "5.20"}, {"sp": "N", "t": "ταῦτα μὲν δὴ αὐτὸς ἑώρων ὀρυσσόμενα· ναὸν δὲ μεγέθει ⟨οὐ⟩ μέγαν καὶ ἐργασίᾳ Δώριον Μητρῷον καὶ ἐς ἐμὲ καλοῦσιν ἔτι, τὸ ὄνομα αὐτῷ διασώζοντες τὸ ἀρχαῖον· κεῖται δὲ οὐκ ἄγαλμα ἐν αὐτῷ θεῶν Μητρός, βασιλέων δὲ ἑστήκασιν ἀνδριάντες Ῥωμαίων. ἔστι δὲ ἐντὸς τῆς Ἄλτεως τό ⟨τε⟩ Μητρῷον καὶ οἴκημα περιφερὲς ὀνομαζόμενον Φιλιππεῖον· ἐπὶ κορυφῇ δέ ἐστι τοῦ Φιλιππείου μήκων χαλκῆ σύνδεσμος ταῖς δοκοῖς.", "st": "5.20"}, {"sp": "N", "t": "τοῦτο τὸ οἴκημα ἔστι μὲν κατὰ τὴν ἔξοδον τὴν κατὰ τὸ πρυτανεῖον ἐν ἀριστερᾷ, πεποίηται δὲ ὀπτῆς πλίνθου, κίονες δὲ περὶ αὐτὸ ἑστήκασι· Φιλίππῳ δὲ ἐποιήθη μετὰ τὸ ἐν Χαιρωνείᾳ τὴν Ἑλλάδα ὀλισθεῖν. κεῖνται δὲ αὐτόθι Φίλιππός τε καὶ Ἀλέξανδρος, σὺν δὲ αὐτοῖς Ἀμύντας ὁ Φιλίππου πατήρ· ἔργα δέ ἐστι καὶ ταῦτα Λεωχάρους ἐλέφαντος καὶ χρυσοῦ, καθὰ καὶ τῆς Ὀλυμπιάδος καὶ Εὐρυδίκης εἰσὶν αἱ εἰκόνες.", "st": "5.20"}, {"sp": "N", "t": "τὸ δὲ ἀπὸ τούτου μοι πρόεισιν ὁ λόγος ἔς τε τῶν ἀνδριάντων καὶ ἐς τῶν ἀναθημάτων ἐξήγησιν. ἀναμῖξαι δὲ οὐκ ἀρεστὰ ἦν μοι τὸν ἐπ’ αὐτοῖς λόγον. ἐν ἀκροπόλει μὲν γὰρ τῇ Ἀθήνῃσιν οἵ τε ἀνδριάντες καὶ ὁπόσα ἄλλα, τὰ πάντα ἐστὶν ὁμοίως ἀναθήματα· ἐν δὲ τῇ Ἄλτει τὰ μὲν τιμῇ τῇ ἐς τὸ θεῖον ἀνάκεινται, οἱ δὲ ἀνδριάντες τῶν νικώντων ἐν ἄθλου λόγῳ σφίσι καὶ οὗτοι δίδονται. τῶν μὲν δὴ ἀνδριάντων ποιησόμεθα καὶ ὕστερον μνήμην· ἐς δὲ τὰ ἀναθήματα ἡμῖν τραπήσεται πρότερα ὁ λόγος, τὰ ἀξιολογώτατα αὐτῶν ἐπερχομένοις.", "st": "5.21"}, {"sp": "N", "t": "ἰόντι γὰρ ἐπὶ τὸ στάδιον τὴν ὁδὸν τὴν ἀπὸ τοῦ Μητρῴου, ἔστιν ἐν ἀριστερᾷ κατὰ τὸ πέρας τοῦ ὄρους τοῦ Κρονίου λίθου τε πρὸς αὐτῷ τῷ ὄρει κρηπὶς καὶ ἀναβασμοὶ δι’ αὐτῆς· πρὸς δὲ τῇ κρηπῖδι ἀγάλματα Διὸς ἀνάκειται χαλκᾶ. ταῦτα ἐποιήθη μὲν ἀπὸ χρημάτων ἐπιβληθείσης ἀθληταῖς ζημίας ὑβρίσασιν ἐς τὸν ἀγῶνα, καλοῦνται δὲ ὑπὸ τῶν ἐπιχωρίων Ζᾶνες.", "st": "5.21"}, {"sp": "N", "t": "πρῶτοι δὲ ἀριθμὸν ἓξ ἐπὶ τῆς ὀγδόης ἔστησαν καὶ ἐνενηκοστῆς Ὀλυμπιάδος· Εὔπωλος γὰρ Θεσσαλὸς χρήμασι διέφθειρε τοὺς ἐλθόντας τῶν πυκτῶν, Ἀγήτορα Ἀρκάδα καὶ Πρύτανιν Κυζικηνόν, σὺν δὲ αὐτοῖς καὶ Φορμίωνα Ἁλικαρνασσέα μὲν γένος, Ὀλυμπιάδι δὲ τῇ πρὸ ταύτης κρατήσαντα. τοῦτο ἐξ ἀθλητῶν ἀδίκημα ἐς τὸν ἀγῶνα πρῶτον γενέσθαι λέγουσι, καὶ πρῶτοι χρήμασιν ἐζημιώθησαν ὑπὸ Ἠλείων Εὔπωλος καὶ οἱ δεξάμενοι δῶρα παρὰ Εὐπώλου. δύο μὲν δὴ ἐξ αὐτῶν ἔργα Κλέωνος Σικυωνίου· τὰ δὲ ἐφεξῆς τέσσαρα ὅστις ἐποίησεν, οὐκ ἴσμεν.", "st": "5.21"}, {"sp": "N", "t": "τῶν δὲ ἀγαλμάτων τούτων παρέντι τρίτον τε ἐξ αὐτῶν καὶ τέταρτον, γεγραμμένα ἐλεγεῖά ἐστιν ἐπὶ τοῖς ἄλλοις. ἐθέλει δὲ τὸ μὲν πρῶτον τῶν ἐλεγείων δηλοῦν ὡς οὐ χρήμασιν ἀλλὰ ὠκύτητι τῶν ποδῶν καὶ ὑπὸ ἰσχύος σώματος Ὀλυμπικὴν ἔστιν εὑρέσθαι νίκην, τὸ δὲ ἐπὶ τῷ δευτέρῳ φησὶν ὡς τὸ ἄγαλμα ἕστηκε τιμῇ τε τῇ ἐς τὸ θεῖον καὶ ὑπὸ εὐσεβείας τῆς Ἠλείων καὶ ἀθληταῖς παρανομοῦσιν εἶναι δέος· πέμπτῳ δὲ καὶ ἕκτῳ, τῷ μέν ἐστιν ἡ τοῦ ἐπιγράμματος γνώμη τά τε ἄλλα ἐς ἔπαινον Ἠλείων καὶ οὐχ ἥκιστα ἐπὶ τῇ ζημίᾳ τῶν πυκτῶν, ἐπὶ δὲ τῷ ὑπολοίπῳ διδασκαλίαν πᾶσιν Ἕλλησιν εἶναι τὰ ἀγάλματα μηδένα ἐπὶ Ὀλυμπικῇ νίκῃ διδόναι χρήματα.", "st": "5.21"}, {"sp": "N", "t": "Εὐπώλου δὲ ὕστερόν φασιν Ἀθηναῖον Κάλλιππον ἀθλήσαντα πένταθλον ἐξωνήσασθαι τοὺς ἀνταγωνιουμένους χρήμασι, δευτέραν δὲ ἐπὶ ταῖς δέκα τε καὶ ἑκατὸν Ὀλυμπιάδα εἶναι ταύτην. ἐπιβληθείσης δὲ τῷ Καλλίππῳ καὶ τοῖς ἀνταγωνισαμένοις ζημίας ὑπὸ Ἠλείων, ἀποστέλλουσιν Ὑπερείδην Ἀθηναῖοι πείσοντα Ἠλείους ἀφεῖναί σφισι τὴν ζημίαν· ἀπειπόντων δὲ Ἠλείων τὴν χάριν, ἐχρῶντο ὑπεροψίᾳ τοιᾷδε ἐς αὐτοὺς οἱ Ἀθηναῖοι, οὔτε ἀποδιδόντες τὰ χρήματα καὶ Ὀλυμπίων εἰργόμενοι, πρὶν ἤ σφισιν ὁ θεὸς ⟨ὁ⟩ ἐν Δελφοῖς οὐ πρότερον ἔφησεν ὑπὲρ οὐδενὸς χρήσειν πρὶν ἢ τὴν ζημίαν ἀποδοῖεν Ἠλείοις.", "st": "5.21"}, {"sp": "N", "t": "οὕτω δὴ ἀποδόντων ἐποιήθη τῷ Διὶ ἀγάλματα, ἓξ μὲν καὶ ταῦτα, γέγραπται δὲ ἐπ’ αὐτοῖς ἐλεγεῖα οὐδέν τι δεξιώτερα ἐς ποίησιν ἢ τὰ ἔχοντα τὴν ζημίαν τὴν Εὐπώλου. γνῶμαι δέ εἰσι τῶν ἐπιγραμμάτων, πρῶτον μὲν ἀνατεθῆναι ⟨τὰ⟩ ἀγάλματα μαντείᾳ τοῦ θεοῦ τιμήσαντος τὰ ἐς τοὺς πεντάθλους δόξαντα Ἠλείοις, τὸ δὲ ἐπὶ τῷ δευτέρῳ καὶ ὡσαύτως ἐπὶ τῷ τρίτῳ Ἠλείους ἐπαινοῦντά ἐστιν ἐπὶ τῶν πεντάθλων τῇ ζημίᾳ·", "st": "5.21"}, {"sp": "N", "t": "τὸ τέταρτον δὲ ἐθέλει λέγειν τὸν Ὀλυμπίασιν ἀγῶνα ἀρετῆς εἶναι καὶ οὐ χρημάτων, τὰ δὲ ἐπιγράμματα ⟨τὰ⟩ ἐπὶ τῷ πέμπτῳ τε καὶ ἕκτῳ, τὸ μὲν αὐτῶν δηλοῖ καθ’ ἥντινα αἰτίαν ἀνετέθη τὰ ἀγάλματα, τὸ δὲ ἀναμιμνήσκει τοῦ χρησμοῦ τοῦ Ἀθηναίοις ἐλθόντος ἐκ Δελφῶν.", "st": "5.21"}, {"sp": "N", "t": "τῶν δὲ κατειλεγμένων τὰ ἐφεξῆς ἀγάλματα δύο μέν ἐστιν ἀριθμόν, ἀνετέθη δὲ ἐπιτεθείσης παλαισταῖς ἀνδράσι ζημίας· οἵτινες δὲ ἐκαλοῦντο, ἐμέ γε ἢ τοὺς Ἠλείων λέληθεν ἐξηγητάς. ἐπιγράμματα μὲν γὰρ καὶ ἐπὶ τούτοις τοῖς ἀγάλμασιν ἔπεστι, λέγει δὲ τὸ μὲν πρῶτον αὐτῶν ὡς τῷ Ὀλυμπίῳ Διὶ Ῥόδιοι χρήματα ὑπὲρ ἀνδρὸς ἀδικίας ἐκτίσαιεν παλαιστοῦ, τὸ δὲ ἕτερον ὡς ἀνδρῶν ἐπὶ δώροις παλαισάντων ἀπὸ τῶν ἐπιβληθέντων χρημάτων αὐτοῖς γένοιτο τὸ ἄγαλμα.", "st": "5.21"}, {"sp": "N", "t": "τὰ δὲ ἐπίλοιπα ἐς τοὺς ἀθλητὰς τούτους οἱ ἐξηγηταὶ λέγουσιν οἱ Ἠλείων, ὀγδόην μὲν ἐπὶ ταῖς ἑβδομήκοντα καὶ ἑκατὸν Ὀλυμπιάδα εἶναι, λαβεῖν δὲ Εὔδηλον παρὰ Φιλοστράτου χρήματα, τοῦτον δὲ εἶναι τὸν Φιλόστρατον Ῥόδιον. τούτῳ τῷ λόγῳ διάφορα ὄντα εὕρισκον τὰ Ἠλείων ἐς τοὺς Ὀλυμπιονίκας γράμματα· ἔστι γὰρ δὴ ἐν τοῖς γράμμασι τούτοις Στράτωνα Ἀλεξανδρέα Ὀλυμπιάδι ὀγδόῃ μετὰ τὰς ἑβδομήκοντα καὶ ἑκατὸν ἐπὶ ἡμέρας ἀνελέσθαι τῆς αὐτῆς παγκρατίου καὶ πάλης νίκην. Ἀλεξανδρείας δὲ τῆς ἐπὶ τῷ Κανωβικῷ τοῦ Νείλου στόματι Ἀλέξανδρος μὲν οἰκιστὴς ἐγένετο ὁ Φιλίππου, λέγεται δὲ καὶ πρότερον ἔτι πόλισμα Αἰγυπτίων ἐνταῦθα οὐ μέγα εἶναι Ῥακῶτιν·", "st": "5.21"}, {"sp": "N", "t": "Στράτωνος δὲ τούτου τρεῖς μὲν ἡλικίᾳ πρότερον, τοσοῦτοι δὲ ἄλλοι μετ’ αὐτόν εἰσι δῆλοι τὸν κότινον παγκρατίου τε ἆθλα εἰληφότες καὶ πάλης, Κάπρος μὲν ἐξ αὐτῆς Ἤλιδος, Ἑλλήνων δὲ τῶν πέραν Αἰγαίου Ῥόδιός τε Ἀριστομένης καὶ Μαγνήτων τῶν ἐπὶ Ληθαίῳ Πρωτοφάνης. οἱ δὲ ὕστερον τοῦ Στράτωνος Μαρίων τε πόλεως ἐκείνῳ τῆς αὐτῆς καὶ Στρατονικεὺς Ἀριστέας—τὰ δὲ παλαιότερα ἥ τε χώρα καὶ ἡ πόλις ἐκαλεῖτο Χρυσαορίς—, ἕβδομος δὲ Νικόστρατος ἐκ τῶν ἐπὶ θαλάσσῃ Κιλίκων, οὐδὲν τοῖς Κίλιξιν αὐτοῦ μετὸν εἰ μὴ ὅσα τῷ λόγῳ.", "st": "5.21"}, {"sp": "N", "t": "τοῦτον τὸν Νικόστρατον νήπιον παῖδα ἔτι ἐκ Πρυμνησσοῦ λῃσταὶ τῆς Φρυγῶν ἥρπασαν, οἰκίας ὄντα οὐκ ἀφανοῦς· κομισθέντα δὲ αὐτὸν ἐς Αἰγέας ὠνήσατο ὅστις δή. χρόνῳ δὲ ὕστερον τῷ ἀνδρὶ τούτῳ ὄνειρον γίνεται· λέοντος δὲ ἔδοξεν ὑπὸ τῷ σκίμποδι κατακεῖσθαι σκύμνον, ἐφ’ ᾧ ἐκάθευδεν ὁ Νικόστρατος. Νικοστράτῳ μὲν δή, ὡς ηὐξήθη, καὶ ἄλλαι νῖκαι ⟨καὶ⟩ Ὀλυμπίασιν ἐγένοντο παγκρατίου καὶ πάλης.", "st": "5.21"}, {"sp": "N", "t": "χρήμασι δὲ ὑπὸ Ἠλείων ἕτεροί τε ὕστερον καὶ Ἀλεξανδρεὺς ἐζημιώθη πύκτης Ὀλυμπιάδι ἐπὶ ταῖς διακοσίαις ὀγδόῃ τε καὶ δεκάτῃ. ὄνομα μὲν τῷ ζημιωθέντι Ἀπολλώνιος, ἐπίκλησις δὲ ἦν Ῥάντης· καί πως καὶ ἐπιχώριον τὸ ἐς τὰς ἐπικλήσεις τοῖς Ἀλεξανδρεῦσίν ἐστιν. οὗτος ὁ ἀνὴρ ἀδικεῖν ὑπὸ Ἠλείων κατεγνώσθη πρῶτος Αἰγυπτίων·", "st": "5.21"}, {"sp": "N", "t": "κατεγνώσθη δὲ οὐ δοῦναι χρήματα ἢ λαβεῖν αὐτός, ἀλλὰ τοιόνδε ἄλλο ἐς τὸν ἀγῶνα ἐξυβρίσαι. ἀφίκετο οὐκ ἐς τὸν εἰρημένον καιρόν, καὶ αὐτὸν ὑπὸ Ἠλείων πειθομένων τῷ νόμῳ ἐλείπετο τοῦ ἀγῶνος εἴργεσθαι· τὴν γάρ οἱ πρόφασιν, ὡς ἐν ταῖς Κυκλάσι νήσοις ὑπὸ ἀνέμων κατείχετο ἐναντίων, Ἡρακλείδης γένος καὶ αὐτὸς Ἀλεξανδρεὺς ἤλεγχεν ἀπάτην οὖσαν· ὑστερῆσαι γὰρ χρήματα ἐκ τῶν ἀγώνων αὐτὸν ἐκλέγοντα τῶν ἐν Ἰωνίᾳ.", "st": "5.21"}, {"sp": "N", "t": "οὕτω δὴ τόν τε Ἀπολλώνιον καὶ εἰ δή τις ἄλλος ἧκεν οὐ κατὰ προθεσμίαν τῶν πυκτῶν, τούτους μὲν οἱ Ἠλεῖοι τοῦ ἀγῶνος ἀπελαύνουσι, τῷ Ἡρακλείδῃ δὲ τὸν στέφανον παριᾶσιν ἀκονιτί· ἐνταῦθα ὁ Ἀπολλώνιος κατεσκευάσατό τε τοῖς ἱμᾶσιν ὡς ἐς μάχην καὶ ἐσδραμὼν ἐπὶ τὸν Ἡρακλείδην ἥπτετο ἐπικειμένου τε ἤδη τὸν κότινον καὶ καταπεφευγότος ἐς τοὺς Ἑλλανοδίκας. τούτῳ μὲν δὴ ἔμελλε τὸ κοῦφον τοῦ νοῦ βλάβος μέγα ἔσεσθαι, ἔστι δὲ καὶ", "st": "5.21"}, {"sp": "N", "t": "ἄλλα δύο τέχνης τῆς ἐφ’ ἡμῶν [τὰ] ἀγάλματα· ἕκτῃ γὰρ ἐπὶ ταῖς εἴκοσι καὶ διακοσίαις Ὀλυμπιάδι πύκτας ἄνδρας, ὑπὲρ αὐτῆς μαχομένους τῆς νίκης, ἐφώρασαν συνθεμένους ὑπὲρ λήμματος. ἀντὶ τούτων μὲν ἐγένετο ζημία· ποιηθέντων δὲ ἀγαλμάτων Διὸς τὸ μὲν ἐν ἀριστερᾷ τῆς ἐς τὸ στάδιον ἐσόδου, τὸ δὲ ἕτερον αὐτῶν ἕστηκεν ἐν δεξιᾷ. τοῖς δὲ πύκταις τούτοις Δίδας τε ὄνομα ἦν καὶ τῷ τὰ χρήματα δόντι αὐτῶν Σαραπάμμων· νομοῦ δὲ ἦσαν τοῦ αὐτοῦ, νεωτάτου τῶν ἐν Αἰγύπτῳ, καλουμένου δὲ Ἀρσινοΐτου.", "st": "5.21"}, {"sp": "N", "t": "θαῦμα μὲν δὴ καὶ ἄλλως ἐν οὐδενὸς λόγῳ τὸν θεὸν θέσθαι τὸν ἐν Ὀλυμπίᾳ καὶ δέξασθαί τινα ἢ δοῦναι δῶρα ἐπὶ τῷ ἀγῶνι· μείζονος δὲ ἔτι θαύματος, εἴ γε καὶ αὐτῶν ἐτόλμησεν ἤδη τις Ἠλείων. λέγεται δὲ ὡς Δαμόνικος τολμήσειεν Ἠλεῖος δευτέρᾳ πρὸς ταῖς ἑκατὸν καὶ ἐνενήκοντα Ὀλυμπιάδι· συνεστηκέναι μὲν γὰρ παλαίοντας ἐπὶ τῷ στεφάνῳ τόν τε τοῦ Δαμονίκου παῖδα Πολύκτορα καὶ Σώσανδρον γένος Σμυρναῖον, ὁμώνυμον τῷ πατρί· Δαμόνικον δέ, ἅτε περισσῶς ἐπιθυμοῦντα γενέσθαι τῷ παιδὶ τὴν νίκην, δοῦναι τοῦ Σωσάνδρου τῷ πατρὶ χρήματα.", "st": "5.21"}, {"sp": "N", "t": "ὡς δὲ ἐγεγόνει τὰ πραχθέντα ἔκπυστα, ἐπιβάλλουσιν οἱ Ἑλλανοδίκαι ζημίαν, ἐπιβάλλουσι δὲ οὐ τοῖς παισίν, ἀλλὰ ἐς τοὺς πατέρας ἔτρεψαν τὴν ὀργήν· οὗτοι γὰρ δὴ καὶ ἠδίκουν. ἀπὸ ταύτης τῆς ζημίας ἀγάλματα ἐποιήθη· καὶ τὸ μὲν ἐν τῷ Ἠλείων ἀνάκειται γυμνασίῳ, τὸ δὲ τῆς Ἄλτεως πρὸ τῆς Ποικίλης στοᾶς καλουμένης, ὅτι ἦσαν ἐπὶ τῶν τοίχων γραφαὶ τὸ ἀρχαῖον. εἰσὶ δ’ οἳ τὴν στοὰν ταύτην καὶ Ἠχοῦς ὀνομάζουσι· βοήσαντι δὲ ἀνδρὶ ἑπτάκις ὑπὸ τῆς ἠχοῦς ἡ φωνή, τὰ δὲ καὶ ἐπὶ πλέον ἔτι ἀποδίδοται.", "st": "5.21"}, {"sp": "N", "t": "παγκρατιαστὴν δέ φασιν Ἀλεξανδρέα, ὄνομα δὲ εἶναί οἱ Σαραπίωνα, τοῦτον ἐν Ὀλυμπιάδι τῇ πρώτῃ μετὰ τὰς διακοσίας ἐς τοσοῦτο δεῖσαι τοὺς ἀνταγωνιστὰς ὥστε ἡμέρᾳ μιᾷ πρότερον ἢ ἐσκληθήσεσθαι τὸ παγκράτιον ἔμελλεν ἀποδράντα οἴχεσθαι. τοῦτον ζημιωθέντα ἐπὶ δειλίᾳ μόνον τῶν τε ἄλλων ἀνθρώπων καὶ αὐτῶν μνημονεύουσιν Αἰγυπτίων. ταῦτα μὲν τὰ κατειλεγμένα ἐπὶ αἰτίαις τοιαῖσδε ποιηθέντα εὕρισκον·", "st": "5.21"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἀγάλματα Διὸς δημοσίᾳ τε καὶ ὑπὸ ἀνδρῶν ἀνατεθέντα ἰδιωτῶν. ἔστι δὲ βωμὸς ἐν τῇ Ἄλτει τῆς ἐσόδου πλησίον τῆς ἀγούσης ἐς τὸ στάδιον· ἐπὶ τούτου θεῶν μὲν οὐδενὶ θύουσιν Ἠλεῖοι, σαλπιγκταῖς δὲ ἐφεστηκόσιν αὐτῷ καὶ τοῖς κήρυξιν ἀγωνίζεσθαι καθέστηκε. παρὰ τοῦτον τὸν βωμὸν βάθρον τε πεποίηται χαλκοῦν καὶ ἄγαλμα ἐπ’ αὐτῷ Διός, μέγεθος μὲν ὅσον ἓξ πήχεις, κεραυνὸν δὲ ἐν ἑκατέρᾳ τῇ χειρὶ ἔχει· ἀνέθεσαν δὲ αὐτὸ Κυναιθαεῖς. ὁ δὲ περικείμενός τε τὸν ὅρμον καὶ ἡλικίαν παῖς ἔτι ἀνάθημα ἀνδρός ἐστι Φλιασίου Κλεόλα.", "st": "5.22"}, {"sp": "N", "t": "παρὰ δὲ τὸ Ἱπποδάμιον καλούμενον λίθου τε βάθρον ἐστὶ κύκλος ἥμισυς καὶ ἀγάλματα ἐπ’ αὐτῷ Ζεὺς καὶ Θέτις τε καὶ Ἡμέρα τὸν Δία ὑπὲρ τῶν τέκνων ἱκετεύουσαι. ταῦτα ἐπὶ μέσῳ τῷ βάθρῳ· οἱ δὲ ἤδη σχῆμα ἀντιτεταγμένων ὅ τε Ἀχιλλεὺς παρέχεται καὶ ὁ Μέμνων ἐπὶ ἑκατέρῳ τοῦ βάθρου τῷ πέρατι ἑκάτερος. ἀνθεστήκασι δὲ καὶ ἄλλος ἄλλῳ κατὰ τὰ αὐτά, ἀνὴρ βάρβαρος ἀνδρὶ Ἕλληνι, Ὀδυσσεὺς μὲν Ἑλένῳ, ὅτι οὗτοι μάλιστα ἐπὶ σοφίᾳ δόξαν ἐν ἑκατέρῳ τῷ στρατεύματι εἰλήφεσαν, Μενελάῳ δὲ κατὰ τὸ ἔχθος τὸ ἐξ ἀρχῆς Ἀλέξανδρος, Διομήδει δὲ Αἰνείας καὶ τῷ Τελαμῶνος Αἴαντι Δηίφοβος.", "st": "5.22"}, {"sp": "N", "t": "ταῦτά ἐστιν ἔργα μὲν Λυκίου τοῦ Μύρωνος, Ἀπολλωνιᾶται δὲ ἀνέθηκαν οἱ ἐν τῷ Ἰονίῳ· καὶ δὴ καὶ ἐλεγεῖον γράμμασίν ἐστιν ἀρχαίοις ὑπὸ τοῦ Διὸς τοῖς ποσί·<br>μνάματ’ Ἀπολλωνίας ἀνακείμεθα, τὰν ἐνὶ πόντῳ<br>Ἰονίῳ Φοῖβος ᾤκισ’ ἀκερσεκόμας·<br>οἳ γᾶς τέρμαθ’ ἑλόντες Ἀβαντίδος ἐνθάδε ταῦτα<br>ἔστασαν σὺν θεοῖς ἐκ Θρονίου δεκάταν.<br>ἡ δὲ Ἀβαντὶς καλουμένη χώρα καὶ πόλισμα ἐν αὐτῇ Θρόνιον τῆς Θεσπρωτίδος ἦσαν ἠπείρου κατὰ ὄρη τὰ Κεραύνια.", "st": "5.22"}, {"sp": "N", "t": "σκεδασθεισῶν γὰρ Ἕλλησιν, ὡς ἐκομίζοντο ἐξ Ἰλίου, τῶν νεῶν, Λοκροί τε ἐκ Θρονίου τῆς ἐπὶ Βοαγρίῳ ποταμῷ καὶ Ἄβαντες ἀπὸ Εὐβοίας ναυσὶν ὀκτὼ συναμφότεροι πρὸς τὰ ὄρη κατηνέχθησαν τὰ Κεραύνια. οἰκήσαντες δὲ ἐνταῦθα καὶ πόλιν οἰκίσαντες Θρόνιον, καὶ τῆς γῆς ἐφ’ ὅσον ἐνέμοντο Ἀβαντίδος ὄνομα ἀπὸ κοινοῦ λόγου θέμενοι, ἐκπίπτουσιν ὕστερον ὑπὸ Ἀπολλωνιατῶν ὁμόρων κρατηθέντες πολέμῳ. ἀποικισθῆναι δὲ ἐκ Κορκύρας τὴν Ἀπολλωνίαν, ⟨τὴν δὲ Κορινθίων εἶναί φασιν ἀποικίαν,⟩ οἱ δὲ Κορινθίοις αὐτοῖς μετεῖναι λαφύρων.", "st": "5.22"}, {"sp": "N", "t": "προελθόντι δὲ ὀλίγον Ζεύς ἐστι πρὸς ἀνίσχοντα τετραμμένος τὸν ἥλιον, ἀετὸν ἔχων τὸν ὄρνιθα καὶ τῇ ἑτέρᾳ τῶν χειρῶν κεραυνόν· ἐπίκειται δὲ αὐτῷ καὶ ἐπὶ τῇ κεφαλῇ στέφανος, ἄνθη τὰ ἠρινά. Μεταποντίνων δέ ἐστιν ἀνάθημα, Αἰγινήτου δὲ ἔργον Ἀριστόνου· τοῦ δὲ Ἀριστόνου τούτου διδάσκαλον, ἢ καθ’ ὅντινα χρόνον ἐγένετο, οὐκ ἴσμεν.", "st": "5.22"}, {"sp": "N", "t": "ἀνέθεσαν δὲ καὶ Φλιάσιοι Δία καὶ θυγατέρας τὰς Ἀσωποῦ καὶ αὐτὸν Ἀσωπόν, διακεκόσμηται δὲ οὕτω σφίσι τὰ ἀγάλματα. Νεμέα μὲν τῶν ἀδελφῶν πρώτη, μετὰ δὲ αὐτὴν Ζεὺς λαμβανόμενός ἐστιν Αἰγίνης, παρὰ δὲ τὴν Αἴγιναν ἕστηκεν Ἅρπινα—ταύτῃ τῷ Ἠλείων καὶ Φλιασίων λόγῳ συνεγένετο Ἄρης, καὶ Οἰνομάῳ δὲ μήτηρ τῷ περὶ τὴν Πισαίαν βασιλεύσαντί ἐστιν Ἅρπινα—, μετὰ δὲ αὐτὴν Κόρκυρά τε καὶ ἐπ’ αὐτῇ Θήβη, τελευταῖος δὲ ὁ Ἀσωπός. λέγεται δὲ ἐς μὲν Κόρκυραν ὡς μιχθείη Ποσειδῶν αὐτῇ· τοιαῦτα δὲ ἕτερα ᾖσε Πίνδαρος ἐς Θήβην τε καὶ ἐς Δία.", "st": "5.22"}, {"sp": "N", "t": "ἰδίᾳ δὲ ἄνδρες Λεοντῖνοι καὶ οὐκ ἀπὸ τοῦ κοινοῦ Δία ἀνέστησαν· μέγεθος μὲν τοῦ ἀγάλματος πήχεις εἰσὶν ἑπτά, ἐν δὲ ταῖς χερσὶν ἀετός τέ ἐστιν αὐτῷ καὶ τὸ βέλος τοῦ Διὸς κατὰ τοὺς τῶν ποιητῶν λόγους. ἀνέθεσαν δὲ Ἱππαγόρας τε καὶ Φρύνων καὶ Αἰνεσίδημος, ὃν ἄλλον πού τινα Αἰνεσίδημον δοκῶ καὶ οὐ τὸν τυραννήσαντα εἶναι Λεοντίνων.", "st": "5.22"}, {"sp": "N", "t": "παρεξιόντι δὲ παρὰ τὴν ἐς τὸ βουλευτήριον ἔσοδον Ζεύς τε ἕστηκεν ἐπίγραμμα ἔχων οὐδὲν καὶ αὖθις ὡς πρὸς ἄρκτον ἐπιστρέψαντι ἄγαλμά ἐστι Διός· τοῦτο τέτραπται μὲν πρὸς ἀνίσχοντα ἥλιον, ἀνέθεσαν δὲ Ἑλλήνων ὅσοι Πλαταιᾶσιν ἐμαχέσαντο ἐναντία Μαρδονίου τε καὶ Μήδων. εἰσὶ δὲ καὶ ἐγγεγραμμέναι κατὰ τοῦ βάθρου τὰ δεξιὰ αἱ μετασχοῦσαι πόλεις τοῦ ἔργου, Λακεδαιμόνιοι μὲν πρῶτοι, μετὰ δὲ αὐτοὺς Ἀθηναῖοι, τρίτοι δὲ γεγραμμένοι καὶ τέταρτοι Κορίνθιοί τε καὶ Σικυώνιοι,", "st": "5.23"}, {"sp": "N", "t": "πέμπτοι δὲ Αἰγινῆται, μετὰ δὲ Αἰγινήτας Μεγαρεῖς καὶ Ἐπιδαύριοι, Ἀρκάδων δὲ Τεγεᾶταί τε καὶ Ὀρχομένιοι, ἐπὶ δὲ αὐτοῖς ὅσοι Φλιοῦντα καὶ Τροίζηνα καὶ Ἑρμιόνα οἰκοῦσιν, ἐκ δὲ χώρας τῆς Ἀργείας Τιρύνθιοι, Πλαταιεῖς δὲ μόνοι Βοιωτῶν, καὶ Ἀργείων οἱ Μυκήνας ἔχοντες, νησιῶται δὲ Κεῖοι καὶ Μήλιοι, Ἀμβρακιῶται δὲ ἐξ ἠπείρου τῆς Θεσπρωτίδος, Τήνιοί τε καὶ Λεπρεᾶται, Λεπρεᾶται μὲν τῶν ἐκ τῆς Τριφυλίας μόνοι, ἐκ δὲ Αἰγαίου καὶ τῶν Κυκλάδων οὐ Τήνιοι μόνοι ἀλλὰ καὶ Νάξιοι καὶ Κύθνιοι, ἀπὸ δὲ Εὐβοίας Στυρεῖς, μετὰ δὲ τούτους Ἠλεῖοι καὶ Ποτιδαιᾶται καὶ Ἀνακτόριοι, τελευταῖοι δὲ Χαλκιδεῖς οἱ ἐπὶ τῷ Εὐρίπῳ.", "st": "5.23"}, {"sp": "N", "t": "τούτων τῶν πόλεων τοσαίδε ἦσαν ἐφ’ ἡμῶν ἔρημοι· Μυκηναῖοι μὲν καὶ Τιρύνθιοι [ὑπὸ] τῶν Μηδικῶν ὕστερον ἐγένοντο ὑπὸ Ἀργείων ἀνάστατοι· Ἀμβρακιώτας δὲ καὶ Ἀνακτορίους ἀποίκους Κορινθίων ὄντας ἐπηγάγετο ὁ Ῥωμαίων βασιλεὺς ἐς Νικοπόλεως συνοικισμὸν πρὸς τῷ Ἀκτίῳ· Ποτιδαιάτας δὲ δὶς μὲν ἐπέλαβεν ἀναστάτους ἐκ τῆς σφετέρας ὑπὸ Φιλίππου τε γενέσθαι τοῦ Ἀμύντου καὶ πρότερον ἔτι ὑπὸ Ἀθηναίων, χρόνῳ δὲ ὕστερον Κάσσανδρος κατήγαγε μὲν Ποτιδαιάτας ἐπὶ τὰ οἰκεῖα, ὄνομα δὲ οὐ τὸ ἀρχαῖον τῇ πόλει, Κασσάνδρεια δὲ ἐγένετο ἀπὸ τοῦ οἰκιστοῦ. τὸ δὲ ἄγαλμα ἐν Ὀλυμπίᾳ τὸ ἀνατεθὲν ὑπὸ τῶν Ἑλλήνων ἐποίησεν Ἀναξαγόρας Αἰγινήτης· τοῦτον οἱ συγγράψαντες τὰ ἐς Πλαταιὰς παριᾶσιν ἐν τοῖς λόγοις.", "st": "5.23"}, {"sp": "N", "t": "ἔστι δὲ πρὸ τοῦ Διὸς τούτου στήλη χαλκῆ, Λακεδαιμονίων καὶ Ἀθηναίων συνθήκας ἔχουσα εἰρήνης ἐς τριάκοντα ἐτῶν ἀριθμόν. ταύτας ἐποιήσαντο Ἀθηναῖοι παραστησάμενοι τὸ δεύτερον Εὔβοιαν, ἔτει τρίτῳ τῆς ⟨τρίτης πρὸς τὰς ὀγδοήκοντα⟩ Ὀλυμπιάδος, ἣν Κρίσων Ἱμεραῖος ἐνίκα στάδιον. ἔστι δὲ ἐν ταῖς συνθήκαις καὶ τόδε εἰρημένον, εἰρήνης μὲν τῆς Ἀθηναίων καὶ Λακεδαιμονίων τῇ Ἀργείων μὴ μετεῖναι πόλει, ἰδίᾳ δὲ Ἀθηναίους καὶ Ἀργείους, ἢν ἐθέλωσιν, ἐπιτηδείως ἔχειν πρὸς ἀλλήλους. αὗται μὲν λέγουσι τοιαῦτα αἱ συνθῆκαι, Διὸς δὲ ἄλλο ἄγαλμα παρὰ τὸ ἅρμα", "st": "5.23"}, {"sp": "N", "t": "ἀνάκειται τὸ Κλεοσθένους· τούτου μὲν δὴ ἡμῖν καὶ ἐν τοῖς ἔπειτα ἔσται μνήμη, τὸ δὲ ἄγαλμα τοῦ Διὸς Μεγαρέων μέν ἐστιν ἀνάθημα, ἀδελφοὶ δὲ αὐτὸ Ψύλακός τε καὶ Ὄναιθος καὶ οἱ παῖδες οἱ τούτων εἰργάσαντο· ἡλικίαν δὲ αὐτῶν ἢ πατρίδα ἢ παρ’ ᾧ τινι ἐδιδάχθησαν, οὐκ ἔχω δηλῶσαι.", "st": "5.23"}, {"sp": "N", "t": "πρὸς δὲ τῷ ἅρματι τῷ Γέλωνος Ζεὺς ἕστηκεν ἀρχαῖος ἔχων σκῆπτρον, Ὑβλαίων δέ φασιν εἶναι ἀνάθημα· αἱ δὲ ἦσαν ἐν Σικελίᾳ πόλεις αἱ Ὕβλαι, ⟨ἡ μὲν⟩ Γερεᾶτις ἐπίκλησιν, τὴν δὲ—ὥσπερ γε καὶ ⟨ἦν⟩ —ἐκάλουν Μείζονα. ἔχουσι δὲ καὶ κατ’ ἐμὲ ἔτι τὰ ὀνόματα, ἐν τῇ Καταναίᾳ δὲ ἡ μὲν ἔρημος ἐς ἅπαν, ἡ δὲ κώμη τε Καταναίων ἡ Γερεᾶτις καὶ ἱερόν σφισιν Ὑβλαίας ἐστὶ θεοῦ, παρὰ Σικελιωτῶν ἔχον τιμάς. παρὰ τούτων δὲ κομισθῆναι τὸ ἄγαλμα ἐς Ὀλυμπίαν ἡγοῦμαι· τεράτων γὰρ σφᾶς καὶ ἐνυπνίων Φίλιστος ὁ Ἀρχομενίδου φησὶν ἐξηγητὰς εἶναι καὶ μάλιστα εὐσεβείᾳ τῶν ἐν Σικελίᾳ βαρβάρων προσκεῖσθαι.", "st": "5.23"}, {"sp": "N", "t": "πλησίον δὲ τοῦ Ὑβλαίων ἀναθήματος βάθρον τε πεποίηται χαλκοῦν καὶ ἐπ’ αὐτῷ Ζεύς· τοῦτον ὀκτὼ μάλιστα εἶναι ποδῶν καὶ δέκα εἰκάζομεν. οἵτινες δὲ αὐτὸν ἔδοσαν τῷ θεῷ καὶ ὧντινών ἐστιν ἔργον, ἐλεγεῖον γεγραμμένον σημαίνει·<br>Κλειτόριοι τόδ’ ἄγαλμα θεῷ δεκάταν ἀνέθηκαν,<br>πολλᾶν ἐκ πολίων χερσὶ βιασσάμενοι.<br>†καιμετρειτ Ἀρίστων ἠδὲ Τελέστας<br>αὐτοκασίγνητοι καλὰ Λάκωνες ἔθεν.<br>τούτους οὐκ ἐς ἅπαν τὸ Ἑλληνικὸν ἐπιφανεῖς νομίζω γενέσθαι· εἶχον γὰρ ἄν τι καὶ Ἠλεῖοι περὶ αὐτῶν λέγειν, καὶ πλέονα ἔτι Λακεδαιμόνιοι πολιτῶν γε ὄντων.", "st": "5.23"}, {"sp": "N", "t": "παρὰ δὲ τοῦ Λαοίτα Διὸς καὶ Ποσειδῶνος Λαοίτα [δὲ], παρὰ τούτων τὸν βωμὸν Ζεὺς ἐπὶ χαλκοῦ βάθρου δῶρον μὲν τοῦ Κορινθίων δήμου, Μούσου δέ ἐστι ποίημα, ὅστις δὴ οὗτός ἐστιν ὁ Μοῦσος. ἀπὸ δὲ τοῦ βουλευτηρίου πρὸς τὸν ναὸν ἐρχομένῳ τὸν μέγαν ἔστιν ἄγαλμα ἐν ἀριστερᾷ Διός, ἐστεφανωμένον δὲ οἷα δὴ ἄνθεσι, καὶ ἐν τῇ δεξιᾷ χειρὶ αὐτοῦ κεραυνὸς πεποίηται. τοῦτο δέ ἐστιν Ἀσκάρου τέχνη Θηβαίου, διδαχθέντος παρὰ τῷ Σικυωνίῳ ⟨Κανάχῳ· τὸ δὲ ἐπίγραμμα τὸ ἐπ’ αὐτῷ δεκάτην ἀπὸ τοῦ πολέμου Φωκέων⟩ καὶ Θεσσαλῶν φησιν εἶναι.", "st": "5.24"}, {"sp": "N", "t": "εἰ δὲ Φωκεῦσιν ἐς πόλεμόν τινα οὗτοι κατέστησαν καὶ ἔστιν ἀπὸ Φωκέων αὐτοῖς τὸ ἀνάθημα, οὐκ ἂν ⟨ὅ γε⟩ ἱερὸς καλούμενος εἴη πόλεμος, ὃν δὲ πρότερον ἔτι ἐπολέμησαν πρὶν ἢ Μήδους καὶ βασιλέα ἐπὶ τὴν Ἑλλάδα διαβῆναι. τούτου δὲ οὐ πόρρω Ζεύς ἐστιν, ὅντινα ἀναθεῖναι Ψωφιδίους ἐπὶ πολέμου κατορθώματι τὸ ἔπος τὸ ἐπ’ αὐτῷ γεγραμμένον δηλοῖ.", "st": "5.24"}, {"sp": "N", "t": "τοῦ ναοῦ δέ ἐστιν ἐν δεξιᾷ τοῦ μεγάλου Ζεὺς πρὸς ἀνατολὰς ἡλίου, μέγεθος μὲν δυόδεκα ποδῶν, ἀνάθημα δὲ λέγουσιν εἶναι Λακεδαιμονίων, ἡνίκα ἀποστᾶσι Μεσσηνίοις δεύτερα τότε ἐς πόλεμον κατέστησαν· ἔπεστι δὲ καὶ ἐλεγεῖον ἐπ’ αὐτῷ,<br>Δέξο ἄναξ Κρονίδα Ζεῦ Ὀλύμπιε καλὸν ἄγαλμα<br>ἱλάῳ θυμῷ τοῖς Λακεδαιμονίοις.", "st": "5.24"}, {"sp": "N", "t": "Ῥωμαίων δὲ οὔτε ἄνδρα ἰδιώτην οὔτε ὁπόσοι τῆς βουλῆς οὐδένα Μομμίου πρότερον ἀνάθημα ἴσμεν ἐς ἱερὸν ἀναθέντα Ἑλληνικόν, Μόμμιος δὲ ἀπὸ λαφύρων ἀνέθηκε τῶν ἐξ Ἀχαΐας Δία ἐς Ὀλυμπίαν χαλκοῦν· οὗτος ἕστηκεν ἐν ἀριστερᾷ τοῦ Λακεδαιμονίων ἀναθήματος, παρὰ τὸν πρῶτον ταύτῃ τοῦ ναοῦ κίονα. ὃ δὲ ἐν τῇ Ἄλτει μέγιστον τῶν χαλκῶν ἐστιν ἀγαλμάτων τοῦ Διός, ἀνετέθη μὲν ὑπὸ αὐτῶν Ἠλείων ἀπὸ τοῦ πρὸς Ἀρκάδας πολέμου, μέγεθος δὲ ἑπτὰ καὶ εἴκοσι ποδῶν ἐστι.", "st": "5.24"}, {"sp": "N", "t": "παρὰ δὲ τῷ Πελοπίῳ κίων τε οὐχ ὑψηλὸς καὶ ἄγαλμα Διός ἐστιν ἐπ’ αὐτῷ μικρόν, τὴν ἑτέραν τῶν χειρῶν προτεῖνον. τούτου δὲ ἀπαντικρὺ ἄλλα ἐστὶν ἀναθήματα ἐπὶ στοίχου, ὡς δὲ αὔτως Διὸς καὶ Γανυμήδους ἀγάλματα· ἔστι δὲ Ὁμήρῳ πεποιημένα ὡς ἁρπασθείη τε ὑπὸ θεῶν Γανυμήδης οἰνοχοεῖν Διὶ καὶ ὡς Τρωὶ δῶρα ἵπποι δοθεῖεν ἀντ’ αὐτοῦ. τοῦτο ἀνέθηκε μὲν Γνᾶθις Θεσσαλός, ἐποίησε δὲ Ἀριστοκλῆς μαθητής τε καὶ υἱὸς Κλεοίτα.", "st": "5.24"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος Ζεὺς οὐκ ἔχων πω γένεια, κεῖται δὲ ἐν τοῖς ἀναθήμασι τοῖς Μικύθου. τὰ δὲ ἐς Μίκυθον, γένος τε ὁποῖον ἦν αὐτῷ καὶ ἀνθ’ ὅτου τὰ ἀναθήματα ἐς Ὀλυμπίαν τὰ πολλὰ ἀνέθηκεν, ὁ ἐφεξῆς μοι λόγος δηλώσει. ἀπὸ δὲ τοῦ ἀγάλματος τοῦ εἰρημένου προελθόντι ὀλίγον κατ’ εὐθεῖαν ἄγαλμά ἐστι Διὸς οὐκ ἔχον γένεια οὐδὲ αὐτό, Ἐλαϊτῶν δὲ ἀνάθημα, οἳ καταβάντι ἐκ Καΐκου πεδίου ἐς θάλασσαν πρῶτοι ⟨ἐν⟩ τῇ Αἰολίδι οἰκοῦσι.", "st": "5.24"}, {"sp": "N", "t": "τούτου δὲ αὖθις ἄλλο ἄγαλμα ἔχεται Διός, τὸ δὲ ἐπίγραμμα τὸ ἐπ’ αὐτῷ τοὺς ἐν Κνίδῳ Χερρονησίους ἀπὸ ἀνδρῶν ἀναθεῖναι πολεμίων φησίν· ἀνέθεσαν δὲ ἑκατέρωθεν παρὰ τὸν Δία Πέλοπά τε καὶ τὸν Ἀλφειὸν ποταμόν. Κνιδίοις δὲ τῆς πόλεως τὸ μὲν πολὺ ἐν τῇ ἠπείρῳ πεπόλισται τῇ Καρικῇ, ἔνθα καὶ τὰ λόγου μάλιστα ⟨ἄξια⟩ αὐτοῖς ἐστιν, ἡ δὲ καλουμένη Χερρόνησός ἐστιν ἐπὶ τῇ ἠπείρῳ κειμένη νῆσος γεφύρᾳ διαβατὸς ἐξ αὐτῆς·", "st": "5.24"}, {"sp": "N", "t": "καὶ τὰ ἀναθήματα ἀνέθεσαν ἐν Ὀλυμπίᾳ τῷ Διὶ ⟨οἱ⟩ ἐνταῦθα οἰκοῦντες, ὡς εἰ τῆς Ἐφεσίων πόλεως οἱ ἔχοντες τὸν ὀνομαζόμενον Κόρησον ἀνάθημα ⟨φαῖεν⟩ ἰδίᾳ τι ἀναθεῖναι τοῦ Ἐφεσίων κοινοῦ. ἔστι δὲ καὶ πρὸς τῷ τείχει τῆς Ἄλτεως Ζεὺς ἐπὶ ἡλίου τετραμμένος δυσμάς, ἐπίγραμμα οὐδὲν παρεχόμενος· ἐλέγετο δὲ καὶ οὗτος Μομμίου τε καὶ ἀπὸ τοῦ Ἀχαιῶν εἶναι πολέμου.", "st": "5.24"}, {"sp": "N", "t": "ὁ δὲ ἐν τῷ βουλευτηρίῳ πάντων ὁπόσα ἀγάλματα Διὸς μάλιστα ἐς ἔκπληξιν ἀδίκων ἀνδρῶν πεποίηται· ἐπίκλησις μὲν Ὅρκιός ἐστιν αὐτῷ, ἔχει δὲ ἐν ἑκατέρᾳ κεραυνὸν χειρί. παρὰ τούτῳ καθέστηκε τοῖς ἀθληταῖς καὶ πατράσιν αὐτῶν καὶ ἀδελφοῖς, ἔτι δὲ γυμνασταῖς ἐπὶ κάπρου κατόμνυσθαι τομίων, μηδὲν ἐς τὸν Ὀλυμπίων ἀγῶνα ἔσεσθαι παρ’ αὐτῶν κακούργημα. οἱ δὲ ἄνδρες οἱ ἀθληταὶ καὶ τόδε ἔτι προσκατόμνυνται, δέκα ἐφεξῆς μηνῶν ἀπηκριβῶσθαί σφισι τὰ πάντα ἐς ἄσκησιν.", "st": "5.24"}, {"sp": "N", "t": "ὀμνύουσι δὲ καὶ ὅσοι τοὺς παῖδας ἢ τῶν ἵππων τῶν ἀγωνιζομένων τοὺς πώλους κρίνουσιν, ἐπὶ δικαίῳ καὶ ἄνευ δώρων ποιεῖσθαι κρίσιν, καὶ τὰ ἐς τὸν δοκιμαζόμενόν τε καὶ μή, φυλάξειν καὶ ταῦτα ἐν ἀπορρήτῳ. τῷ κάπρῳ δὲ ὅ τι χρῆσθαί σφισι μετὰ τῶν ἀθλητῶν τὸν ὅρκον καθέστηκεν, οὐκ ἐμνημόνευσα ἐπερέσθαι, ἐπεὶ τοῖς γε ἀρχαιοτέροις ἐπὶ ἱερεῖα ἦν καθεστηκός, ἐφ’ ᾧ τις ὅρκον ἐποιήσατο, μηδὲ ἐδώδιμον εἶναι τοῦτο ἔτι ἀνθρώπῳ. δηλοῖ δὲ οὐχ ἥκιστα καὶ Ὅμηρος·", "st": "5.24"}, {"sp": "N", "t": "τὸν γοῦν κάπρον καθ’ ὅτου τῶν τομίων Ἀγαμέμνων ἐπώμοσεν ἦ μὴν εἶναι τὴν Βρισηίδα ἑαυτοῦ τῆς εὐνῆς ἀπείρατον, τοῦτον τὸν κάπρον ἀφιέμενον ὑπὸ τοῦ κήρυκος ἐποίησεν ἐς θάλασσαν·<br>ἦ, καὶ ἀπὸ σφάραγον κάπρου τάμε νηλέι χαλκῷ.<br>τὸν μὲν Ταλθύβιος πολιῆς ἁλὸς ἐς μέγα λαῖτμα<br>ῥῖψ’ ἐπιδινήσας, βόσιν ἰχθύσιν.<br>οὕτω μὲν τὸ ἀρχαῖον τὰ τοιαῦτα ἐνόμιζον· ἔστι δὲ πρὸ τῶν ποδῶν τοῦ Ὁρκίου πινάκιον χαλκοῦν, ἐπιγέγραπται δὲ ἐλεγεῖα ἐπ’ αὐτοῦ, δεῖμα ἐθέλοντα τοῖς ἐπιορκοῦσι παριστάναι.", "st": "5.24"}, {"sp": "N", "t": "τοσαῦτα ἐντὸς τῆς Ἄλτεως ἀγάλματα εἶναι Διὸς ἀνηριθμησάμεθα ἐς τὸ ἀκριβέστατον. τὸ ἀνάθημα γὰρ τὸ πρὸς τῷ μεγάλῳ ναῷ ὑπὸ ἀνδρὸς Κορινθίου τεθέν, Κορινθίων δὲ οὐ τῶν ἀρχαίων ἀλλ’ οἳ παρὰ βασιλέως ἔχουσιν εἰληφότες τὴν πόλιν, τοῦτο τὸ ἀνάθημα Ἀλέξανδρός ἐστιν ὁ Φιλίππου, Διὶ εἰκασμένος δῆθεν. ὁπόσα δὲ ἀλλοῖα καὶ οὐ μίμησίς ἐστι Διός, ἐπιμνησόμεθα καὶ τούτων· εἰκόνας δὲ οὐ τιμῇ τῇ πρὸς τὸ θεῖον, τῇ δὲ ἐς αὐτοὺς χάριτι ἀνατεθείσας τοὺς ἀνθρώπους, λόγῳ σφᾶς τῷ ἐς τοὺς ἀθλητὰς ἀναμίξομεν.", "st": "5.25"}, {"sp": "N", "t": "Μεσσηνίους τοὺς ἐπὶ τῷ πορθμῷ κατὰ ἔθος δή τι ἀρχαῖον πέμποντας ἐς Ῥήγιον χορὸν παίδων πέντε ἀριθμὸν καὶ τριάκοντα καὶ διδάσκαλόν τε ὁμοῦ τῷ χορῷ καὶ ἄνδρα αὐλητὴν ἐς ἑορτήν τινα ἐπιχώριον Ῥηγίνων, κατέλαβεν αὐτούς ποτε συμφορά, μηδένα ὀπίσω τῶν ἀποσταλέντων σφίσιν ἀποσωθῆναι· ἀλλὰ ἡ ναῦς ἡ ἄγουσα τοὺς παῖδας ἠφανίσθη σὺν αὐτοῖς κατὰ τοῦ βυθοῦ. ἔστι γὰρ δὴ ἡ κατὰ τοῦτον θάλασσα τὸν πορθμὸν θαλάσσης χειμεριωτάτη πάσης·", "st": "5.25"}, {"sp": "N", "t": "οἵ τε γὰρ ἄνεμοι ταράσσουσιν αὐτὴν ἀμφοτέρωθεν τὸ κῦμα ἐπάγοντες ἐκ τοῦ Ἀδρίου καὶ ἐξ ἑτέρου πελάγους ὃ καλεῖται Τυρσηνόν, ἤν τε καὶ ἀνέμων ἀπῇ πνεύματα, ὁ δὲ καὶ τηνικαῦτα ὁ πορθμὸς κίνησιν βιαιοτάτην αὐτὸς ἐξ αὑτοῦ καὶ ἰσχυρὰς παρέχεται παλιρροίας· θηρία τε τοσαῦτα ἐς αὐτὸν τὰ ἀθροιζόμενά ἐστιν, ὡς καὶ τὸν ἀέρα τὸν ὑπὲρ τῆς θαλάσσης ταύτης ἀναπίμπλασθαι τῶν θηρίων τῆς ὀσμῆς, ὡς σωτηρίας γε ἐκ τοῦ πορθμοῦ μηδὲ ἐλπίδος τι ὑπολείπεσθαι ναυαγῷ. εἰ δὲ ἐνταῦθα συνέπεσε καὶ Ὀδυσσεῖ διαφθαρῆναι τὴν ναῦν, ἄλλως μὲν οὐκ ἄν τις πείθοιτο ἐκνήξασθαι ζῶντα ἐς τὴν Ἰταλίαν αὐτόν· τὸ δὲ ἐκ τῶν θεῶν εὐμενὲς ἐπὶ παντὶ ἐργάζεται ῥᾳστώνην.", "st": "5.25"}, {"sp": "N", "t": "τότε δὲ ἐπὶ τῇ ἀπωλείᾳ τῶν παίδων οἱ Μεσσήνιοι πένθος ἦγον, καὶ ἄλλα τέ σφισιν ἐς τιμὴν αὐτῶν ἐξευρέθη καὶ εἰκόνας ἐς Ὀλυμπίαν ἀνέθεσαν χαλκᾶς, σὺν δὲ αὐτοῖς τὸν διδάσκαλον τοῦ χοροῦ καὶ τὸν αὐλητήν. τὸ μὲν δὴ ἐπίγραμμα ἐδήλου τὸ ἀρχαῖον ἀναθήματα εἶναι τῶν ἐν πορθμῷ Μεσσηνίων· χρόνῳ δὲ ὕστερον Ἱππίας ὁ λεγόμενος ὑπὸ Ἑλλήνων γενέσθαι σοφὸς τὰ ἐλεγεῖα ἐπ’ αὐτοῖς ἐποίησεν. ἔργα δέ εἰσιν Ἠλείου Κάλλωνος αἱ εἰκόνες.", "st": "5.25"}, {"sp": "N", "t": "ἔστι δὲ κατὰ τὴν ἄκραν ἐν Σικελίᾳ τὴν τετραμμένην ἐπὶ Λιβύης καὶ Νότου, καλουμένην δὲ Πάχυνον, Μοτύη πόλις· οἰκοῦσι δὲ Λίβυες ἐν αὐτῇ καὶ Φοίνικες. τούτοις τοῖς ἐν Μοτύῃ βαρβάροις Ἀκραγαντῖνοι καταστάντες ἐς πόλεμον καὶ λείαν τε καὶ λάφυρα ἀπ’ αὐτῶν λαβόντες ἀνέθεσαν τοὺς παῖδας ἐς Ὀλυμπίαν τοὺς χαλκοῦς, προτείνοντάς τε τὰς δεξιὰς καὶ εἰκασμένους εὐχομένοις τῷ θεῷ. κεῖνται δὲ ἐπὶ τοῦ τείχους οὗτοι τῆς Ἄλτεως· Καλάμιδος δὲ εἶναι σφᾶς ἔργα ἐγώ τε εἴκαζον καὶ ἐς αὐτοὺς κατὰ τὰ αὐτὰ εἶχεν ὁ λόγος.", "st": "5.25"}, {"sp": "N", "t": "Σικελίαν δὲ ἔθνη τοσάδε οἰκεῖ, Σικανοί τε καὶ Σικελοὶ καὶ Φρύγες, οἱ μὲν ἐξ Ἰταλίας διαβεβηκότες ἐς αὐτήν, Φρύγες δὲ ἀπὸ τοῦ Σκαμάνδρου ποταμοῦ καὶ χώρας τῆς Τρῳάδος· οἱ δὲ Φοίνικες καὶ Λίβυες στόλῳ ἀφίκοντο ἐς τὴν νῆσον κοινῷ καὶ ἄποικοι Καρχηδονίων εἰσὶ. τοσαῦτα μὲν ἐν Σικελίᾳ ἔθνη βάρβαρα· Ἑλλήνων δὲ Δωριεῖς τε ἔχουσιν αὐτὴν καὶ Ἴωνες καὶ τοῦ Φωκικοῦ καὶ τοῦ Ἀττικοῦ γένους ἑκατέρου μοῖρα οὐ πολλή.", "st": "5.25"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ αὐτοῦ τείχους τά τε Ἀκραγαντίνων ἀναθήματα καὶ Ἡρακλέους δύο εἰσὶν ἀνδριάντες γυμνοί, παῖδες ἡλικίαν· τὸν δὲ ἐν Νεμέᾳ τοξεύοντι ἔοικε λέοντα. τοῦτον μὲν δὴ τόν τε Ἡρακλέα καὶ ὁμοῦ τῷ Ἡρακλεῖ τὸν λέοντα Ταραντῖνος ἀνέθηκεν Ἱπποτίων, Νικοδάμου δέ ἐστι Μαιναλίου τέχνη· τὸ δὲ ἄγαλμα τὸ ἕτερον Ἀναξίππου μέν ἐστιν ἀνάθημα Μενδαίου, μετεκομίσθη δὲ ἐνταῦθα ὑπὸ Ἠλείων· τὰ πρὸ τούτου δὲ ἔκειτο ἐπὶ τῆς ὁδοῦ τῷ πέρατι, ἣ ἄγει μὲν ἐξ Ἤλιδος ἐς Ὀλυμπίαν, καλεῖται δὲ Ἱερά.", "st": "5.25"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἀναθήματα ἐν κοινῷ τοῦ Ἀχαιῶν ἔθνους, ὅσοι προκαλεσαμένου τοῦ Ἕκτορος ἐς μονομαχίαν ἄνδρα Ἕλληνα τὸν κλῆρον ἐπὶ τῷ ἀγῶνι ὑπέμειναν. οὗτοι μὲν δὴ ἑστήκασι τοῦ ναοῦ τοῦ μεγάλου πλησίον, δόρασι καὶ ἀσπίσιν ὡπλισμένοι· ἀπαντικρὺ δὲ ἐπὶ ἑτέρου βάθρου πεποίηται Νέστωρ, τὸν ἑκάστου κλῆρον ἐσβεβληκὼς ἐς τὴν κυνῆν. τῶν δὲ ἐπὶ τῷ Ἕκτορι κληρουμένων ἀριθμὸν ὄντων ὀκτώ—τὸν γὰρ ἔνατον αὐτῶν, τὴν τοῦ Ὀδυσσέως εἰκόνα, Νέρωνα κομίσαι λέγουσιν ἐς Ῥώμην —, τῶν δὲ ὀκτὼ τούτων ἐπὶ μόνῳ τῷ [ἀγάλματι]", "st": "5.25"}, {"sp": "N", "t": "Ἀγαμέμνονι τὸ ὄνομά ἐστι γεγραμμένον· γέγραπται δὲ καὶ τοῦτο ἐπὶ τὰ λαιὰ ἐκ δεξιῶν. ὅτου δὲ ὁ ἀλεκτρυών ἐστιν ἐπίθημα τῇ ἀσπίδι, Ἰδομενεύς ἐστιν ὁ ἀπόγονος Μίνω· τῷ δὲ Ἰδομενεῖ γένος ἀπὸ Ἡλίου τοῦ πατρὸς Πασιφάης, Ἡλίου δὲ ἱερόν φασιν εἶναι τὸν ὄρνιθα καὶ ἀγγέλλειν ἀνιέναι μέλλοντος τοῦ ἡλίου.", "st": "5.25"}, {"sp": "N", "t": "γέγραπται δὲ καὶ ἐπίγραμμα ἐπὶ τῷ βάθρῳ·<br>τῷ Διὶ τἈχαιοὶ τἀγάλματα ταῦτ’ ἀνέθηκαν,<br>ἔγγονοι ἀντιθέου Τανταλίδα Πέλοπος.<br>τοῦτο μὲν δὴ ἐνταῦθά ἐστι γεγραμμένον· ὁ δὲ ἀγαλματοποιὸς ὅστις ἦν, ἐπὶ τοῦ Ἰδομενέως γέγραπται τῇ ἀσπίδι·<br>πολλὰ μὲν ἄλλα σοφοῦ ποιήματα καὶ τόδ’ Ὀνάτα<br>[ἔργον] Αἰγινήτεω, τὸν γείνατο παῖδα Μίκων.", "st": "5.25"}, {"sp": "N", "t": "οὐ πόρρω δὲ τοῦ Ἀχαιῶν ἀναθήματος καὶ Ἡρακλῆς ἐστιν ὑπὲρ τοῦ ζωστῆρος μαχόμενος πρὸς τὴν Ἀμαζόνα ἔφιππον γυναῖκα· τοῦτον Εὐαγόρας μὲν γένος Ζαγκλαῖος ἀνέθηκεν, ἐποίησε δὲ Κυδωνιάτης Ἀριστοκλῆς. ἐν δὲ τοῖς μάλιστα ἀρχαίοις καταριθμήσασθαι καὶ τὸν Ἀριστοκλέα ἔστι· καὶ σαφῶς μὲν ἡλικίαν οὐκ ἔχοι τις ἂν εἰπεῖν αὐτοῦ, δῆλα δὲ ὡς πρότερον ἔτι ἐγένετο πρὶν ἢ τῇ Ζάγκλῃ τὸ ὄνομα γενέσθαι τὸ ἐφ’ ἡμῶν Μεσσήνην.", "st": "5.25"}, {"sp": "N", "t": "Θάσιοι δέ, Φοίνικες τὸ ἀνέκαθεν ὄντες καὶ ἐκ Τύρου καὶ Φοινίκης τῆς ἄλλης ὁμοῦ Θάσῳ τῷ Ἀγήνορος κατὰ ζήτησιν ἐκπλεύσαντες τὴν Εὐρώπης, ἀνέθεσαν Ἡρακλέα ἐς Ὀλυμπίαν, τὸ βάθρον χαλκοῦν ὁμοίως τῷ ἀγάλματι· μέγεθος μὲν δὴ τοῦ ἀγάλματός εἰσι πήχεις δέκα, ῥόπαλον δὲ ἐν τῇ δεξιᾷ, τῇ δὲ ἀριστερᾷ χειρὶ ἔχει τόξον. ἤκουσα δὲ ἐν Θάσῳ τὸν αὐτὸν σφᾶς Ἡρακλέα ὃν καὶ Τύριοι σέβεσθαι, ὕστερον δὲ ἤδη τελοῦντας ἐς Ἕλληνας νομίσαι καὶ Ἡρακλεῖ τῷ Ἀμφιτρύωνος νέμειν τιμάς.", "st": "5.25"}, {"sp": "N", "t": "τῷ δὲ ἀναθήματι τῷ ἐς Ὀλυμπίαν Θασίων ἔπεστιν ἐλεγεῖον·<br>υἱὸς μέν ⟨με⟩ Μίκωνος Ὀνάτας ἐξετέλεσσεν<br>αὐτὸς ἐν Αἰγίνῃ δώματα ναιετάων.<br>τὸν δὲ Ὀνάταν τοῦτον ὅμως, καὶ τέχνης ἐς τὰ ἀγάλματα ὄντα Αἰγιναίας, οὐδενὸς ὕστερον θήσομεν τῶν ἀπὸ Δαιδάλου τε καὶ ἐργαστηρίου τοῦ Ἀττικοῦ.", "st": "5.25"}, {"sp": "N", "t": "Μεσσηνίων δὲ τῶν Δωριέων οἱ Ναύπακτόν ποτε παρὰ Ἀθηναίων λαβόντες ἄγαλμα ἐν Ὀλυμπίᾳ Νίκης ἐπὶ τῷ κίονι ἀνέθεσαν· τοῦτό ἐστιν ἔργον μὲν Μενδαίου Παιωνίου, πεποίηται δὲ ἀπὸ ἀνδρῶν πολεμίων, ὅτε Ἀκαρνᾶσι καὶ Οἰνιάδαις ἐμοὶ δοκεῖν ἐπολέμησαν. Μεσσήνιοι δὲ αὐτοὶ λέγουσι τὸ ἀνάθημά σφισιν ἀπὸ τοῦ ἔργου τοῦ ἐν τῇ Σφακτηρίᾳ νήσῳ μετὰ Ἀθηναίων ⟨πραχθέντος εἶναι⟩, καὶ οὐκ ἐπιγράψαι τὸ ὄνομα τῶν πολεμίων σφᾶς τῷ ἀπὸ Λακεδαιμονίων δείματι, ἐπεὶ Οἰνιαδῶν γε καὶ Ἀκαρνάνων οὐδένα ἔχειν φόβον.", "st": "5.26"}, {"sp": "N", "t": "τὰ δὲ ἀναθήματα Μικύθου πολλά τε ἀριθμὸν καὶ οὐκ ἐφεξῆς ὄντα εὕρισκον, ἀλλὰ Ἰφίτου μὲν τοῦ Ἠλείου καὶ Ἐκεχειρίας στεφανούσης τὸν Ἴφιτον, τούτων μὲν τῶν εἰκόνων ἔχεται τοσάδε ἀναθήματα τῶν Μικύθου, Ἀμφιτρίτη καὶ Ποσειδῶν τε καὶ Ἑστία· Γλαῦκος δὲ ὁ ποιήσας ἐστὶν Ἀργεῖος. παρὰ δὲ τοῦ ναοῦ τοῦ μεγάλου τὴν ἐν ἀριστερᾷ πλευρὰν ἀνέθηκεν ἄλλα, Κόρην τὴν Δήμητρος καὶ Ἀφροδίτην Γανυμήδην τε καὶ Ἄρτεμιν, ποιητῶν δὲ Ὅμηρον καὶ Ἡσίοδον, καὶ θεοὺς αὖθις Ἀσκληπιὸν καὶ Ὑγείαν.", "st": "5.26"}, {"sp": "N", "t": "Ἀγών τε ἐν τοῖς ἀναθήμασίν ἐστι τοῖς Μικύθου φέρων ἁλτῆρας, οἱ δὲ ἁλτῆρες οὗτοι παρέχονται σχῆμα τοιόνδε· κύκλου παραμηκεστέρου καὶ οὐκ ἐς τὸ ἀκριβέστατον περιφεροῦς εἰσιν ἥμισυ, πεποίηται δὲ ὡς καὶ τοὺς δακτύλους τῶν χειρῶν διιέναι καθάπερ δι’ ὀχάνων ἀσπίδος. τούτων μὲν δὴ σχῆμά ἐστι τὸ εἰρημένον· παρὰ δὲ τοῦ Ἀγῶνος τὴν εἰκόνα Διόνυσος καὶ ὁ Θρᾷξ ἐστιν Ὀρφεὺς καὶ ἄγαλμα Διός, οὗ δὴ καὶ ὀλίγῳ πρότερον ἐπεμνήσθην. ταῦτα ἔργα ἐστὶν Ἀργείου Διονυσίου· τεθῆναι δὲ ὑπὸ τοῦ Μικύθου καὶ ἄλλα ὁμοῦ τούτοις λέγουσι, Νέρωνα δὲ ἀφελέσθαι φασὶ καὶ ταῦτα.", "st": "5.26"}, {"sp": "N", "t": "τοῖς δὲ ἐργασαμένοις αὐτά, γένος οὖσιν Ἀργείοις, Διονυσίῳ τε καὶ Γλαύκῳ, διδάσκαλόν σφισιν οὐδένα ἐπιλέγουσιν· ἡλικίαν δὲ αὐτῶν ὁ τὰ ἔργα ἐς Ὀλυμπίαν ἀναθεὶς ἐπιδείκνυσιν ὁ Μίκυθος. τὸν γὰρ δὴ Μίκυθον τοῦτον Ἡρόδοτος ἔφη ἐν τοῖς λόγοις, ὡς Ἀναξίλα τοῦ ἐν Ῥηγίῳ τυραννήσαντος γενόμενος δοῦλος καὶ ταμίας τῶν Ἀναξίλα χρημάτων ὕστερον τούτων ἀπιὼν οἴχοιτο ἐς Τεγέαν τελευτήσαντος Ἀναξίλα.", "st": "5.26"}, {"sp": "N", "t": "τὰ δὲ ἐπὶ τοῖς ἀναθήμασιν ἐπιγράμματα καὶ πατέρα Μικύθῳ Χοῖρον καὶ Ἑλληνίδας αὐτῷ πόλεις Ῥήγιόν τε πατρίδα καὶ τὴν ἐπὶ τῷ πορθμῷ Μεσσήνην δίδωσιν· οἰκεῖν δὲ τὰ μὲν ἐπιγράμματα ἐν Τεγέᾳ φησιν αὐτόν, τὰ δὲ ἀναθήματα ἀνέθηκεν ἐς Ὀλυμπίαν εὐχήν τινα ἐκτελῶν ἐπὶ σωτηρίᾳ παιδὸς νοσήσαντος νόσον φθινάδα.", "st": "5.26"}, {"sp": "N", "t": "πλησίον δὲ τῶν μειζόνων ἀναθημάτων Μικύθου, τέχνης δὲ τοῦ Ἀργείου Γλαύκου, Ἀθηνᾶς ἄγαλμα ἕστηκε κράνος ἐπικειμένη καὶ αἰγίδα ἐνδεδυκυῖα· Νικόδαμος μὲν εἰργάσατο ὁ Μαινάλιος, Ἠλείων δέ ἐστιν ἀνάθημα. παρὰ δὲ τὴν Ἀθηνᾶν πεποίηται Νίκη· ταύτην Μαντινεῖς ἀνέθεσαν, τὸν πόλεμον δὲ οὐ δηλοῦσιν ἐν τῷ ἐπιγράμματι· Κάλαμις δὲ οὐκ ἔχουσαν πτερὰ ποιῆσαι λέγεται ἀπομιμούμενος τὸ Ἀθήνῃσι τῆς Ἀπτέρου καλουμένης ξόανον.", "st": "5.26"}, {"sp": "N", "t": "πρὸς δὲ τοῖς ἐλάσσοσιν ἀναθήμασι τοῦ Μικύθου, ποιηθεῖσι δὲ ὑπὸ Διονυσίου, πρὸς τούτοις Ἡρακλέους ἐστὶ τῶν ἔργων τὸ ἐς τὸν λέοντα τὸν ἐν Νεμέᾳ καὶ ὕδραν τε καὶ ἐς τὸν κύνα τοῦ Ἅιδου καὶ τὸν ἐπὶ Ἐρυμάνθῳ ποταμῷ κάπρον· ἐκόμισαν δὲ αὐτὰ ἐς Ὀλυμπίαν Ἡρακλεῶται Μαριανδυνῶν ὁμόρων βαρβάρων καταδραμόντες τὴν χώραν. ἡ δὲ Ἡράκλεια πεπόλισται μὲν ἐπὶ Εὐξείνῳ πόντῳ, ἀπῳκίσθη δὲ ἐκ Μεγάρων· μετέσχον δὲ καὶ Βοιωτῶν Ταναγραῖοι τοῦ οἰκισμοῦ.", "st": "5.26"}, {"sp": "N", "t": "τούτων δὲ ἀντικρὺ τῶν κατειλεγμένων ἔστιν ἄλλα ἀναθήματα ἐπὶ στοίχου, τετραμμένα μὲν πρὸς μεσημβρίαν, τοῦ τεμένους δὲ ἐγγύτατα ὃ τῷ Πέλοπι ἀνεῖται. ἐν δὲ αὐτοῖς καὶ τὰ ἀνατεθέντα ἐστὶν ὑπὸ τοῦ Μαιναλίου Φόρμιδος, ὃς ἐκ Μαινάλου διαβὰς ἐς Σικελίαν παρὰ Γέλωνα τὸν Δεινομένους καὶ ἐκείνῳ τε αὐτῷ καὶ Ἱέρωνι ὕστερον ἀδελφῷ τοῦ Γέλωνος ἐς τὰς στρατείας ἀποδεικνύμενος λαμπρὰ ἔργα ἐς τοσοῦτο προῆλθεν εὐδαιμονίας, ὡς ἀναθεῖναι μὲν ταῦτα ἐς Ὀλυμπίαν, ἀναθεῖναι δὲ καὶ τῷ Ἀπόλλωνι [δὲ] ἄλλα ἐς Δελφούς.", "st": "5.27"}, {"sp": "N", "t": "τὰ δὲ ἐς Ὀλυμπίαν δύο τέ εἰσιν ἵπποι καὶ ἡνίοχοι δύο, ἑκατέρῳ τῶν ἵππων παρεστὼς ἀνὴρ ἡνίοχος· ὁ μὲν δὴ πρότερος τῶν ἵππων καὶ ὁ ἀνὴρ Διονυσίου τοῦ Ἀργείου, τὰ δεύτερα δὲ ἔργα ἐστὶν Αἰγινήτου Σίμωνος. τῷ προτέρῳ δὲ τῶν ἵππων ἐπίγραμμα ἔπεστιν ἐπὶ τῇ πλευρᾷ, τὰ πρῶτα οὐ σὺν μέτρῳ· λέγει γὰρ δὴ οὕτω·<br>Φόρμις ἀνέθηκεν<br>Ἀρκὰς Μαινάλιος, νῦν δὲ Συρακόσιος.", "st": "5.27"}, {"sp": "N", "t": "οὗτός ἐστιν ὁ ἵππος ὅτῳ καὶ τὸ ἱππομανὲς λόγῳ τῷ Ἠλείων ἔγκειται· δῆλα δὲ καὶ ἄλλως ἐστὶν ἀνδρὸς μάγου σοφίᾳ γενέσθαι ⟨τὰ⟩ συμβαίνοντα τῷ ἵππῳ. μέγεθος μὲν ἢ εἶδος ἵππων ἀποδεῖ πολλῷ, ὅσοι τῆς Ἄλτεως ἐντὸς ἑστήκασι, πρὸς δὲ ἀποκέκοπταί τε τὴν οὐρὰν καὶ ἔστιν ἐπὶ τῷ τοιῷδε ἔτι αἰσχίων· οἱ δὲ ἵπποι οἱ ἄρσενες οὔτι που τοῦ ἦρος μόνον ἀλλὰ καὶ ἀνὰ πᾶσαν ἐπ’ αὐτὸν ὀργῶσιν ἡμέραν.", "st": "5.27"}, {"sp": "N", "t": "καὶ γὰρ ἐσθέουσιν ἐς τὴν Ἄλτιν ἀπορρηγνύοντες ⟨τὰ⟩ δεσμὰ ἢ καὶ ἐκφεύγοντες τοὺς ἄγοντας καὶ ἐπιπηδῶσιν αὐτῷ πολλῷ δή τι ἐμμανέστερον ἢ ἐπὶ τὴν καλλίστην ἵππον ζῶσάν τε καὶ ἠθάδα ἀναβαίνεσθαι· ἀπολισθάνουσί τε δὴ αὐτοῖς αἱ ὁπλαὶ καὶ ὅμως οὐκ ἀπαγορεύουσι χρεμετίζοντές τε μᾶλλον καὶ ἐπιπηδῶντες μετὰ βιαιοτέρας τῆς ὁρμῆς, πρὶν ἂν ὑπὸ μαστίγων καὶ ἀνάγκης ἰσχυρᾶς ἀφελκυσθῶσι· πρότερον δὲ οὐκ ἔστιν ἀπαλλαγή σφισιν οὐδεμία ἀπὸ τοῦ χαλκοῦ.", "st": "5.27"}, {"sp": "N", "t": "καὶ ἄλλο ἐν Λυδίᾳ θεασάμενος οἶδα διάφορον μὲν θαῦμα ἢ κατὰ τὸν ἵππον τὸν Φόρμιδος, μάγων μέντοι σοφίας οὐδὲ αὐτὸ ἀπηλλαγμένον. ἔστι γὰρ Λυδοῖς ἐπίκλησιν Περσικοῖς ἱερὰ ἔν τε Ἱεροκαισαρείᾳ καλουμένῃ πόλει καὶ ἐν Ὑπαίποις, ἐν ἑκατέρῳ δὲ τῶν ἱερῶν οἴκημά τε καὶ ἐν τῷ οἰκήματί ἐστιν ἐπὶ βωμοῦ τέφρα· χρόα δὲ οὐ κατὰ τέφραν ἐστὶν αὐτῇ τὴν ἄλλην.", "st": "5.27"}, {"sp": "N", "t": "ἐσελθὼν δὲ ἐς τὸ οἴκημα ἀνὴρ μάγος καὶ ξύλα ἐπιφορήσας αὖα ἐπὶ τὸν βωμὸν πρῶτα μὲν τιάραν ἐπέθετο ἐπὶ τῇ κεφαλῇ, δεύτερα δὲ ἐπίκλησιν ὅτου δὴ θεῶν ἐπᾴδει βάρβαρα καὶ οὐδαμῶς συνετὰ Ἕλλησιν· ἐπᾴδει δὲ ἐπιλεγόμενος ἐκ βιβλίου· ἄνευ τε δὴ πυρὸς ἀνάγκη πᾶσα ἁφθῆναι τὰ ξύλα καὶ περιφανῆ φλόγα ἐξ αὐτῶν ἐκλάμψαι.", "st": "5.27"}, {"sp": "N", "t": "τάδε μὲν ἐς τοσοῦτο ἡμῖν δεδηλώσθω· ἔστι δὲ ἐν τοῖς ἀναθήμασι τούτοις καὶ αὐτὸς ὁ Φόρμις ἀνδρὶ ἀνθεστηκὼς πολεμίῳ, καὶ ἐφεξῆς ἑτέρῳ καὶ τρίτῳ γε αὖθις μάχεται. γέγραπται δὲ ἐπὶ τούτοις τὸν στρατιώτην μὲν τὸν μαχόμενον Φόρμιν εἶναι τὸν Μαινάλιον, τὸν δὲ ἀναθέντα Συρακόσιον Λυκόρταν· δῆλα δὲ ὡς οὗτος ὁ Λυκόρτας κατὰ φιλίαν ἀναθείη τοῦ Φόρμιδος. τὰ δὲ ἀναθήματα τοῦ Λυκόρτα καλεῖται Φόρμιδος καὶ ταῦτα ὑπὸ Ἑλλήνων.", "st": "5.27"}, {"sp": "N", "t": "ὁ δὲ Ἑρμῆς ὁ τὸν κριὸν φέρων ὑπὸ τῇ μασχάλῃ καὶ ἐπικείμενος τῇ κεφαλῇ κυνῆν καὶ χιτῶνά τε καὶ χλαμύδα ἐνδεδυκὼς οὐ τῶν Φόρμιδος ἔτι ἀναθημάτων ἐστίν, ὑπὸ δὲ Ἀρκάδων ⟨τῶν⟩ ἐκ Φενεοῦ δέδοται τῷ θεῷ· Ὀνάταν δὲ τὸν Αἰγινήτην, σὺν δὲ αὐτῷ Καλλιτέλην ἐργάσασθαι λέγει τὸ ἐπίγραμμα, δοκεῖν δέ μοι τοῦ Ὀνάτα μαθητὴς ἢ παῖς ὁ Καλλιτέλης ἦν. οὐ πόρρω δὲ τοῦ Φενεατῶν ἀναθήματος ἄλλο ἐστὶν ἄγαλμα, κηρυκεῖον Ἑρμῆς ἔχων· ἐπίγραμμα δὲ ἐπ’ αὐτῷ Γλαυκίαν ἀναθεῖναι γένος Ῥηγῖνον, ποιῆσαι δὲ Κάλλωνα Ἠλεῖον.", "st": "5.27"}, {"sp": "N", "t": "βοῶν δὲ τῶν χαλκῶν ὁ μὲν Κορκυραίων, ὁ δὲ ἀνάθημα Ἐρετριέων, τέχνη δὲ Ἐρετριέως ἐστὶ Φιλησίου· καὶ ἀνθ’ ὅτου μὲν οἱ Κορκυραῖοι τόν τε ἐν Ὀλυμπίᾳ καὶ ἕτερον βοῦν ἐς Δελφοὺς ἀνέθεσαν, δηλώσει μοι τὰ ἐς Φωκέας τοῦ λόγου, ἐπὶ δὲ τῷ Ὀλυμπίασιν αὐτῶν ἀναθήματι συμβῆναι τοιόνδε ἤκουσα.", "st": "5.27"}, {"sp": "N", "t": "παῖς μικρὸς ὑπὸ τούτῳ καθήμενος τῷ βοῒ ἐς τὸ κάτω νενευκὼς ἔπαιζεν· ἀνασχὼν δὲ ἐξαίφνης τὴν κεφαλὴν κατεάγη τε αὐτὴν πρὸς τὸν χαλκὸν καὶ ἐκ τοῦ τραύματος ἡμέραις ὕστερον ἀπέθανεν οὐ πολλαῖς. Ἠλεῖοι μὲν δὴ τὸν βοῦν ἅτε αἵματι ἔνοχον ἐβουλεύοντο ἐκκομίσαι τῆς Ἄλτεως· ὁ δὲ σφᾶς [ὁ] θεὸς ὁ ἐν Δελφοῖς κατὰ ⟨χώραν ἐᾶν⟩ τὸ ἀνάθημα καθάρσια ἔχρα ἐπ’ αὐτῷ ποιησαμένους, ὁπόσα Ἕλληνες ἐπὶ ἀκουσίῳ φόνῳ νομίζουσιν.", "st": "5.27"}, {"sp": "N", "t": "ἔστι δὲ ὑπὸ ταῖς ἐν τῇ Ἄλτει πλατάνοις κατὰ μέσον μάλιστά που τὸν περίβολον τρόπαιον χαλκοῦν καὶ ἐπίγραμμα ἐπὶ τοῦ τροπαίου τῇ ἀσπίδι, Ἠλείους ἀπὸ Λακεδαιμονίων ἀναστῆσαι. ἐν ταύτῃ τῇ μάχῃ καὶ τὸν ἄνδρα ἐπέλαβεν ἐκεῖνον ἀφεῖναι τὴν ψυχήν, ὃς τοῦ Ἡραίου τῆς ὀροφῆς κατ’ ἐμὲ ἀνασκευαζομένης ἐνταῦθα ὁμοῦ τοῖς ὅπλοις εὑρέθη κείμενος.", "st": "5.27"}, {"sp": "N", "t": "τῶν δὲ ἐν Θρᾴκῃ Μενδαίων τὸ ἀνάθημα ἐγγύτατα ἀφίκετο ἀπατῆσαί με ὡς ἀνδρὸς εἰκὼν εἴη πεντάθλου· καὶ κεῖται μὲν παρὰ τὸν Ἠλεῖον Ἀναυχίδαν, ἔχει δὲ ἁλτῆρας ἀρχαίους. ἐλεγεῖον δὲ ἐπ’ αὐτὸ γεγραμμένον ἐστὶν ἐπὶ τοῦ μηροῦ·<br>Ζηνὶ θεῶν βασιλεῖ μ’ ἀκροθίνιον ἐνθάδ’ ἔθηκαν<br>Μενδαῖοι, Σίπτην χερσὶ βιασσάμενοι.<br>τὸ μὲν δὴ Θρᾴκιόν τι εἶναι τεῖχος καὶ πόλις ἔοικεν, ἡ Σίπτη· Μενδαίοις δὲ αὐτοῖς γένος τε Ἑλληνικὸν καὶ ἀπὸ Ἰωνίας ἐστίν, οἰκοῦσι δὲ ἀπὸ θαλάσσης ἄνω τῆς πρὸς Αἴνῳ πόλει.", "st": "5.27"}, {"sp": "HDR", "t": "Βιβλίον Ϛʹ — Ἠλιακῶν Βʹ", "st": "6"}, {"sp": "N", "t": "ἕπεται δέ μοι τῷ λόγῳ τῷ ἐς τὰ ἀναθήματα τὸ μετὰ τοῦτο ἤδη ποιήσασθαι καὶ ἵππων ἀγωνιστῶν μνήμην καὶ ἀνδρῶν ἀθλητῶν τε καὶ ἰδιωτῶν ὁμοίως. τῶν δὲ νικησάντων Ὀλυμπίασιν οὐχ ἁπάντων εἰσὶν ἑστηκότες ἀνδριάντες, ἀλλὰ καὶ ἀποδειξάμενοι λαμπρὰ ἐς τὸν ἀγῶνα, οἱ δὲ καὶ ἐπὶ ἄλλοις ἔργοις, ὅμως οὐ τετυχήκασιν εἰκόνων·", "st": "6.1"}, {"sp": "N", "t": "τούτους ἐκέλευσεν ἀφεῖναί με ὁ λόγος, ὅτι οὐ κατάλογός ἐστιν ἀθλητῶν ὁπόσοις γεγόνασιν Ὀλυμπικαὶ νῖκαι, ἀναθημάτων δὲ ἄλλων τε καὶ εἰκόνων συγγραφή. οὐδὲ ὁπόσων ἑστήκασιν ἀνδριάντες, οὐδὲ τούτοις πᾶσιν ἐπέξειμι, ἐπιστάμενος ὅσοι τῷ παραλόγῳ τοῦ κλήρου καὶ οὐχ ὑπὸ ἰσχύος ἀνείλοντο ἤδη τὸν κότινον· ὁπόσοις δὲ ἢ αὐτοῖς ⟨τι⟩ εἶχεν ἐς δόξαν ἢ καὶ τοῖς ἀνδριᾶσιν ὑπῆρχεν ἄμεινον ἑτέρων πεποιῆσθαι, τοσαῦτα καὶ αὐτὸς μνησθήσομαι.", "st": "6.1"}, {"sp": "N", "t": "ἔστιν ἐν δεξιᾷ τοῦ ναοῦ τῆς Ἥρας ἀνδρὸς εἰκὼν παλαιστοῦ, γένος δὲ ἦν Ἠλεῖος, Σύμμαχος Αἰσχύλου· παρὰ δὲ αὐτὸν ἐκ Φενεοῦ τῆς Ἀρκάδων Νεολαΐδας Προξένου, πυγμῆς ἐν παισὶν ἀνῃρημένος νίκην· ἐφεξῆς δὲ Ἀρχέδαμος Ξενίου, καταβαλὼν καὶ οὗτος παλαιστὰς παῖδας, γένος καὶ αὐτὸς Ἠλεῖος. τούτων τῶν κατειλεγμένων εἰργάσατο Ἄλυπος τὰς εἰκόνας Σικυώνιος, Ναυκύδους τοῦ Ἀργείου μαθητής.", "st": "6.1"}, {"sp": "N", "t": "Κλεογένην δὲ Σιληνοῦ τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ φησιν εἶναι τῶν ἐπιχωρίων, ἐκ δὲ ἀγέλης αὐτὸν οἰκείας ἵππῳ κρατῆσαι κέλητι. πλησίον δὲ τοῦ Κλεογένους Δεινόλοχός τε κεῖται Πύρρου [τε] καὶ Τρωίλος Ἀλκίνου. τούτοις γένος μὲν καὶ αὐτοῖς ἐστιν ἐξ Ἤλιδος, γεγόνασι δέ σφισιν οὐ κατὰ ταὐτὰ αἱ νῖκαι· ἀλλὰ τῷ μὲν ἑλλανοδικεῖν τε ὁμοῦ καὶ ἵππων ὑπῆρξεν ἀνελέσθαι νίκας τῷ Τρωίλῳ [δὲ] τελείᾳ τε συνωρίδι καὶ πώλων ἅρματι —Ὀλυμπιάδι δὲ ἐκράτει δευτέρᾳ πρὸς ταῖς ἑκατόν,", "st": "6.1"}, {"sp": "N", "t": "ἀπὸ τούτου δὲ καὶ νόμος ἐγένετο Ἠλείοις μηδὲ ἵππους τοῦ λοιποῦ τῶν ἑλλανοδικούντων καθιέναι μηδένα—, τούτου μὲν δὴ τὸν ἀνδριάντα ἐποίησε Λύσιππος· ἡ δὲ τοῦ Δεινολόχου μήτηρ εἶδεν ὄψιν ὀνείρατος ὡς ἔχοιτο τοῦ παιδὸς ἐν τοῖς κόλποις ἐστεφανωμένου, καὶ τοῦδε ἕνεκα ἐς τὸν ἀγῶνα ὁ Δεινόλοχος ἠσκήθη καὶ τοὺς παῖδας παρέθει τρέχων. Σικυωνίου δὲ Κλέωνός ἐστιν ⟨ἡ⟩ εἰκών.", "st": "6.1"}, {"sp": "N", "t": "ἐς δὲ τὴν Ἀρχιδάμου Κυνίσκαν, ἐς τὸ γένος τε αὐτῆς καὶ ἐπὶ ταῖς Ὀλυμπικαῖς νίκαις, πρότερον ἔτι ἐδήλωσα ἐν τοῖς λόγοις οἳ ἐς τοὺς βασιλέας τοὺς Λακεδαιμονίων ἔχουσι· πεποίηται δὲ ἐν Ὀλυμπίᾳ παρὰ τὸν ἀνδριάντα τοῦ Τρωίλου λίθου κρηπὶς καὶ ἅρμα τε ἵππων καὶ ἀνὴρ ἡνίοχος καὶ αὐτῆς Κυνίσκας εἰκών, Ἀπελλοῦ τέχνη, γέγραπται δὲ καὶ ἐπιγράμματα ἐς τὴν Κυνίσκαν ἔχοντα.", "st": "6.1"}, {"sp": "N", "t": "εἰσὶ δὲ Λακεδαιμόνιοι καὶ ἐφεξῆς ἀνακείμενοι τῇ Κυνίσκᾳ, ἵππων νῖκαι γεγόνασιν αὐτοῖς· Ἀνάξανδρος μὲν ἅρματι ἀνηγορεύθη πρῶτος, τὸ δὲ ἐπίγραμμά φησι τὸ ἐπ’ αὐτῷ τοῦ πατρὸς τοῦ Ἀναξάνδρου πρότερον ἔτι στεφανωθῆναι τὸν πατέρα πεντάθλῳ. οὗτος μὲν δὴ ἔοικεν εὐχόμενος τῷ θεῷ, Πολυκλῆς ⟨δὲ⟩ ἐπίκλησιν λαβὼν Πολύχαλκος τεθρίππῳ μὲν καὶ οὗτος ἐκράτησεν, ἡ δὲ εἰκὼν ἐπὶ τῇ χειρὶ ἔχει οἱ τῇ δεξιᾷ ταινίαν·", "st": "6.1"}, {"sp": "N", "t": "παρὰ δὲ αὐτῷ παιδία δύο τὸ μὲν τροχὸν κατέχει, τὸ δὲ αἰτεῖ τὴν ταινίαν. ἐνίκησε δὲ ὁ Πολυκλῆς ἵπποις, ὡς τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ λέγει, καὶ Πυθοῖ καὶ Ἰσθμοῖ τε καὶ Νεμέᾳ.", "st": "6.1"}, {"sp": "N", "t": "παγκρατιαστοῦ δὲ ἀνδρὸς τὸν μὲν ἀνδριάντα εἰργάσατο Λύσιππος· ὁ δὲ ἀνὴρ οὗτος ἀνείλετο ἐπὶ παγκρατίῳ νίκην τῶν ἄλλων τε Ἀκαρνάνων καὶ τῶν ἐξ αὐτῆς Στράτου πρῶτος Ξενάρκης τε ἐκαλεῖτο Φιλανδρίδου. Λακεδαιμόνιοι δὲ ἄρα μετὰ τὴν ἐπιστρατείαν τοῦ Μήδου διετέθησαν πάντων φιλοτιμότατα Ἑλλήνων πρὸς ἵππων τροφάς. χωρὶς γὰρ ἢ ὅσους αὐτῶν κατέλεξα ἤδη, τοσοίδε ἄλλοι τῶν ἐκ Σπάρτης ἱπποτρόφων μετὰ τὴν εἰκόνα ἀνάκεινται τοῦ Ἀκαρνᾶνος ἀθλητοῦ, Ξενάρκης καὶ Λυκῖνος Ἀρκεσίλαός τε καὶ ὁ παῖς τοῦ Ἀρκεσιλάου Λίχας.", "st": "6.2"}, {"sp": "N", "t": "Ξενάρκει μὲν δὴ καὶ ἐν Δελφοῖς καὶ ἐν Ἄργει τε ὑπῆρξε καὶ ἐν Κορίνθῳ προσανελέσθαι νίκας· Λυκῖνος δὲ ἀγαγὼν ἐς Ὀλυμπίαν πώλους, καὶ οὐ δοκιμασθέντος ἑνὸς ἐξ αὐτῶν, καθῆκεν ἐς τῶν ἵππων τὸν δρόμον τῶν τελείων τοὺς πώλους καὶ ἐνίκα δι’ αὐτῶν, ἀνέθηκε δὲ καὶ ἀνδριάντας δύο ἐς Ὀλυμπίαν, Μύρωνος τοῦ Ἀθηναίου ποιήματα. τῷ δὲ Ἀρκεσιλάῳ καὶ Λίχᾳ τῷ παιδί, τῷ μὲν αὐτῶν γεγόνασι δύο Ὀλυμπικαὶ νῖκαι, Λίχας δὲ εἰργομένων τηνικαῦτα τοῦ ἀγῶνος Λακεδαιμονίων καθῆκεν ἐπὶ ὀνόματι τοῦ Θηβαίων δήμου τὸ ἅρμα, τὸν δὲ ἡνίοχον νικήσαντα ἀνέδησεν αὐτὸς ταινίᾳ· καὶ ἐπὶ τούτῳ μαστιγοῦσιν αὐτὸν οἱ Ἑλλανοδίκαι, καὶ διὰ τὸν Λίχαν τοῦτον ἡ κατὰ", "st": "6.2"}, {"sp": "N", "t": "Ἆγιν βασιλέα ἐπιστρατεία Λακεδαιμονίων ἐγένετο ἐπὶ Ἠλείους καὶ ἐντὸς τῆς Ἄλτεως μάχη. καταπαυσθέντος δὲ τοῦ πολέμου τὴν μὲν εἰκόνα ἐνταῦθα ἔστησε, τὰ δὲ Ἠλείων ἐς τοὺς Ὀλυμπιονίκας [καὶ] γράμματα οὐ Λίχαν, Θηβαίων δὲ τὸν δῆμον ἔχει νενικηκότα.", "st": "6.2"}, {"sp": "N", "t": "τοῦ δὲ Λίχα πλησίον μάντις ἕστηκεν Ἠλεῖος Θρασύβουλος Αἰνέου τῶν Ἰαμιδῶν, ὃς καὶ Μαντινεῦσιν ἐμαντεύσατο ἐναντία Λακεδαιμονίων καὶ Ἄγιδος τοῦ Εὐδαμίδου βασιλέως· ἃ δὴ καὶ ἐς πλέον ἐν τῷ λόγῳ τῷ ἐς Ἀρκάδας ἐπέξειμι. τοῦ Θρασυβούλου δὲ τῇ εἰκόνι γαλεώτης πρὸς τὸν ὦμον προσέρπων ἐστὶ τὸν δεξιόν, καὶ κύων ἱερεῖον δὴ παρ’ αὐτῷ κεῖται διατετμημένος τε δίχα καὶ φαίνων τὸ ἧπαρ.", "st": "6.2"}, {"sp": "N", "t": "μαντικὴ δὲ ἡ μὲν ⟨δι’⟩ ἐρίφων καὶ ἀρνῶν τε καὶ μόσχων ἐκ παλαιοῦ δήλη καθεστῶσά ἐστιν ἀνθρώποις, Κύπριοι δὲ ὡς καὶ ὑσὶν ἐπεξευρόντες ἔστι μαντεύεσθαι, κυσὶ δὲ οὐδένες ἐπί γε μαντικῆς νομίζουσιν οὐδὲν χρᾶσθαι· ἔοικεν οὖν ἰδίαν τινὰ ὁ Θρασύβουλος ἐπὶ σπλάγχνων μαντικὴν κυνείων καταστήσασθαι. οἱ δ’ Ἰαμίδαι καλούμενοι μάντεις γεγόνασιν ἀπὸ Ἰάμου· τὸν δὲ εἶναι παῖδα Ἀπόλλωνος καὶ λαβεῖν μαντικήν φησιν ἐν ᾄσματι Πίνδαρος.", "st": "6.2"}, {"sp": "N", "t": "παρὰ δὲ τοῦ Θρασυβούλου τὴν εἰκόνα Τιμοσθένης τε Ἠλεῖος ἕστηκε σταδίου νίκην ἐν παισὶν εἰληφὼς καὶ Μιλήσιος Ἀντίπατρος Κλεινοπάτρου παῖδας κατειργασμένος πύκτας. Συρακοσίων δὲ ἄνδρες, ἄγοντες ἐς Ὀλυμπίαν παρὰ Διονυσίου θυσίαν, τὸν πατέρα τοῦ Ἀντιπάτρου χρήμασιν ἀναπείθουσιν ἀναγορευθῆναί οἱ τὸν παῖδα ἐκ Συρακουσῶν· Ἀντίπατρος δὲ ἐν οὐδενὶ τοῦ τυράννου τὰ δῶρα ἡγούμενος ἀνεῖπεν αὑτὸν Μιλήσιον καὶ ἀνέγραψε τῇ εἰκόνι ὡς γένος τε εἴη Μιλήσιος καὶ Ἰώνων ἀναθείη πρῶτος ἐς Ὀλυμπίαν εἰκόνα.", "st": "6.2"}, {"sp": "N", "t": "τούτου μὲν δὴ Πολύκλειτος τὸν ἀνδριάντα εἰργάσατο, τὸν δὲ Τιμοσθένην Εὐτυχίδης Σικυώνιος παρὰ Λυσίππῳ δεδιδαγμένος· ὁ δὲ Εὐτυχίδης οὗτος καὶ Σύροις τοῖς ἐπὶ Ὀρόντῃ Τύχης ἐποίησεν ἄγαλμα, μεγάλας παρὰ τῶν ἐπιχωρίων ἔχον τιμάς.", "st": "6.2"}, {"sp": "N", "t": "ἐν δὲ τῇ Ἄλτει παρὰ τὸν τοῦ Τιμοσθένους ἀνδριάντα ἀνάκειται Τίμων καὶ ὁ παῖς τοῦ Τίμωνος Αἴσυπος, παιδίον ἐπὶ ἵππῳ καθήμενον· ἔστι γὰρ δὴ καὶ ἡ νίκη τῷ παιδὶ ἵππου κέλητος, ὁ Τίμων δὲ ἐπὶ ἅρματι ἀνηγορεύθη. τῷ δὲ Τίμωνι εἰργάσατο καὶ τῷ παιδὶ τὰς εἰκόνας Δαίδαλος Σικυώνιος, ὃς καὶ ἐπὶ τῇ Λακωνικῇ νίκῃ τὸ ἐν τῇ Ἄλτει τρόπαιον ἐποίησεν Ἠλείοις.", "st": "6.2"}, {"sp": "N", "t": "ἐπίγραμμα δὲ τὸ ἐπὶ τῷ Σαμίῳ πύκτῃ τὸν ἀναθέντα μὲν ὅτι ὁ παιδοτρίβης εἴη Μύκων καὶ ὅτι Σάμιοι τὰ ἐς ἀθλητὰς καὶ ἐπὶ ναυμαχίαις εἰσὶν Ἰώνων ἄριστοι, τάδε μὲν λέγει τὸ ἐπίγραμμα, ἐς δὲ αὐτὸν τὸν πύκτην ἐσήμαινεν οὐδέν.", "st": "6.2"}, {"sp": "N", "t": "παρὰ δὲ Μεσσήνιος Δαμίσκος, ὃς δύο γεγονὼς ἔτη καὶ δέκα ἐνίκησεν ἐν Ὀλυμπίᾳ. θαῦμα δὲ εἴπερ ἄλλο τι καὶ τόδε ἐποιησάμην· Μεσσηνίους γὰρ ἐκ Πελοποννήσου φεύγοντας ἐπέλιπεν ἡ περὶ τὸν ἀγῶνα τύχη τὸν Ὀλυμπικόν. ὅτι γὰρ μὴ Λεοντίσκος καὶ Σύμμαχος τῶν ἐπὶ πορθμῷ Μεσσηνίων, ἄλλος γε οὐδεὶς Μεσσήνιος οὔτε Σικελιώτης οὔτ’ ἐκ Ναυπάκτου δῆλός ἐστιν Ὀλυμπίασιν ἀνῃρημένος νίκην· εἶναι δὲ οἱ Σικελιῶται καὶ τούτους τῶν ἀρχαίων Ζαγκλαίων καὶ οὐ Μεσσηνίους φασί.", "st": "6.2"}, {"sp": "N", "t": "συγκατῆλθε μέντοι Μεσσηνίοις ἐς Πελοπόννησον καὶ ἡ περὶ τὸν ἀγῶνα τύχη τὸν Ὀλυμπικόν· ἐνιαυτῷ γὰρ ὕστερον τοῦ οἰκισμοῦ τοῦ Μεσσήνης ἀγόντων Ὀλύμπια Ἠλείων ἐνίκα στάδιον παῖδας ὁ Δαμίσκος οὗτος, καί οἱ καὶ πενταθλήσαντι ὕστερον ἐγένοντο ἐν Νεμέᾳ τε νῖκαι καὶ Ἰσθμοῖ.", "st": "6.2"}, {"sp": "N", "t": "Δαμίσκου δὲ ἐγγύτατα ἕστηκεν ἀνὴρ ὅστις δή, τὸ γὰρ ὄνομα οὐ λέγουσιν ἐπ’ αὐτῷ, Πτολεμαίου δὲ ἀνάθημά ἐστι τοῦ Λάγου· Μακεδόνα δὲ αὑτὸν ὁ Πτολεμαῖος ἐν τῷ ἐπιγράμματι ἐκάλεσε, βασιλεύων ὅμως Αἰγύπτου. Χαιρέᾳ δὲ Σικυωνίῳ πύκτῃ παιδὶ ἐπίγραμμά ἐστιν ὡς νικήσειεν ἡλικίαν νέος καὶ ὡς πατρὸς εἴη Χαιρήμονος, γέγραπται δὲ καὶ ὁ τὸν ἀνδριάντα εἰργασμένος Ἀστερίων Αἰσχύλου.", "st": "6.3"}, {"sp": "N", "t": "μετὰ δὲ τὸν Χαιρέαν Μεσσήνιός τε παῖς Σόφιος καὶ ἀνὴρ Ἠλεῖος ἀνάκειται Στόμιος, καὶ τῷ μὲν τοὺς συνθέοντας τῶν παίδων παρελθεῖν, Στομίῳ δὲ πενταθλοῦντι ἐν Ὀλυμπίᾳ καὶ Νεμείων τρεῖς ὑπῆρξεν ἀνελέσθαι νίκας. τὸ δὲ ἐπίγραμμα τὸ ἐπ’ αὐτῷ καὶ τάδε ἐπιλέγει, τῆς ἵππου τε Ἠλείοις αὐτὸν ἡγούμενον ἀναστῆσαι τρόπαια καὶ ἄνδρα τοῖς πολεμίοις στρατηγοῦντα ἀποθανεῖν ὑπὸ τοῦ Στομίου, μονομαχήσαντά οἱ κατὰ πρόκλησιν·", "st": "6.3"}, {"sp": "N", "t": "εἶναι δὲ αὐτὸν ἐκ Σικυῶνος οἱ Ἠλεῖοί φασι καὶ ἄρχειν Σικυωνίων, στρατεῦσαι δὲ ἐπὶ Σικυῶνα αὐτοὶ φιλίᾳ Θηβαίων ὁμοῦ τῇ ἐκ Βοιωτίας δυνάμει. φαίνοιτο ἂν οὖν ἡ ἐπὶ Σικυῶνα Ἠλείων καὶ Θηβαίων στρατεία γεγενῆσθαι μετὰ τὸ ἀτύχημα Λακεδαιμονίων τὸ ἐν Λεύκτροις.", "st": "6.3"}, {"sp": "N", "t": "ἐφεξῆς δὲ ἀνάκειται μὲν πύκτης ἐκ Λεπρέου τοῦ Ἠλείων, Λάβαξ Εὔφρονος, ἀνάκειται δὲ καὶ ἐξ αὐτῆς Ἤλιδος παλαιστὴς ἀνὴρ Ἀριστόδημος Θράσιδος· γεγόνασι δὲ αὐτῷ καὶ Πυθοῖ δύο νῖκαι, ἡ δὲ εἰκών ἐστι τοῦ Ἀριστοδήμου τέχνη Δαιδάλου τοῦ Σικυωνίου, μαθητοῦ καὶ πατρὸς Πατροκλέους.", "st": "6.3"}, {"sp": "N", "t": "Ἵππον δὲ Ἠλεῖον πυγμῇ παῖδας κρατήσαντα ἐποίησε Δαμόκριτος Σικυώνιος, ὃς ἐς πέμπτον διδάσκαλον ἀνῄει τὸν Ἀττικὸν Κριτίαν· Πτόλιχος μὲν γὰρ ἔμαθεν ὁ Κορκυραῖος παρ’ αὐτῷ Κριτίᾳ, Πτολίχου δὲ ἦν μαθητὴς Ἀμφίων, Πίσων δὲ ἀνὴρ ἐκ Καλαυρείας ἐδιδάχθη παρ’ Ἀμφίονι, ὁ δὲ παρὰ τῷ Πίσωνι Δαμόκριτος.", "st": "6.3"}, {"sp": "N", "t": "Κρατῖνος δὲ ἐξ Αἰγείρας τῆς Ἀχαιῶν τότε ἐγένετο κάλλιστος τῶν ἐφ’ ἑαυτοῦ καὶ σὺν τέχνῃ μάλιστα ἐπάλαισε, καταπαλαίσαντι δὲ αὐτῷ τοὺς παῖδας προσαναστῆσαι καὶ τὸν παιδοτρίβην ὑπὸ Ἠλείων ἐδόθη· τὸν δὲ ἀνδριάντα ἐποίησε Σικυώνιος Κάνθαρος, Ἀλέξιδος μὲν πατρός, διδασκάλου δὲ ὢν Εὐτυχίδου.", "st": "6.3"}, {"sp": "N", "t": "Εὐπολέμου δὲ Ἠλείου τὴν μὲν εἰκόνα Σικυώνιος εἴργασται Δαίδαλος· τὸ δὲ ἐπίγραμμα τὸ ἐπ’ αὐτῷ μηνύει σταδίου μὲν ἀνδρῶν Ὀλυμπίασι νίκην ἀνελέσθαι τὸν Εὐπόλεμον, εἶναι δὲ καὶ δύο Πυθικοὺς αὐτῷ πεντάθλου στεφάνους καὶ ἄλλον Νεμείων. λέγεται δὲ ἐπὶ τῷ Εὐπολέμῳ καὶ τάδε, ὡς ἐφεστήκοιεν τρεῖς ἐπὶ τῷ δρόμῳ [τῷ πέρατι] Ἑλλανοδίκαι, νικᾶν δὲ τῷ μὲν Εὐπολέμῳ δύο ἐξ αὐτῶν δοῖεν, ὁ τρίτος δὲ Ἀμβρακιώτῃ Λέοντι, καὶ ὡς χρημάτων καταδικάσαιτο ὁ Λέων ἐπὶ τῆς Ὀλυμπικῆς βουλῆς ἑκατέρου τῶν Ἑλλανοδικῶν οἳ νικᾶν τὸν Εὐπόλεμον ἔγνωσαν.", "st": "6.3"}, {"sp": "N", "t": "Οἰβώτα δὲ τὸν μὲν ἀνδριάντα Ἀχαιοὶ κατὰ πρόσταγμα ἀνέθεσαν τοῦ ἐν Δελφοῖς Ἀπόλλωνος ἐπὶ Ὀλυμπιάδος ὀγδοηκοστῆς· ἡ δὲ τοῦ σταδίου νίκη τῷ Οἰβώτᾳ γέγονεν Ὀλυμπιάδι ἕκτῃ. πῶς ἂν οὖν τήν γε ἐν Πλαταιαῖς μάχην μεμαχημένος ὁ Οἰβώτας εἴη μετὰ Ἑλλήνων; πέμπτῃ γὰρ ἐπὶ τῇ ἑβδομηκοστῇ Ὀλυμπιάδι τὸ πταῖσμα ἐγένετο ⟨τὸ⟩ ἐν Πλαταιαῖς Μαρδονίῳ καὶ Μήδοις. ἐμοὶ μὲν οὖν λέγειν μὲν τὰ ὑπὸ Ἑλλήνων λεγόμενα ἀνάγκη, πείθεσθαι δὲ πᾶσιν οὐκέτι ἀνάγκη. τὰ δὲ ἄλλα ὁποῖα τὰ συμβάντα ἦν ἐς τὸν Οἰβώταν, τῇ ἐς Ἀχαιοὺς προσέσται μοι συγγραφῇ.", "st": "6.3"}, {"sp": "N", "t": "Ἀντιόχου δὲ ἀνδριάντα ἐποίησε μὲν Νικόδαμος, γένος δὲ ὁ Ἀντίοχος ἦν ἐκ Λεπρέου· παγκρατίῳ δὲ ἄνδρας ἐν Ὀλυμπίᾳ μὲν ἐκράτησεν ἅπαξ, ἐν Ἰσθμῷ δὲ καὶ Νεμέᾳ δὶς πεντάθλῳ ἐν ἑκατέρῳ τῷ ἀγῶνι. οὐ γάρ τι Ἰσθμίων Λεπρεάταις δεῖμα ὥσπερ γε αὐτοῖς ἐστιν Ἠλείοις, ἐπεὶ Ὕσμωνί γε τῷ Ἠλείῳ—πλησίον δὲ τοῦ Ἀντιόχου καὶ Ὕσμων οὗτος ἕστηκε—τούτῳ τῷ ἀνδρὶ ἀθλήσαντι πένταθλον ἥ τε Ὀλυμπικὴ νίκη καὶ Νεμείων γέγονεν ἡ ἑτέρα, Ἰσθμίων δὲ δῆλα ὡς καὶ οὗτος κατὰ ταὐτὰ Ἠλείοις τοῖς ἄλλοις εἴργετο.", "st": "6.3"}, {"sp": "N", "t": "λέγεται δὲ παιδὶ ἔτι ὄντι τῷ Ὕσμωνι κατασκῆψαι ῥεῦμα ἐς τὰ νεῦρα, καὶ αὐτὸν ἐπὶ τούτῳ μελετῆσαι πένταθλον, ἵνα δὴ ἐκ τῶν πόνων ὑγιής τε καὶ ἄνοσος ἀνὴρ εἴη· τῷ δὲ ἄρα τὸ μάθημα καὶ νίκας ἔμελλεν ἐπιφανεῖς οὕτω παρασκευάσειν. ὁ δὲ ἀνδριὰς αὐτῷ Κλέωνος μέν ἐστιν ἔργον, ἔχει δὲ ἁλτῆρας ἀρχαίους.", "st": "6.3"}, {"sp": "N", "t": "μετὰ δὲ Ὕσμωνα παλαιστὴς παῖς ἐξ Ἡραίας ἀνάκειται τῆς Ἀρκάδων, Νικόστρατος Ξενοκλείδου· Παντίας δὲ αὐτῷ τὴν εἰκόνα ἐποίησεν, ὃς ἀπὸ Ἀριστοκλέους τοῦ Σικυωνίου καταριθμουμένῳ τοὺς διδαχθέντας ἕβδομος ἀπὸ τούτου ⟨ἦν⟩ μαθητής. Δίκων δὲ ὁ Καλλιβρότου πέντε μὲν Πυθοῖ δρόμου νίκας, τρεῖς δὲ ἀνείλετο Ἰσθμίων, τέσσαρας δὲ ἐν Νεμέᾳ, καὶ Ὀλυμπικὰς μίαν μὲν ἐν παισί, δύο δὲ ἄλλας ἀνδρῶν· καί οἱ καὶ ἀνδριάντες ἴσοι ταῖς νίκαις εἰσὶν ἐν Ὀλυμπίᾳ. παιδὶ μὲν δὴ ὄντι αὐτῷ Καυλωνιάτῃ, καθάπερ γε καὶ ἦν, ὑπῆρξεν ἀναγορευθῆναι· τὸ δὲ ἀπὸ τούτου Συρακούσιον αὑτὸν ἀνηγόρευσεν ἐπὶ χρήμασι.", "st": "6.3"}, {"sp": "N", "t": "Καυλωνία δὲ ἀπῳκίσθη μὲν ἐς Ἰταλίαν ὑπὸ Ἀχαιῶν, οἰκιστὴς δὲ ἐγένετο αὐτῆς Τύφων Αἰγιεύς· Πύρρου δὲ τοῦ Αἰακίδου καὶ Ταραντίνων ἐς τὸν πρὸς Ῥωμαίους πόλεμον καταστάντων ἄλλαι τε τῶν ἐν Ἰταλίᾳ πόλεων ἐγένοντο αἱ μὲν ὑπὸ Ῥωμαίων, αἱ δὲ ὑπὸ τῶν Ἠπειρωτῶν ἀνάστατοι, κατέλαβε δὲ ἐς ἅπαν ἐρημωθῆναι καὶ τὴν Καυλωνίαν ἁλοῦσαν ὑπὸ Καμπανῶν, οἳ Ῥωμαίοις μεγίστη τοῦ συμμαχικοῦ μοῖρα ἦσαν.", "st": "6.3"}, {"sp": "N", "t": "ἐπὶ δὲ τῷ Δίκωνι ἀνάκειται μὲν Ξενοφῶν Μενεφύλου παγκρατιαστὴς ἀνὴρ ἐξ Αἰγίου τῆς Ἀχαιῶν, ἀνάκειται δὲ Πυριλάμπης Ἐφέσιος λαβὼν δολίχου νίκην. τοῦ μὲν δὴ τὴν εἰκόνα ἐποίησεν Ὄλυμπος, Πυριλάμπει δὲ ὁμώνυμος καὶ ὁ πλάστης, γένος δὲ οὐ Σικυώνιος, ἀλλὰ ἐκ Μεσσήνης τῆς ὑπὸ τῇ Ἰθώμῃ.", "st": "6.3"}, {"sp": "N", "t": "Λύσανδρον δὲ τὸν Ἀριστοκρίτου Σπαρτιάτην ἀνέθεσαν ἐν Ὀλυμπίᾳ Σάμιοι, καὶ αὐτοῖς τὸ μὲν πρότερον τῶν ἐπιγραμμάτων ἐστὶν<br>ἐν πολυθαήτῳ τεμένει Διὸς ὑψιμέδοντος<br>ἕστηκ’ ἀνθέντων δημοσίᾳ Σαμίων·<br>τοῦτο μὲν δὴ τοὺς τὸ ἀνάθημα ἀναθέντας μηνύει, τὸ δ’ ἐφεξῆς ἐς αὐτὸν ἔπαινός ἐστι Λύσανδρον·<br>ἀθάνατον πάτρᾳ καὶ Ἀριστοκρίτῳ κλέος ἔργων,<br>Λύσανδρ’, ἐκτελέσας δόξαν ἔχεις ἀρετᾶς.<br>δῆλοι οὖν εἰσιν οἵ τε Σάμιοι καὶ οἱ ἄλλοι Ἴωνες,", "st": "6.3"}, {"sp": "N", "t": "κατὰ τὸ λεγόμενον ὑπ’ αὐτῶν Ἰώνων, τοὺς τοίχους τοὺς δύο ἐπαλείφοντες. Ἀλκιβιάδου μέν γε τριήρεσιν Ἀθηναίων περὶ Ἰωνίαν ἰσχύοντος ἐθεράπευον αὐτὸν Ἰώνων οἱ πολλοί, καὶ εἰκὼν Ἀλκιβιάδου χαλκῆ παρὰ τῇ Ἥρᾳ [τῇ] Σαμίων ἐστὶν ἀνάθημα· ὡς δὲ ἐν Αἰγὸς ποταμοῖς ἑάλωσαν αἱ ναῦς αἱ Ἀττικαί, Σάμιοι μὲν ἐς Ὀλυμπίαν τὸν Λύσανδρον, Ἐφέσιοι δὲ ἐς τὸ ἱερὸν ἀνετίθεσαν τῆς Ἀρτέμιδος Λύσανδρόν τε αὐτὸν καὶ Ἐτεόνικον καὶ Φάρακα καὶ ἄλλους Σπαρτιατῶν ἥκιστα ἔς γε τὸ Ἑλληνικὸν γνωρίμους.", "st": "6.3"}, {"sp": "N", "t": "μεταπεσόντων δὲ αὖθις τῶν πραγμάτων καὶ Κόνωνος κεκρατηκότος τῇ ναυμαχίᾳ περὶ Κνίδον καὶ ὄρος τὸ Δώριον ὀνομαζόμενον, οὕτω μετεβάλλοντο οἱ Ἴωνες, καὶ Κόνωνα ἀνακείμενον χαλκοῦν καὶ Τιμόθεον ἐν Σάμῳ τε ἔστιν ἰδεῖν παρὰ τῇ Ἥρᾳ καὶ ὡσαύτως ἐν Ἐφέσῳ παρὰ τῇ Ἐφεσίᾳ θεῷ. ταῦτα μέν ἐστιν ἔχοντα οὕτω τὸν ἀεὶ χρόνον, καὶ Ἴωσιν ὡσαύτως οἱ πάντες ἄνθρωποι θεραπεύουσι τὰ ὑπερέχοντα τῇ ἰσχύι.", "st": "6.3"}, {"sp": "N", "t": "ἔχεται δὲ τοῦ Λυσάνδρου τῆς εἰκόνος Ἐφέσιός τε πύκτης τοὺς ἐλθόντας κρατήσας τῶν παίδων—ὄνομα δέ οἱ ἦν Ἀθήναιος—καὶ Σικυώνιος Σώστρατος παγκρατιαστὴς ἀνήρ, ἐπίκλησις δὲ ἦν Ἀκροχερσίτης αὐτῷ· παραλαμβανόμενος γὰρ ἄκρων τοῦ ἀνταγωνιζομένου τῶν χειρῶν ἔκλα, καὶ οὐ πρότερον ἀνίει πρὶν ἢ αἴσθοιτο ἀπαγορεύσαντος.", "st": "6.4"}, {"sp": "N", "t": "γεγόνασι δὲ αὐτῷ Νεμείων μὲν νῖκαι καὶ Ἰσθμίων ἀναμὶξ δυόδεκα, Ὀλυμπίασι δὲ καὶ Πυθοῖ, τῇ μὲν δύο, τρεῖς δὲ ἐν Ὀλυμπίᾳ. τὴν τετάρτην δὲ Ὀλυμπιάδα ἐπὶ ταῖς ἑκατόν—πρώτην γὰρ δὴ ἐνίκησεν ὁ Σώστρατος ταύτην—οὐκ ἀναγράφουσιν οἱ Ἠλεῖοι, διότι μὴ αὐτοὶ τὸν ἀγῶνα ἀλλὰ Πισαῖοι καὶ Ἀρκάδες ἔθεσαν ἀντ’ αὐτῶν.", "st": "6.4"}, {"sp": "N", "t": "παρὰ δὲ τὸν Σώστρατον παλαιστὴς ἀνὴρ πεποίηται Λεοντίσκος, ἐκ Σικελίας τε ὢν γένος καὶ ἀπὸ τῆς ἐν τῷ πορθμῷ Μεσσήνης· στεφανωθῆναι δὲ ὑπό τε Ἀμφικτυόνων καὶ δὶς ὑπὸ Ἠλείων, εἶναι δὲ αὐτῷ λέγεται τὴν πάλην καθὰ δὴ καὶ τὸ παγκράτιον τῷ Σικυωνίῳ Σωστράτῳ· καὶ γὰρ τὸν Λεοντίσκον καταβαλεῖν μὲν οὐκ ἐπίστασθαι τοὺς παλαίοντας, νικᾶν δὲ αὐτὸν κλῶντα τοὺς δακτύλους.", "st": "6.4"}, {"sp": "N", "t": "τὸν δὲ ἀνδριάντα Πυθαγόρας ἐποίησεν ὁ Ῥηγῖνος, εἴπερ τις καὶ ἄλλος ἀγαθὸς τὰ ἐς πλαστικήν. διδαχθῆναι δὲ παρὰ Κλεάρχῳ φασὶν αὐτόν, Ῥηγίνῳ μὲν καὶ αὐτῷ, μαθητῇ δὲ Εὐχείρου· τὸν δὲ Εὔχειρον εἶναι Κορίνθιον, φοιτῆσαι δὲ ὡς Συάδραν τε καὶ Χάρταν Σπαρτιάτας.", "st": "6.4"}, {"sp": "N", "t": "ὁ δὲ παῖς ὁ ἀναδούμενος ταινίᾳ τὴν κεφαλὴν ἐπεισήχθω μοι καὶ οὗτος ἐς τὸν λόγον Φειδίου τε ἕνεκα καὶ τῆς ἐς τὰ ἀγάλματα τοῦ Φειδίου σοφίας, ἐπεὶ ἄλλως γε οὐκ ἴσμεν ὅτου τὴν εἰκόνα ὁ Φειδίας ἐποίησε. Σάτυρος δὲ Ἠλεῖος Λυσιάνακτος πατρός, γένους δὲ τοῦ Ἰαμιδῶν, ἐν Νεμέᾳ πεντάκις ἐνίκησε πυκτεύων καὶ Πυθοῖ τε δὶς καὶ δὶς ἐν Ὀλυμπίᾳ· τέχνη δὲ Ἀθηναίου Σιλανίωνος ὁ ἀνδριάς ἐστι. πλάστης δὲ ἄλλος τῶν Ἀττικῶν Πολυκλῆς, Σταδιέως μαθητὴς Ἀθηναίου, πεποίηκε παῖδα Ἐφέσιον παγκρατιαστήν, Ἀμύνταν Ἑλλανίκου.", "st": "6.4"}, {"sp": "N", "t": "Χίλωνι δὲ Ἀχαιῷ Πατρεῖ δύο μὲν Ὀλυμπικαὶ νῖκαι πάλης ἀνδρῶν, μία δὲ ἐγένετο ἐν Δελφοῖς, τέσσαρες δὲ ἐν Ἰσθμῷ καὶ Νεμείων τρεῖς· ἐτάφη δὲ ὑπὸ τοῦ κοινοῦ τῶν Ἀχαιῶν, καί οἱ καὶ τοῦ βίου συνέπεσεν ⟨ἐν⟩ πολέμῳ τὴν τελευτὴν γενέσθαι. μαρτυρεῖ δέ μοι καὶ τὸ ἐπίγραμμα τὸ ἐν Ὀλυμπίᾳ·<br>μουνοπάλης νικῶ δὶς Ὀλύμπια Πύθιά τ’ ἄνδρας,<br>τρὶς Νεμέᾳ, τετράκις δ’ Ἰσθμῷ ἐν ἀγχιάλῳ,<br>⟨Χίλων⟩ Χίλωνος Πατρεύς, ὃν λαὸς Ἀχαιῶν<br>ἐν πολέμῳ φθίμενον θάψ’ ἀρετῆς ἕνεκεν.<br>τὸ μὲν δὴ ἐπίγραμμα ἐπὶ τοσοῦτο ἐδήλωσεν·", "st": "6.4"}, {"sp": "N", "t": "εἰ δὲ Λυσίππου τοῦ ποιήσαντος τὴν εἰκόνα τεκμαιρόμενον τῇ ἡλικίᾳ συμβαλέσθαι δεῖ με τὸν πόλεμον ἔνθα ὁ Χίλων ἔπεσεν, ἤτοι ἐς Χαιρώνειαν Ἀχαιοῖς τοῖς πᾶσιν ὁμοῦ στρατεύσασθαι ⟨ἢ⟩ ἰδίᾳ κατ’ ἀρετήν τε καὶ τόλμαν Ἀχαιῶν μόνος Ἀντιπάτρου μοι καὶ Μακεδόνων ἐναντία ἀγωνίσασθαι περὶ Λάμιαν φαίνεται τὴν ἐν Θεσσαλίᾳ.", "st": "6.4"}, {"sp": "N", "t": "ἐφεξῆς δὲ τοῦ Χίλωνος ⟨δύο⟩ ἀνάκεινται· τῷ μὲν Μολπίων ἐστὶν ὄνομα, στεφανωθῆναι δὲ τὸ ἐπίγραμμά φησιν αὐτὸν ὑπὸ Ἠλείων· τὸν δὲ ἕτερον, ὅτῳ μηδέν ἐστιν ἐπίγραμμα, μνημονεύουσιν ὡς Ἀριστοτέλης ἐστὶν ὁ ἐκ τῶν Θρᾳκίων Σταγείρων, καὶ αὐτὸν ἤτοι μαθητὴς ἢ καὶ στρατιωτικὸς ἀνέθηκεν ἀνὴρ ἅτε παρὰ Ἀντιπάτρῳ καὶ πρότερον ἰσχύσαντα παρὰ Ἀλεξάνδρῳ.", "st": "6.4"}, {"sp": "N", "t": "Σωδάμας δὲ ἐξ Ἀσσοῦ τῆς ἐν τῇ Τρῳάδι, κειμένης δὲ ὑπὸ τῇ Ἴδῃ, πρῶτος Αἰολέων τῶν ταύτῃ στάδιον Ὀλυμπίασιν ἐνίκησεν ἐν παισίν. παρὰ δὲ Σωδάμαν Ἀρχίδαμος ἕστηκεν ὁ Ἀγησιλάου, Λακεδαιμονίων βασιλεύς. πρὸ δὲ τοῦ Ἀρχιδάμου τούτου βασιλέως εἰκόνα οὐδενὸς ἔν γε τῇ ὑπερορίᾳ Λακεδαιμονίους ἀναθέντας εὕρισκον· Ἀρχιδάμου δὲ ἄλλων τε καὶ τῆς τελευτῆς ἐμοὶ δοκεῖν ἕνεκα ἀνδριάντα ἐς Ὀλυμπίαν ἀπέστειλαν, ὅτι ἐν βαρβάρῳ τε ἐπέλαβεν αὐτὸν τὸ χρεὼν καὶ βασιλέων μόνος τῶν ἐν Σπάρτῃ δῆλός ἐστιν ἁμαρτὼν τάφου.", "st": "6.4"}, {"sp": "N", "t": "ταῦτα μὲν δὴ καὶ ἐν τοῖς Σπαρτιατικοῖς λόγοις ἐς πλέον ἡμῖν δεδήλωται· Εὐάνθει δὲ Κυζικηνῷ γεγόνασι πυγμῆς νῖκαι, μία μὲν ἐν ἀνδράσιν Ὀλυμπική, Νεμείων δὲ ἐν παισὶ καὶ Ἰσθμίων. πεποίηται δὲ παρὰ τὸν Εὐάνθην ἀνήρ τε ἱπποτρόφος καὶ τὸ ἅρμα, ἀναβεβηκυῖα δὲ ἐπὶ τὸ ἅρμα παῖς παρθένος· ὄνομα μὲν Λάμπος τῷ ἀνδρί, πατρὶς δὲ ἦν αὐτῷ νεωτάτη τῶν ἐν Μακεδονίᾳ πόλεων, καλουμένη δὲ ἀπὸ τοῦ οἰκιστοῦ Φιλίππου τοῦ Ἀμύντου.", "st": "6.4"}, {"sp": "N", "t": "Κυνίσκῳ δὲ τῷ ἐκ Μαντινείας πύκτῃ παιδὶ ἐποίησε Πολύκλειτος τὴν εἰκόνα. Ἐργοτέλης δὲ ὁ Φιλάνορος δολίχου δύο ἐν Ὀλυμπίᾳ νίκας, τοσαύτας δὲ ἄλλας Πυθοῖ καὶ ἐν Ἰσθμῷ τε καὶ Νεμείων ἀνῃρημένος, οὐχ Ἱμεραῖος εἶναι τὸ ἐξ ἀρχῆς, καθάπερ γε τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ φησι, Κρὴς δὲ εἶναι λέγεται Κνώσσιος· ἐκπεσὼν δὲ ὑπὸ στασιωτῶν ἐκ Κνωσσοῦ καὶ ἐς Ἱμέραν ἀφικόμενος πολιτείας τ’ ἔτυχε καὶ πολλὰ εὕρετο ἄλλα ἐς τιμήν. ἔμελλεν οὖν ὡς τὸ εἰκὸς Ἱμεραῖος ἐν τοῖς ἀγῶσιν ἀναγορευθήσεσθαι.", "st": "6.4"}, {"sp": "N", "t": "ὁ δὲ ἐπὶ τῷ βάθρῳ τῷ ὑψηλᾷ Λυσίππου μέν ἐστιν ἔργον, μέγιστος δὲ ἁπάντων ἐγένετο ἀνθρώπων πλὴν τῶν ἡρώων καλουμένων καὶ εἰ δή τι ἄλλο ἦν πρὸ τῶν ἡρώων θνητὸν γένος· ἀνθρώπων δὲ τῶν καθ’ ἡμᾶς οὗτός ἐστιν ὁ μέγιστος Πουλυδάμας Νικίου.", "st": "6.5"}, {"sp": "N", "t": "Σκοτοῦσσα δὲ ἡ τοῦ Πουλυδάμαντας πατρὶς οὐκ ᾠκεῖτο ἔτι ἐφ’ ἡμῶν· Ἀλέξανδρος γὰρ τὴν πόλιν ὁ Φεραίων τυραννήσας κατέλαβεν ἐν σπονδαῖς, καὶ Σκοτουσσαίων τούς τε ἐς τὸ θέατρον συνειλεγμένους—ἔτυχε γάρ σφισι καὶ ἐκκλησία τηνικαῦτα οὖσα—τούτους τε ἅπαντας κατηκόντισε, πελτασταῖς ἐν κύκλῳ περισχὼν καὶ τοξόταις, καὶ τὸ ἄλλο ὅσον ἐν ἡλικίᾳ κατεφόνευσε, γυναῖκας δὲ ἀπέδοτο καὶ παῖδας, μισθὸν εἶναι τὰ χρήματα τοῖς ξένοις.", "st": "6.5"}, {"sp": "N", "t": "αὕτη Σκοτουσσαίοις ἡ συμφορὰ Φρασικλείδου μὲν Ἀθήνῃσιν ἐγένετο ἄρχοντος, δευτέρᾳ δὲ Ὀλυμπιάδι ἐπὶ ταῖς ἑκατόν, ἣν Δάμων Θούριος ἐνίκα τὸ δεύτερον, ταύτης ἔτει δευτέρῳ τῆς Ὀλυμπιάδος. καὶ ὀλίγον τε ἔμενε τὸ διαφυγὸν τῶν Σκοτουσσαίων καὶ αὖθις ὑπὸ ἀσθενείας ἐξέλιπον καὶ οὗτοι τὴν πόλιν, ὅτε καὶ τοῖς πᾶσιν Ἕλλησι προσπταῖσαι δεύτερα ἐν τῷ πρὸς Μακεδόνας πολέμῳ παρεσκεύασεν ὁ δαίμων.", "st": "6.5"}, {"sp": "N", "t": "παγκρατίου μὲν δὴ καὶ ἄλλοις ἤδη γεγόνασιν ἐπιφανεῖς νῖκαι· Πουλυδάμαντι δὲ τάδε ἀλλοῖα παρὰ τοὺς ἐπὶ τῷ παγκρατίῳ στεφάνους ὑπάρχοντά ἐστιν. ἡ ὀρεινὴ τῆς Θρᾴκης, ἡ ἔνδον Νέστου ποταμοῦ τοῦ ῥέοντος διὰ τῆς Ἀβδηριτῶν, καὶ ἄλλα θηρία, ἐν δὲ αὐτοῖς παρέχεται καὶ λέοντας, οἳ καὶ τῷ στρατῷ ποτε ἐπιθέμενοι τῷ Ξέρξου τὰς ἀγούσας καμήλους τὰ σιτία ἐλυμήναντο.", "st": "6.5"}, {"sp": "N", "t": "οὗτοι πολλάκις οἱ λέοντες καὶ ἐς τὴν περὶ τὸν Ὄλυμπον πλανῶνται χώραν· τούτου δὲ τοῦ ὄρους ἡ μὲν ἐς Μακεδονίαν πλευρά, ἡ δὲ ἐπὶ Θεσσαλοὺς καὶ τὸν ποταμὸν τέτραπται τὸν Πηνειόν· ἐνταῦθα ὁ Πουλυδάμας λέοντα ἐν τῷ Ὀλύμπῳ, μέγα καὶ ἄλκιμον θηρίον, κατειργάσατο οὐδενὶ ἐσκευασμένος ὅπλῳ. προήχθη δὲ ἐς τὸ τόλμημα φιλοτιμίᾳ πρὸς τὰ Ἡρακλέους ἔργα, ὅτι καὶ Ἡρακλέα ἔχει λόγος κρατῆσαι τοῦ ἐν Νεμέᾳ λέοντος.", "st": "6.5"}, {"sp": "N", "t": "ἕτερον δὲ ἐπὶ τούτῳ θαῦμα ὑπελίπετο ὁ Πουλυδάμας ἐς μνήμην· ἐς ἀγέλην ἐσελθὼν βοῶν τὸν μέγιστον καὶ ἀγριώτατον ταῦρον λαβὼν τοῦ ἑτέρου τῶν ὄπισθεν ποδῶν τὰς χηλὰς κατεῖχεν ἄκρας, καὶ πηδῶντα καὶ ἐπειγόμενον οὐκ ἀνίει, πρίν γε δὴ ὁ ταῦρος ὀψέ ποτε καὶ ἐς ἅπαν ἀφικόμενος βίας ἀπέφυγεν ἀφεὶς ταύτῃ τῷ Πουλυδάμαντι τὰς χηλάς. λέγεται δὲ καὶ ὡς ἄνδρα ἡνίοχον ἐλαύνοντα σπουδῇ τὸ ἅρμα ἐπέσχε τοῦ πρόσω· λαβόμενος γὰρ τῇ ἑτέρᾳ τῶν χειρῶν ὄπισθε τοῦ ἅρματος, ὁμοῦ καὶ τοὺς ἵππους πεδήσας καὶ τὸν ἡνίοχον εἶχε.", "st": "6.5"}, {"sp": "N", "t": "Δαρεῖος δὲ Ἀρταξέρξου παῖς νόθος, ὃς ὁμοῦ τῷ Περσῶν [καὶ] δήμῳ Σόγδιον καταπαύσας παῖδα Ἀρταξέρξου γνήσιον ἔσχεν ἀντ’ ἐκείνου τὴν ἀρχήν, οὗτος ὡς ἐβασίλευσεν ὁ Δαρεῖος—ἐπυνθάνετο γὰρ τοῦ Πουλυδάμαντος τὰ ἔργα—, πέμπων ἀγγέλους ὑπισχνούμενος δῶρα ἀνέπεισεν αὐτὸν ἐς Σοῦσά τε καὶ ἐς ὄψιν ἀφικέσθαι τὴν αὑτοῦ. ἔνθα δὴ κατὰ πρόκλησιν Περσῶν ἄνδρας τῶν καλουμένων ἀθανάτων ἀριθμὸν τρεῖς ἀθρόους οἱ μονομαχήσαντας ἀπέκτεινεν. ἔργων δὲ τῶν κατειλεγμένων οἱ τὰ μὲν ἐπὶ τῷ βάθρῳ τοῦ ἀνδριάντος ἐν Ὀλυμπίᾳ, τὰ δὲ καὶ δηλούμενά ἐστιν ὑπὸ τοῦ ἐπιγράμματος.", "st": "6.5"}, {"sp": "N", "t": "ἔμελλε δὲ ἄρα τὸ ὑπὸ Ὁμήρου προθεσπισθὲν ἄλλους τε τῶν φρονησάντων ἐπὶ ἰσχύι καὶ Πουλυδάμαντα ἐπιλήψεσθαι, καὶ ὑπὸ τῆς αὑτοῦ ῥώμης ἔμελλεν ἀπολεῖσθαι καὶ οὗτος. ἐς σπήλαιον γὰρ οἵ τε ἄλλοι τῶν συμποτῶν καὶ ὁ Πουλυδάμας ἐσῆλθεν ὥρᾳ θέρους, καί πως οὐ κατά τινα ἀγαθὸν δαίμονα ἡ κορυφὴ τηνικαῦτα τοῦ σπηλαίου κατερρήγνυτο, καὶ δῆλα ἦν ὡς αὐτίκα ἐμπεσεῖσθαι καὶ χρόνον οὐκ ἐπὶ πολὺν ἔμελλεν ἀνθέξειν·", "st": "6.5"}, {"sp": "N", "t": "γενομένης δὲ αἰσθήσεως τοῦ ἐπιόντος κακοῦ καὶ τρεπομένων ἐς φυγὴν τῶν λοιπῶν παρέστη καταμεῖναι τῷ Πουλυδάμαντι, καὶ ἀνέσχε τὰς χεῖρας ὡς ἐπιπίπτοντι ἀνθέξων τῷ σπηλαίῳ καὶ οὐ βιασθησόμενος ὑπὸ τοῦ ὄρους.", "st": "6.5"}, {"sp": "N", "t": "τούτῳ μὲν ἐνταῦθα ἐγένετο ἡ τελευτή· ἐν δὲ Ὀλυμπίᾳ παρὰ τοῦ Πουλυδάμαντος τὸν ἀνδριάντα δύο τε ἐκ τῆς Ἀρκάδων καὶ Ἀττικὸς ὁ τρίτος ἕστηκεν ἀθλητής. τὸν μὲν δὴ Μαντινέα Πρωτόλαον Διαλκοῦς πυγμῇ παῖδας κρατήσαντα ὁ Ῥηγῖνος Πυθαγόρας, Ναρυκίδαν δὲ τὸν Δαμαρέτου παλαιστὴν ἄνδρα ἐκ Φιγαλίας Σικυώνιος Δαίδαλος, Καλλίᾳ δὲ Ἀθηναίῳ παγκρατιαστῇ τὸν ἀνδριάντα ἀνὴρ Ἀθηναῖος Μίκων ἐποίησεν ὁ ζωγράφος. Νικοδάμου δὲ ἔργον τοῦ Μαιναλίου παγκρατιαστής ἐστιν ἐκ Μαινάλου, δύο νίκας ἐν ἀνδράσιν ἀνελόμενος, Ἀνδροσθένης Λοχαίου.", "st": "6.6"}, {"sp": "N", "t": "ἐπὶ δὲ τούτοις Εὐκλῆς ἀνάκειται Καλλιάνακτος, γένος μὲν Ῥόδιος, οἴκου δὲ τοῦ Διαγοριδῷν· θυγατρὸς γὰρ Διαγόρου παῖς ἦν, ἐν δὲ ἀνδράσι πυγμῆς ἔσχεν Ὀλυμπικὴν νίκην. τούτου μὲν δὴ ἡ εἰκὼν Ναυκύδους ἐστὶν ἔργον· Πολύκλειτος δὲ Ἀργεῖος, οὐχ ὁ τῆς Ἥρας τὸ ἄγαλμα ποιήσας, μαθητὴς δὲ Ναυκύδους, παλαιστὴν παῖδα εἰργάσατο Θηβαῖον Ἀγήνορα. ἀνετέθη δὲ ἡ εἰκὼν ὑπὸ τοῦ Φωκέων κοινοῦ· Θεόπομπος γὰρ ὁ πατὴρ τοῦ Ἀγήνορος πρόξενος τοῦ ἔθνους ἦν αὐτῶν.", "st": "6.6"}, {"sp": "N", "t": "Νικόδαμος δὲ ὁ πλάστης ὁ ἐκ Μαινάλου Δαμοξενίδαν ἄνδρα πύκτην ἐποίησεν ἐκ Μαινάλου. ἕστηκε δὲ καὶ Λαστρατίδα παιδὸς εἰκὼν Ἠλείου, πάλης ἀνελομένου στέφανον· ἐγένετο δὲ αὐτῷ καὶ Νεμείων ἔν τε παισὶ καὶ ἀγενείων ἑτέρα νίκη. Παραβάλλοντι δὲ τῷ Λαστρατίδα πατρὶ ὑπῆρξε μὲν διαύλου παρελθεῖν δρόμῳ, ὑπελίπετο δὲ καὶ ἐς τοὺς ἔπειτα φιλοτιμίαν, τῶν νικησάντων Ὀλυμπίασι τὰ ὀνόματα ἀναγράψας ἐν τῷ γυμνασίῳ τῷ ἐν Ὀλυμπίᾳ.", "st": "6.6"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐς τούτους εἶχεν οὕτω· τὰ δὲ ἐς Εὔθυμον τὸν πύκτην, οὔ με εἰκὸς ὑπερβαίνειν ἦν τὰ ἐς τὰς νίκας αὐτῷ καὶ τὰ ἐς δόξαν ὑπάρχοντα τὴν ἄλλην. γένος μὲν δὴ ἦν ὁ Εὔθυμος ἐκ τῶν ἐν Ἰταλίᾳ Λοκρῶν, οἳ χώραν τὴν πρὸς τῷ Ζεφυρίῳ τῇ ἄκρᾳ νέμονται, πατρὸς δὲ ἐκαλεῖτο Ἀστυκλέους· εἶναι δὲ αὐτὸν οὐ τούτου, ποταμοῦ δὲ οἱ ἐπιχώριοι τοῦ Καικίνου φασίν, ὃς τὴν Λοκρίδα καὶ Ῥηγίνην ὁρίζων τὸ ἐς τοὺς τέττιγας παρέχεται θαῦμα. οἱ μὲν γὰρ τέττιγες οἱ ἐντὸς τῆς Λοκρίδος ἄχρι τοῦ Καικίνου κατὰ τὰ αὐτὰ τοῖς ἄλλοις τέττιξιν ᾄδουσι· διαβάντων δὲ τὸν Καικίνην οὐδεμίαν ἔτι οἱ ἐν τῇ Ῥηγίνῃ τέττιγες ἀφιᾶσι τὴν φωνήν.", "st": "6.6"}, {"sp": "N", "t": "τούτου μὲν δὴ παῖδα εἶναι λέγεται τὸν Εὔθυμον· ἀνελομένῳ δέ οἱ πυγμῆς ἐν Ὀλυμπίᾳ νίκην τετάρτῃ πρὸς ταῖς ἑβδομήκοντα Ὀλυμπιάδι οὐ κατὰ τὰ αὐτὰ ἐς τὴν ἐπιοῦσαν Ὀλυμπιάδα ἔμελλε χωρήσειν· Θεαγένης γὰρ ὁ Θάσιος Ὀλυμπιάδι ἐθέλων τῇ αὐτῇ πυγμῆς τε ἀνελέσθαι καὶ παγκρατίου νίκας ὑπερεβάλετο πυκτεύων τὸν Εὔθυμον, οὐ μὴν οὐδὲ ὁ Θεαγένης ἐπὶ τῷ παγκρατίῳ λαβεῖν ἐδυνήθη τὸν κότινον ἅτε προκατεργασθεὶς τῇ μάχῃ πρὸς τὸν Εὔθυμον.", "st": "6.6"}, {"sp": "N", "t": "ἐπὶ τούτῳ δὲ ἐπιβάλλουσιν οἱ Ἑλλανοδίκαι τῷ Θεαγένει τάλαντον μὲν ἱερὰν ἐς τὸν θεὸν ζημίαν, τάλαντον δὲ βλάβης τῆς ἐς Εὔθυμον, ὅτι ἐπηρείᾳ τῇ ἐς ἐκεῖνον ἐδόκει σφίσιν ἐπανελέσθαι τὸ ἀγώνισμα τῆς πυγμῆς· τούτων ἕνεκα καταδικάζουσιν αὐτὸν ἐκτῖσαι καὶ ἰδίᾳ τῷ Εὐθύμῳ χρήματα. ἕκτῃ δὲ Ὀλυμπιάδι ἐπὶ ταῖς ἑβδομήκοντα τὸ μὲν τῷ θεῷ τοῦ ἀργυρίου γινόμενον ἐξέτισεν ὁ Θεαγένης, … καὶ ἀμειβόμενος αὐτὸν οὐκ ἐσῆλθεν ἐπὶ τὴν πυγμήν· καὶ ἐπ’ ἐκείνης τε αὐτῆς καὶ ἐπὶ τῆς μετ’ ἐκείνην Ὀλυμπιάδος τὸν ἐπὶ πυγμῇ στέφανον ἀνείλετο ὁ Εὔθυμος. ὁ δέ οἱ ἀνδριὰς τέχνη τέ ἐστι Πυθαγόρου καὶ θέας ἐς τὰ μάλιστα ἄξιος.", "st": "6.6"}, {"sp": "N", "t": "ἐπανήκων δὲ ἐς Ἰταλίαν τότε δὴ ἐμαχέσατο πρὸς τὸν Ἥρω· τὰ δὲ ἐς αὐτὸν εἶχεν οὕτως. Ὀδυσσέα πλανώμενον μετὰ ἅλωσιν τὴν Ἰλίου κατενεχθῆναί φασιν ὑπὸ ἀνέμων ἔς τε ἄλλας τῶν ἐν Ἰταλίᾳ καὶ Σικελίᾳ πόλεων, ἀφικέσθαι δὲ καὶ ἐς Τεμέσαν ὁμοῦ ταῖς ναυσί· μεθυσθέντα οὖν ἐνταῦθα ἕνα τῶν ναυτῶν παρθένον βιάσασθαι καὶ ὑπὸ τῶν ἐπιχωρίων ἀντὶ τούτου καταλευσθῆναι τοῦ ἀδικήματος.", "st": "6.6"}, {"sp": "N", "t": "Ὀδυσσέα μὲν δὴ ἐν οὐδενὶ λόγῳ θέμενον αὐτοῦ τὴν ἀπώλειαν ἀποπλέοντα οἴχεσθαι, τοῦ καταλευσθέντος δὲ ἀνθρώπου τὸν δαίμονα οὐδένα ἀνιέναι καιρὸν ἀποκτείνοντά τε ὁμοίως τοὺς ἐν τῇ Τεμέσῃ καὶ ἐπεξερχόμενον ἐπὶ πᾶσαν ἡλικίαν, ἐς ὃ ἡ Πυθία τὸ παράπαν ἐξ Ἰταλίας ὡρμημένους φεύγειν Τεμέσαν μὲν ἐκλιπεῖν οὐκ εἴα, τὸν δὲ Ἥρω σφᾶς ἐκέλευσεν ἱλάσκεσθαι τέμενός τε ἀποτεμομένους οἰκοδομήσασθαι ναόν, διδόναι δὲ κατὰ ἔτος αὐτῷ γυναῖκα τῶν ἐν Τεμέσῃ παρθένων τὴν καλλίστην.", "st": "6.6"}, {"sp": "N", "t": "τοῖς μὲν δὴ τὰ ὑπὸ τοῦ θεοῦ προστεταγμένα ὑπουργοῦσι δεῖμα ἀπὸ τοῦ δαίμονος ἐς τἄλλα ἦν οὐδέν· Εὔθυμος δὲ— ἀφίκετο γὰρ ἐς τὴν Τεμέσαν, καί πως τηνικαῦτα τὸ ἔθος ἐποιεῖτο τῷ δαίμονι—πυνθάνεται τὰ παρόντα σφίσι, καὶ ἐσελθεῖν τε ἐπεθύμησεν ἐς τὸν ναὸν καὶ τὴν παρθένον ἐσελθὼν θεάσασθαι. ὡς δὲ εἶδε, τὰ μὲν πρῶτα ἐς οἶκτον, δεύτερα δὲ ἀφίκετο καὶ ἐς ἔρωτα αὐτῆς· καὶ ἡ παῖς τε συνοικήσειν κατώμνυτο αὐτῷ σώσαντι αὐτὴν καὶ ὁ Εὔθυμος ἐνεσκευασμένος ἔμενε τὴν ἔφοδον τοῦ δαίμονος.", "st": "6.6"}, {"sp": "N", "t": "ἐνίκα τε δὴ τῇ μάχῃ καὶ —ἐξηλαύνετο γὰρ ἐκ τῆς γῆς—ὁ Ἥρως ἀφανίζεταί τε καταδὺς ἐς θάλασσαν καὶ γάμος τε ἐπιφανὴς Εὐθύμῳ καὶ ἀνθρώποις τοῖς ἐνταῦθα ἐλευθερία τοῦ λοιποῦ σφισιν ἦν ἀπὸ τοῦ δαίμονος. ἤκουσα δὲ καὶ τοιόνδε ἔτι ἐς τὸν Εὔθυμον, ὡς γήρως τε ἐπὶ μακρότατον ἀφίκοιτο καὶ ὡς ἀποθανεῖν ἐκφυγὼν αὖθις ἕτερόν τινα ἐξ ἀνθρώπων [ἄλλον] ἀπέλθοι τρόπον· οἰκεῖσθαι δὲ τὴν Τεμέσαν καὶ ἐς ἐμὲ ἀνδρὸς ἤκουσα πλεύσαντος κατὰ ἐμπορίαν.", "st": "6.6"}, {"sp": "N", "t": "τόδε μὲν ἤκουσα, γραφῇ δὲ τοιάδε ἐπιτυχὼν οἶδα· ἦν δὲ αὕτη γραφῆς μίμημα ἀρχαίας. νεανίσκος Σύβαρις καὶ Κάλαβρός τε ποταμὸς καὶ Λύκα πηγή, πρὸς δὲ ἡρῷόν τε καὶ Τεμέσα ἦν ἡ πόλις, ἐν δέ σφισι καὶ δαίμων ὅντινα ἐξέβαλεν ὁ Εὔθυμος, χρόαν τε δεινῶς μέλας καὶ τὸ εἶδος ἅπαν ἐς τὰ μάλιστα φοβερός, λύκου δὲ ἀμπίσχετο δέρμα ἐσθῆτα· ἐτίθετο δὲ καὶ ὄνομα Λύκαν τὰ ἐπὶ τῇ γραφῇ γράμματα.", "st": "6.6"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἐς τοσοῦτο εἰρήσθω· μετὰ δὲ τὸν ἀνδριάντα τοῦ Εὐθύμου Πύθαρχός τε ἕστηκε Μαντινεὺς σταδιοδρόμος καὶ πύκτης Ἠλεῖος Χαρμίδης, λαβόντες νίκας ἐπὶ παισί. θεασάμενος δὲ καὶ τούτους ἐπὶ τῶν Ῥοδίων ἀθλητῶν ἀφίξῃ τὰς εἰκόνας, Διαγόραν καὶ τὸ ἐκείνου γένος· οἱ δὲ συνεχεῖς τε ἀλλήλοις καὶ ἐν κόσμῳ τοιῷδε ἀνέκειντο, Ἀκουσίλαος μὲν λαβὼν πυγμῆς ἐν ἀνδράσι στέφανον, Δωριεὺς δὲ ὁ νεώτατος παγκρατίῳ νικήσας Ὀλυμπιάσιν ἐφεξῆς τρισί. πρότερον δὲ ἔτι τοῦ Δωριέως ἐκράτησε καὶ Δαμάγητος τοὺς ἐσελθόντας ἐς τὸ παγκράτιον.", "st": "6.7"}, {"sp": "N", "t": "οὗτοι μὲν ἀδελφοί τέ εἰσι καὶ Διαγόρου παῖδες, ἐπὶ δὲ αὐτοῖς κεῖται καὶ ὁ Διαγόρας, πυγμῆς ἐν ἀνδράσιν ἀνελόμενος νίκην· τοῦ Διαγόρου δὲ τὴν εἰκόνα Μεγαρεὺς εἰργάσατο Καλλικλῆς Θεοκόσμου τοῦ ποιήσαντος τὸ ἄγαλμα ἐν Μεγάροις τοῦ Διός. Διαγόρου δὲ καὶ οἱ τῶν θυγατέρων παῖδες πύξ τε ἤσκησαν καὶ ἔσχον Ὀλυμπικὰς νίκας, ἐν μὲν ἀνδράσιν Εὐκλῆς Καλλιάνακτός τε ὢν καὶ Καλλιπατείρας τῆς Διαγόρου, Πεισίροδος δὲ ἐν παισίν, ὃν ἡ μήτηρ ἀνδρὸς ἐπιθεμένη γυμναστοῦ σχῆμα ἐπὶ τῶν Ὀλυμπίων αὐτὴ τὸν ἀγῶνα ἤγαγεν·", "st": "6.7"}, {"sp": "N", "t": "οὗτος δὲ ὁ Πεισίροδος καὶ ἐν τῇ Ἄλτει παρὰ τῆς μητρὸς τὸν πατέρα ἕστηκε. Διαγόραν δὲ καὶ ὁμοῦ τοῖς παισὶν Ἀκουσιλάῳ καὶ Δαμαγήτῳ λέγουσιν ἐς Ὀλυμπίαν ἐλθεῖν· νικήσαντες δὲ οἱ νεανίσκοι διὰ τῆς πανηγύρεως τὸν πατέρα ἔφερον βαλλόμενόν τε ὑπὸ τῶν Ἑλλήνων ἄνθεσι καὶ εὐδαίμονα ἐπὶ τοῖς παισὶ καλούμενον. γένος δὲ ὁ Διαγόρας τὸ ἐξ ἀρχῆς Μεσσήνιος πρὸς γυναικῶν ἦν καὶ ἀπὸ τῆς Ἀριστομένους ἐγεγόνει θυγατρός.", "st": "6.7"}, {"sp": "N", "t": "Δωριεῖ δὲ τῷ Διαγόρου παρὲξ ἢ Ὀλυμπίασιν Ἰσθμίων μὲν γεγόνασιν ὀκτὼ νῖκαι, Νεμείων δὲ ἀποδέουσαι μιᾶς ἐς τὰς ὀκτώ· λέγεται δὲ καὶ ὡς Πύθια ἀνέλοιτο ἀκονιτί. ἀνηγορεύοντο δὲ οὗτός τε καὶ ὁ Πεισίροδος Θούριοι, διωχθέντες ὑπὸ τῶν ἀντιστασιωτῶν ἐκ τῆς Ῥόδου καὶ ἐς Ἰταλίαν παρὰ Θουρίους ἀπελθόντες. χρόνῳ δὲ ὕστερον κατῆλθεν ὁ Δωριεὺς ἐς Ῥόδον· καὶ φανερώτατα δὴ ἁπάντων ἀνὴρ εἷς φρονήσας οὗτος τὰ Λακεδαιμονίων φαίνεται, ὥστε καὶ ἐναυμάχησεν ἐναντία Ἀθηναίων ναυσὶν οἰκείαις, ἐς ὃ τριήρων ἁλοὺς Ἀττικῶν ἀνήχθη ζῶν παρὰ Ἀθηναίους.", "st": "6.7"}, {"sp": "N", "t": "οἱ δὲ Ἀθηναῖοι πρὶν μὲν ἢ Δωριέα παρὰ σφᾶς ἀναχθῆναι θυμῷ τε ἐς αὐτὸν καὶ ἀπειλαῖς ἐχρῶντο· ὡς δὲ ἐς ἐκκλησίαν συνελθόντες ἄνδρα οὕτω μέγαν καὶ δόξης ἐς τοσοῦτο ἥκοντα ἐθεάσαντο ἐν σχήματι αἰχμαλώτου, μεταπίπτει σφίσιν ἐς αὐτὸν ἡ γνώμη καὶ ἀπελθεῖν ἀφιᾶσιν οὐδὲ ἔργον οὐδὲν ἄχαρι ἐργάζονται, παρόν σφισι πολλά τε καὶ σὺν τῷ δικαίῳ δρᾶσαι.", "st": "6.7"}, {"sp": "N", "t": "τὰ δὲ ἐς τοῦ Δωριέως τὴν τελευτήν ἐστιν ἐν τῇ συγγραφῇ τῇ Ἀτθίδι Ἀνδροτίωνι εἰρημένα, εἶναι μὲν τηνικαῦτα ἐν Καύνῳ τὸ βασιλέως ναυτικὸν καὶ Κόνωνα ἐπ’ αὐτῷ στρατηγόν, Ῥοδίων δὲ τὸν δῆμον πεισθέντα ὑπὸ τοῦ Κόνωνος ἀπὸ Λακεδαιμονίων μεταβαλέσθαι σφᾶς ἐς τὴν βασιλέως καὶ Ἀθηναίων συμμαχίαν, Δωριέα δὲ ἀποδημεῖν μὲν τότε ἐκ Ῥόδου περὶ τὰ ἐντὸς Πελοποννήσου χωρία, συλληφθέντα δὲ ὑπὸ ἀνδρῶν Λακεδαιμονίων αὐτὸν καὶ ἀναχθέντα ἐς Σπάρτην ἀδικεῖν τε ὑπὸ Λακεδαιμονίων καταγνωσθῆναι καὶ ἐπιβληθῆναί οἱ θάνατον ζημίαν.", "st": "6.7"}, {"sp": "N", "t": "εἰ δὲ τὸν ὄντα εἶπεν Ἀνδροτίων λόγον, ἐθέλειν μοι φαίνεται Λακεδαιμονίους ἐς τὸ ἴσον ἔτι Ἀθηναίοις καταστῆσαι, ὅτι καὶ Ἀθηναίοις ἐς Θράσυλλον καὶ τοὺς ἐν Ἀργινούσαις ὁμοῦ τῷ Θρασύλλῳ στρατηγήσαντας προπετείας ἐστὶν ἔγκλημα. Διαγόρας μὲν δὴ καὶ τὸ ἀπ’ αὐτοῦ γένος δόξης ἐς τοσοῦτο ἀφίκοντο·", "st": "6.7"}, {"sp": "N", "t": "ἐγένοντο δὲ καὶ Ἀλκαινέτῳ τῷ Θεάντου Λεπρεάτῃ καὶ αὐτῷ καὶ τοῖς παισὶν Ὀλυμπικαὶ νῖκαι. αὐτὸς μέν γε πυκτεύων ὁ Ἀλκαίνετος ἔν τε ἀνδράσι καὶ πρότερον ἔτι ἐπεκράτησεν ἐν παισίν· Ἑλλάνικον δὲ τὸν Ἀλκαινέτου καὶ Θέαντον ἐπὶ πυγμῇ παίδων ἀναγορευθῆναι τὸν μὲν ἐνάτῃ πρὸς ταῖς ὀγδοήκοντα Ὀλυμπιάδι, τὸν δὲ τῇ ἐφεξῆς ταύτῃ συνέβη τὸν Θέαντον· καί σφισιν ἀνδριάντες ἅπασιν ἐν Ὀλυμπίᾳ κεῖνται.", "st": "6.7"}, {"sp": "N", "t": "ἐπὶ δὲ τοῦ Ἀλκαινέτου τοῖς υἱοῖς Γνάθων τε Διπαιεὺς τῆς Μαιναλέων χώρας καὶ Λυκῖνος ἕστηκεν Ἠλεῖος· κρατῆσαι δὲ Ὀλυμπίασι πυγμῇ παῖδας ὑπῆρξε καὶ τούτοις. Γνάθωνα δὲ καὶ ἐς τὰ μάλιστα, ὅτε ἐνίκησεν, εἶναι νέον τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ φησί· Καλλικλέους δὲ τοῦ Μεγαρέως ποίημα ὁ ἀνδριάς ἐστιν.", "st": "6.7"}, {"sp": "N", "t": "ἀνὴρ δὲ ἐκ Στυμφήλου Δρομεὺς ὄνομα, καὶ δὴ καὶ ἔργον τοῦτο ἐπὶ δολίχῳ παρεσχημένος, δύο μὲν ἔσχεν ἐν Ὀλυμπίᾳ νίκας, τοσαύτας δὲ ἄλλας Πυθοῖ καὶ Ἰσθμίων τε τρεῖς καὶ ἐν Νεμέᾳ πέντε. λέγεται δὲ ὡς καὶ κρέας ἐσθίειν ἐπινοήσειε· τέως δὲ τοῖς ἀθληταῖς σιτία τυρὸν ἐκ τῶν ταλάρων εἶναι. τούτου μὲν δὴ Πυθαγόρας τὴν εἰκόνα, τὴν δὲ ἐφεξῆς ταύτῃ, πένταθλον Ἠλεῖον Πυθοκλέα, Πολύκλειτός ἐστιν εἰργασμένος.", "st": "6.7"}, {"sp": "N", "t": "Σωκράτους δὲ Πελληνέως δρόμου νίκην ἐν παισὶν εἰληφότος καὶ Ἠλείου Ἀμέρτου καταπαλαίσαντος ἐν Ὀλυμπίᾳ παῖδας, καταπαλαίσαντος δὲ καὶ Πυθοῖ τοὺς ἐλθόντας τῶν ἀνδρῶν, τοῦ μὲν τὸν ποιήσαντα τὴν εἰκόνα οὐ λέγουσι, τὴν δὲ τοῦ Ἀμέρτου Φράδμων ἐποίησεν Ἀργεῖος. Εὐανορίδᾳ δὲ Ἠλείῳ πάλης ἐν παισὶν ὑπῆρξεν ἔν τε Ὀλυμπίᾳ καὶ Νεμείων νίκη· γενόμενος δὲ Ἑλλανοδίκης ἔγραψε καὶ οὗτος τὰ ὀνόματα ἐν Ὀλυμπίᾳ τῶν νενικηκότων.", "st": "6.8"}, {"sp": "N", "t": "ἐς δὲ πύκτην ἄνδρα, γένος μὲν Ἀρκάδα ἐκ Παρρασίων, Δάμαρχον δὲ ὄνομα, οὔ μοι πιστὰ ἦν πέρα γε τῆς ἐν Ὀλυμπίᾳ νίκης ὁπόσα ἄλλα ἀνδρῶν ἀλαζόνων ἐστὶν εἰρημένα, ὡς ἐξ ἀνθρώπου μεταβάλοι τὸ εἶδος ἐς λύκον ἐπὶ τῇ θυσίᾳ τοῦ Λυκαίου Διός, καὶ ὡς ὕστερον τούτων ἔτει δεκάτῳ γένοιτο αὖθις ἄνθρωπος. οὐ μὴν οὐδὲ ὑπὸ τῶν Ἀρκάδων λέγεσθαί μοι τοῦτο ἐφαίνετο ἐς αὐτόν, ἐλέγετο γὰρ ἂν καὶ ὑπὸ τοῦ ἐπιγράμματος τοῦ ἐν Ὀλυμπίᾳ· ἔχει γὰρ δὴ οὕτως·<br>υἱὸς Δινύτα Δάμαρχος τάνδ’ ἀνέθηκεν<br>εἰκόν’ ἀπ’ Ἀρκαδίας Παρράσιος γενεάν.<br>τοῦτο μὲν δὴ ἐς τοσοῦτο πεποίηται·", "st": "6.8"}, {"sp": "N", "t": "Εὐβώτας δὲ ὁ Κυρηναῖος, ἅτε τὴν ἐσομένην οἱ δρόμου νίκην ἐν Ὀλυμπίᾳ παρὰ τοῦ μαντείου τοῦ ἐν Λιβύῃ προπεπυσμένος, τήν τε εἰκόνα ἐπεποίητο πρότερον καὶ ἐπὶ ἡμέρας τῆς αὐτῆς ἀνηγορεύθη τε νικήσας καὶ ἀνέθηκε τὴν εἰκόνα. λέγεται δὲ [καὶ] ὡς κρατήσειε καὶ ἅρματι ἐπὶ Ὀλυμπιάδος ταύτης ἣ λόγῳ τῷ Ἠλείων ἐστὶ κίβδηλος τῶν ἀγωνοθετησάντων Ἀρκάδων ἕνεκα.", "st": "6.8"}, {"sp": "N", "t": "Κλεωναίῳ δὲ Τιμάνθει παγκρατίου λαβόντι ἐν ἀνδράσι στέφανον καὶ Τροιζηνίῳ Βαύκιδι παλαιστὰς καταβαλόντι ἄνδρας, τῷ μὲν τοῦ Ἀθηναίου Μύρωνος, Βαύκιδι δὲ Ναυκύδους ἐστὶν ὁ ἀνδριὰς ἔργον. τῷ δὲ Τιμάνθει τὸ τέλος τοῦ βίου συμβῆναί φασιν ἐπὶ αἰτίᾳ τοιᾷδε. πεπαῦσθαι μὲν ἀθλοῦντα, ἀποπειρᾶσθαι δὲ ὅμως αὐτὸν ἔτι τῆς ἰσχύος, τόξον μέγα ἐπὶ ἑκάστης τείνοντα τῆς ἡμέρας, ἀποδημῆσαί τε δὴ αὐτὸν καὶ ἐπὶ τῷ τόξῳ τηνικαῦτα ἐκλειφθῆναί οἱ τὴν μελέτην· ὡς δὲ ἐπανήκων οὐχ οἷός τε ἔτι τεῖναι τὸ τόξον ἐγίνετο, πῦρ ἀνακαύσας ἀφίησι ζῶντα ἐς τὴν πυρὰν αὑτόν. ὁπόσα δὲ ἤδη τοιαῦτα ἐγένετο ἐν ἀνθρώποις ἢ καὶ ὕστερόν ποτε ἔσται, μανία μᾶλλον ἢ ἀνδρία νομίζοιτο ἂν κατά γε ἐμὴν γνώμην.", "st": "6.8"}, {"sp": "N", "t": "μετὰ δὲ τὸν Βαύκιδά εἰσιν ἀθλητῶν Ἀρκάδων εἰκόνες, Εὐθυμένης τε ἐξ αὐτῆς Μαινάλου, νίκας τὴν μὲν ἀνδρῶν πάλης, τὴν δ’ ἔτι πρότερον ἐν παισὶν εἰληφώς, καὶ Ἀζὰν ἐκ Πελλάνας Φίλιππος κρατήσας πυγμῇ παῖδας, καὶ Κριτόδαμος ἐκ Κλείτορος, ἐπὶ πυγμῇ καὶ οὗτος ἀναγορευθεὶς παίδων· τὰς δέ σφισιν εἰκόνας, τὴν μὲν ἐν παισὶ τοῦ Εὐθυμένους Ἄλυπος, τὴν δὲ τοῦ Δαμοκρίτου Κλέων, Φιλίππου δὲ τοῦ Ἀζᾶνος Μύρων τὴν εἰκόνα ἐποίησε. τὰ δὲ ἐς Πρόμαχον τὸν Δρύωνος παγκρατιαστὴν Πελληνέα προσέσται μοι καὶ ταῦτα τῷ ἐς Ἀχαιοὺς λόγῳ.", "st": "6.8"}, {"sp": "N", "t": "Προμάχου δὲ οὐ πόρρω Τιμασίθεος ἀνάκειται γένος Δελφός, Ἀγελάδα μὲν ἔργον τοῦ Ἀργείου, παγκρατίου δὲ δύο μὲν ἐν Ὀλυμπίᾳ νίκας, τρεῖς δὲ ἀνῃρημένος Πυθοῖ. καὶ αὐτῷ καὶ ἐν πολέμοις ἐστὶν ἔργα τῇ τε τόλμῃ λαμπρὰ καὶ οὐκ ἀποδέοντα τῇ εὐτυχίᾳ, πλήν γε δὴ τοῦ τελευταίου· τοῦτο δὲ αὐτῷ θάνατον τὸ ἐγχείρημα ἤνεγκεν. Ἰσαγόρᾳ γὰρ τῷ Ἀθηναίῳ τὴν ἀκρόπολιν τὴν Ἀθηναίων καταλαβόντι ἐπὶ τυραννίδι μετασχὼν τοῦ ἔργου καὶ ὁ Τιμασίθεος—ἐγένετο γὰρ τῶν ἐγκαταληφθέντων ἐν τῇ ἀκροπόλει—θάνατον ζημίαν εὕρετο [εὕρετο δὲ] τοῦ ἀδικήματος παρὰ Ἀθηναίων.", "st": "6.8"}, {"sp": "N", "t": "Θεογνήτῳ δὲ Αἰγινήτῃ πάλης μὲν στέφανον λαβεῖν ὑπῆρξεν ἐν παισί, τὸν δὲ ἀνδριάντα οἱ Πτόλιχος ἐποίησεν Αἰγινήτης. διδάσκαλοι δὲ ἐγεγόνεσαν Πτολίχῳ μὲν Συννοῶν ὁ πατήρ, ἐκείνῳ δὲ Ἀριστοκλῆς Σικυώνιος, ἀδελφός τε Κανάχου καὶ οὐ πολὺ τὰ ἐς δόξαν ἐλασσούμενος. ἐφ’ ὅτῳ δὲ ὁ Θεόγνητος πίτυος τῆς γ’ ἡμέρου καὶ ῥοιᾶς φέρει καρπόν, ἐμοὶ μὲν οὐχ οἷά τε ἦν συμβαλέσθαι, τάχα δ’ ἂν Αἰγινήταις τισὶν ἐπιχώριος ἐς αὐτὰ ἂν εἴη λόγος.", "st": "6.9"}, {"sp": "N", "t": "μετὰ δὲ τὴν εἰκόνα τοῦ ἀνδρὸς ὃν Ἠλεῖοί φασιν οὐ γραφῆναι μετὰ τῶν ἄλλων, ὅτι ἐπὶ κάλπης ἀνηγορεύθη δρόμῳ, μετὰ τούτου τὴν εἰκόνα Ξενοκλῆς τε Μαινάλιος ἕστηκε παλαιστὰς καταβαλὼν παῖδας καὶ Ἄλκετος Ἀλκίνου κρατήσας πυγμῇ παῖδας, Ἀρκὰς καὶ οὗτος ἐκ Κλείτορος· καὶ τοῦ μὲν Κλέων, Ξενοκλέους δὲ τὸν ἀνδριάντα Πολύκλειτός ἐστιν εἰργασμένος.", "st": "6.9"}, {"sp": "N", "t": "Ἀριστεὺς δὲ Ἀργεῖος δολίχου μὲν νίκην ἔσχεν αὐτός, πάλης δὲ ὁ πατὴρ τοῦ Ἀριστέως Χείμων· ἑστήκασι μὲν δὴ ἐγγὺς ἀλλήλων, ἐποίησε δὲ τὸν μὲν Παντίας Χῖος παρὰ τῷ πατρὶ δεδιδαγμένος Σωστράτῳ, αἱ δὲ εἰκόνες τοῦ Χείμωνος ἔργον ἐστὶν ἐμοὶ δοκεῖν ⟨τῶν⟩ δοκιμωτάτων Ναυκύδους, ἥ τε ἐν Ὀλυμπίᾳ καὶ ἡ ἐς τὸ ἱερὸν τῆς Εἰρήνης τὸ ἐν Ῥώμῃ κομισθεῖσα ἐξ Ἄργους. λέγεται δὲ ὡς Ταυροσθένην καταπαλαίσειεν ὁ Χείμων τὸν Αἰγινήτην καὶ ὡς Ταυροσθένης τῇ Ὀλυμπιάδι τῇ ἐφεξῆς καταβάλοι τοὺς ἐσελθόντας ἐς τὴν πάλην καὶ ὡς ἐοικὸς Ταυροσθένει φάσμα ἐπ’ ἐκείνης τῆς ἡμέρας ἐν Αἰγίνῃ φανὲν ἀπαγγείλειε τὴν νίκην.", "st": "6.9"}, {"sp": "N", "t": "Φίλλην δὲ Ἠλεῖον κρατήσαντα παῖδας πάλῃ Σπαρτιάτης Κρατῖνος ἐποίησε. τὰ δὲ ἐς τὸ ἅρμα τὸ Γέλωνος οὐ κατὰ ταὐτὰ δοξάζειν ἐμοί τε παρίστατο καὶ τοῖς πρότερον ἢ ἐγὼ τὰ ἐς αὐτὸ εἰρηκόσιν, οἳ Γέλωνος τοῦ ἐν Σικελίᾳ τυραννήσαντός φασιν ἀνάθημα εἶναι τὸ ἅρμα. ἐπίγραμμα μὲν δή ἐστιν αὐτῷ Γέλωνα Δεινομένους ἀναθεῖναι Γελῷον, καὶ ὁ χρόνος τούτῳ τῷ Γέλωνί ἐστι τῆς νίκης τρίτη πρὸς τὰς ἑβδομήκοντα Ὀλυμπιάδας·", "st": "6.9"}, {"sp": "N", "t": "Γέλων δὲ ὁ Σικελίας τυραννήσας Συρακούσας ἔσχεν Ὑβριλίδου μὲν Ἀθήνῃσιν ἄρχοντος, δευτέρῳ δὲ ἔτει τῆς δευτέρας καὶ ἑβδομηκοστῆς Ὀλυμπιάδος, ἣν Τισικράτης ἐνίκα Κροτωνιάτης στάδιον. δῆλα οὖν ὡς Συρακούσιον ἤδη καὶ οὐ Γελῷον ἀναγορεύειν αὑτὸν ἔμελλεν· ἀλλὰ γὰρ ἰδιώτης εἴη ἄν τις ὁ Γέλων οὗτος, πατρός τε ὁμωνύμου τῷ τυράννῳ καὶ αὐτὸς ὁμώνυμος. Γλαυκίας δὲ Αἰγινήτης τό τε ἅρμα καὶ αὐτῷ τῷ Γέλωνι ἐποίησε τὴν εἰκόνα.", "st": "6.9"}, {"sp": "N", "t": "τῇ δὲ Ὀλυμπιάδι τῇ πρὸ ταύτης Κλεομήδην φασὶν Ἀστυπαλαιέα ὡς Ἴκκῳ πυκτεύων ἀνδρὶ Ἐπιδαυρίῳ τὸν Ἴκκον ἀποκτείνειεν ἐν τῇ μάχῃ, καταγνωσθεὶς δὲ ὑπὸ τῶν Ἑλλανοδικῶν ἄδικα εἰργάσθαι καὶ ἀφῃρημένος τὴν νίκην ἔκφρων ἐγένετο ὑπὸ τῆς λύπης καὶ ἀνέστρεψε μὲν ἐς Ἀστυπάλαιαν, διδασκαλείῳ δ’ ἐπιστὰς ἐνταῦθα ὅσον ἑξήκοντα ἀριθμὸν παίδων ἀνατρέπει τὸν κίονα ὃς τὸν ὄροφον ἀνεῖχεν.", "st": "6.9"}, {"sp": "N", "t": "ἐμπεσόντος δὲ τοῦ ὀρόφου τοῖς παισί, καταλιθούμενος ὑπὸ τῶν ἀστῶν κατέφυγεν ἐς Ἀθηνᾶς ἱερόν· ἐσβάντος δὲ ἐς κιβωτὸν κειμένην ἐν τῷ ἱερῷ καὶ ἐφελκυσαμένου τὸ ἐπίθημα, κάματον ἐς ἀνωφελὲς οἱ Ἀστυπαλαιεῖς ἔκαμνον ἀνοίγειν τὴν κιβωτὸν πειρώμενοι· τέλος δὲ τὰ ξύλα τῆς κιβωτοῦ καταρρήξαντες, ὡς οὔτε ζῶντα Κλεομήδην οὔτε τεθνεῶτα εὕρισκον, ἀποστέλλουσιν ἄνδρας ἐς Δελφοὺς ἐρησομένους ὁποῖα ἐς Κλεομήδην τὰ συμβάντα ἦν.", "st": "6.9"}, {"sp": "N", "t": "τούτοις χρῆσαι τὴν Πυθίαν φασίν·<br>ὕστατος ἡρώων Κλεομήδης Ἀστυπαλαιεύς,<br>ὃν θυσίαις τιμᾶ⟨θ’ ἅ⟩τε μηκέτι θνητὸν ἐόντα.<br>Κλεομήδει μὲν οὖν Ἀστυπαλαιεῖς ἀπὸ τούτου τιμὰς ὡς ἥρωι νέμουσι·", "st": "6.9"}, {"sp": "N", "t": "παρὰ δὲ τοῦ Γέλωνος τὸ ἅρμα ἀνάκειται Φίλων, τέχνη τοῦ Αἰγινήτου Γλαυκίου. τούτῳ τῷ Φίλωνι Σιμωνίδης ὁ Λεωπρέπους ἐλεγεῖον δεξιώτατον ἐποίησε·<br>πατρὶς μὲν Κόρκυρα, Φίλων δ’ ὄνομ’· εἰμὶ δὲ Γλαύκου<br>υἱὸς καὶ νικῶ πὺξ δύ’ Ὀλυμπιάδας.<br>ἀνάκειται καὶ Μαντινεὺς Ἀγαμήτωρ, κρατήσας πυγμῇ παῖδας.", "st": "6.9"}, {"sp": "N", "t": "ἐπὶ δὲ τοῖς κατειλεγμένοις ἕστηκεν ὁ Καρύστιος Γλαῦκος· εἶναι δέ φασιν ἐξ Ἀνθηδόνος τῆς Βοιωτῶν τὸ ἄνωθεν αὐτὸν γένος ἀπὸ Γλαύκου τοῦ ἐν θαλάσσῃ δαίμονος. πατρὸς δὲ οὗτος ὁ Καρύστιος ἦν Δημύλου, καὶ γῆν φασιν αὐτὸν κατ’ ἀρχὰς ἐργάζεσθαι· ἐκπεσοῦσαν δὲ ἐκ τοῦ ἀρότρου τὴν ὕνιν πρὸς τὸ ἄροτρον καθήρμοσε τῇ χειρὶ ἀντὶ σφύρας χρώμενος, καί πως", "st": "6.10"}, {"sp": "N", "t": "ἐθεάσατο ὁ Δημύλος τὸ ὑπὸ τοῦ παιδὸς ποιούμενον καὶ ἐπὶ τούτῳ πυκτεύσοντα ἐς Ὀλυμπίαν αὐτὸν ἀνήγαγεν. ἔνθα δὴ ὁ Γλαῦκος ἅτε οὐκ ἐμπείρως ἔχων τῆς μάχης ἐτιτρώσκετο ὑπὸ τῶν ἀνταγωνιζομένων, καὶ ἡνίκα πρὸς τὸν λειπόμενον ἐξ αὐτῶν ἐπύκτευεν, ἀπαγορεύειν ὑπὸ πλήθους τῶν τραυμάτων ἐνομίζετο· καί οἱ τὸν πατέρα βοῆσαί φασιν “ὦ παῖ τὴν ἀπ’ ἀρότρου”. οὕτω γε δὴ βιαιοτέραν ἐς τὸν ἀνταγωνιζόμενον ἐνεγκὼν τὴν πληγὴν αὐτίκα εἶχε τὴν νίκην.", "st": "6.10"}, {"sp": "N", "t": "στεφάνους δὲ λέγεται καὶ ἄλλους Πύθια μὲν δὶς λαβεῖν, Νεμείων δὲ καὶ Ἰσθμίων ὀκτάκις ἐν ἑκατέρῳ ἀγῶνι. τοῦ Γλαύκου δὲ τὴν εἰκόνα ἀνέθηκε μὲν ὁ παῖς αὐτοῦ, Γλαυκίας δὲ Αἰγινήτης ἐποίησε· σκιαμαχοῦντος δὲ ὁ ἀνδριὰς παρέχεται σχῆμα, ὅτι ὁ Γλαῦκος ἦν ἐπιτηδειότατος τῶν κατ’ αὐτὸν χειρονομῆσαι πεφυκώς. ἀποθανόντα δὲ οἱ Καρύστιοι ταφῆναί φασιν αὐτὸν ἐν νήσῳ καλουμένῃ Γλαύκου καὶ ἐς ἡμᾶς ἔτι.", "st": "6.10"}, {"sp": "N", "t": "Δαμαρέτῳ δὲ Ἡραιεῖ υἱῷ τε τοῦ Δαμαρέτου καὶ υἱωνῷ δύο ἐν Ὀλυμπίᾳ γεγόνασιν ἑκάστῳ νῖκαι, Δαμαρέτῳ μὲν πέμπτῃ ἐπὶ ταῖς ἑξήκοντα Ὀλυμπιάδι, ὅτε ἐνομίσθη πρῶτον ὁ τοῦ ὁπλίτου δρόμος, καὶ ὡσαύτως τῇ ἐφεξῆς—πεποίηται ὁ ἀνδριὰς ἀσπίδα τε κατὰ τὰ αὐτὰ ἔχων τοῖς ἐφ’ ἡμῶν καὶ κράνος ἐπὶ τῇ κεφαλῇ καὶ κνημῖδας ἐπὶ τοῖς ποσί· ταῦτα μὲν δὴ ἀνὰ χρόνον ὑπό τε Ἠλείων καὶ ὑπὸ Ἑλλήνων τῶν ἄλλων ἀφῃρέθη τοῦ δρόμου—, Θεοπόμπῳ δὲ τῷ Δαμαρέτου καὶ αὖθις ἐκείνου παιδὶ ὁμωνύμῳ ἐπὶ πεντάθλῳ, Θεοπόμπῳ δὲ τῷ δευτέρῳ πάλης ἐγένοντο αἱ νῖκαι.", "st": "6.10"}, {"sp": "N", "t": "τὴν δὲ εἰκόνα Θεοπόμπου μὲν τοῦ παλαίσαντος τὸν ποιήσαντα οὐκ ἴσμεν, τὰς δὲ τοῦ πατρὸς αὐτοῦ καὶ τοῦ πάππου φησὶ τὸ ἐπίγραμμα Εὐτελίδα τε εἶναι καὶ Χρυσοθέμιδος Ἀργείων· οὐ μὴν παρ’ ὅτῳ γε ἐδιδάχθησαν δεδήλωκεν, ἔχει γὰρ δὴ οὕτως·<br>Εὐτελίδας καὶ Χρυσόθεμις τάδε ἔργα τέλεσσαν<br>Ἀργεῖοι, τέχναν εἰδότες ἐκ προτέρων.<br>Ἴκκος δὲ ὁ Νικολαΐδα Ταραντῖνος τόν τε Ὀλυμπικὸν στέφανον ἔσχεν ἐπὶ πεντάθλῳ καὶ ὕστερον γυμναστὴς ἄριστος λέγεται τῶν ἐφ’ αὑτοῦ γενέσθαι·", "st": "6.10"}, {"sp": "N", "t": "μετὰ δὲ Ἴκκον καταπαλαίσας παῖδας Παντάρκης ἕστηκεν Ἠλεῖος ὁ ἐρώμενος Φειδίου. ἐπὶ δὲ τῷ Παντάρκει Κλεοσθένους ἐστὶν ἅρμα ἀνδρὸς Ἐπιδαμνίου· τοῦτο ἔργον μέν ἐστιν Ἀγελάδα, ἕστηκε δὲ ὄπισθεν τοῦ Διὸς τοῦ ἀπὸ τῆς μάχης τῆς Πλαταιᾶσιν ἀνατεθέντος ὑπὸ Ἑλλήνων. ἐνίκα μὲν δὴ τὴν ἕκτην Ὀλυμπιάδα καὶ ἑξηκοστὴν ὁ Κλεοσθένης, ἀνέθηκε δὲ ὁμοῦ τοῖς ἵπποις αὑτοῦ τε εἰκόνα καὶ τὸν ἡνίοχον.", "st": "6.10"}, {"sp": "N", "t": "ἐπιγέγραπται δὲ καὶ τῶν ἵππων τὰ ὀνόματα Φοῖνιξ καὶ Κόραξ, ἑκατέρωθεν δὲ οἱ παρὰ τὸ ζυγόν, κατὰ μὲν τὰ δεξιὰ Κνακίας, ἐν δὲ τῇ ἀριστερᾷ Σάμος· καὶ ἐλεγεῖον τόδε ἐστὶν ἐπὶ τῷ ἅρματι·<br>Κλεοσθένης μ’ ἀνέθηκεν ὁ Πόντιος ἐξ Ἐπιδάμνου,<br>νικήσας ἵπποις καλὸν ἀγῶνα Διός.", "st": "6.10"}, {"sp": "N", "t": "τῶν δὲ ἱπποτροφησάντων ἐν Ἕλλησι πρῶτος ἐς Ὀλυμπίαν εἰκόνα ἀνέθηκεν ὁ Κλεοσθένης οὗτος. τὰ γὰρ Μιλτιάδου τοῦ Ἀθηναίου καὶ Εὐαγόρου τοῦ Λάκωνος ἀναθήματα, τοῦ μὲν ἅρματά ἐστιν, οὐ μὴν καὶ αὐτὸς ἐπὶ τοῖς ἅρμασιν Εὐαγόρας· τὰ Μιλτιάδου δέ, ὁποῖα ἐς Ὀλυμπίαν ἀνέθηκεν, ἑτέρωθι δὴ δηλώσω τοῦ λόγου. Ἐπιδάμνιοι δὲ χώραν μὲν ἥνπερ καὶ ἐξ ἀρχῆς, πόλιν δὲ οὐ τὴν ἀρχαίαν ἐπὶ ἡμῶν ἔχουσιν, ἐκείνης δὲ ἀφεστηκυῖαν ὀλίγον· ὄνομα δὲ τῇ πόλει τῇ νῦν Δυρράχιον ἀπὸ τοῦ οἰκιστοῦ.", "st": "6.10"}, {"sp": "N", "t": "Λυκῖνον δὲ Ἡραιέα καὶ Ἐπικράδιον Μαντινέα καὶ Τέλλωνα Ὀρεσθάσιον καὶ Ἠλεῖον Ἀγιάδαν ἐν παισὶν ἀνελομένους νίκας, Λυκῖνον μὲν δρόμου, τοὺς δὲ ἐπ’ αὐτῷ κατειλεγμένους πυγμῆς, Ἐπικράδιον μὲν καὶ Ἀγιάδαν, τὸν μὲν αὐτῶν Πτόλιχος Αἰγινήτης ἐποίησε, τὸν δὲ Ἀγιάδαν Σήραμβος, γένος καὶ οὗτος Αἰγινήτης· Λυκίνου δέ ἐστιν ὁ ἀνδριὰς Κλέωνος τέχνη· τὸν δὲ Τέλλωνα ὅστις εἰργάσατο, οὐ μνημονεύουσιν.", "st": "6.10"}, {"sp": "N", "t": "ἐφεξῆς τούτων ἀναθήματά ἐστιν Ἠλείων, Φίλιππος ὁ Ἀμύντου καὶ Ἀλέξανδρος ὁ Φιλίππου καὶ Σέλευκός τε καὶ Ἀντίγονος· τοῖς μὲν δὴ ἐφ’ ἵππων, Ἀντιγόνῳ δὲ ἀνὴρ πεζός ἐστιν ἡ εἰκών.", "st": "6.11"}, {"sp": "N", "t": "τῶν δὲ βασιλέων τῶν εἰρημένων ἕστηκεν οὐ πόρρω Θεαγένης ὁ Τιμοσθένους Θάσιος· Θάσιοι δὲ οὐ Τιμοσθένους παῖδα εἶναι Θεαγένην φασίν, ἀλλὰ ἱερᾶσθαι μὲν Ἡρακλεῖ τὸν Τιμοσθένην Θασίῳ, τοῦ Θεαγένους δὲ τῇ μητρὶ Ἡρακλέους συγγενέσθαι φάσμα ἐοικὸς Τιμοσθένει. ἔνατόν τε δὴ ἔτος εἶναι τῷ παιδὶ καὶ αὐτὸν ἀπὸ τῶν διδασκάλων φασὶν ἐς τὴν οἰκίαν ἐρχόμενον ἄγαλμα ὅτου δὴ θεῶν ἀνακείμενον ἐν τῇ ἀγορᾷ χαλκοῦν—χαίρειν γὰρ τῷ ἀγάλματι αὐτόν—, ἀνασπάσαι τε δὴ τὸ ἄγαλμα καὶ ἐπὶ τὸν ἕτερον τῶν ὤμων ἀναθέμενον ἐνεγκεῖν παρ’ αὑτόν.", "st": "6.11"}, {"sp": "N", "t": "ἐχόντων δὲ ὀργὴν ἐς αὐτὸν ἐπὶ τῷ πεποιημένῳ τῶν πολιτῶν, ἀνήρ τις αὐτῶν δόκιμος καὶ ἡλικίᾳ προήκων ἀποκτεῖναι μὲν σφᾶς τὸν παῖδα οὐκ ἐᾷ, ἐκεῖνον δὲ ἐκέλευσεν ἐκ τῆς οἰκίας αὖθις κομίσαι τὸ ἄγαλμα ἐς τὴν ἀγοράν· ὡς δὲ ἤνεγκε, μέγα αὐτίκα ἦν κλέος τοῦ παιδὸς ἐπὶ ἰσχύι, καὶ τὸ ἔργον ἀνὰ πᾶσαν ἐβεβόητο τὴν Ἑλλάδα.", "st": "6.11"}, {"sp": "N", "t": "ὅσα μὲν δὴ ἔργων τῶν Θεαγένους ἐς τὸν ἀγῶνα ἥκει τὸν Ὀλυμπικόν, προεδήλωσεν ὁ λόγος ἤδη μοι τὰ δοκιμώτατα ἐξ αὐτῶν, Εὔθυμόν τε ὡς κατεμαχέσατο τὸν πύκτην καὶ ὡς ὑπὸ Ἠλείων ἐπεβλήθη τῷ Θεαγένει ζημία. τότε μὲν δὴ τοῦ παγκρατίου τὴν νίκην ἀνὴρ ἐκ Μαντινείας Δρομεὺς ὄνομα πρῶτος ὧν ἴσμεν ἀκονιτὶ λέγεται λαβεῖν· τὴν δὲ Ὀλυμπιάδα τὴν ἐπὶ ταύτῃ παγκρατιάζων ὁ Θεαγένης ἐκράτει.", "st": "6.11"}, {"sp": "N", "t": "γεγόνασι δὲ αὐτῷ καὶ Πυθοῖ νῖκαι τρεῖς, αὗται μὲν ἐπὶ πυγμῇ, Νεμείων δὲ ἐννέα καὶ Ἰσθμίων δέκα παγκρατίου τε ἀναμὶξ καὶ πυγμῆς. ἐν Φθίᾳ δὲ τῇ Θεσσαλῶν πυγμῆς μὲν ἢ παγκρατίου παρῆκε τὴν σπουδήν, ἐφρόντιζε δὲ ὅπως καὶ ἐπὶ δρόμῳ ἐμφανὴς ἐν Ἕλλησιν εἴη, καὶ τοὺς ἐσελθόντας ἐς τὸν δόλιχον ἐκράτησεν· ἦν δέ οἱ πρὸς Ἀχιλλέα ἐμοὶ δοκεῖν τὸ φιλοτίμημα, ἐν πατρίδι τοῦ ὠκίστου τῶν καλουμένων ἡρώων ἀνελέσθαι δρόμου νίκην. τοὺς δὲ σύμπαντας στεφάνους τετρακοσίους τε ἔσχε καὶ χιλίους.", "st": "6.11"}, {"sp": "N", "t": "ὡς δὲ ἀπῆλθεν ἐξ ἀνθρώπων, ἀνὴρ τῶν τις ἀπηχθημένων ζῶντι αὐτῷ παρεγίνετο ἀνὰ πᾶσαν νύκτα ἐπὶ τοῦ Θεαγένους τὴν εἰκόνα καὶ ἐμαστίγου τὸν χαλκὸν ἅτε αὐτῷ Θεαγένει λυμαινόμενος· καὶ τὸν μὲν ὁ ἀνδριὰς ἐμπεσὼν ὕβρεως παύει, τοῦ ἀνθρώπου δὲ τοῦ ἀποθανόντος οἱ παῖδες τῇ εἰκόνι ἐπεξῄεσαν φόνου. καὶ οἱ Θάσιοι καταποντοῦσι τὴν εἰκόνα ἐπακολουθήσαντες γνώμῃ τῇ Δράκοντος, ὃς Ἀθηναίοις θεσμοὺς γράψας φονικοὺς ὑπερώρισε καὶ τὰ ἄψυχα, εἴγε ἐμπεσόν τι ἐξ αὐτῶν ἀποκτείνειεν ἄνθρωπον.", "st": "6.11"}, {"sp": "N", "t": "ἀνὰ χρόνον δέ, ὡς τοῖς Θασίοις οὐδένα ἀπεδίδου καρπὸν ἡ γῆ, θεωροὺς ἀποστέλλουσιν ἐς Δελφούς, καὶ αὐτοῖς ἔχρησεν ὁ θεὸς καταδέχεσθαι τοὺς δεδιωγμένους. καὶ οἱ μὲν ἐπὶ τῷ λόγῳ τούτῳ καταδεχθέντες οὐδὲν τῆς ἀκαρπίας παρείχοντο ἴαμα· δεύτερα οὖν ἐπὶ τὴν Πυθίαν ἔρχονται, λέγοντες ὡς καὶ ποιήσασιν αὐτοῖς τὰ χρησθέντα διαμένοι τὸ ἐκ τῶν θεῶν μήνιμα.", "st": "6.11"}, {"sp": "N", "t": "ἐνταῦθα ἀπεκρίνατό σφισιν ἡ Πυθία·<br>Θεαγένην δ’ ἄμνηστον ἀφήκατε τὸν μέγαν ὑμέων.<br>ἀπορούντων δὲ αὐτῶν ὁποίᾳ μηχανῇ τοῦ Θεαγένους τὴν εἰκόνα ἀνασώσωνται, φασὶν ἁλιέας ἀναχθέντας ἐς τὸ πέλαγος ἐπὶ ἰχθύων θήραν περισχεῖν τῷ δικτύῳ τὴν εἰκόνα καὶ ἀνενεγκεῖν αὖθις ἐς τὴν γῆν· Θάσιοι δὲ ἀναθέντες, ἔνθα καὶ ἐξ ἀρχῆς ἔκειτο, νομίζουσιν ἅτε θεῷ θύειν.", "st": "6.11"}, {"sp": "N", "t": "πολλαχοῦ δὲ καὶ ἑτέρωθι ἔν τε Ἕλλησιν οἶδα καὶ παρὰ βαρβάροις ἀγάλματα ἱδρυμένα Θεαγένους καὶ νοσήματά τε αὐτὸν ἰώμενον καὶ ἔχοντα παρὰ τῶν ἐπιχωρίων τιμάς. ὁ δὲ ἀνδριὰς τοῦ Θεαγένους ἐστὶν ἐν τῇ Ἄλτει, τέχνη τοῦ Αἰγινήτου Γλαυκίου.", "st": "6.11"}, {"sp": "N", "t": "πλησίον δὲ ἅρμα τέ ἐστι χαλκοῦν καὶ ἀνὴρ ἀναβεβηκὼς ἐπ’ αὐτό, κέλητες δὲ ἵπποι παρὰ τὸ ἅρμα εἷς ἑκατέρωθεν ἕστηκε καὶ ἐπὶ τῶν ἵππων καθέζονται παῖδες· ὑπομνήματα δὲ ἐπὶ νίκαις Ὀλυμπικαῖς ἐστιν Ἱέρωνος τοῦ Δεινομένους τυραννήσαντος Συρακουσίων μετὰ τὸν ἀδελφὸν Γέλωνα. τὰ δὲ ἀναθήματα οὐχ Ἱέρων ἀπέστειλεν, ἀλλ’ ὁ μὲν ἀποδοὺς τῷ θεῷ Δεινομένης ἐστὶν ὁ Ἱέρωνος, ἔργα δὲ τὸ μὲν Ὀνάτα τοῦ Αἰγινήτου τὸ ἅρμα, Καλάμιδος δὲ οἱ ἵπποι τε οἱ ἑκατέρωθεν καὶ ἐπ’ αὐτῶν εἰσιν οἱ παῖδες.", "st": "6.12"}, {"sp": "N", "t": "παρὰ δὲ τοῦ Ἱέρωνος τὸ ἅρμα ἀνήρ ἐστιν ὁμώνυμός τε τῷ Δεινομένους καὶ ἐν Συρακούσαις καὶ οὗτος τυραννήσας, Ἱέρων δὲ ἐκαλεῖτο Ἱεροκλέους· μετὰ δὲ τὴν Ἀγαθοκλέους τοῦ πρότερον τυραννήσαντος τελευτὴν Συρακουσίοις αὖθις ἀναπεφύκει τύραννος ὁ Ἱέρων οὗτος, τὴν δὲ ἀρχὴν εἶχεν ἔτει δευτέρῳ τῆς ἕκτης Ὀλυμπιάδος ἐπὶ ταῖς εἴκοσι καὶ ἑκατόν, ἣν Κυρηναῖος στάδιον ἐνίκησεν Ἰδαῖος.", "st": "6.12"}, {"sp": "N", "t": "οὗτος ὁ Ἱέρων ξενίαν πρὸς Πύρρον τὸν Αἰακίδου καὶ ὁμοῦ τῇ ξενίᾳ καὶ ἐπιγαμίαν ἐποιήσατο, Γέλωνι τῷ παιδὶ Νηρηίδα ἀγαγόμενος τὴν Πύρρου. Ῥωμαίων δὲ περὶ Σικελίας ἐς τὴν πρὸς Καρχηδονίους πόλεμον καταστάντων εἶχον μὲν οἱ Καρχηδόνιοι τῆς νήσου πλέον ἢ ἥμισυ, Ἱέρωνι δὲ συνιόντων μὲν ἄρτι ἐς τὸν πόλεμον ἑλέσθαι τὰ Καρχηδονίων ἤρεσε, μετὰ δὲ οὐ πολὺ δυνάμει τε εἶναι νομίζων τὰ Ῥωμαίων ἐχυρώτερα καὶ βεβαιότερα ἅμα ἐς φιλίαν μετεβάλετο ὡς τούτους.", "st": "6.12"}, {"sp": "N", "t": "τοῦ δέ οἱ βίου συνέβη γενέσθαι τὴν τελευτὴν ὑπὸ Δεινομένους, γένος μὲν Συρακουσίου, δυσμενέστατα δὲ ἀνδρὸς ἐς τυραννίδα ἔχοντος, ὃς καὶ ὕστερον τούτων Ἱπποκράτει τῷ ἀδελφῷ τῷ Ἐπικύδους ἐξ Ἐρβησσοῦ παρεληλυθότι ἄρτι ἐς Συρακούσας καὶ ἐς τὸ πλῆθος ποιεῖσθαι λόγους ἀρχομένῳ ἐπέδραμεν ὡς ἀποκτενῶν τὸν Ἱπποκράτην· τοῦ δέ οἱ ἀντιστάντος, κρατήσαντες τῶν δορυφόρων ἄλλοι διαφθείρουσι τὸν Δεινομένην. τοὺς ἀνδριάντας δὲ τοῦ Ἱέρωνος ἐν Ὀλυμπίᾳ, ἐφ’ ἵππου τὸν ἕτερον, τὸν δὲ αὐτῶν πεζόν, ἀνέθεσαν μὲν τοῦ Ἱέρωνος οἱ παῖδες, ἐποίησε δὲ Μίκων Νικηράτου Συρακούσιος.", "st": "6.12"}, {"sp": "N", "t": "μετὰ δὲ τοῦ Ἱέρωνος τὰς εἰκόνας Ἀρεὺς ὁ Ἀκροτάτου Λακεδαιμονίων βασιλεὺς καὶ Ἄρατος ἕστηκεν ὁ Κλεινίου, καὶ αὖθις ἀναβεβηκώς ἐστιν Ἀρεὺς ἵππον. ἀνάθημα δὲ ὁ μὲν Κορινθίων ὁ Ἄρατος, Ἀρεὺς δὲ Ἠλείων ἐστί· καί μοι τοῦ λόγου τὰ πρότερα οὔτε τῶν ἐς Ἄρατον οὔτε τῶν ἐς Ἀρέα ἀμνημόνως ἔσχεν, Ἄρατος δὲ καὶ ἅρματι ἀνηγορεύθη νικῶν ἐν Ὀλυμπίᾳ.", "st": "6.12"}, {"sp": "N", "t": "Τίμωνι δὲ τῷ Αἰσύπου καθέντι ἐς Ὀλυμπίαν ἵππους ἀνδρὶ Ἠλείῳ … ἐστι τοῦτο χαλκοῦν, ἐπ’ αὐτὸν ἀναβέβηκε παρθένος, ἐμοὶ δοκεῖν Νίκη. Κάλλωνα δὲ τὸν Ἁρμοδίου καὶ τὸν Μοσχίωνος Ἱππόμαχον, γένος τε Ἠλείους καὶ πυγμῇ κρατήσαντας ἐν παισί, τὸν μὲν αὐτῶν ἐποίησε Δάιππος, Ἱππομάχου δὲ ὅστις μὲν τὸν ἀνδριάντα εἰργάσατο οὐκ ἴσμεν, καταμαχέσασθαι δὲ τρεῖς φασιν ἀνταγωνιστὰς αὐτὸν οὔτε πληγὴν ἀποδεξάμενον οὔτε τι τρωθέντα τοῦ σώματος.", "st": "6.12"}, {"sp": "N", "t": "Θεόχρηστον δὲ Κυρηναῖον ἱπποτροφήσαντα κατὰ τὸ ἐπιχώριον τοῖς Λίβυσι καὶ αὐτόν τε ἐν Ὀλυμπίᾳ καὶ ἔτι πρότερον τὸν ὁμώνυμόν τε αὐτῷ καὶ τοῦ πατρὸς πατέρα, τούτους μὲν ἐνταῦθα ἵππων νίκας, ἐν δὲ Ἰσθμῷ τοῦ Θεοχρήστου λαβεῖν τὸν πατέρα, τὸ ἐπίγραμμα δηλοῖ τὸ ἐπὶ τῷ ἅρματι.", "st": "6.12"}, {"sp": "N", "t": "Ἀγήσαρχον δὲ τὸν Αἱμοστράτου Τριταιέα κρατῆσαι μὲν πύκτας ἄνδρας ἐν Ὀλυμπίᾳ καὶ Νεμέᾳ τε καὶ Πυθοῖ καὶ ἐν Ἰσθμῷ μαρτυρεῖ τὸ ἐλεγεῖον, Ἀρκάδας δὲ τοὺς Τριταιεῖς εἶναι τοῦ ἐλεγείου λέγοντος ⟨οὐκ⟩ ἀληθεύοντα εὕρισκον. πόλεων γὰρ τῶν ἐν Ἀρκαδίᾳ ταῖς μὲν ἐπειλημμέναις δόξης οὐδὲ τὰ ἐς τοὺς οἰκιστάς ἐστιν ἄγνωστα, τὰς δὲ ἐξ ἀρχῆς τε ὑπὸ ἀσθενείας ἀφανεστέρας καὶ δι’ αὐτὸ ἀνοικισθείσας ἐς Μεγάλην πόλιν, οὐ περιέχει σφᾶς γενόμενον ⟨τότε⟩ ὑπὸ [τε] τοῦ Ἀρκάδων κοινοῦ δόγμα;", "st": "6.12"}, {"sp": "N", "t": "οὐδέ τινα ἔστιν ἐν Ἕλλησι Τρίτειαν πόλιν ἄλλην γε ἢ τὴν Ἀχαιῶν εὑρεῖν. τηνικαῦτα γοῦν ἐς Ἀρκάδας ἡγοῖτο ἄν τις συντελέσαι τοὺς Τριταιεῖς, καθὰ καὶ νῦν ἔτι Ἀρκάδων αὐτῶν εἰσιν οἱ ἐς τὸ Ἀργολικὸν τελοῦντες. τοῦ Ἀγησάρχου δέ ἐστιν ἡ εἰκὼν τέχνη τῶν Πολυκλέους παίδων. τούτων μὲν δὴ ποιησόμεθα μνήμην καὶ ἐν τοῖς ὑστέροις τοῦ λόγου·", "st": "6.12"}, {"sp": "N", "t": "Ἀστύλος δὲ Κροτωνιάτης Πυθαγόρου μέν ἐστιν ἔργον, τρεῖς δὲ ἐφεξῆς Ὀλυμπίασι σταδίου τε καὶ διαύλου νίκας ἔσχεν. ὅτι δὲ ἐν δύο ταῖς ὑστέραις ἐς χάριν τὴν Ἱέρωνος τοῦ Δεινομένους ἀνηγόρευσεν αὑτὸν Συρακούσιον, τούτων ἕνεκα οἱ Κροτωνιᾶται τὴν οἰκίαν αὐτοῦ δεσμωτήριον εἶναι κατέγνωσαν καὶ τὴν εἰκόνα καθεῖλον παρὰ τῇ Ἥρᾳ τῇ Λακινίᾳ κειμένην.", "st": "6.13"}, {"sp": "N", "t": "ἀνάκειται δὲ [τῇ] ἐν Ὀλυμπίᾳ καὶ στήλη λέγουσα τοῦ Λακεδαιμονίου Χιόνιδος τὰς νίκας. εὐηθείας μὲν δὴ μετέχουσι καὶ ὅσοι Χίονιν αὐτὸν ἀναθεῖναι τὴν στήλην, ἀλλ’ οὐ Λακεδαιμονίων ἥγηνται τὸ δημόσιον· ἔστω γὰρ δήπου, ὡς ἐν τῇ στήλῃ, οὐκ εἶναί πω τοῦ ὅπλου τὸν δρόμον· πῶς ἂν οὖν ἐπίσταιτο ὁ Χίονις εἰ αὖθίς ποτε προσνομοθετήσουσιν Ἠλεῖοι; τούτων δὲ ἔτι ἐς πλέον ἥκουσιν εὐηθείας οἳ τὸν ἑστηκότα ἀνδριάντα παρὰ τῇ στήλῃ φασὶν εἰκόνα εἶναι Χιόνιδος, ἔργον ὄντα τοῦ Ἀθηναίου Μύρωνος.", "st": "6.13"}, {"sp": "N", "t": "ἐοικότα δὲ Χιόνιδι τὰ ἐς δόξαν καὶ ἀνὴρ Λύκιος παρέσχετο Ἑρμογένης Ξάνθιος, ὃς τὸν κότινον ἐν τρισὶν Ὀλυμπιάσιν ἀνείλετο ὀκτάκις ἐπίκλησίν τε ἔσχεν Ἵππος ὑπὸ Ἑλλήνων· ποιήσαιο δ’ ἂν καὶ Πολίτην ἐν μεγάλῳ θαύματι. ὁ Πολίτης δ’ ἦν οὗτος ἐκ Κεράμου τῆς ἐν τῇ [Θρακίᾳ] Καρίᾳ, ἀνέφηνε δὲ ἀρετὴν ποδῶν ἐν Ὀλυμπίᾳ πᾶσαν· ἀπὸ γὰρ τοῦ μηκίστου καὶ διαρκεστάτου δι’ ὀλιγίστου δὴ καιροῦ μεθηρμόσατο ἐπὶ ⟨τὸ⟩ βραχύτατον ὁμοῦ καὶ ὤκιστον, καὶ δολίχου τε ἐν ἡμέρᾳ τῇ αὐτῇ καὶ παραυτίκα σταδίου λαβὼν νίκην προσέθηκε [δὲ] διαύλου σφίσι τὴν τρίτην.", "st": "6.13"}, {"sp": "N", "t": "Πολίτης μὲν δὴ ἐπὶ τῆς δευτέρας … καὶ τέσσαρας, ὡς ⟨ἂν⟩ ἕκαστοι συνταχθῶσιν ὑπὸ τοῦ κλήρου, καὶ οὐκ ἀθρόους ἀφιᾶσιν ἐς τὸν δρόμον· οἳ δ’ ἂν ἐν ἑκάστῃ τάξει κρατήσωσιν, ὑπὲρ αὐτῶν αὖθις θέουσι τῶν ἄθλων· καὶ οὕτω σταδίου δύο ὁ στεφανούμενος ἀναιρήσεται νίκας. τὰ μέντοι ἐπιφανέστατα ἐς δρόμον Λεωνίδᾳ Ῥοδίῳ ἐστίν· ἐπὶ γὰρ τέσσαρας Ὀλυμπιάδας ἀκμάζων τε τῇ ὠκύτητι ἀντήρκεσε, καὶ γεγόνασιν αὐτῷ δρόμου νῖκαι δύο ἀριθμὸν καὶ δέκα.", "st": "6.13"}, {"sp": "N", "t": "Χιόνιδος δὲ οὐ πόρρω τῆς ἐν Ὀλυμπίᾳ στήλης Σκαῖος ἕστηκεν ὁ Δούριος Σάμιος, κρατήσας πυγμῇ παῖδας· τέχνη δὲ ἡ εἰκών ἐστι μὲν Ἱππίου τοῦ …, τὸ δὲ ἐπίγραμμα δηλοῖ τὸ ἐπ’ αὐτῷ, νικῆσαι Σκαῖον ἡνίκα ὁ Σαμίων δῆμος ἔφευγεν ἐκ τῆς νήσου, τὸν δὲ καιρὸν … ἐπὶ τὰ οἰκεῖα τὸν δῆμον.", "st": "6.13"}, {"sp": "N", "t": "παρὰ δὲ τὸν τύραννον Δίαλλος ὁ Πόλλιδος ἀνάκειται, γένος μὲν Σμυρναῖος, Ἰώνων δὲ πρῶτος λαβεῖν ἐν Ὀλυμπίᾳ φησὶν οὗτος ὁ Δίαλλος παγκρατίου στέφανον ἐν παισίν. Θερσίλοχον δὲ Κορκυραῖον καὶ Ἀριστίωνα Θεοφίλους Ἐπιδαύριον, τὸν μὲν ἀνδρῶν πυγμῆς, Θερσίλοχον δὲ λαβόντα ἐν παισὶ στέφανον, Πολύκλειτος ἐποίησε σφᾶς ὁ Ἀργεῖος.", "st": "6.13"}, {"sp": "N", "t": "Βύκελος δέ, ὃς Σικυωνίων πρῶτος πὺξ ἐκράτησεν ἐν παισίν, ἔστιν ἔργον Σικυωνίου Κανάχου παρὰ τῷ Ἀργείῳ Πολυκλείτῳ διδαχθέντος. παρὰ δὲ τὸν Βύκελον ὁπλίτης ἀνὴρ ἐπίκλησιν Λίβυς Μνασέας Κυρηναῖος ἕστηκε· Πυθαγόρας δὲ ὁ Ῥηγῖνος ἐποίησε τὴν εἰκόνα. Κυζικηνῷ δὲ Ἀγεμάχῳ τῶν ἐκ τῆς Ἀσιανῆς ἠπείρου … γενέσθαι ἐν Ἄργει τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ μηνύει.", "st": "6.13"}, {"sp": "N", "t": "Νάξου δὲ οἰκισθείσης ποτὲ ἐν Σικελίᾳ ὑπὸ Χαλκιδέων τῶν ἐπὶ Εὐρίπῳ, τῆς πόλεως μὲν οὐδὲ ἐρείπια ἐλείπετο ἐς ἡμᾶς ἔτι, ὄνομα δὲ καὶ ἐς τοὺς ἔπειτα εἶναι τῆς Νάξου Τίσανδρος ὁ Κλεοκρίτου μάλιστα αἰτίαν ἐχέτω· τετράκις γὰρ δὴ ἐν ἀνδράσι κατεμαχέσατο ὁ Τίσανδρος πύκτας ἐν Ὀλυμπίᾳ, τοσαῦται δὲ καὶ Πυθοῖ γεγόνασιν αὐτῷ νῖκαι, [καὶ] Κορινθίοις δὲ οὐκ ἦν πω τηνικαῦτα οὐδὲ Ἀργείοις ἐς ἅπαντας ὑπομνήματα τοὺς Νέμεια ⟨καὶ Ἴσθμια νικήσαν⟩τας.", "st": "6.13"}, {"sp": "N", "t": "ἡ δὲ ἵππος ἡ τοῦ Κορινθίου Φειδώλα ὄνομα μέν, ὡς οἱ Κορίνθιοι μνημονεύουσιν, ἔχει Αὔρα, τὸν δὲ ἀναβάτην ἔτι ἀρχομένου τοῦ δρόμου συνέπεσεν ἀποβαλεῖν αὐτήν· καὶ οὐδέν τι ἧσσον θέουσα ἐν κόσμῳ περί τε τὴν νύσσαν ἐπέστρεφε, καὶ ἐπεὶ τῆς σάλπιγγος ἤκουσεν, ἐπετάχυνεν ἐς πλέον τὸν δρόμον, φθάνει τε δὴ ἐπὶ τοὺς Ἑλλανοδίκας ἀφικομένη καὶ νικῶσα ἔγνω καὶ παύεται τοῦ δρόμου. Ἠλεῖοι δὲ ἀνηγόρευσαν ἐπὶ τῇ νίκῃ τὸν Φειδώλαν καὶ ἀναθεῖναί οἱ τὴν ἵππον ταύτην ἐφιᾶσιν.", "st": "6.13"}, {"sp": "N", "t": "ἐγένετο δὲ καὶ τοῦ Φειδώλα τοῖς παισὶν ἐπὶ κέλητι ἵππῳ νίκη, καὶ ὅ τε ἵππος ἐπὶ στήλῃ πεποιημένος καὶ ἐπίγραμμά ἐστιν ἐπ’ αὐτῷ·<br>ὠκυδρόμας Λύκος Ἴσθμι’ ἅπαξ, δύο δ’ ἐνθάδε νίκαις<br>Φειδώλα παίδων ἐστεφάνωσε δόμους.<br>οὐ μὴν τῷ γε ἐπιγράμματι καὶ τὰ Ἠλείων ἐς τοὺς Ὀλυμπιονίκας ὁμολογεῖ γράμματα· ὀγδόῃ γὰρ Ὀλυμπιάδι καὶ ἑξηκοστῇ καὶ οὐ πέρα ταύτης ἐστὶν ἐν τοῖς Ἠλείων γράμμασιν ἡ νίκη τῶν Φειδώλα παίδων·", "st": "6.13"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτως ἔχοντα ἴστω τις· Ἠλείοις δὲ ἀνδράσιν Ἀγαθίνῳ τε τῷ Θρασυβούλου καὶ Τηλεμάχῳ, Τηλεμάχῳ μὲν ἐπὶ ἵππων νίκῃ γέγονεν ἡ εἰκών, Ἀγαθῖνον δὲ ἀνέθεσαν Ἀχαιοὶ Πελληνεῖς. ἀνέθηκε δὲ καὶ ὁ Ἀθηναίων δῆμος Ἀριστοφῶντα Λυσίνου, παγκρατιαστὰς ἐν τῷ ἀγῶνι τῷ ἐν Ὀλυμπίᾳ κρατήσαντα ἄνδρας.", "st": "6.13"}, {"sp": "N", "t": "Φερίας δὲ Αἰγινήτης—οὗτος γὰρ δὴ παρὰ τὸν Ἀθηναῖον Ἀριστοφῶντα ἀνάκειται—ὀγδόῃ μὲν πρὸς ταῖς ἑβδομήκοντα Ὀλυμπιάδι κομιδῇ τε ἔδοξεν εἶναι νέος καὶ οὐκ ἐπιτήδειός πω νομισθεὶς παλαίειν ἀπηλάθη τοῦ ἀγῶνος, τῇ δὲ ἑξῆς—κατεδέχθη γὰρ τηνικαῦτα ἐς τοὺς παῖδας—ἐνίκα παλαίων. τῷ δὲ Φερίᾳ τούτῳ διάφορον καὶ οὐδαμῶς ἐοικυῖαν ἔσχεν ἐν Ὀλυμπίᾳ τύχην Νικασύλος Ῥόδιος.", "st": "6.14"}, {"sp": "N", "t": "ὄγδοον γὰρ ἐπὶ τοῖς δέκα ἔτεσι γεγονὼς μὴ παλαῖσαι μὲν ἐν παισὶν ὑπὸ Ἠλείων ἀπηλάθη, ἀνηγορεύθη δὲ ἐν ἀνδράσιν, ὥσπερ γε καὶ ἐνίκησεν· ἀνηγορεύθη δὲ καὶ ὕστερον Νεμέᾳ τε καὶ Ἰσθμῷ. γεγονότα δὲ εἰκοσαετῆ τὸ χρεὼν ἐπιλαμβάνει, πρὶν ἢ ἐς τὴν Ῥόδον αὐτὸν οἴκαδε ἀναστρέψαι. τὸ δὲ ἐν Ὀλυμπίᾳ τοῦ Ῥοδίου παλαιστοῦ τόλμημα Ἀρτεμίδωρος γένος Τραλλιανὸς ὑπερεβάλετο κατὰ ἐμὴν δόξαν. Ἀρτεμιδώρῳ γὰρ ἁμαρτεῖν μὲν Ὀλυμπίων συνέβη παγκρατιάζοντι ἐν παισίν, αἰτία δέ οἱ ἐγένετο τῆς διαμαρτίας τὸ ἄγαν νέον·", "st": "6.14"}, {"sp": "N", "t": "ὡς δὲ ἀφίκετο ἀγῶνος καιρὸς ὃν Σμυρναῖοι Ἰώνων ἄγουσιν, ἐς τοσοῦτο ἄρα αὐτῷ τὰ τῆς ῥώμης ἐπηύξητο ὡς κρατῆσαι παγκρατιάζοντα ἐπὶ ἡμέρας τῆς αὐτῆς τούς τε ἐξ Ὀλυμπίας ἀνταγωνιστὰς καὶ ἐπὶ τοῖς παισὶν οὓς ἀγενείους καλοῦσι καὶ τρίτα δὴ ὅ τι ἄριστον ἦν τῶν ἀνδρῶν. γενέσθαι δέ οἱ τὴν ἅμιλλαν πρὸς ἀγενείους τε καὶ ἄνδρας τὴν μὲν ἐκ γυμναστοῦ παρακλήσεώς φασι, τὴν δὲ ἐξ ἀνδρὸς παγκρατιαστοῦ λοιδορίας. ἀνείλετο δὲ ἐν ἀνδράσιν ὁ Ἀρτεμίδωρος Ὀλυμπικὴν νίκην δευτέρᾳ καὶ δεκάτῃ πρὸς διακοσίαις Ὀλυμπιάδι.", "st": "6.14"}, {"sp": "N", "t": "Νικασύλου δὲ τῆς εἰκόνος ἵππος τε οὐ μέγας ἔχεται χαλκοῦς, ὃν Κρόκων Ἐρετριεὺς ἀνέθηκεν ἀνελόμενος κέλητι ἵππῳ στέφανον, καὶ πλησίον τοῦ ἵππου Τελέστας ἐστὶ Μεσσήνιος κρατήσας πυγμῇ παῖδας· Σιλανίωνος δὲ ἔργον ἐστὶν ὁ Τελέστας.", "st": "6.14"}, {"sp": "N", "t": "Μίλωνα δὲ τὸν Διοτίμου πεποίηκε μὲν Δαμέας ἐκ Κρότωνος καὶ οὗτος· ἐγένοντο δὲ τῷ Μίλωνι ἓξ μὲν ἐν Ὀλυμπίᾳ πάλης νῖκαι, μία ⟨δὲ⟩ ἐν παισὶν ἐξ αὐτῶν, Πυθοῖ δὲ ἔν τε ἀνδράσιν ἓξ καὶ μία ἐνταῦθα ἐν παισίν. ἀφίκετο δὲ καὶ ἕβδομον παλαίσων ἐς Ὀλυμπίαν· ἀλλὰ γὰρ οὐκ ἐγένετο οἷός τε καταπαλαῖσαι Τιμασίθεον πολίτην τε ὄντα αὐτῷ καὶ ἡλικίᾳ νέον, πρὸς δὲ καὶ σύνεγγυς οὐκ ἐθέλοντα ἵστασθαι.", "st": "6.14"}, {"sp": "N", "t": "λέγεται δὲ καὶ ὡς ἐσκομίσειεν αὐτὸς αὑτοῦ τὸν ἀνδριάντα ἐς τὴν Ἄλτιν ὁ Μίλων, λέγεται δὲ ἐς αὐτὸν καὶ ⟨τὸ⟩ ἐπὶ τῇ ῥοιᾷ καὶ τὸ ἐπὶ τῷ δίσκῳ· ῥοιὰν μὲν δὴ οὕτω κατεῖχεν ὡς μήτε ἄλλῳ παρεῖναι βιαζομένῳ μήτε αὐτὸς λυμήνασθαι πιέζων, ἱστάμενος δὲ ἐπὶ ἀληλιμμένῳ τῷ δίσκῳ γέλωτα ἐποιεῖτο τοὺς ἐμπίπτοντάς τε καὶ ὠθοῦντας ἀπὸ τοῦ δίσκου. παρείχετο δὲ καὶ ἄλλα τοιάδε ἐς ἐπίδειξιν.", "st": "6.14"}, {"sp": "N", "t": "περιέδει τῷ μετώπῳ χορδὴν κατὰ ταὐτὰ δὴ καὶ εἰ ταινίαν περιθεῖτο ἢ στέφανον· κατέχων δὲ ἐντὸς χειλῶν τὸ ἆσθμα καὶ ἐμπιπλὰς αἵματος τὰς ἐν τῇ κεφαλῇ φλέβας, διερρήγνυεν ὑπὸ ἰσχύος τῶν φλεβῶν τὴν χορδήν. λέγεται δὲ καὶ ὡς τῆς δεξιᾶς χειρὸς τὸ μὲν ἐς τὸν ἀγκῶνα ἐκ τοῦ ὤμου παρ’ αὐτὴν καθίει τὴν πλευράν, τὸ δὲ ἀπὸ τοῦ ἀγκῶνος ἔτεινεν ἐς εὐθύ, τῶν δακτύλων τὸν μὲν αὐτῶν ἀναστρέφων τὸν ἀντίχειρα ἐς τὸ ἄνω, τῶν λοιπῶν δὲ ἀλλήλοις ἐπικειμένων κατὰ στοῖχον· τὸν ἐλάχιστον οὖν τῶν δακτύλων κάτω γινόμενον οὐκ ἀπεκίνησεν ἄν τις βιαζόμενος.", "st": "6.14"}, {"sp": "N", "t": "ἀποθανεῖν δὲ ὑπὸ θηρίων φασὶν αὐτόν· ἐπιτυχεῖν γὰρ αὐτὸν ἐν τῇ Κροτωνιάτιδι αὐαινομένῳ ξύλῳ, σφῆνες δὲ ἐγκείμενοι διίστασαν τὸ ξύλον· ὁ δὲ ὑπὸ φρονήματος ὁ Μίλων καθίησι τὰς χεῖρας ἐς τὸ ξύλον, ὀλισθάνουσί τε δὴ οἱ σφῆνες καὶ ἐχόμενος ὁ Μίλων ὑπὸ τοῦ ξύλου λύκοις ἐγίνετο εὕρημα. μάλιστα δέ πως τὸ θηρίον τοῦτο ἐν τῇ Κροτωνιάτιδι πολύ τε νέμεται καὶ ἄφθονον.", "st": "6.14"}, {"sp": "N", "t": "Μίλωνι μὲν δὴ τοιόνδε τέλος ἐπηκολούθησε· Πύρρον δὲ τὸν Αἰακίδου βασιλεύσαντα ἐν τῇ Θεσπρωτίδι ἠπείρῳ καὶ ἔργα πολλὰ ἐργασάμενον καὶ ἄξια μνήμης, ἃ ἐν τῷ λόγῳ τῷ ἐς Ἀθηναίους ἐδήλωσα, τοῦτον ἐς τὴν Ἄλτιν ἀνέθηκε Θρασύβουλος Ἠλεῖος. παρὰ δὲ τὸν Πύρρον ἀνὴρ μικρὸς αὐλοὺς ἔχων ἐστὶν ἐκτετυπωμένος ἐπὶ στήλῃ. τούτῳ Πυθικαὶ νῖκαι γεγόνασι τῷ ἀνδρὶ δευτέρῳ μετὰ Σακάδαν τὸν Ἀργεῖον·", "st": "6.14"}, {"sp": "N", "t": "Σακάδας μὲν γὰρ τὸν ἀγῶνα τὸν τεθέντα ὑπὸ Ἀμφικτυόνων οὐκ ὄντα πω στεφανίτην καὶ ἐπ’ ἐκείνῳ στεφανίτας δύο ἐνίκησε, Πυθόκριτος δὲ ὁ Σικυώνιος τὰς ἐφεξῆς τούτων πυθιάδας ἕξ, μόνος δὴ οὗτος αὐλητής· δῆλα δὲ ὅτι καὶ ἐν τῷ ἀγῶνι τῷ Ὀλυμπίασιν ἐπηύλησεν ἑξάκις τῷ πεντάθλῳ. Πυθοκρίτῳ μὲν γέγονεν ἀντὶ τούτων ἡ ἐν Ὀλυμπίᾳ στήλη καὶ ἐπίγραμμα ἐπ’ αὐτῇ,<br>Πυθοκρίτου<br>⟨τοῦ⟩ Καλλινίκου μνᾶμα ταὐλητᾶ ⟨τά⟩δε·<br>ἀνέθεσαν δὲ καὶ τὸ κοινὸν τὸ Αἰτωλῶν Κύλωνα, ὃς", "st": "6.14"}, {"sp": "N", "t": "ἀπὸ τῆς Ἀριστοτίμου τυραννίδος ἠλευθέρωσεν Ἠλείους. Γόργον δὲ τὸν Εὐκλήτου Μεσσήνιον ἀνελόμενον πεντάθλου νίκην καὶ Δαμάρετον καὶ τοῦτον Μεσσήνιον κρατήσαντα πυγμῇ παῖδας, τὸν μὲν αὐτῶν Βοιώτιος Θήρων, Δαμαρέτου δὲ τὴν εἰκόνα Ἀθηναῖος Σιλανίων ἐποίησεν. Ἀναυχίδας δὲ ὁ Φίλυος Ἠλεῖος πάλης ἔσχεν ἐν παισὶ στέφανον καὶ ἐν ἀνδράσιν ὕστερον· τούτῳ μὲν δὴ τὴν εἰκόνα ὅστις ὁ εἰργασμένος ἐστὶν οὐκ ἴσμεν, Ἄνοχος δὲ ὁ Ἀδαμάτα Ταραντῖνος, σταδίου λαβὼν καὶ διαύλου νίκην, ἐστὶν Ἀγελάδα τέχνη τοῦ Ἀργείου.", "st": "6.14"}, {"sp": "N", "t": "παῖδα δὲ ἐφ’ ἵππου καθήμενον καὶ ἑστηκότα ἄνδρα παρὰ τὸν ἵππον φησὶ τὸ ἐπίγραμμα εἶναι Ξενόμβροτον ἐκ Κῶ τῆς Μεροπίδος, ἐπὶ ἵππου νίκῃ κεκηρυγμένον, Ξενόδικον δὲ ἐπὶ πυγμῇ παίδων ἀναγορευθέντα· τὸν μὲν Παντίας αὐτῶν, Ξενόμβροτον δὲ Φιλότιμος Αἰγινήτης ἐποίησε. Πύθου δὲ τοῦ Ἀνδρομάχου, γένος ἀνδρὸς ἐξ Ἀβδήρων, ἐποίησε μὲν Λύσιππος, ἀνέθεσαν δὲ οἱ στρατιῶται δύο εἰκόνας· εἶναι δὲ ἡγεμών τις ξένων ἢ καὶ ἄλλως τὰ πολεμικὰ ἀγαθὸς ὁ Πύθης ἔοικε.", "st": "6.14"}, {"sp": "N", "t": "κεῖνται δὲ καὶ ἐν παισὶν εἰληφότες δρόμου νίκας Μενεπτόλεμος ἐξ Ἀπολλωνίας τῆς ἐν τῷ Ἰονίῳ ⟨κόλπῳ⟩ καὶ Κορκυραῖος Φίλων, ἐπὶ δὲ αὐτοῖς Ἱερώνυμος Ἄνδριος, ὃς τὸν Ἠλεῖον Τισαμενὸν πενταθλοῦντα ἐν Ὀλυμπίᾳ κατεπάλαισε τὸν [ἐν] Ἕλλησιν ὕστερον τούτων ἐναντία Μαρδονίου καὶ Μήδων Πλαταιᾶσι μαντευσάμενον. οὗτός τε δὴ ὁ Ἱερώνυμος ἀνάκειται καὶ παρ’ αὐτὸν παλαιστὴς παῖς, Ἄνδριος καὶ οὗτος, Προκλῆς ὁ Λυκαστίδα· τοῖς πλάσταις δὲ οἳ τοὺς ἀνδριάντας ἐποίησαν, τῷ μὲν Στόμιός ἐστιν ὄνομα, τῷ δὲ τὸν Προκλέα εἰργασμένῳ Σῶμις. Αἰσχίνῃ δὲ Ἠλείῳ νῖκαί τε δύο ἐγένοντο πεντάθλου καὶ ἴσαι ταῖς νίκαις αἱ εἰκόνες.", "st": "6.14"}, {"sp": "N", "t": "Ἀρχίππῳ δὲ Μιτυληναίῳ τοὺς ἐς τὴν πυγμὴν ἐσελθόντας κρατήσαντι ἄνδρας ἄλλο τοιόνδε προσποιοῦσιν οἱ Μιτυληναῖοι ἐς δόξαν, ὡς καὶ τὸν ἐν Ὀλυμπίᾳ καὶ Πυθοῖ καὶ Νεμέᾳ καὶ Ἰσθμῷ λάβοι στέφανον ἡλικίαν οὐ πρόσω γεγονὼς ἐτῶν εἴκοσι. τὸν δὲ παῖδα σταδιοδρόμον Ξένωνα Καλλιτέλους ἐν Λεπρέου τοῦ ἐν τῇ Τριφυλίᾳ Πυριλάμπης Μεσσήνιος, Κλεινόμαχον δὲ Ἠλεῖον ὅστις ὁ ποιήσας ἐστὶν οὐκ ἴσμεν· ἀνηγορεύθη δὲ ὁ Κλεινόμαχος ἐπὶ νίκῃ πεντάθλου.", "st": "6.15"}, {"sp": "N", "t": "Παντάρκην δὲ Ἠλεῖον Ἀχαιῶν ἀνάθημα εἶναι τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ φησιν· εἰρήνην τε γὰρ Ἀχαιοῖς ποιῆσαι καὶ Ἠλείοις αὐτόν, καὶ ὅσοι παρ’ ἀμφοτέρων πολεμούντων ἑαλώκεσαν, ἄφεσιν καὶ τούτοις γενέσθαι [καὶ] δι’ αὐτόν. οὗτος ἀνείλετο καὶ κέλητι ἵππῳ νίκην ὁ Παντάρκης, καί οἱ καὶ τῆς νίκης ὑπόμνημά ἐστιν ἐν Ὀλυμπίᾳ. Ὀλίδαν δὲ ἀνέθηκεν Ἠλεῖον τὸ ἔθνος τὸ Αἰτωλῶν, Χαρῖνος δὲ Ἠλεῖος ἐπὶ διαύλου τε ἀνάκειται καὶ ὅπλου νίκῃ· παρὰ δὲ αὐτὸν Ἀγέλης Χῖος κρατήσας πυγμῇ παῖδας, Θεομνήστου Σαρδιανοῦ τέχνη.", "st": "6.15"}, {"sp": "N", "t": "Κλειτομάχου δὲ Θηβαίου τὴν μὲν εἰκόνα ἀνέθηκεν Ἑρμοκράτης ὁ [τοῦ] ⟨Κλει⟩τομάχου πατήρ, τὰ δὲ οἱ ἐς δόξαν ἦν τοιάδε. ἐν Ἰσθμῷ παλαιστὰς κατεπάλαισεν ἄνδρας καὶ ἐπὶ ἡμέρας τῆς αὐτῆς τούς τε ⟨ἐς⟩ τὴν πυγμὴν καὶ τοὺς ἐς τὸ παγκράτιον ἐσελθόντας ἐκράτει τῇ μάχῃ· αἱ δὲ Πυθοῖ νῖκαι παγκρατίου μέν εἰσιν αὐτῷ πᾶσαι, τρεῖς δὲ ἀριθμόν· ἐν δὲ Ὀλυμπίᾳ δεύτερος ὁ Κλειτόμαχος οὗτος μετὰ τὸν Θάσιον Θεαγένην ἐπὶ παγκρατίῳ τε ἀνηγορεύθη καὶ πυγμῇ.", "st": "6.15"}, {"sp": "N", "t": "παγκρατίου μὲν οὖν μιᾷ πρὸς ⟨ταῖς⟩ τεσσαράκοντα καὶ ἑκατὸν Ὀλυμπιάσιν ἔφθανεν ἀνῃρημένος νίκην· ἡ δὲ Ὀλυμπιὰς ἡ ἐφεξῆς εἶχε μὲν τὸν Κλειτόμαχον τοῦτον παγκρατίου καὶ πυγμῆς ἀγωνιστήν, εἶχε δὲ καὶ Ἠλεῖον Κάπρον ἐπὶ ἡμέρας τῆς αὐτῆς παλαῖσαί τε ὁμοῦ καὶ παγκρατιάσαι προθυμούμενον.", "st": "6.15"}, {"sp": "N", "t": "γεγονυίας δὲ ἤδη τῷ Κάπρῳ νίκης ἐπὶ τῇ πάλῃ, ἀνεδίδασκεν ὁ Κλειτόμαχος τοὺς Ἑλλανοδίκας γενήσεσθαι σὺν τῷ δικαίῳ σφίσιν, εἰ τὸ παγκράτιον ἐσκαλέσαιντο πρὶν ἢ πυκτεύσαντα αὐτὸν λαβεῖν τραύματα· λέγει τε δὴ εἰκότα καὶ οὕτως ἐσκληθέντος τοῦ παγκρατίου κρατηθεὶς ὑπὸ τοῦ Κάπρου ὅμως ἐχρήσατο ἐς τοὺς πύκτας θυμῷ τε ἐρρωμένῳ καὶ ἀκμῆτι τῷ σώματι.", "st": "6.15"}, {"sp": "N", "t": "Ἐρυθραῖοι δὲ οἱ Ἴωνες Ἐπιθέρσην τὸν Μητροδώρου, δύο μὲν ἐν Ὀλυμπίᾳ πυγμῆς, δὶς δὲ Πυθοῖ νίκας καὶ ἐν Νεμέᾳ τε καὶ ἐν Ἰσθμῷ λαβόντα, οὗτοι μὲν τὸν Ἐπιθέρσην τοῦτον, Συρακούσιοι δὲ δύο μὲν Ἱέρωνος εἰκόνας τὸ δημόσιον, τρίτην δὲ ἀνέθεσαν οἱ τοῦ Ἱέρωνος παῖδες· ἐδήλωσα δὲ ὀλίγῳ τι πρότερον ὡς ὁμώνυμός τε τῷ Δεινομένους ὁ Ἱέρων οὗτος καὶ Συρακουσῶν εἴη κατὰ ταὐτὰ ἐκείνῳ τύραννος.", "st": "6.15"}, {"sp": "N", "t": "ἀνέθεσαν δὲ καὶ Ἠλεῖον ἄνδρα Τιμόπτολιν Λάμπιδος Παλεῖς, ἡ τετάρτη Κεφαλλήνων μοῖρα· οὗτοι δὲ οἱ Παλεῖς ἐκαλοῦντο Δουλιχιεῖς τὰ ἀρχαιότερα. ἀνάκειται δὲ καὶ Ἀρχίδαμος ὁ Ἀγησιλάου καὶ ἀνὴρ ὅστις δὴ θηρεύοντος παρεχόμενος σχῆμα. Δημήτριον δὲ τὸν ἐλάσαντα ἐπὶ Σέλευκον στρατιᾷ καὶ ἁλόντα ἐν τῇ μάχῃ καὶ τοῦ Δημητρίου τὸν παῖδα Ἀντίγονον ἀναθήματα ἴστω τις Βυζαντίων ὄντας.", "st": "6.15"}, {"sp": "N", "t": "Σπαρτιάτῃ δὲ Εὐτελίδᾳ γεγόνασιν ἐν παισὶ νῖκαι δύο ἐπὶ τῆς ὀγδόης καὶ τριακοστῆς Ὀλυμπιάδος πάλης, ἡ δὲ ἑτέρα πεντάθλου· πρῶτον γὰρ δὴ τότε οἱ παῖδες καὶ ὕστατον πενταθλήσοντες ἐσεκλήθησαν· ἔστι δὲ ἥ τε εἰκὼν ἀρχαία τοῦ Εὐτελίδα, καὶ τὰ ἐπὶ τῷ βάθρῳ γράμματα ἀμυδρὰ ὑπὸ τοῦ χρόνου.", "st": "6.15"}, {"sp": "N", "t": "μετὰ δὲ τὸν Εὐτελίδαν Ἀρεύς τε αὖθις ὁ Λακεδαιμονίων βασιλεὺς καὶ Ἠλεῖος παρ’ αὐτὸν ἀνάκειται Γόργος. μόνῳ δὲ ἀνθρώπων ἄχρι ἐμοῦ τῷ Γόργῳ τέσσαρες μὲν ⟨ἐν⟩ Ὀλυμπίᾳ γεγόνασιν ἐπὶ πεντάθλῳ, διαύλου δὲ καὶ ὅπλου μία ἐφ’ ἑκατέρῳ νίκη.", "st": "6.15"}, {"sp": "N", "t": "ὅτῳ δὲ παρεστήκασιν οἱ παῖδες, τοῦτον μὲν Πτολεμαῖον τὸν Λάγου φασὶν εἶναι· παρὰ δὲ αὐτὸν ἀνδριάντες δύο ἀνδρός εἰσιν Ἠλείου Κάπρου τοῦ Πυθαγόρου, πάλης τε εἰληφότος καὶ παγκρατίου στέφανον ἐπὶ ἡμέρας τῆς αὐτῆς· πρώτῳ δὲ γεγόνασιν ἀνθρώπων αἱ δύο νῖκαι τῷ Κάπρῳ τούτῳ. τὸν μὲν δὴ ἐπὶ τοῦ παγκρατίου καταγωνισθέντα ὑπ’ αὐτοῦ δεδήλωκεν [δὲ] ὁ λόγος ἤδη μοι· παλαίων δὲ κατέβαλεν Ἠλεῖον Παιάνιον Ὀλυμπιάδα πάλῃ τὴν προτέραν ἀνῃρημένον καὶ Πύθια παίδων τε πυγμῇ καὶ αὖθις ἐν ἀνδράσι πάλῃ τε καὶ πυγμῇ στεφανωθέντα ἐπὶ ἡμέρας τῆς αὐτῆς.", "st": "6.15"}, {"sp": "N", "t": "Κάπρῳ μὲν δὴ οὐκ ἄνευ μεγάλων πόνων καὶ ἰσχυρᾶς ταλαιπωρίας ἐγένοντο αἱ νῖκαι· εἰσὶ δὲ εἰκόνες ἐν Ὀλυμπίᾳ καὶ Ἀναυχίδᾳ καὶ Φερενίκῳ, γένος μὲν Ἠλείοις, πάλης δὲ ἐν παισὶν ἀνελομένοις στεφάνους. Πλείσταινον δὲ τὸν Εὐρυδάμου τοῦ ἐναντία Γαλατῶν στρατηγήσαντος Αἰτωλοῖς Θεσπιεῖς εἰσιν οἱ ἀναθέντες.", "st": "6.16"}, {"sp": "N", "t": "Τυδεὺς δὲ Ἠλεῖος Ἀντίγονόν τε τὸν Δημητρίου πατέρα καὶ Σέλευκον ἀνέθηκε· Σελεύκου δὲ ἐς ἅπαντας ἤρθη τὸ ὄνομα ἀνθρώπους ἄλλων τε ἕνεκα καὶ διὰ τὴν Δημητρίου μάλιστα ἅλωσιν. Τίμωνι δὲ ἀγώνων τε νῖκαι τῶν ἐν Ἕλλησιν ὑπάρχουσιν ἐπὶ πεντάθλῳ πλὴν τοῦ Ἰσθμικοῦ—τούτου δὲ [τῷ] μὴ ἀγωνιστὴς γενέσθαι κατὰ τὰ αὐτὰ Ἠλείοις τοῖς ἄλλοις εἴργετο —καὶ τάδε ἄλλα φησὶ τὸ ἐς αὐτὸν ἐπίγραμμα, Αἰτωλοῖς αὐτὸν ἐπιστρατείας μετασχεῖν ἐπὶ Θεσσαλοὺς καὶ φρουρᾶς ἡγεμόνα ἐν Ναυπάκτῳ φιλίᾳ γενέσθαι τῇ ἐς Αἰτωλούς.", "st": "6.16"}, {"sp": "N", "t": "Τίμωνος δὲ οὐ πόρρω τῆς εἰκόνος Ἑλλάς τε δὴ καὶ Ἦλις παρὰ τὴν Ἑλλάδα, ἡ μὲν Ἀντίγονον τὸν ἐπιτροπεύσαντα Φιλίππου τοῦ Δημητρίου, τῇ δὲ ἑτέρᾳ τῶν χειρῶν τὸν Φίλιππον στεφανοῦσα αὐτόν, ἡ δὲ Ἦλις Δημήτριον τὸν στρατεύσαντα ἐπὶ Σέλευκον καὶ Πτολεμαῖον τὸν Λάγου στεφανοῦσά ἐστιν.", "st": "6.16"}, {"sp": "N", "t": "Ἀριστείδῃ δὲ Ἠλείῳ γενέσθαι μὲν ὅπλου νίκην ἐν Ὀλυμπίᾳ, γενέσθαι δὲ καὶ διαύλου Πυθοῖ τὸ ἐπίγραμμα τὸ ἐπ’ αὐτῷ δηλοῖ Νεμείων τε ἐν παισὶν ἐπὶ τῷ ἱππίῳ ⟨δρόμῳ⟩. δρόμου δέ εἰσι τοῦ ἱππίου μῆκος μὲν δίαυλοι δύο, ἐκλειφθέντα δὲ ἐκ Νεμείων τε καὶ Ἰσθμίων αὐτὸν βασιλεὺς Ἀδριανὸς ἐς Νεμείων ἀγῶνα τῶν χειμερινῶν ἀπέδωκεν Ἀργείοις.", "st": "6.16"}, {"sp": "N", "t": "τοῦ δὲ Ἀριστείδου ἐγγύτατα Μενάλκης ἕστηκεν Ἠλεῖος, ἀναγορευθεὶς Ὀλυμπίασιν ἐπὶ πεντάθλῳ, καὶ Φιλωνίδης Ζώτου, γένος μὲν ἐκ Χερρονήσου τῆς Κρητῶν, Ἀλεξάνδρου δὲ ἡμεροδρόμος τοῦ Φιλίππου. μετὰ δὲ τοῦτον Βριμίας ἐστὶν Ἠλεῖος, κρατήσας ἄνδρας πυγμῇ, Λεωνίδας τε ἐκ Νάξου τῆς ἐν τῷ Αἰγαίῳ, Ψωφιδίων ἀνάθημα Ἀρκάδων, Ἀσάμωνός τε εἰκὼν ἐν ἀνδράσι πυγμῇ νενικηκότος, ἡ δὲ Νικάνδρου, διαύλου μὲν δύο ἐν Ὀλυμπίᾳ, Νεμείων δὲ ⟨καὶ Ἰσθμίων⟩ ἀναμὶξ ἐπὶ δρόμῳ νίκας ἓξ ἀνῃρημένου. ὁ δὲ Ἀσάμων καὶ ὁ Νίκανδρος Ἠλεῖοι μὲν ἦσαν, πεποίηκε δὲ τῷ μὲν Δάιππος τὴν εἰκόνα, Ἀσάμωνι δὲ Πυριλάμπης Μεσσήνιος.", "st": "6.16"}, {"sp": "N", "t": "Εὐαλκίδᾳ δὲ Ἠλείῳ καὶ Σελεάδᾳ Λακεδαιμονίῳ, τῷ μὲν ἐν παισὶν ἐγένοντο πυγμῆς νῖκαι, Σελεάδᾳ δὲ ἀνδρῶν πάλης. ἐνταῦθα καὶ ἅρμα οὐ μέγα ἀνάκειται Πολυπείθους Λάκωνος καὶ ἐπὶ στήλης τῆς αὐτῆς Καλλιτέλης ὁ τοῦ Πολυπείθους πατήρ, παλαιστὴς ἀνήρ· νῖκαι δέ σφισι τῷ μὲν ἵπποις, Καλλιτέλει δὲ παλαίσαντί εἰσιν.", "st": "6.16"}, {"sp": "N", "t": "ἰδιώτας δὲ ἄνδρας Ἠλείους Λάμπον Ἀρνίσκου καὶ … Ἀριστάρχου Ψωφίδιοι προξένους ὄντας σφίσιν ἀνέθεσαν ἢ καὶ ἄλλην τινὰ ἐς αὐτοὺς ἔχοντας εὔνοιαν· μέσος δὲ ἕστηκεν αὐτῶν Λύσιππος Ἠλεῖος καταπαλαίσας τοὺς ἐσελθόντας τῶν παίδων, Ἀνδρέας δὲ Ἀργεῖος ἐποίησε τοῦ Λυσίππου τὴν εἰκόνα.", "st": "6.16"}, {"sp": "N", "t": "Λακεδαιμονίῳ δὲ Δεινοσθένει σταδίου τε ἐγένετο ἐν ἀνδράσιν Ὀλυμπικὴ νίκη καὶ στήλην ἐν τῇ Ἄλτει παρὰ τὸν ἀνδριάντα ἀνέθηκεν ὁ Δεινοσθένης· ὁδοῦ δὲ τῆς ἐς Λακεδαίμονα ἐξ Ὀλυμπίας ἐπὶ ἑτέραν στήλην τὴν ἐν Λακεδαίμονι μέτρα ⟨φησὶν⟩ εἶναι σταδίους ἑξήκοντα καὶ ἑξακοσίους. Θεόδωρον δὲ λαβόντα ἐπὶ πεντάθλῳ νίκην καὶ Πύτταλον Λάμπιδος πυγμῇ παῖδας κρατήσαντα καὶ Νε⟨ο⟩λαΐδαν σταδίου τε ἀνελόμενον καὶ ὅπλου στέφανον, Ἠλείους σφᾶς ὄντας ἴστω τις· ἐπὶ δὲ τῷ Πυττάλῳ καὶ τάδε ἔτι λέγουσιν, ὡς γενομένης πρὸς Ἀρκάδας Ἠλείοις ἀμφισβητήσεως περὶ γῆς ὅρων εἶπεν οὗτος ὁ Πύτταλος τὴν δίκην· ὁ δέ οἱ ἀνδριὰς ἔργον ἐστὶν Ὀλυνθίου Σθέν⟨ν⟩ιδος.", "st": "6.16"}, {"sp": "N", "t": "ἐφεξῆς δὲ Πτολεμαῖός τέ ἐστιν ἀναβεβηκὼς ἵππον καὶ παρ’ αὐτὸν Ἠλεῖος ἀθλητὴς Παιάνιος ὁ Δαματρίου πάλης τε ἐν Ὀλυμπίᾳ καὶ τὰς δύο Πυθικὰς ἀνῃρημένος νίκας. Κλεάρετός τέ ἐστιν Ἠλεῖος πεντάθλου λαβὼν στέφανον καὶ ἅρμα ἀνδρὸς Ἀθηναίου Γλαύκωνος τοῦ Ἐτεοκλέους· ἀνηγορεύθη δὲ ὁ Γλαύκων οὗτος ἐπὶ ἅρματος τελείου δρόμῳ.", "st": "6.16"}, {"sp": "N", "t": "ταῦτα μὲν δὴ τὰ ἀξιολογώτατα ἀνδρὶ ποιουμένῳ τὴν ἔφοδον ἐν τῇ Ἄλτει κατὰ τὰ ἡμῖν εἰρημένα· εἰ δὲ ἀπὸ τοῦ Λεωνιδαίου πρὸς τὸν βωμὸν τὸν μέγαν ἀφικέσθαι τῇ δεξιᾷ θελήσειας, τοσάδε ἔστι σοι τῶν ἀνηκόντων ἐς μνήμην. Δημοκράτης Τενέδιος καὶ Ἠλεῖος Κριάννιος, οὗτος μὲν ὅπλου λαβὼν νίκην, Δημοκράτης δὲ ἀνδρῶν πάλης· ἀνδριάντας δὲ τοῦ μὲν Μιλήσιος Διονυσικλῆς, τοῦ δὲ Κριαννίου Μακεδὼν Λῦσός ἐστιν ὁ ἐργασάμενος.", "st": "6.17"}, {"sp": "N", "t": "Κλαζομενίου δὲ Ἡροδότου καὶ Φιλίνου τοῦ Ἡγεπόλιδος Κῴου ἀνέθεσαν τὰς εἰκόνας αἱ πόλεις, Κλαζομένιοι μὲν ὅτι ἐν Ὀλυμπίᾳ Κλαζομενίων πρῶτος ἀνηγορεύθη νικῶν Ἡρόδοτος, ἡ δέ οἱ νίκη σταδίου γέγονεν ἐν παισί, Φιλῖνον δὲ οἱ Κῷοι δόξης ἕνεκα ἀνέθεσαν· ἐν μέν γε Ὀλυμπίᾳ δρόμου γεγόνασιν αὐτῷ νῖκαι πέντε, τέσσαρες δὲ Πυθοῖ καὶ ἴσαι Νεμείων, ἐν δὲ Ἰσθμῷ μία ἐπὶ ταῖς δέκα.", "st": "6.17"}, {"sp": "N", "t": "Πτολεμαῖον δὲ τὸν Πτολεμαίου τοῦ Λάγου Ἀριστόλαος ἀνέθηκε Μακεδὼν ἀνήρ. ἀνάκειται δὲ καὶ πύκτης κρατήσας ἐν παισὶ Βούτας Πολυνείκους Μιλήσιος, καὶ Καλλικράτης ἀπὸ τῆς ἐπὶ Ληθαίῳ Μαγνησίας ἐπὶ τῷ ὁπλίτῃ δρόμῳ στεφάνους δύο ἀνῃρημένος· Λυσίππου δὲ ἔργον ἡ τοῦ Καλλικράτους ἐστὶν εἰκών.", "st": "6.17"}, {"sp": "N", "t": "Ἐνατίωνι δὲ καὶ Ἀλεξιβίῳ, τῷ μὲν ἐν παισὶ σταδίου, Ἀλεξιβίῳ δὲ πεντάθλου γέγονε νίκη, καὶ Ἡραία τε Ἀρκάδων ἐστὶν αὐτῷ πατρὶς καὶ Ἀκέστωρ ὁ τὴν εἰκόνα εἰργασμένος· Ἐνατίωνα δὲ ἧστινος ἦν οὐ δηλοῖ τὸ ἐπίγραμμα, ὅτι δὲ τοῦ Ἀρκάδων ἦν ἔθνους δηλοῖ. Κολοφώνιοι δὲ Ἑρμησιάναξ Ἀγονέου καὶ Εἰκάσιος Λυκίνου τε ὢν καὶ τῆς Ἑρμησιάνακτος θυγατρὸς κατεπάλαισαν μὲν παῖδας ἀμφότεροι, Ἑρμησιάνακτι δὲ καὶ ἀπὸ τοῦ κοινοῦ τοῦ Κολοφωνίων ὑπῆρξεν ἀνατεθῆναι τὴν εἰκόνα.", "st": "6.17"}, {"sp": "N", "t": "τούτων δέ εἰσιν Ἠλεῖοι πλησίον πυγμῇ παῖδας κρατήσαντες, ὁ μὲν Σθέννιδος ἔργον τοῦ Ὀλυνθίου Χοιρίλος, Θεότιμος δὲ Δαιτώνδα Σικυωνίου· παῖς δὲ ὁ Θεότιμος ἦν Μοσχίωνος, Ἀλεξάνδρῳ τῷ Φιλίππου τῆς ἐπὶ Δαρεῖον καὶ Πέρσας στρατείας μετασχόντος. δύο δὲ αὖθις ἐξ Ἤλιδος, Ἀρχίδαμος τεθρίππῳ νενικηκὼς καὶ Ἐπέραστός ἐστιν ὁ Θεογόνου ὅπλου νίκην ἀνῃρημένος·", "st": "6.17"}, {"sp": "N", "t": "εἶναι δὲ καὶ μάντις ὁ Ἐπέραστος τοῦ Κλυτιδῶν γένους φησὶν ἐπὶ τοῦ ἐπιγράμματος τῇ τελευτῇ,<br>τῶν δ’ ἱερογλώσσων Κλυτιδᾶν γένος εὔχομαι εἶναι<br>μάντις, ἀπ’ ἰσοθέων αἷμα Μελαμποδιδᾶν.<br>Μελάμποδος γὰρ ἦν τοῦ Ἀμυθάονος Μάντιος, τοῦ δὲ Ὀικλῆς, Κλυτίος δὲ Ἀλκμαίωνος τοῦ Ἀμφιαράου τοῦ Ὀϊκλέους· ἐγεγόνει δὲ τῷ Ἀλκμαίωνι ὁ Κλυτίος ἐκ τῆς Φηγέως θυγατρὸς καὶ ἐς τὴν Ἦλιν μετῴκησε, τοῖς ἀδελφοῖς εἶναι τῆς μητρὸς σύνοικος φεύγων, ἅτε τοῦ Ἀλκμαίωνος ἐπιστάμενος σφᾶς εἰργασμένους τὸν φόνον.", "st": "6.17"}, {"sp": "N", "t": "ἀνδριάντας δὲ ἀναμεμιγμένους οὐκ ἐπιφα⟨νέ⟩σιν ἄγαν ἀναθήμασιν Ἀλεξίνικόν τε Ἠλεῖον, τέχνην τοῦ Σικυωνίου Κανθάρου, πάλης ἐν παισὶν ἀνῃρημένον νίκην, καὶ τὸν Λεοντῖνον Γοργίαν ἰδεῖν ἔστιν· ἀναθεῖναι δὲ τὴν εἰκόνα ἐς Ὀλυμπίαν φησὶν Εὔμολπος ἀπόγονος τρίτος Δηικράτους συνοικήσαντος ἀδελφῇ τῇ Γοργίου.", "st": "6.17"}, {"sp": "N", "t": "οὗτος ὁ Γοργίας πατρὸς μὲν ἦν Χαρμαντίδου, λέγεται δὲ ἀνασώσασθαι μελέτην λόγων πρῶτος ἠμελημένην τε ἐς ἅπαν καὶ ἐς λήθην ὀλίγου δεῖν ἥκουσαν ἀνθρώποις· εὐδοκιμῆσαι δὲ Γοργίαν λόγων ἕνεκα ἔν τε πανηγύρει τῇ Ὀλυμπικῇ φασι καὶ ἀφικόμενον κατὰ πρεσβείαν ὁμοῦ Τισίᾳ παρ’ Ἀθηναίους. καίτοι ἄλλα τε Τισίας ἐς λόγους ἐσηνέγκατο καὶ πιθανώτατα τῶν καθ’ αὑτὸν γυναικὶ Συρακουσίᾳ χρημάτων ἔγραψεν ἀμφισβήτησιν·", "st": "6.17"}, {"sp": "N", "t": "ἀλλά γε ἐκείνου τε ἐς πλέον τιμῆς ἀφίκετο ὁ Γοργίας παρὰ Ἀθηναίοις, καὶ Ἰάσων ἐν Θεσσαλίᾳ τυραννήσας Πολυκράτους, οὐ τὰ ἔσχατα ἐνεγκαμένου διδασκαλείου τοῦ Ἀθήνῃσι, τούτου τοῦ ἀνδρὸς ἐπίπροσθεν αὐτὸν ὁ Ἰάσων ἐποιήσατο. βιῶναι δὲ ἔτη Γοργίαν πέντε φασὶν ἐπὶ τοῖς ἑκατόν· Λεοντίνων ⟨δὲ⟩ ἐρημωθεῖσάν ποτε ὑπὸ Συρακουσίων τὴν πόλιν κατ’ ἐμὲ αὖθις συνέβαινεν οἰκεῖσθαι.", "st": "6.17"}, {"sp": "N", "t": "ἔστι δὲ καὶ τοῦ Κυρηναίου Κρατισθένους χαλκοῦν ἅρμα, καὶ Νίκη τε ἐπιβέβηκε τοῦ ἅρματος καὶ αὐτὸς ὁ Κρατισθένης. δῆλα μὲν δὴ ὅτι ἵππων γέγονεν αὐτῷ νίκη· λέγεται δὲ καὶ ὡς Μνασέου τοῦ δρομέως, ἐπικληθέντος δὲ ὑπὸ Ἑλλήνων Λίβυος, εἴη παῖς ὁ Κρατισθένης. τὰ δὲ ἀναθήματα αὐτῷ τὰ ἐς Ὀλυμπίαν ἐστὶ τοῦ Ῥηγίνου Πυθαγόρου τέχνη.", "st": "6.18"}, {"sp": "N", "t": "ἐνταῦθα καὶ Ἀναξιμένους οἶδα εἰκόνα ἀνευρών, ὃς τὰ ἐν Ἕλλησιν ἀρχαῖα, καὶ ὅσα Φίλιππος ὁ Ἀμύντου καὶ ὕστερον Ἀλέξανδρος εἰργάσατο, συνέγραψεν ὁμοίως ἅπαντα· ἡ δέ οἱ τιμὴ γέγονεν ἐν Ὀλυμπίᾳ παρὰ τῶν Λαμψακηνῶν τοῦ δήμου. ὑπελίπετο δὲ Ἀναξιμένης τοσάδε ἐς μνήμην· βασιλέα γὰρ οὐ τὰ πάντα ἤπιον ἀλλὰ καὶ τὰ μάλιστα θυμῷ χρώμενον, Ἀλέξανδρον τὸν Φιλίππου, τέχνῃ περιῆλθε τοιᾷδε.", "st": "6.18"}, {"sp": "N", "t": "Λαμψακηνῶν τὰ βασιλέως τοῦ Περσῶν φρονησάντων ἢ καὶ αἰτίαν φρονῆσαι λαβόντων, ὁ Ἀλέξανδρος ἅτε ὑπερζέων ἐς αὐτοὺς τῇ ὀργῇ κακῶν ἠπείλει τὰ μέγιστα ἐργάσασθαι· οἱ δὲ ἅτε θέοντες περὶ γυναικῶν τε καὶ παίδων καὶ αὐτῆς πατρίδος ἀποστέλλουσιν Ἀναξιμένην ἱκετεύειν, Ἀλεξάνδρῳ τε αὐτῷ καὶ ἔτι Φιλίππῳ πρότερον γεγονότα ἐν γνώσει. προσῄει τε ὁ Ἀναξιμένης, καὶ τὸν Ἀλέξανδρον, πεπυσμένον καθ’ ἥντινα αἰτίαν ἥκοι, κατομόσασθαί φασιν ἐπονομάζοντα θεοὺς τοὺς Ἑλλήνων ἦ μὴν αὐτοῦ ταῖς δεήσεσιν ὁπόσα ἐστὶν ἐναντία ἐργάσασθαι.", "st": "6.18"}, {"sp": "N", "t": "ἔνθα δὴ εἶπεν Ἀναξιμένης· “χαρίσασθαι μοι τήνδε ὦ βασιλεῦ τὴν χάριν, ἐξανδραποδίσασθαι μὲν γυναῖκας καὶ τέκνα Λαμψακηνῶν, καταβαλεῖν δὲ καὶ ἐς ἔδαφος τὴν πόλιν πᾶσαν, τὰ δὲ ἱερὰ τῶν θεῶν σφισιν ἐμπρῆσαι”. ὁ μὲν ταῦτα ἔλεγεν, Ἀλέξανδρος δὲ οὔτε πρὸς τὸ σόφισμα ἀντιμηχανήσασθαί τι εὑρίσκων καὶ ἐνεχόμενος τῇ ἀνάγκῃ τοῦ ὅρκου συγγνώμην ἔνεμεν οὐκ ἐθέλων Λαμψακηνοῖς.", "st": "6.18"}, {"sp": "N", "t": "φαίνεται δὲ καὶ ἄνδρα ὁ Ἀναξιμένης ἐχθρὸν οὐκ ἀμαθέστατα ἀλλὰ καὶ ἐπιφθονώτατα ἀμυνάμενος. ἐπεφύκει μὲν αὐτὸς σοφιστὴς καὶ σοφιστῶν λόγους μιμεῖσθαι· ὡς δέ οἱ διαφορὰ ἐς Θεόπομπον ἐγεγόνει τὸν Δαμασιστράτου, γράφει βιβλίον ἐς Ἀθηναίους καὶ ἐπὶ Λακεδαιμονίοις ὁμοῦ καὶ Θηβαίοις συγγραφὴν λοίδορον. ὡς δὲ ἦν ἐς τὸ ἀκριβέστατον αὐτῷ μεμιμημένα, ἐπιγράψας τοῦ Θεοπόμπου τὸ ὄνομα τῷ βιβλίῳ διέπεμπεν ἐς τὰς πόλεις· καὶ αὐτός τε συγγεγραφὼς ἦν καὶ τὸ ἔχθος τὸ ἐς Θεόπομπον ἀνὰ πᾶσαν τὴν Ἑλλάδα ἐπηύξητο.", "st": "6.18"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ εἰπεῖν τις αὐτοσχεδίως Ἀναξιμένους πρότερός ἐστιν εὑρηκώς· τὰ ἔπη δὲ τὰ ἐς Ἀλέξανδρον οὔ μοι πιστά ἐστιν Ἀναξιμένην τὸν ποιήσαντα εἶναι. Σωτάδης δὲ ἐπὶ δολίχου νίκαις Ὀλυμπιάδι μὲν ἐνάτῃ καὶ ἐνενηκοστῇ Κρής, καθάπερ γε καὶ ἦν, ἀνερρήθη, ⟨τῇ⟩ ἐπὶ ταύτῃ δὲ λαβὼν χρήματα παρὰ τοῦ Ἐφεσίων κοινοῦ Ἐφεσίοις ἐσεποίησεν αὑτόν· καὶ αὐτὸν ἐπὶ τῷ ἔργῳ φυγῇ ζημιοῦσιν οἱ Κρῆτες.", "st": "6.18"}, {"sp": "N", "t": "πρῶται δὲ ἀθλητῶν ἀνετέθησαν ἐς Ὀλυμπίαν εἰκόνες Πραξιδάμαντός τε Αἰγινήτου νικήσαντος πυγμῇ τὴν ἐνάτην Ὀλυμπιάδα ἐπὶ ταῖς πεντήκοντα καὶ Ὀπουντίου Ῥηξιβίου παγκρατιαστὰς καταγωνισαμένου μιᾷ πρὸς ταῖς ἑξήκοντα Ὀλυμπιάδι· αὗται κεῖνται μὲν αἱ εἰκόνες οὐ πρόσω τῆς Οἰνομάου κίονος, ξύλου δέ εἰσιν εἰργασμέναι, Ῥηξιβίου μὲν συκῆς, ἡ δὲ τοῦ Αἰγινήτου κυπαρίσσου καὶ ἧσσον τῆς ἑτέρας πεπονηκυῖά ἐστιν.", "st": "6.18"}, {"sp": "N", "t": "ἔστι δὲ λίθου πωρίνου κρηπὶς ἐν τῇ Ἄλτει πρὸς ἄρκτον τοῦ Ἡραίου, κατὰ νώτου δὲ αὐτῆς παρήκει τὸ Κρόνιον· ἐπὶ ταύτης τῆς κρηπῖδός εἰσιν οἱ θησαυροί, καθὰ δὴ καὶ ἐν Δελφοῖς Ἑλλήνων τινὲς ἐποίησαν τῷ Ἀπόλλωνι θησαυρούς. ἔστι δὲ θησαυρὸς ἐν Ὀλυμπίᾳ Σικυωνίων καλούμενος, Μύρωνος δὲ ἀνάθημα τυραννήσαντος Σικυωνίων·", "st": "6.19"}, {"sp": "N", "t": "τοῦτον ᾠκοδόμησεν ὁ Μύρων νικήσας ἅρματι τὴν τρίτην καὶ τριακοστὴν Ὀλυμπιάδα. ἐν δὲ τῷ θησαυρῷ καὶ θαλάμους δύο ἐποίησε, τὸν μὲν Δώριον, τὸν δὲ ἐργασίας τῆς Ἰώνων. χαλκοῦ μὲν δὴ αὐτοὺς ἑώρων εἰργασμένους· εἰ δὲ καὶ Ταρτήσσιος χαλκὸς λόγῳ τῷ Ἠλείων ἐστίν, οὐκ οἶδα.", "st": "6.19"}, {"sp": "N", "t": "Ταρτήσσιον δὲ εἶναι ποταμὸν ἐν χώρᾳ τῇ Ἰβήρων λέγουσι στόμασιν ἐς θάλασσαν κατερχόμενον δυσὶ καὶ ὁμώνυμον αὐτῷ πόλιν ἐν μέσῳ τοῦ ποταμοῦ τῶν ἐκβολῶν κειμένην· τὸν δὲ ποταμὸν μέγιστόν τε ὄντα τῶν ἐν Ἰβηρίᾳ καὶ ἄμπωτιν παρεχόμενον Βαῖτιν ὠνόμασαν οἱ ὕστερον, εἰσὶ δ’ οἳ Καρπίαν Ἰβήρων πόλιν καλεῖσθαι νομίζουσι τὰ ἀρχαιότερα Ταρτησσόν.", "st": "6.19"}, {"sp": "N", "t": "ἐν Ὀλυμπίᾳ δὲ ἐπιγράμματα ἐπὶ τῷ ἐλάσσονί ἐστι τῶν θαλάμων, ἐς μὲν τοῦ χαλκοῦ τὸν σταθμόν, ὅτι πεντακόσια εἴη τάλαντα, ἐς δὲ τοὺς ἀναθέντας, Μύρωνα εἶναι καὶ τὸν Σικυωνίων δῆμον. ἐν τούτῳ τῷ θησαυρῷ δίσκοι τὸν ἀριθμὸν ἀνάκεινται τρεῖς, ὅσους ἐς τοῦ πεντάθλου τὸ ἀγώνισμα ἐσκομίζουσι· καὶ ἀσπίς ἐστιν ἐπίχαλκος γραφῇ τὰ ἐντὸς πεποικιλμένη καὶ κράνος τε καὶ κνημῖδες ὁμοῦ τῇ ἀσπίδι· ἐπίγραμμα δὲ ἐπὶ τοῖς ὅπλοις, ἀκροθίνιον τῷ Διὶ ὑπὸ Μυάνων ⟨ἀνα⟩τεθῆναι. οἵτινες δὲ οὗτοι ἦσαν, οὐ κατὰ τὰ αὐτὰ παρίστατο ἅπασιν εἰκάζειν·", "st": "6.19"}, {"sp": "N", "t": "ἐμὲ δὲ ἐσῆλθεν ἀνάμνησις ὡς Θουκυδίδης ποιήσειεν ἐν τοῖς λόγοις Λοκρῶν τῶν πρὸς τῇ Φωκίδι καὶ ἄλλας πόλεις, ἐν δὲ αὐταῖς εἶναι καὶ Μυονέας. οἱ Μυᾶνες οὖν οἱ ἐπὶ τῇ ἀσπίδι κατά γε ἡμετέραν γνώμην ἄνθρωποι μέν εἰσιν οἱ αὐτοὶ ⟨καὶ⟩ Μυονεῖς οἱ ἐν τῇ Λοκρίδι ἠπείρῳ· τὰ δὲ ἐπὶ τῇ ἀσπίδι γράμματα παρῆκται μὲν ἐπὶ βραχύ, πέπονθε δὲ αὐτὸ διὰ τοῦ ἀναθήματος τὸ ἀρχαῖον.", "st": "6.19"}, {"sp": "N", "t": "κεῖνται δὲ καὶ ἄλλα ἐνταῦθα ἄξια ἐπιμνησθῆναι, μάχαιρα ἡ Πέλοπος χρυσοῦ τὴν λαβὴν πεποιημένη, καὶ εἰργασμένον ἐλέφαντος κέρας τὸ Ἀμαλθείας, ἀνάθημα Μιλτιάδου τοῦ Κίμωνος, ὃς ⟨τὴν⟩ ἀρχὴν ἔσχεν ἐν χερρονήσῳ τῇ Θρᾳκίᾳ πρῶτος τῆς οἰκίας ταύτης· καὶ ἐπίγραμμα ἐπὶ τῷ κέρατί ἐστιν ἀρχαίοις Ἀττικοῖς γράμμασι,<br>Ζηνί μ’ ἄγαλμ’ ἀνέθηκαν Ὀλυμπίῳ ἐκ χερονήσου<br>τεῖχος ἑλόντες Ἀράτου· ἐπῆρχε δὲ Μιλτιάδης σφίν.<br>κεῖται δὲ καὶ ἄγαλμα πύξινον Ἀπόλλωνος ἐπιχρύσου τὴν κεφαλήν· ἀνατεθῆναι δὲ ὑπὸ Λοκρῶν φησι τῶν πρὸς Ζεφυρίῳ τῇ ἄκρᾳ, Πατροκλέα δὲ εἶναι Κατίλλου Κροτωνιάτην τὸν εἰργασμένον.", "st": "6.19"}, {"sp": "N", "t": "ἐφεξῆς δὲ τῷ Σικυωνίων ἐστὶν ὁ Καρχηδονίων θησαυρός, Ποθαίου τέχνη καὶ Ἀντιφίλου τε καὶ Μεγακλέους· ἀναθήματα δὲ ἐν αὐτῷ Ζεὺς μεγέθει μέγας καὶ θώρακες λινοῖ τρεῖς ἀριθμόν, Γέλωνος δὲ ἀνάθημα καὶ Συρακοσίων Φοίνικας ἤτοι τριήρεσιν ἢ καὶ πεζῇ μάχῃ κρατησάντων.", "st": "6.19"}, {"sp": "N", "t": "ὁ δὲ τρίτος τῶν θησαυρῶν καὶ ὁ τέταρτος ἀνάθημά ἐστιν Ἐπιδαμνίων … ἔχει μὲν πόλον ἀνεχόμενον ὑπὸ Ἄτλαντος, ἔχει δὲ Ἡρακλέα καὶ δένδρον τὸ παρὰ Ἑσπερίσι, τὴν μηλέαν, καὶ περι[ελ]ειλιγμένον τῇ μηλέᾳ τὸν δράκοντα, κέδρου μὲν καὶ ταῦτα, Θεοκλέους δὲ ἔργα τοῦ Ἡγύλου· ποιῆσαι δὲ αὐτὸν ὁμοῦ τῷ παιδί φησι τὰ ἐπὶ τοῦ πόλου γράμματα. αἱ δὲ Ἑσπερίδες —μετεκινήθησαν γὰρ ὑπὸ Ἠλείων—αὗται μὲν ἔτι καὶ ἐς ἐμὲ ἦσαν ἐν τῷ Ἡραίῳ· τὸν δὲ θησαυρὸν τοῖς Ἐπιδαμνίοις Πύρρος καὶ οἱ παῖδες Λακράτης τε καὶ Ἕρμων ἐποίησαν.", "st": "6.19"}, {"sp": "N", "t": "ᾠκοδόμησαν δὲ καὶ Συβαρῖται θησαυρὸν ἐχόμενον τοῦ Βυζαντίων· ὁπόσοι δὲ περὶ Ἰταλίας καὶ πόλεων ἐπολυπραγμόνησαν τῶν ἐν αὐτῇ, Λουπίας φασὶ κειμένην Βρεντεσίου τε μεταξὺ καὶ Ὑδροῦντος μεταβεβληκέναι τὸ ὄνομα, Σύβαριν οὖσαν τὸ ἀρχαῖον· ὁ δὲ ὅρμος ταῖς ναυσὶ χειροποίητος καὶ Ἀδριανοῦ βασιλέως ἐστὶν ἔργον.", "st": "6.19"}, {"sp": "N", "t": "πρὸς δὲ τῷ Συβαριτῶν Λιβύων ἐστὶ τῶν ἐν Κυρήνῃ θησαυρός· κεῖνται δὲ βασιλεῖς ἐν αὐτῷ Ῥωμαίων. Σικελιώτας δὲ Σελινουντίους ἀνέστησαν μὲν Καρχηδόνιοι πολέμῳ· πρὶν δὲ ἢ τὴν συμφορὰν γενέσθαι σφίσι, θησαυρὸν τῷ ἐν Ὀλυμπίᾳ Διὶ ἐποίησαν. Διόνυσος δέ ἐστιν ἐνταῦθα πρόσωπον καὶ ἄκρους πόδας καὶ τὰς χεῖρας ἐλέφαντος εἰργασμένος.", "st": "6.19"}, {"sp": "N", "t": "ἐν δὲ τῷ Μεταποντίνων θησαυρῷ—προσεχὴς γὰρ τῷ Σελινουντίων ἐστὶν οὗτος—ἐν τούτῳ πεποιημένος ἐστὶν Ἐνδυμίων· πλὴν δὲ ἐσθῆτός ἐστι τὰ λοιπὰ καὶ τῷ Ἐνδυμίωνι ἐλέφαντος. Μεταποντίνους δὲ ἥτις μὲν ἐπέλαβεν ἀπολέσθαι πρόφασις, οὐκ οἶδα· ἐπ’ ἐμοῦ δὲ ὅτι μὴ θέατρον καὶ περίβολοι τείχους ἄλλο ἐλείπετο οὐδὲν Μεταποντίου.", "st": "6.19"}, {"sp": "N", "t": "Μεγαρεῖς δὲ οἱ πρὸς τῇ Ἀττικῇ θησαυρόν τε ᾠκοδομήσαντο καὶ ἀναθήματα ἀνέθεσαν ἐς τὸν θησαυρὸν κέδρου ζῴδια χρυσῷ διηνθισμένα, τὴν πρὸς Ἀχελῷον Ἡρακλέους μάχην· Ζεὺς δὲ ἐνταῦθα καὶ ἡ Δηιάνειρα καὶ Ἀχελῷος καὶ Ἡρακλῆς ἐστιν, Ἄρης τε τῷ Ἀχελῴῳ βοηθῶν. εἱστήκει δὲ καὶ Ἀθηνᾶς ἄγαλμα ἅτε οὖσα τῷ Ἡρακλεῖ σύμμαχος· αὕτη παρὰ τὰς Ἑσπερίδας ἀνάκειται νῦν τὰς ἐν τῷ Ἡραίῳ.", "st": "6.19"}, {"sp": "N", "t": "τοῦ θησαυροῦ δὲ ἐπείργασται τῷ ἀετῷ ὁ γιγάντων καὶ θεῶν πόλεμος· ἀνάκειται δὲ καὶ ἀσπὶς ὑπὲρ τοῦ ἀετοῦ, τοὺς Μεγαρέας ἀπὸ Κορινθίων ἀναθεῖναι τὸν θησαυρὸν λέγουσα. ταύτην Μεγαρεῦσιν ἡγοῦμαι τὴν νίκην Ἀθήνῃσιν ἄρχοντος γενέσθαι Φόρβαντος, ἄρχοντος δὲ διὰ τοῦ αὑτοῦ βίου παντός· ἐνιαύσιαι γὰρ οὐκ ἦσάν πω τότε Ἀθηναίοις αἱ ἀρχαί, οὐ μὴν οὐδὲ ὑπὸ Ἠλείων ἀνεγράφοντό πω τηνικαῦτα αἱ Ὀλυμπιάδες.", "st": "6.19"}, {"sp": "N", "t": "λέγονται δὲ καὶ Ἀργεῖοι μετασχεῖν πρὸς τοὺς Κορινθίους Μεγαρεῦσι τοῦ ἔργου. τὸν δὲ ἐν Ὀλυμπίᾳ θησαυρὸν ἔτεσιν ὕστερον τῆς μάχης ἐποίησαν οἱ Μεγαρεῖς· τὰ δὲ ἀναθήματα ἐκ παλαιοῦ σφᾶς ἔχειν εἰκός, ἅ γε ὁ Λακεδαιμόνιος †Δόντας Διποίνου καὶ Σκύλλιδος μαθητὴς ἐποίησε.", "st": "6.19"}, {"sp": "N", "t": "τελευταῖος δὲ τῶν θησαυρῶν πρὸς αὐτῷ μέν ἐστιν ἤδη τῷ σταδίῳ, Γελῴων δὲ ἀνάθημα τόν τε θησαυρὸν καὶ τὰ ἀγάλματα εἶναι τὰ ἐν αὐτῷ λέγει τὸ ἐπίγραμμα· οὐ μέντοι ἀνακείμενά γε ἔτι ἀγάλματά ἐστιν.", "st": "6.19"}, {"sp": "N", "t": "τὸ δὲ ὄρος τὸ Κρόνιον κατὰ τὰ ἤδη λελεγμένα μοι παρὰ τὴν κρηπῖδα καὶ τοὺς ἐπ’ αὐτῇ παρήκει θησαυρούς. ἐπὶ δὲ τοῦ ὄρους τῇ κορυφῇ θύουσιν οἱ Βασίλαι καλούμενοι τῷ Κρόνῳ κατὰ ἰσημερίαν τὴν ἐν τῷ ἦρι, Ἐλαφίῳ μηνὶ παρὰ Ἠλείοις.", "st": "6.20"}, {"sp": "N", "t": "ἐν δὲ τοῖς πέρασι τοῦ Κρονίου κατὰ τὸ πρὸς τὴν ἄρκτον ἔστιν ἐν μέσῳ τῶν θησαυρῶν καὶ τοῦ ὄρους ἱερὸν Εἰλειθυίας, ἐν δὲ αὐτῷ Σωσίπολις Ἠλείοις ἐπιχώριος δαίμων ἔχει τιμάς. τὴν μὲν δὴ Εἰλείθυιαν ἐπονομάζοντες Ὀλυμπίαν, ἱερασομένην αἱροῦνται τῇ θεῷ κατὰ ἔτος ἕκαστον· ἡ δὲ πρεσβῦτις ἡ θεραπεύουσα τὸν Σωσίπολιν νόμῳ τε ἁγιστεύει τῷ Ἠλείων καὶ αὐτὴ λουτρά τε ἐσφέρει τῷ θεῷ καὶ μάζας κατατίθησιν αὐτῷ μεμαγμένας μέλιτι.", "st": "6.20"}, {"sp": "N", "t": "ἐν μὲν δὴ τῷ ἔμπροσθεν τοῦ ναοῦ—διπλοῦς γὰρ δὴ πεποίηται—τῆς τε Εἰλειθυίας βωμὸς καὶ ἔσοδος ἐς αὐτό ἐστιν ἀνθρώποις· ἐν δὲ τῷ ἐντὸς ὁ Σωσίπολις ἔχει τιμάς, καὶ ἐς αὐτὸ ἔσοδος οὐκ ἔστι πλὴν τῇ θεραπευούσῃ τὸν θεὸν ἐπὶ τὴν κεφαλὴν καὶ τὸ πρόσωπον ἐφειλκυσμένῃ ὕφος λευκόν· παρθένοι δὲ ἐν τῷ τῆς Εἰλειθυίας ὑπομένουσαι καὶ γυναῖκες ὕμνον ᾄδουσι, καθαγίζουσ⟨α⟩ι δὲ καὶ θυμιάματα παντοῖα αὐτῷ ἐπισπένδειν οὐ νομίζουσιν οἶνον. καὶ ὅρκος παρὰ τῷ Σωσιπόλιδι ἐπὶ μεγίστοις καθέστηκεν.", "st": "6.20"}, {"sp": "N", "t": "λέγεται δὲ καὶ Ἀρκάδων ἐς τὴν Ἠλείαν ἐσβεβληκότων στρατιᾷ καὶ τῶν Ἠλείων σφίσιν ἀντικαθημένων γυναῖκα ἀφικομένην παρὰ τῶν Ἠλείων τοὺς στρατηγούς, νήπιον παῖδα ἔχουσαν ἐπὶ τῷ μαστῷ, λέγειν ὡς τέκοι μὲν αὐτὴ τὸν παῖδα, διδοίη δὲ ἐξ ὀνειράτων συμμαχήσοντα Ἠλείοις. οἱ δὲ ἐν ταῖς ἀρχαῖς—πιστὰ γὰρ τὴν ἄνθρωπον ἡγοῦντο εἰρηκέναι—τιθέασι τὸ παιδίον πρὸ τοῦ στρατεύματος γυμνόν.", "st": "6.20"}, {"sp": "N", "t": "ἐπῄεσάν τε δὴ οἱ Ἀρκάδες καὶ τὸ παιδίον ἐνταῦθα ἤδη δράκων ἦν· ταραχθεῖσι δὲ ἐπὶ τῷ θεάματι τοῖς Ἀρκάσι καὶ ἐνδοῦσιν ἐς φυγὴν ἐπέκειντο οἱ Ἠλεῖοι, καὶ νίκην τε ἐπιφανεστάτην ἀνείλοντο καὶ ὄνομα τῷ θεῷ τίθενται Σωσίπολιν. ἔνθα δέ σφισιν ὁ δράκων ἔδοξεν ἐσδῦναι μετὰ τὴν μάχην, τὸ ἱερὸν ἐποίησαν ἐνταῦθα· σὺν δὲ αὐτῷ σέβεσθαι καὶ τὴν Εἰλείθυιαν ἐνόμισαν, ὅτι τὸν παῖδά σφισιν ἡ θεὸς αὕτη προήγαγεν ἐς ἀνθρώπους.", "st": "6.20"}, {"sp": "N", "t": "τοῖς δὲ τῶν Ἀρκάδων ἀποθανοῦσιν ἐν τῇ μάχῃ ἐστὶ τὸ μνῆμα ἐπὶ τοῦ λόφου διαβάντων τὸν Κλάδεον ὡς ἐπὶ ἡλίου δυσμάς. πλησίον δὲ τῆς Εἰλειθυίας ἐρείπια Ἀφροδίτης Οὐρανίας ἱεροῦ λείπεται, θύουσι δὲ καὶ αὐτόθι ἐπὶ τῶν βωμῶν.", "st": "6.20"}, {"sp": "N", "t": "ἔστι δὲ ἐντὸς τῆς Ἄλτεως κατὰ τὴν πομπικὴν ἔσοδον Ἱπποδάμειον καλούμενον, ὅσον πλέθρου χωρίον περιεχόμενον θριγκῷ· ἐς τοῦτο ἅπαξ κατὰ ἔτος ἕκαστον ἔστι ταῖς γυναιξὶν ἔσοδος, αἳ θύουσι τῇ Ἱπποδαμείᾳ καὶ ἄλλα ἐς τιμὴν δρῶσιν αὐτῆς. τὴν δὲ Ἱπποδάμειάν φασιν ἐς Μιδέαν τὴν ἐν τῇ Ἀργολίδι ἀποχωρῆσαι, ἅτε τοῦ Πέλοπος ἐπὶ τῷ Χρυσίππου θανάτῳ μάλιστα ἐς ἐκείνην ἔχοντος τὴν ὀργήν· αὐτοὶ δὲ ὕστερον ἐκ μαντείας κομίσαι φασὶ τῆς Ἱπποδαμείας τὰ ὀστᾶ ἐν Ὀλυμπίᾳ.", "st": "6.20"}, {"sp": "N", "t": "ἔστι δὲ ἐπὶ τῷ πέρατι τῶν ἀγαλμάτων ἃ ἐπὶ ζημίαις ἐποιήσαντο ἀθλητῶν, ἐπὶ τούτῳ τῷ πέρατί ἐστιν ἣν Κρυπτὴν ὀνομάζουσιν ἔσοδον· διὰ δὲ αὐτῆς τούς τε Ἑλλανοδίκας ἐσιέναι ἐς τὸ στάδιον καὶ τοὺς ἀγωνιστάς. τὸ μὲν δὴ στάδιον γῆς χῶμά ἐστι, πεποίηται δὲ ἐν αὐτῷ καθέδρα τοῖς τιθεῖσι τὸν ἀγῶνα. ἔστι δὲ ἀπαντικρὺ τῶν Ἑλλανοδικῶν βωμὸς λίθου λευκοῦ·", "st": "6.20"}, {"sp": "N", "t": "ἐπὶ τούτου καθεζομένη τοῦ βωμοῦ θεᾶται γυνὴ τὰ Ὀλύμπια, ἱέρεια Δήμητρος Χαμύνης, τιμὴν ταύτη⟨ν⟩ ἄλλοτε ἄλλη[ν] λαμβάνουσα παρὰ Ἠλείων. παρθένους δὲ οὐκ εἴργουσι θεᾶσθαι. πρὸς δὲ τοῦ σταδίου τῷ πέρατι, ᾗ τοῖς σταδιαδρόμοις ἄφεσις πεποίηται, Ἐνδυμίωνος μνῆμα ἐνταῦθα λόγῳ Ἠλείων ἐστίν.", "st": "6.20"}, {"sp": "N", "t": "ὑπερβάλλοντι δὲ ἐκ τοῦ σταδίου, καθότι οἱ Ἑλλανοδίκαι καθέζονται, κατὰ τοῦτο [τὸ] χωρίον ἐς τῶν ἵππων ἀνειμένον τοὺς δρόμους καὶ ἡ ἄφεσίς ἐστι τῶν ἵππων. παρέχεται μὲν οὖν σχῆμα ἡ ἄφεσις κατὰ πρῷραν νεώς, τέτραπται δὲ αὐτῆς τὸ ἔμβολον ἐς τὸν δρόμον· καθότι δὲ τῇ Ἀγνάπτου στοᾷ προσεχής ἐστιν ἡ πρῷρα, κατὰ τοῦτο εὐρεῖα γίνεται, δελφὶς δὲ ἐπὶ κανόνος κατὰ ἄκρον μάλιστα τὸ ἔμβολον πεποίηται χαλκοῦς.", "st": "6.20"}, {"sp": "N", "t": "ἑκατέρα μὲν δὴ πλευρὰ τῆς ἀφέσεως πλέον ἢ τετρακοσίους πόδας παρέχεται τοῦ μήκους, ᾠκοδόμηται δὲ ἐν αὐταῖς οἰκήματα· ταῦτα [τὰ] κλήρῳ τὰ οἰκήματα διαλαγχάνουσιν οἱ ἐσιόντες ἐς τὸν ἀγῶνα τῶν ἵππων. πρὸ δὲ τῶν ἁρμάτων ἢ καὶ ἵππων τῶν κελήτων, διήκει πρὸ αὐτῶν καλῴδιον ἀντὶ ὕσπληγος· βωμὸς δὲ ὠμῆς πλίνθου τὰ ἐκτὸς κεκονιαμένος ἐπὶ ἑκάστης Ὀλυμπιάδος ποιεῖται κατὰ τὴν πρῷραν μάλιστά που μέσην, ἀετὸς", "st": "6.20"}, {"sp": "N", "t": "δὲ ἐπὶ τῷ βωμῷ χαλκοῦς κεῖται τὰ πτερὰ ἐπὶ μήκιστον ἐκτείνων. ἀνακινεῖ μὲν δὴ τὸ ἐν τῷ βωμῷ μηχάνημα ὁ τεταγμένος ἐπὶ τῷ δρόμῳ· ἀνακινηθέντος δὲ ὁ μὲν ἐς τὸ ἄνω πεποίηται πηδᾶν ὁ ἀετός, ὡς τοῖς ἥκουσιν ἐπὶ τὴν θέαν γενέσθαι σύνοπτος, ὁ δελφὶς δὲ ἐς ἔδαφος πίπτει.", "st": "6.20"}, {"sp": "N", "t": "πρῶται μὲν δὴ ἑκατέρωθεν αἱ πρὸς τῇ στοᾷ τῇ Ἀγνάπτου χαλῶσιν ὕσπληγες, καὶ οἱ κατὰ ταύτας ἑστηκότες ἐκθέουσιν ἵπποι πρῶτοι· θέοντές τε δὴ γίνονται κατὰ τοὺς εἰληχότας ἑστάναι τὴν δευτέραν τάξιν, καὶ τηνικαῦτα χαλῶσιν αἱ ὕσπληγες αἱ ἐν τῇ δευτέρᾳ τάξει· διὰ πάντων τε κατὰ τὸν αὐτὸν λόγον συμβαίνει τῶν ἵππων, ἔστ’ ἂν ἐξισωθῶσιν ἀλλήλοις κατὰ τῆς πρῴρας τὸ ἔμβολον· τὸ ἀπὸ τούτου δὲ ἤδη καθέστηκεν ἐπίδειξις ἐπιστήμης τε ἡνιόχων καὶ ἵππων ὠκύτητος.", "st": "6.20"}, {"sp": "N", "t": "τὸ μὲν δὴ ἐξ ἀρχῆς Κλεοίτας ἐστὶν ἄφεσιν μηχανησάμενος, καὶ φρονῆσαί γε ⟨φαίνεται⟩ ἐπὶ τῷ εὑρήματι, ὡς καὶ ἐπίγραμμα ἐπὶ ἀνδριάντι τῷ Ἀθήνῃσιν ἐπιγράψαι<br>ὃς τὴν ἱππάφεσιν ⟨ἐν⟩ Ὀλυμπίᾳ εὕρατο πρῶτος,<br>τεῦξέ με Κλεοίτας υἱὸς Ἀριστοκλέους·<br>Κλεοίτα δέ φασιν ὕστερον Ἀριστείδην σοφίαν τινὰ καὶ αὐτὸν ἐς τὸ μηχάνημα ἐσενέγκασθαι.", "st": "6.20"}, {"sp": "N", "t": "παρεχομένου δὲ τοῦ ἱπποδρόμου παρήκουσαν ἐς πλέον τὴν ἑτέραν τῶν πλευρῶν, ἔστιν ἐπὶ τῆς μείζονος πλευρᾶς, οὔσης χώματος, κατὰ τὴν διέξοδον τὴν διὰ τοῦ χώματος τὸ τῶν ἵππων δεῖμα ὁ Ταράξιππος. σχῆμα μὲν βωμοῦ περιφεροῦς ἐστι, παραθέοντας δὲ κατὰ τοῦτο τοὺς ἵππους φόβος τε αὐτίκα ἰσχυρὸς ἀπ’ οὐδεμιᾶς προφάσεως φανερᾶς καὶ ἀπὸ τοῦ φόβου λαμβάνει ταραχή, τά τε δὴ ἅρματα καταγνύουσιν ὡς ἐπίπαν καὶ οἱ ἡνίοχοι τιτρώσκονται· καὶ τοῦδε ἡνίοχοι ἕνεκα θυσίας θύουσι καὶ γενέσθαι σφίσιν ἵλεων εὔχονται τὸν Ταράξιππον.", "st": "6.20"}, {"sp": "N", "t": "Ἕλληνες δὲ οὐ κατὰ τὰ αὐτὰ νομίζουσιν ἐς τὸν Ταράξιππον, ἀλλ’ οἱ μὲν εἶναι τάφον ἀνδρὸς αὐτόχθονος καὶ ἀγαθοῦ τὰ ἐς ἱππικήν— καὶ ὄνομα Ὠλένιον αὐτῷ τίθενται, ἀπὸ τούτου δὲ καὶ τὴν Ὠλενίαν ἐν τῇ Ἠλείᾳ πέτραν φασὶν ὀνομασθῆναι—, οἱ δὲ τὸν Φλιοῦντος Δαμέωνα μετασχόντα Ἡρακλεῖ τῆς ἐπὶ Αὐγέαν καὶ Ἠλείους στρατείας αὐτόν τε ἀποθανεῖν καὶ τὸν ἵππον ἐφ’ ᾧ ἐπωχεῖτο ὑπὸ Κτεάτου λέγουσι τοῦ Ἄκτορος, καὶ τὸ μνῆμα κοινὸν Δαμέωνι καὶ τῷ ἵππῳ γενέσθαι.", "st": "6.20"}, {"sp": "N", "t": "λέγουσι δὲ καὶ ὡς Μυρτίλῳ κενὸν ἐνταῦθα ἠρίον ποιήσειε Πέλοψ καὶ θύσειέ τε αὐτῷ τὸ ἐπὶ τῷ φόνῳ μήνιμα ἰώμενος καὶ ἐπονομάσαι Ταράξιππον, ὅτι τῷ Οἰνομάῳ διὰ τοῦ Μυρτίλου τῆς τέχνης ἐταράχθησαν αἱ ἵπποι· τοῖς δέ ἐστιν εἰρημένον ὡς αὐτὸς Οἰνόμαος ὁ τοὺς ἱππεύοντάς ἐστιν ἐν τῷ δρόμῳ βλάπτων. ἤκουσα δὲ καὶ ἐς τὸν Πορθάονος Ἀλκάθουν ἀγόντων τὴν αἰτίαν, ὡς ἐνταῦθα μέρη λάβοι γῆς ὁ Ἀλκάθους ἀποθανὼν ὑπὸ Οἰνομάου τῶν Ἱπποδαμείας γάμων ἕνεκα· ἅτε δὲ ἀτυχήσαντα ἐν ἱπποδρόμῳ, βάσκανόν τε εἶναι τοῖς ἱππεύουσι καὶ οὐκ εὐμενῆ δαίμονα.", "st": "6.20"}, {"sp": "N", "t": "ἀνὴρ δὲ Αἰγύπτιος Πέλοπα ἔφη παρὰ τοῦ Θηβαίου λαβόντα Ἀμφίονος κατορύξαι τι ἐνταῦθα, ἔνθα καλοῦσι τὸν Ταράξιππον, καὶ ὑπὸ τοῦ κατορωρυγμένου ταραχθῆναι μὲν τῷ Οἰνομάῳ τότε, ταράσσεσθαι δὲ καὶ ὕστερον τοῖς πᾶσι τὰς ἵππους· ἠξίου δὲ οὗτος ⟨ὁ⟩ Αἰγύπτιος εἶναι μὲν Ἀμφίονα, εἶναι δὲ καὶ τὸν Θρᾷκα Ὀρφέα μαγεῦσαι δεινόν, καὶ αὐτοῖς ἐπᾴδουσι θηρία τε ἀφικνεῖσθαι τῷ Ὀρφεῖ καὶ Ἀμφίονι ἐς τὰς τοῦ τείχους οἰκοδομίας τὰς πέτρας. ὁ δὲ πιθανώτατος ἐμοὶ δοκεῖν τῶν λόγων Ποσειδῶνος ἐπίκλησιν εἶναι τοῦ Ἱππίου φησίν.", "st": "6.20"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἐν Ἰσθμῷ Ταράξιππος Γλαῦκος ὁ Σισύφου· γενέσθαι δὲ αὐτῷ τὴν τελευτὴν λέγουσιν ὑπὸ τῶν ἵππων, ὅτε Ἄκαστος τὰ ἆθλα ἔθηκεν ἐπὶ τῷ πατρί. ἐν Νεμέᾳ δὲ τῇ Ἀργείων ἥρως μὲν ἦν οὐδεὶς ὅστις ἔβλαπτε τοὺς ἵππους· πέτρας δὲ ὑπὲρ τῶν ἵππων τὴν καμπὴν ἀνεστηκυίας χρόαν πυρρᾶς, ἡ ἀπ’ αὐτῆς αὐγὴ κατὰ ταὐτὰ καὶ εἰ πῦρ ἐνεποίει φόβον τοῖς ἵπποις. ἀλλὰ γὰρ ὁ ἐν Ὀλυμπίᾳ Ταράξιππος πολὺ δή τι ὑπερηρκώς ἐστιν ἐς ἵππων φόβον. ἐπὶ δὲ νύσσης μιᾶς Ἱπποδαμείας ἐστὶν εἰκὼν χαλκῆ, ταινίαν τε ἔχουσα καὶ ἀναδεῖν τὸν Πέλοπα μέλλουσα ἐπὶ τῇ νίκῃ.", "st": "6.20"}, {"sp": "N", "t": "τὸ δὲ ἕτερον τοῦ ἱπποδρόμου μέρος οὐ χῶμα γῆς ἐστιν, ὄρος δὲ οὐχ ὑψηλόν. ἐπὶ τῷ πέρατι τοῦ ὄρους ἱερὸν πεποίηται Δήμητρι ἐπίκλησιν Χαμύνῃ· καὶ οἱ μὲν ἀρχαῖον τὸ ὄνομα ἥγηνται, χανεῖν γὰρ τὴν γῆν ἐνταῦθα τὸ ἅρμα τοῦ Ἅιδου καὶ αὖθις μύσαι· οἱ δὲ Χάμυνον ἄνδρα Πισαῖον Πανταλέοντι ἐναντιούμενον τῷ Ὀμφαλίωνος τυραννοῦντι ἐν Πίσῃ καὶ ἀπόστασιν βουλεύοντι ἀπὸ Ἠλείων, ἀποθανεῖν φασιν αὐτὸν ὑπὸ τοῦ Πανταλέοντος καὶ ἀπὸ τοῦ Χαμύνου τῆς οὐσίας τῇ Δήμητρι οἰκοδομηθῆναι τὸ ἱερόν.", "st": "6.21"}, {"sp": "N", "t": "ἀγάλματα δὲ ἀντὶ τῶν ἀρχαίων Κόρην καὶ Δήμητρα λίθου τοῦ Πεντελῆσιν Ἀθηναῖος ἀνέθηκεν Ἡρώδης. ἐν τῷ γυμνασίῳ τῷ ἐν Ὀλυμπίᾳ πεντάθλοις μὲν καθεστήκασιν ἐν αὐτῷ καὶ δρομεῦσιν αἱ μελέται, κρηπὶς δὲ ἐν τῷ ὑπαίθρῳ λίθου πεποίηται· τὸ δὲ ἐξ ἀρχῆς καὶ τρόπαιον κατὰ Ἀρκάδων ἐπὶ τῇ κρηπῖδι εἱστήκει. ἔστι δὲ καὶ ἄλλος ἐλάσσων περίβολος ἐν ἀριστερᾷ τῆς ἐσόδου τῆς ἐς τὸ γυμνάσιον, καὶ αἱ παλαῖστραι τοῖς ἀθληταῖς εἰσιν ἐνταῦθα· τῆς στοᾶς δὲ τῆς πρὸς ἀνίσχοντα ἥλιον τοῦ γυμνασίου προσεχεῖς τῷ τοίχῳ τῶν ἀθλητῶν εἰσιν αἱ οἰκήσεις, ἐπί τε ἄνεμον τετραμμέναι Λίβα καὶ ἡλίου δυσμάς.", "st": "6.21"}, {"sp": "N", "t": "διαβάντων δὲ τὸν Κλάδεον τάφος τε Οἰνομάου γῆς χῶμα περιῳκοδομημένον λίθοις ἐστὶ καὶ ὑπὲρ τοῦ μνήματος ἐρείπια οἰκοδομημάτων, ἔνθα τῷ Οἰνομάῳ τὰς ἵππους αὐλίζεσθαι λέγουσιν. ὅροι δὲ πρὸς Ἀρκάδας τῆς χώρας τὰ μὲν παρόντα Ἠλείοις, τὰ δὲ ἐξ ἀρχῆς οἱ αὐτοὶ Πισαίοις καθεστήκεσαν ἀνέχοντες κατὰ τάδε. διαβάντων [δὲ] ποταμὸν Ἐρύμανθον κατὰ τὴν Σαύρου καλουμένην δειράδα τοῦ Σαύρου τε μνῆμα καὶ ἱερόν ἐστιν Ἡρακλέους, ἐρείπια ἐφ’ ἡμῶν· λέγουσι δὲ ὡς ὁδοιπόρους τε καὶ τοὺς προσοικοῦντας ὁ Σαῦρος ἐκακούργει, πρὶν ἢ παρὰ Ἡρακλέους τὴν δίκην ἔσχε.", "st": "6.21"}, {"sp": "N", "t": "κατὰ ταύτην τὴν ἐπώνυμον τοῦ λῃστοῦ δειράδα ποταμὸς ἀπὸ μεσημβρίας κατιὼν ἐς τὸν Ἀλφειὸν καταντικρὺ τοῦ Ἐρυμάνθου μάλιστα, οὗτός ἐστιν ὁ τὴν Πισαίαν πρὸς Ἀρκάδας διορίζων, ὄνομα δέ οἱ Διάγων. τεσσαράκοντα δὲ ἀπὸ τῆς Σαύρου δειράδος προελθόντι στάδια ἔστιν Ἀσκληπιοῦ ναός, ἐπίκλησιν μὲν Δημαινέτου ἀπὸ τοῦ ἱδρυσαμένου, ἐρείπια δὲ καὶ αὐτός· ᾠκοδομήθη δὲ ἐπὶ τοῦ ὑψηλοῦ παρὰ τὸν Ἀλφειόν.", "st": "6.21"}, {"sp": "N", "t": "τούτου δὲ οὐ πόρρω ἱερὸν Διονύσου Λευκυανίτου πεποίηται, καὶ ποταμὸς παρέξεισι ταύτῃ Λευκυανίας· ἐκδίδωσι μὲν οὖν καὶ οὗτος ἐς τὸν Ἀλφειόν, κάτεισι δὲ ἐκ Φολόης τοῦ ὄρους. διαβήσῃ τε δὴ τὸ ἀπὸ τούτου τὸν Ἀλφειὸν καὶ ἐντὸς γῆς ἔσῃ τῆς Πισαίας.", "st": "6.21"}, {"sp": "N", "t": "ἐν ταύτῃ τῇ χώρᾳ λόφος ἐστὶν ἀνήκων ἐς ὀξύ, ἐπὶ δὲ αὐτῷ πόλεως Φρίξας ἐρείπια καὶ Ἀθηνᾶς ἐστιν ἐπίκλησιν Κυδωνίας ναός. οὗτος μὲν οὐ τὰ πάντα ἐστὶ σῶς, βωμὸς δὲ καὶ ἐς ἐμὲ ἔτι· ἱδρύσασθαι δὲ τῇ θεῷ τὸ ἱερὸν Κλύμενόν φασιν ἀπόγονον Ἡρακλέους τοῦ Ἰδαίου, παραγενέσθαι δὲ αὐτὸν ἀπὸ Κυδωνίας τῆς Κρητικῆς καὶ τοῦ Ἰαρδάνου ποταμοῦ. λέγουσι δὲ καὶ Πέλοπα οἱ Ἠλεῖοι τῇ Ἀθηνᾷ θῦσαι τῇ Κυδωνίᾳ πρὶν ἢ ἐς τὸν ἀγῶνα αὐτὸν τῷ Οἰνομάῳ καθίστασθαι.", "st": "6.21"}, {"sp": "N", "t": "προϊόντι δὲ ἐντεῦθεν τό τε ὕδωρ τῆς Παρθενίας ἐστὶ καὶ πρὸς τῷ ποταμῷ τάφος ἵππων τῶν Μάρμακος· Ἱπποδαμείας δὲ μνηστῆρα ἔχει λόγος ἀφικέσθαι πρῶτον τοῦτον Μάρμακα καὶ ἀποθανεῖν ὑπὸ τοῦ Οἰνομάου πρὸ τῶν ἄλλων, ὀνόματα δὲ αὐτοῦ ταῖς ἵπποις Παρθενίαν τε εἶναι καὶ Ἐρίφαν—Οἰνόμαον δὲ ἐπικατασφάξαι μὲν τὰς ἵππους τῷ Μάρμακι, μεταδοῦναι μέντοι καὶ ταύταις ταφῆναι—, καὶ ὄνομα Παρθενίας τῷ ποταμῷ ἀπὸ ἵππου τῆς Μάρμακος.", "st": "6.21"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος Ἁρπινάτης καλούμενος ποταμὸς καὶ οὐ πολὺ ἀπὸ τοῦ ποταμοῦ πόλεως Ἁρπίνης ἄλλα τε ἐρείπια καὶ μάλιστα οἱ βωμοί· οἰκίσαι δὲ Οἰνόμαον τὴν πόλιν καὶ θέσθαι τὸ ὄνομα ἀπὸ τῆς μητρὸς λέγουσιν Ἁρπίνης.", "st": "6.21"}, {"sp": "N", "t": "προελθόντι δὲ οὐ πολὺ γῆς χῶμά ἐστιν ὑψηλόν, τῶν μνηστήρων τῶν Ἱπποδαμείας τάφος. Οἰνόμαον μὲν οὖν ἐγγὺς ἀλλήλων κρύπτειν γῇ φασιν οὐκ ἐπιφανῶς αὐτούς· Πέλοψ δὲ ὕστερον μνῆμα ἐν κοινῷ σφισιν ἐπὶ μέγα ἐξῆρε τιμῇ τῇ ἐς αὐτοὺς καὶ Ἱπποδαμείας χάριτι, δοκεῖν δέ μοι καὶ ὑπόμνημα ἐς τοὺς ἔπειτα ὅσων τε καὶ οἵων τὸν Οἰνόμαον κρατήσαντα ἐνίκησεν αὐτός.", "st": "6.21"}, {"sp": "N", "t": "ἀπέθανον δὲ ὑπὸ τοῦ Οἰνομάου κατὰ τὰ ἔπη τὰς μεγάλας Ἠοίας Ἀλκάθους ὁ Πορθάονος, δεύτερος οὗτος ἐπὶ τῷ Μάρμακι, μετὰ δὲ Ἀλκάθουν Εὐρύαλος καὶ Εὐρύμαχός τε καὶ Κρόταλος· τούτων μὲν οὖν γονέας τε καὶ πατρίδας οὐχ οἷά τε ἦν πυθέσθαι μοι, τὸν δὲ ἀποθανόντα ἐπ’ αὐτοῖς Ἀκρίαν τεκμαίροιτο ἄν τις Λακεδαιμόνιόν τε εἶναι καὶ οἰκιστὴν Ἀκριῶν. ἐπὶ δὲ τῷ Ἀκρίᾳ Κάπετόν φασιν ὑπὸ τοῦ Οἰνομάου φονευθῆναι καὶ Λυκοῦργον Λάσιόν τε καὶ Χαλκώδοντα καὶ Τρικόλωνον· ἀπόγονον δὲ αὐτὸν εἶναι καὶ ὁμώνυμον Τρικολώνῳ τῷ Λυκάονος λέγουσιν οἱ Ἀρκάδες.", "st": "6.21"}, {"sp": "N", "t": "Τρικολώνου δὲ ὕστερον ἐπέλαβεν ἐν τῷ δρόμῳ τὸ χρεὼν Ἀριστόμαχόν τε καὶ Πρίαντα, ἔτι δὲ Πελάγοντα καὶ Αἰόλιόν τε καὶ Κρόνιον. οἱ δὲ καὶ ἐπαριθμοῦσι τοῖς κατειλεγμένοις Ἐρύθραν παῖδα Λεύκωνος τοῦ Ἀθάμαντος—ἀπὸ τούτου Ἐρυθραὶ πόλισμα ἐκαλεῖτο Βοιωτῶν—καὶ Ἠιονέα Μάγνητος τοῦ Αἰόλου. τούτοις μὲν δὴ ἐνταῦθά ἐστι τὸ μνῆμα, καὶ τὸν Πέλοπα, ἡνίκα τῶν Πισαίων ἔσχε τὴν ἀρχήν, φασὶν ἐναγίζειν αὐτοῖς ἀνὰ πᾶν ἔτος.", "st": "6.21"}, {"sp": "N", "t": "προελθόντι δὲ ὅσον τε στάδιον ἀπὸ τοῦ τάφου σημεῖά ἐστιν ἱεροῦ Κορδάκας ἐπίκλησιν Ἀρτέμιδος, ὅτι οἱ τοῦ Πέλοπος ἀκόλουθοι τὰ ἐπινίκια ἤγαγον παρὰ τῇ θεῷ ταύτῃ καὶ ὠρχήσαντο ἐπιχώριον τοῖς περὶ τὸν Σίπυλον κόρδακα ὄρχησιν. τοῦ ἱεροῦ δὲ οὐ πόρρω οἴκημά τε οὐ μέγα καὶ κιβωτός ἐστιν ἐν αὐτῷ χαλκῆ· ὀστᾶ τὰ Πέλοπος ἐν τῇ κιβωτῷ φυλάσσουσι. τείχους δὲ ἢ ἄλλου κατασκευάσματος ἐλείπετο οὐδὲν ἔτι, ἄμπελοι δὲ ἦσαν διὰ τοῦ χωρίου πεφυτευμέναι παντός, ἔνθα ἡ Πίσα ᾠκεῖτο.", "st": "6.22"}, {"sp": "N", "t": "οἰκιστὴν μὲν δὴ γενέσθαι τῇ πόλει Πίσον τὸν Περιήρους φασὶ τοῦ Αἰόλου· Πισαῖοι δὲ ἐφειλκύσαντο αὐθαίρετον συμφορὰν ἀπεχθανόμενοί τε Ἠλείοις καὶ σπουδὴν ποιούμενοι τιθέναι τὸν Ὀλυμπικὸν ἀγῶνα ἀντὶ Ἠλείων, οἵγε Ὀλυμπιάδι μὲν τῇ ὀγδόῃ τὸν Ἀργεῖον ἐπηγάγοντο Φείδωνα τυράννων τῶν ἐν Ἕλλησι μάλιστα ὑβρίσαντα καὶ τὸν ἀγῶνα ἔθεσαν ὁμοῦ τῷ Φείδωνι, τετάρτῃ δὲ Ὀλυμπιάδι καὶ τριακοστῇ στρατὸν οἱ Πισαῖοι καὶ βασιλεὺς αὐτῶν Πανταλέων ὁ Ὀμφαλίωνος παρὰ τῶν προσχώρων ἀθροίσαντες ἐποίησαν ἀντὶ Ἠλείων τὰ Ὀλύμπια.", "st": "6.22"}, {"sp": "N", "t": "ταύτας τὰς Ὀλυμπιάδας καὶ ἐπ’ αὐταῖς τὴν τετάρτην τε καὶ ἑκατοστήν, τεθεῖσαν δὲ ὑπὸ Ἀρκάδων, ἀνολυμπιάδα⟨ς⟩ οἱ Ἠλεῖοι καλοῦντες οὐ σφᾶς ἐν καταλόγῳ τῶν Ὀλυμπιάδων γράφουσιν. ὀγδόῃ δὲ ἐπὶ ταῖς τεσσαράκοντα Ὀλυμπιάδι Δαμοφῶν ὁ Πανταλέοντος ὑπόνοιαν μέν τινα παρέσχεν Ἠλείοις νεώτερα ἐς αὐτοὺς βουλεύειν, ἐσβαλόντας δὲ ἐς τὴν Πισαίαν σὺν ὅπλοις ἀπελθεῖν οἴκαδε ἀπράκτους ἔπεισε δεήσεσί τε καὶ ὅρκοις.", "st": "6.22"}, {"sp": "N", "t": "Πύρρου δὲ τοῦ Πανταλέοντος μετὰ Δαμοφῶντα τὸν ἀδελφὸν βασιλεύσαντος Πισαῖοι πόλεμον ἑκούσιον ἐπανείλοντο Ἠλείοις, συναπέστησαν δέ σφισιν ἀπὸ Ἠλείων Μακίστιοι καὶ Σκιλλούντιοι, οὗτοι μὲν ἐκ τῆς Τριφυλίας, τῶν δὲ ἄλλων περιοίκων Δυσπόντιοι· τούτοις καὶ μάλιστα ἐς τοὺς Πισαίους οἰκεῖα ἦν, καὶ οἰκιστὴν Δυσποντέα γενέσθαι σφίσιν Οἰνομάου παῖδα ἐμνημόνευον. Πισαίους μὲν δὴ καὶ ὅσοι τοῦ πολέμου Πισαίοις μετέσχον, ἐπέλαβεν ἀναστάτους ὑπὸ Ἠλείων γενέσθαι·", "st": "6.22"}, {"sp": "N", "t": "Πύλου δὲ τῆς ἐν τῇ Ἠλείᾳ δῆλα τὰ ἐρείπια κατὰ τὴν ἐξ Ὀλυμπίας ἐστὶν ἐς Ἦλιν ὀρεινὴν ὁδόν, ὀγδοήκοντα δὲ στάδια ἐς Ἦλιν ἀπὸ τῆς Πύλου. ταύτην τὴν Πύλον ᾤκισε μὲν κατὰ τὰ ἤδη λελεγμένα μοι Μεγαρεὺς ἀνὴρ Πύλων ὁ Κλήσωνος· γενομένη δὲ ὑπὸ Ἡρακλέους ἀνάστατος καὶ αὖθις ἐπισυνοικισθεῖσα ὑπὸ Ἠλείων, ἔμελλεν ἀνὰ χρόνον οὐχ ἕξειν οἰκήτορας. παρὰ δὲ αὐτὴν ποταμὸς Λάδων κάτεισιν ἐς τὸν Πηνειόν.", "st": "6.22"}, {"sp": "N", "t": "λέγουσι δὲ οἱ Ἠλεῖοι καὶ ἔπος ἐς τὴν Πύλον ταύτην ἔχειν τῶν Ὁμήρου,<br>γένος δ’ ἦν ἐκ ποταμοῖο<br>Ἀλφειοῦ, ὅστ’ εὐρὺ ῥέει Πυλίων διὰ γαίης,<br>καὶ ἐμὲ ἔπειθον λέγοντες· ῥεῖ γὰρ δὴ διὰ τῆς χώρας ταύτης ὁ Ἀλφειός, ἐς δὲ ἄλλην Πύλον οὐκ ἔστιν ἐπενεγκεῖν τὸ ἔπος· Πυλίων γὰρ τῶν ὑπὲρ νήσου τῆς Σφακτηρίας οὐ πέφυκεν ἀρχὴν διοδεύειν τὴν γῆν ὁ Ἀλφειός, οὐ μὴν οὐδὲ ἐν τῇ Ἀρκάδων Πύλον ποτὲ ὀνομασθεῖσαν ἴσμεν πόλιν.", "st": "6.22"}, {"sp": "N", "t": "ἀπέχει δὲ ὡς πεντήκοντα Ὀλυμπίας σταδίους κώμη τε Ἠλείων Ἡράκλεια καὶ πρὸς αὐτῇ Κύθηρος ποταμός· πηγὴ δὲ ἐκδιδοῦσα ἐς τὸν ποταμὸν καὶ νυμφῶν ἐστιν ἱερὸν ἐπὶ τῇ πηγῇ. ὀνόματα δὲ ἰδίᾳ μὲν ἑκάστῃ τῶν νυμφῶν Καλλιφάεια καὶ Συνάλλασις καὶ Πηγαία τε καὶ Ἴασις, ἐν κοινῷ δέ σφισιν ἐπίκλησις Ἰωνίδες. λουομένοις δὲ ἐν τῇ πηγῇ καμάτων τέ ἐστι καὶ ἀλγημάτων παντοίων ἰάματα· καλεῖσθαι δὲ τὰς νύμφας ἀπὸ Ἴωνος λέγουσι τοῦ Γαργηττοῦ, μετοικήσαντος ἐνταῦθα ἐξ Ἀθηνῶν.", "st": "6.22"}, {"sp": "N", "t": "εἰ δὲ ἐλθεῖν ἐς Ἦλιν διὰ τοῦ πεδίου θελήσειας, σταδίους μὲν εἴκοσι καὶ ἑκατὸν ἐς Λετρίνους ἕξεις, ὀγδοήκοντα δὲ ἐκ Λετρίνων καὶ ἑκατὸν ἐπὶ Ἦλιν. τὸ μὲν δὴ ἐξ ἀρχῆς πόλισμα ἦν οἱ Λετρῖνοι, καὶ Λετρεὺς ὁ Πέλοπος ἐγεγόνει σφίσιν οἰκιστής· ἐπ’ ἐμοῦ δὲ οἰκήματά τε ἐλείπετο ὀλίγα καὶ Ἀλφειαίας Ἀρτέμιδος ἄγαλμα ἐν ναῷ.", "st": "6.22"}, {"sp": "N", "t": "γενέσθαι δὲ τὴν ἐπίκλησιν τῇ θεῷ λέγουσιν ἐπὶ λόγῳ τοιῷδε· ἐρασθῆναι τῆς Ἀρτέμιδος τὸν Ἀλφειόν, ἐρασθέντα δέ, ὡς ἐπέγνω μὴ γενήσεσθαί οἱ διὰ πειθοῦς καὶ δεήσεως τὸν γάμον, ἐπιτολμᾶν ὡς βιασόμενον τὴν θεόν, καὶ αὐτὸν ἐς παννυχίδα ἐς Λετρίνους ἐλθεῖν ὑπὸ αὐτῆς τε ἀγομένην τῆς Ἀρτέμιδος καὶ νυμφῶν αἷς παίζουσα συνῆν [αὐτῇ]· τὴν δὲ—ἐν ὑπονοίᾳ γὰρ τοῦ Ἀλφειοῦ τὴν ἐπιβουλὴν ἔχειν— ἀλείψασθαι τὸ πρόσωπον πηλῷ καὶ αὐτὴν καὶ ὅσαι τῶν νυμφῶν παρῆσαν, καὶ τὸν Ἀλφειόν, ὡς ἐσῆλθεν, οὐκ ἔχειν αὐτὸν ἀπὸ τῶν ἄλλων διακρῖναι τὴν Ἄρτεμιν, ἅτε δὲ οὐ διαγινώσκοντα ἀπελθεῖν ἐπὶ ἀπράκτῳ τῷ ἐγχειρήματι.", "st": "6.22"}, {"sp": "N", "t": "Λετριναῖοι μὲν δὴ Ἀλφειαίαν ἐκάλουν τὴν θεὸν ἐπὶ τοῦ Ἀλφειοῦ τῷ ἐς αὐτὴν ἔρωτι· οἱ δὲ Ἠλεῖοι —φιλία γάρ σφισιν ὑπῆρχεν ἐξ ἀρχῆς ἐς Λετριναίους —τὰ παρὰ σφίσιν Ἀρτέμιδι ἐς τιμὴν τῇ Ἐλαφιαίᾳ καθεστηκότα ἐς Λετρίνους τε μετήγαγον καὶ τῇ Ἀρτέμιδι ἐνόμισαν τῇ Ἀλφειαίᾳ δρᾶν, καὶ οὕτω τὴν Ἀλφειαίαν θεὸν Ἐλαφιαίαν ἀνὰ χρόνον ἐξενίκησεν ὀνομασθῆναι.", "st": "6.22"}, {"sp": "N", "t": "Ἐλαφιαίαν δὲ ἐκάλουν οἱ Ἠλεῖοι τὴν Ἄρτεμιν ἐπὶ τῶν ἐλάφων ἐμοὶ δοκεῖν τῇ θήρᾳ· αὐτοὶ δὲ γυναικὸς ἐπιχωρίας ὄνομα εἶναι τὴν Ἐλάφιον καὶ ὑπὸ ταύτης τραφῆναι τὴν Ἄρτεμίν φασι. Λετρίνων δὲ ὅσον τε ἕξ ἀπωτέρω σταδίοις ἐστὶν ἀέναος λίμνη τριῶν που τὴν διάμετρον σταδίων μάλιστα.", "st": "6.22"}, {"sp": "N", "t": "ἐν δὲ Ἤλιδι τὰ ἄξια μνήμης γυμνάσιόν ἐστιν ἀρχαῖον· καὶ ὅσα ἐς τοὺς ἀθλητὰς πρὶν ἢ ἐς Ὀλυμπίαν ἀφικνεῖσθαι νομίζουσιν, ἐν τούτῳ σφίσι τῷ γυμνασίῳ δρᾶν καθέστηκε. πλάτανοι μὲν ὑψηλαὶ διὰ τῶν δρόμων πεφύκασιν ἐντὸς τοίχου· ὁ σύμπας δὲ οὗτος περίβολος καλεῖται Ξυστός, ὅτι Ἡρακλεῖ τῷ Ἀμφιτρύωνος ἐς ἄσκησιν ἐγίνετο, ὅσαι τῶν ἀκανθῶν ἐφύοντο ἐνταῦθα ἐπὶ ἑκάστῃ ἡμέρᾳ σφᾶς ἀναξύειν.", "st": "6.23"}, {"sp": "N", "t": "χωρὶς μὲν δὴ ἐς ἅμιλλαν τῶν δρομέων ἐστὶν ἀποκεκριμένος δρόμος, ὀνομάζεται δὲ ὑπὸ τῶν ἐπιχωρίων ἱερός, χωρὶς δὲ ἔνθα ἐπὶ μελέτῃ δρομεῖς καὶ οἱ πένταθλοι θέουσιν. ἔστι δὲ ἐν τῷ γυμνασίῳ καλούμενον Πλέθριον· ἐν δὲ αὐτῷ συμβάλλουσιν οἱ Ἑλλανοδίκαι τοὺς καθ’ ἡλικίαν ἢ καὶ αὐτῷ διαφέροντας τῷ ἐπιτηδεύματι· συμβάλλουσι δὲ ἐπὶ πάλῃ.", "st": "6.23"}, {"sp": "N", "t": "εἰσὶ δὲ καὶ θεῶν ἐν τῷ γυμνασίῳ βωμοί, Ἡρακλέους τοῦ Ἰδαίου, Παραστάτου δὲ ἐπίκλησιν, καὶ Ἔρωτος καὶ ὃν Ἠλεῖοι καὶ Ἀθηναῖοι κατὰ ταὐτὰ Ἠλείοις Ἀντέρωτα ὀνομάζουσι, Δήμητρός τε καὶ τῆς παιδός. Ἀχιλλεῖ δὲ οὐ βωμός, κενὸν δέ ἐστιν αὐτῷ μνῆμα ἐκ μαντείας· τῆς πανηγύρεως δὲ ἀρχομένης ἐν ἡμέρᾳ ῥητῇ περὶ ἀποκλίνοντα ἐς δυσμὰς τοῦ ἡλίου τὸν δρόμον αἱ γυναῖκες αἱ Ἠλεῖαι ἄλλα τε τοῦ Ἀχιλλέως δρῶσιν ἐς τιμὴν καὶ κόπτεσθαι νομίζουσιν αὐτόν.", "st": "6.23"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἄλλος ἐλάσσων γυμνασίου περίβολος, ὃς ἔχεται μὲν τοῦ μείζονος, τετράγωνον δὲ ὀνομάζουσιν ἐπὶ τῷ σχήματι· καὶ παλαῖστραι τοῖς ἀθλοῦσιν ἐνταῦθα ποιοῦνται, καὶ συμβάλλουσιν αὐτόθι τοὺς ἀθλητὰς οὐ παλαίσοντας ἔτι, ἐπὶ δὲ ἱμάντων τῶν μαλακωτέρων ταῖς πληγαῖς. ἀνάκειται δὲ καὶ τῶν ἀγαλμάτων τὸ ἕτερον, ἃ ἐπὶ ζημίᾳ Σωσάνδρου τε τοῦ Σμυρναίου καὶ Ἠλείου Πολύκτορος τῷ Διὶ ἐποιήθη.", "st": "6.23"}, {"sp": "N", "t": "ἔστι δὲ καὶ τρίτος γυμνασίου περίβολος, ὄνομα μὲν Μαλθὼ τῆς μαλακότητος τοῦ ἐδάφους ἕνεκα, τοῖς δὲ ἐφήβοις ἀνεῖται τῆς πανηγύρεως τὸν χρόνον πάντα. ἔστι δὲ ἐν γωνίᾳ τῆς Μαλθοῦς πρόσωπον Ἡρακλέους ἄχρι ἐς τοὺς ὤμους, καὶ ἐν τῶν παλαιστρῶν μιᾷ τύπος Ἔρωτα ἔχων ἐπειργασμένον καὶ τὸν καλούμενον Ἀντέρωτα· ἔχει δὲ ὁ μὲν φοίνικος ὁ Ἔρως κλάδον, ὁ δὲ ἀφελέσθαι πειρᾶται τὸν φοίνικα ὁ Ἀντέρως.", "st": "6.23"}, {"sp": "N", "t": "τῆς ἐσόδου δὲ ἑκατέρωθεν τῆς ἐς τὴν Μαλθὼ παιδὸς ἕστηκεν εἰκὼν πύκτου· καὶ αὐτὸν ἔφασκεν ὁ νομοφύλαξ Ἠλείων γένος μὲν Ἀλεξανδρέα εἶναι τῆς ὑπὲρ Φάρου τῆς νήσου, Σαραπίωνα δὲ ὄνομα, ἀφικόμενον δὲ ἐς Ἦλιν σπανίζουσι σίτου σφίσι τροφὰς δοῦναι. τούτῳ μὲν αὐτόθι ἀντὶ τούτου γεγόνασιν αἱ τιμαί· χρόνος δὲ στεφάνου τε τοῦ ἐν Ὀλυμπίᾳ καὶ εὐεργεσίας αὐτῷ τῆς ἐς Ἠλείους Ὀλυμπιὰς ἑβδόμη πρὸς ταῖς δέκα τε καὶ διακοσίαις.", "st": "6.23"}, {"sp": "N", "t": "ἐν τούτῳ τῷ γυμνασίῳ καὶ βουλευτήριόν ἐστιν Ἠλείοις, καὶ ἐπιδείξεις ἐνταῦθα λόγων τε αὐτοσχεδίων καὶ συγγραμμάτων ποιοῦνται παντοίων· καλεῖται δὲ Λαλίχμιον τοῦ ἀναθέντος ἐπώνυμον. περὶ δὲ αὐτὸ ἀσπίδες ἀνάκεινται, θέας ἕνεκα καὶ οὐκ ἐς ἔργον πολέμου πεποιημέναι.", "st": "6.23"}, {"sp": "N", "t": "ἐκ δὲ τοῦ γυμνασίου πρὸς τὰ λουτρὰ ἐρχομένῳ δι’ ἀγυιᾶς τε ἡ ὁδὸς Σιωπῆς καὶ παρὰ τὸ ἱερὸν τῆς Φιλομείρακός ἐστιν Ἀρτέμιδος. τῇ μὲν δὴ θεῷ γέγονεν ἡ ἐπίκλησις ἅτε τοῦ γυμνασίου γείτονι· τῇ ἀγυιᾷ δὲ Σιωπῇ ὄνομα ἐπὶ λόγῳ τοιῷδε τεθῆναι λέγουσιν. ἄνδρες τοῦ Ὀξύλου στρατεύματος ἐπὶ κατασκοπῇ τῶν ἐν Ἤλιδι ἀποπεμφθέντες καὶ ἀλλήλοις διακελευσάμενοι κατὰ τὴν ὁδόν, ἐπειδὰν πλησίον γίνωνται τοῦ τείχους, φθέγγεσθαι μὲν μηδὲν ἔτι αὐτοί, ἐπακροᾶσθαι δὲ εἴ τι παρὰ τῶν ἐντὸς πυθέσθαι δυνήσονται, οὗτοι λανθάνουσι παρελθόντες ἐς τὴν πόλιν κατὰ τὴν ἀγυιὰν ταύτην καὶ ἐπακούσαντες ὁπόσα ἐβούλοντο ἐπανίασιν αὖθις ἐς τοὺς Αἰτωλούς· καὶ ἡ ἀγυιὰ τὸ ὄνομα εἴληφεν ἀπὸ τῶν κατασκόπων τῆς σιωπῆς.", "st": "6.23"}, {"sp": "N", "t": "ἑτέρα δὲ ἔξοδος ἐκ τοῦ γυμνασίου φέρει μὲν ἔς τε τὴν ἀγορὰν καὶ ἐπὶ τὸν Ἑλλανοδικαιῶνα καλούμενον, ἔστι δὲ ὑπὲρ τοῦ Ἀχιλλέως τὸν τάφον· καὶ ταύτῃ τοὺς Ἑλλανοδίκας ἰέναι καθέστηκεν ἐς τὸ γυμνάσιον. ἐσίασι δὲ πρὶν μὲν ἥλιον ἀνίσχειν συμβαλοῦντες δρομέας, μεσούσης δὲ τῆς ἡμέρας ἐπὶ τὸ πένταθλον καὶ ὅσα βαρέα ἆθλα ὀνομάζουσιν.", "st": "6.24"}, {"sp": "N", "t": "ἡ δὲ ἀγορὰ τοῖς Ἠλείοις οὐ κατὰ τὰς Ἰώνων καὶ ὅσαι πρὸς Ἰωνίᾳ πόλεις εἰσὶν Ἑλλήνων, τρόπῳ δὲ πεποίηται τῷ ἀρχαιοτέρῳ στοαῖς τε ἀπὸ ἀλλήλων διεστώσαις καὶ ἀγυιαῖς δι’ αὐτῶν. ὄνομα δὲ τῇ ἀγορᾷ τὸ ἐφ’ ἡμῶν ἐστιν Ἱππόδρομος, καὶ οἱ ἐπιχώριοι τοὺς ἵππους παιδεύουσιν ἐνταῦθα. τῶν στοῶν δὲ ἡ πρὸς μεσημβρίαν ἐργασίας ἐστὶ τῆς Δωρίου, διαιροῦσι δὲ αὐτὴν ἐς μοίρας τρεῖς οἱ κίονες· ἐν ταύτῃ διημερεύουσι τὰ πολλὰ οἱ Ἑλλανοδίκαι.", "st": "6.24"}, {"sp": "N", "t": "ποιοῦνται δὲ πρὸς αὐτοῖς καὶ βωμοὺς τῷ Διί, καὶ εἰσὶν ἐν τῷ ὑπαίθρῳ τῆς ἀγορᾶς οἱ βωμοὶ πλῆθος οὐ πολλοί· καταλύονται γὰρ οὐ χαλεπῶς ἅτε αὐτοσχεδίως οἰκοδομούμενοι. κατὰ ταύτην τὴν στοὰν ἰόντι ἐς τὴν ἀγορὰν ἔστιν ἐν ἀριστερᾷ παρὰ τὸ πέρας τῆς στοᾶς ὁ Ἑλλανοδικαιών· ἀγυιὰ δὲ ἡ διείργουσα ἀπὸ τῆς ἀγορᾶς ἐστιν αὐτόν. ἐν τούτῳ τῷ Ἑλλανοδικαιῶνι οἰκοῦσι δέκα ἐφεξῆς μῆνας οἱ αἱρεθέντες ἑλλανοδικεῖν καὶ ὑπὸ τῶν νομοφυλάκων ὅσα ἐς τὸν ἀγῶνα σφᾶς ⟨δεῖ ποιεῖν⟩ διδάσκονται.", "st": "6.24"}, {"sp": "N", "t": "τῇ στοᾷ δὲ ἔνθα οἱ Ἑλλανοδίκαι διημερεύουσιν ἔστιν ἐγγὺς ἄλλη στοά· τὸ μεταξὺ αὐτῶν ἀγυιὰ μία. ταύτην ὀνομάζουσι Κορκυραϊκὴν οἱ Ἠλεῖοι· ναυσὶ γὰρ ἐς τὴν σφετέραν Κορκυραίους ἐλθόντας … ἐλάσαι μοῖραν τῆς λείας λέγοντες λαβεῖν τε ἐκ τῆς Κορκυραίων πολλαπλάσια καὶ οἰκοδομήσασθαι τὴν στοὰν ἀπὸ τῶν λαφύρων τῆς δεκάτης.", "st": "6.24"}, {"sp": "N", "t": "ἔστι δὲ ἡ κατασκευὴ τῆς στοᾶς Δώριος καὶ διπλῆ, τῇ μὲν ἐς τὴν ἀγορὰν τοὺς κίονας, τῇ δὲ ἐς τὰ ἐπέκεινα τῆς ἀγορᾶς ἔχουσα· κατὰ μέσον δὲ αὐτῆς οὐ κίονες, ἀλλὰ τοῖχος ὁ ταύτῃ τὸν ὄροφον ἀνέχων ἐστίν, ἀνάκεινται δὲ καὶ εἰκόνες ἑκατέρωθεν πρὸς τῷ τοίχῳ. κατὰ δὲ τῆς στοᾶς τὸ ἐς τὴν ἀγορὰν ἕστηκε Πύρρωνος τοῦ Πιστοκράτους εἰκών, σοφιστοῦ τε ἀνδρὸς καὶ ἐς βέβαιον ὁμολογίαν ἐπὶ οὐδενὶ λόγῳ καταστάντος. ἔστι δὲ καὶ μνῆμα τῷ Πύρρωνι οὐ πόρρω τοῦ Ἠλείων ἄστεως· Πέτρα μὲν τῷ χωρίῳ τὸ ὄνομα, λέγεται ⟨δὲ⟩ ὡς ἡ Πέτρα δῆμος εἴη τὸ ἀρχαῖον.", "st": "6.24"}, {"sp": "N", "t": "Ἠλείοις δὲ ἐν τῷ ὑπαίθρῳ τῆς ἀγορᾶς τὰ ἐπιφανέστατα ναός ἐστι καὶ ἄγαλμα Ἀπόλλωνος Ἀκεσίου· σημαίνοι δ’ ἂν τὸ ὄνομα οὐδέν τι ἀλλοῖον ἢ ὁ καλούμενος Ἀλεξίκακος ὑπὸ Ἀθηναίων. ἑτέρωθι δὲ Ἡλίῳ πεποίηται καὶ Σελήνῃ λίθου τὰ ἀγάλματα, καὶ τῆς μὲν κέρατα ἐκ τῆς κεφαλῆς, τοῦ δὲ αἱ ἀκτῖνες ἀνέχουσιν. ἔστι δὲ καὶ Χάρισιν ἱερὸν καὶ ξόανα ἐπίχρυσα τὰ ἐς ἐσθῆτα, πρόσωπα δὲ καὶ χεῖρες καὶ πόδες λίθου λευκοῦ· ἔχουσι δὲ ἡ μὲν αὐτῶν ῥόδον, ἀστράγαλον δὲ ἡ μέση, καὶ ἡ τρίτη κλῶνα οὐ μέγαν μυρσίνης.", "st": "6.24"}, {"sp": "N", "t": "ἔχειν δὲ αὐτὰς ἐπὶ τοιῷδε εἰκάζοι τις ἂν τὰ εἰρημένα, ῥόδον μὲν καὶ μυρσίνην Ἀφροδίτης τε ἱερὰ εἶναι καὶ οἰκεῖα τῷ ἐς Ἄδωνιν λόγῳ, Χάριτας δὲ Ἀφροδίτῃ μάλιστα ⟨φίλας⟩ εἶναι θεῶν· ἀστράγαλον δὲ μειρακίων τε καὶ παρθένων, οἷς ἄχαρι οὐδέν πω πρόσεστιν ἐκ γήρως, τούτων εἶναι τὸν ἀστράγαλον παίγνιον. τῶν Χαρίτων δὲ ἐν δεξιᾷ ἄγαλμά ἐστιν Ἔρωτος· ἕστηκε δὲ ἐπὶ βάθρου τοῦ αὐτοῦ.", "st": "6.24"}, {"sp": "N", "t": "ἔστι δὲ καὶ Σιληνοῦ ναὸς ἐνταῦθα, ἰδίᾳ τῷ Σιληνῷ καὶ οὐχ ὁμοῦ Διονύσῳ πεποιημένος· Μέθη δὲ οἶνον ἐν ἐκπώματι αὐτῷ δίδωσι. θνητὸν δὲ εἶναι τὸ γένος τῶν Σιληνῶν εἰκάσαι τις ἂν μάλιστα ἐπὶ τοῖς τάφοις αὐτῶν· ἐν γὰρ τῇ Ἑβραίων χώρᾳ Σιληνοῦ μνῆμα καὶ ἄλλου Σιληνοῦ Περγαμηνοῖς ἐστιν.", "st": "6.24"}, {"sp": "N", "t": "Ἠλείων δὲ ἐν τῇ ἀγορᾷ καὶ ἄλλο τοιόνδε εἶδον, ναοῦ σχῆμα· ἔστι δὲ οὐχ ὑψηλόν, καὶ τοῖχοι μὲν οὐκ εἰσί, τὸν ὄροφον δὲ δρυὸς ἀνέχουσιν εἰργασμένοι κίονες. τοῦτο εἶναι μὲν ὁμολογοῦσιν οἱ ἐπιχώριοι μνῆμα, ὅτου δὲ οὐ μνημονεύουσιν· εἰ δὲ ὁ γέρων ὅντινα ἠρόμην εἶπεν ἀληθῆ λόγον, Ὀξύλου τοῦτο ἂν μνῆμα εἴη.", "st": "6.24"}, {"sp": "N", "t": "πεποίηται δὲ ἐν τῇ ἀγορᾷ καὶ ταῖς γυναιξὶν οἴκημα ταῖς ἑκκαίδεκα καλουμέναις, ἔνθα τὸν πέπλον ὑφαίνουσι τῇ Ἥρᾳ. ἔχεται δὲ τῆς ἀγορᾶς ναὸς ἀρχαῖος στοαῖς ἐν κύκλῳ περίστυλος, ὁ δὲ ὄροφος κατερρύηκε τῷ ναῷ καὶ ἄγαλμα οὐδὲν ἐλείπετο· βασιλεῦσι δὲ ἀνεῖται Ῥωμαίοις.", "st": "6.24"}, {"sp": "N", "t": "ἔστι δὲ τῆς στοᾶς ὀπίσω τῆς ἀπὸ τῶν λαφύρων τῶν ἐκ Κορκύρας Ἀφροδίτης ναός, τὸ δὲ ἐν ὑπαίθρῳ τέμενος οὐ πολὺ ἀφεστηκὸς ἀπὸ τοῦ ναοῦ. καὶ τὴν μὲν ἐν τῷ ναῷ καλοῦσιν Οὐρανίαν, ἐλέφαντος δέ ἐστι καὶ χρυσοῦ, τέχνη Φειδίου, τῷ δὲ ἑτέρῳ ποδὶ ἐπὶ χελώνης βέβηκε· τῆς δὲ περιέχεται μὲν τὸ τέμενος θριγκῷ, κρηπὶς δὲ ἐντὸς τοῦ τεμένους πεποίηται καὶ ἐπὶ τῇ κρηπῖδι ἄγαλμα Ἀφροδίτης χαλκοῦν ἐπὶ τράγῳ κάθηται χαλκῷ· Σκόπα τοῦτο ἔργον, Ἀφροδίτην δὲ Πάνδημον ὀνομάζουσι. τὰ δὲ ἐπὶ τῇ χελώνῃ τε καὶ ἐς τὸν τράγον παρίημι τοῖς θέλουσιν εἰκάζειν.", "st": "6.25"}, {"sp": "N", "t": "ὁ δὲ ἱερὸς τοῦ Ἅιδου περίβολός τε καὶ ναός—ἔστι γὰρ δὴ Ἠλείοις καὶ Ἅιδου περίβολός τε καὶ ναός— ἀνοίγνυται μὲν ἅπαξ κατὰ ἔτος ἕκαστον, ἐσελθεῖν δὲ οὐδὲ τότε ἐφεῖται πέρα γε τοῦ ἱερωμένου. ἀνθρώπων δὲ ὧν ἴσμεν μόνοι τιμῶσιν Ἅιδην Ἠλεῖοι κατὰ αἰτίαν τήνδε. Ἡρακλεῖ στρατιὰν ἄγοντι ἐπὶ Πύλον τὴν ἐν τῇ Ἤλιδι, παρεῖναί οἱ καὶ Ἀθηνᾶν συνεργὸν λέγουσιν· ἀφικέσθαι οὖν καὶ Πυλίοις τὸν Ἅιδην συμμαχήσοντα τῇ ἀπεχθείᾳ τοῦ Ἡρακλέους, ἔχοντα ἐν τῇ Πύλῳ τιμάς.", "st": "6.25"}, {"sp": "N", "t": "ἐπάγονται δὲ καὶ Ὅμηρον τῷ λόγῳ μάρτυρα ποιήσαντα ἐν Ἰλιάδι<br>τλῆ δ’ Ἀίδης ἐν τοῖσι πελώριος ὠκὺν ὀιστόν,<br>εὖτέ μιν ωὐτὸς ἀνὴρ υἱὸς Διὸς αἰγιόχοιο<br>ἐν Πύλῳ ἐν νεκύεσσι βαλὼν ὀδύνῃσιν ἔδωκεν·<br>εἰ δὲ κατὰ τὴν Ἀγαμέμνονος καὶ Μενελάου στρατείαν ἐπὶ Ἴλιον Ποσειδῶν τῷ Ὁμήρου λόγῳ τοῖς Ἕλλησιν ἐπίκουρος ἦν, οὐκ ἂν ἄπο τοῦ εἰκότος οὐδὲ Ἅιδην εἴη δόξῃ γε τοῦ αὐτοῦ ποιητοῦ Πυλίοις ἀμῦναι. Ἠλεῖοι δ’ οὖν ὡς σφίσι τε εὔνῳ καὶ ἀπεχθανομένῳ πρὸς τὸν Ἡρακλέα ἐποιήσαντο ⟨τὸ⟩ ἱερὸν τῷ θεῷ· ἑκάστου δὲ ἅπαξ ἀνοίγειν τοῦ ἐνιαυτοῦ νομίζουσιν, ὅτι οἶμαι καὶ ἀνθρώποις ἅπαξ ἡ κάθοδος ἡ ἐς τοῦ Ἅιδου γίνεται.", "st": "6.25"}, {"sp": "N", "t": "τοῖς δὲ Ἠλείοις καὶ Τύχης ⟨ἐστὶν⟩ [τὸ] ἱερὸν· ἐν στοᾷ δὲ τοῦ ἱεροῦ μεγέθει μέγα ἄγαλμα ἀνάκειται, ξόανον ἐπίχρυσον πλὴν προσώπου καὶ χειρῶν τε ἄκρων καὶ ποδῶν, ταῦτα δέ οἵ ἐστι λίθου λευκοῦ. ἐνταῦθα ἔχει τιμὰς καὶ ὁ Σωσίπολις ἐν ἀριστερᾷ τῆς Τύχης, ἐν οἰκήματι οὐ μεγάλῳ· κατὰ δὲ ὄψιν ὀνείρατος γραφῇ μεμιμημένος ἐστὶν ὁ θεός, παῖς μὲν ἡλικίαν, ἀμπέχεται δὲ χλαμύδα ποικίλην ὑπὸ ἀστέρων, τῇ χειρὶ δὲ ἔχει τῇ ἑτέρᾳ τὸ κέρας τῆς Ἀμαλθείας.", "st": "6.25"}, {"sp": "N", "t": "καθότι δὲ Ἠλείων ἡ πόλις πληθύει μάλιστα ἀνθρώποις, κατὰ τοῦτο ἀνδριάς σφισιν ἀνδρὸς οὐ μείζων μεγάλου χαλκοῦς ἐστιν οὐκ ἔχων πω γένεια τόν τε ἕτερον τῶν ποδῶν ἐπιπλέκων τῷ ἑτέρῳ καὶ ταῖς χερσὶν ἀμφοτέραις ἐπὶ δόρατι ἠρεισμένος· ἐσθῆτα δὲ ἐρεᾶν αὐτῷ καὶ ἀπὸ λίνου τε καὶ βύσσου περιβάλλουσι.", "st": "6.25"}, {"sp": "N", "t": "τοῦτο τὸ ἄγαλμα ἐλέγετο εἶναι Ποσειδῶνος, ἔχειν δὲ τὸ ἀρχαῖον ἐπὶ Σαμικῷ τῷ ἐν τῇ Τριφυλίᾳ τιμάς· μετακομισθὲν δὲ ἐς τὴν Ἦλιν τιμῆς μὲν καὶ ἐς πλέον ἔτι ἥκει, Σατράπην δὲ καὶ οὐ Ποσειδῶνα ὄνομα αὐτῷ τίθενται, μετὰ τὴν Πατρέων προσοίκησιν τὸ ὄνομα τοῦ Σατράπου διδαχθέντες· Κορύβαντός τε ἐπίκλησις ὁ Σατράπης ἐστί.", "st": "6.25"}, {"sp": "N", "t": "θέατρον δὲ ἀρχαῖον, μεταξὺ τῆς ἀγορᾶς καὶ τοῦ Μηνίου τὸ θέατρόν τε καὶ ἱερόν ἐστι Διονύσου· τέχνη τὸ ἄγαλμα Πραξιτέλους, θεῶν δὲ ἐν τοῖς μάλιστα Διόνυσον σέβουσιν Ἠλεῖοι καὶ τὸν θεόν σφισιν ἐπιφοιτᾶν ἐς τῶν Θυίων τὴν ἑορτὴν λέγουσιν. ἀπέχει μέν γε τῆς πόλεως ὅσον τε ὀκτὼ στάδια ἔνθα τὴν ἑορτὴν ἄγουσι Θυῖα ὀνομάζοντες· λέβητας δὲ ἀριθμὸν τρεῖς ἐς οἴκημα ἐσκομίσαντες οἱ ἱερεῖς κατατίθενται κενούς, παρόντων καὶ τῶν ἀστῶν καὶ ξένων, εἰ τύχοιεν ἐπιδημοῦντες· σφραγῖδας δὲ αὐτοί τε οἱ ἱερεῖς καὶ τῶν ἄλλων ὅσοις ἂν κατὰ γνώμην ᾖ ταῖς θύραις τοῦ οἰκήματος ἐπιβάλλουσιν, ἐς δὲ τὴν ἐπιοῦσαν τά τε", "st": "6.26"}, {"sp": "N", "t": "σημεῖα ἐπιγνῶναι πάρεστί σφισι καὶ ἐσελθόντες ἐς τὸ οἴκημα εὑρίσκουσιν οἴνου πεπλησμένους τοὺς λέβητας. ταῦτα Ἠλείων τε οἱ δοκιμώτατοι ἄνδρες, σὺν αὐτοῖς δὲ καὶ ξένοι κατώμνυντο ἔχειν κατὰ τὰ εἰρημένα, ἐπεὶ αὐτός γε οὐκ ἐς καιρὸν ἀφικόμην τῆς ἑορτῆς· λέγουσι δὲ καὶ Ἄνδριοι παρὰ ἔτος σφίσιν ἐς τοῦ Διονύσου τὴν ἑορτὴν ῥεῖν οἶνον αὐτόματον ἐκ τοῦ ἱεροῦ. ⟨εἰ⟩ πιστεύειν χρὴ ταῦτα Ἕλλησιν, [εἰ] ἀποδέχοιτο ἄν τις τῷ λόγῳ γε τῷ αὐτῷ καὶ ὅσα Αἰθίοπες οἱ ὑπὲρ Συήνης ἐς τοῦ ἡλίου τὴν τράπεζαν λέγουσιν.", "st": "6.26"}, {"sp": "N", "t": "ἐν ἀκροπόλει δὲ τῇ Ἠλείων ἐστὶν ἱερὸν Ἀθηνᾶς· ἐλέφαντος δὲ τὸ ἄγαλμα καὶ χρυσοῦ. εἶναι μὲν δὴ Φειδίου φασὶν αὐτήν, πεποίηται δὲ ἀλεκτρυὼν ἐπὶ τῷ κράνει, ὅτι οὗτοι προχειρότατα ἔχουσιν ἐς μάχας οἱ ἀλεκτρυόνες· δύναιτο δ’ ἂν καὶ Ἀθηνᾶς τῆς Ἐργάνης ἱερὸς ὁ ὄρνις νομίζεσθαι.", "st": "6.26"}, {"sp": "N", "t": "Κυλλήνη δὲ σταδίους μὲν εἴκοσιν Ἤλιδος καὶ ἑκατὸν ἀφέστηκε, κεῖται δὲ τετραμμένη τε πρὸς Σικελίαν καὶ ὅρμον παρεχομένη ναυσὶν ἐπιτήδειον· ἐπίνειον δὲ οὖσα Ἠλείων ἀπὸ ἀνδρὸς Ἀρκάδος τὸ ὄνομα εἴληφε. Κυλλήνης δὲ ἐν μὲν Ἠλείων καταλόγῳ λόγον οὐδένα Ὅμηρος ἐποιήσατο, ἐν δὲ ἔπεσι τοῖς ὕστερον δεδήλωκεν ὡς πόλισμα οὖσαν καὶ τὴν Κυλλήνην ἐπίσταται·", "st": "6.26"}, {"sp": "N", "t": "Πουλυδάμας δ’ Ὦτον Κυλλήνιον ἐξενάριξεν,<br>Φυλείδεω ἕταρον, μεγαθύμων ἀρχὸν Ἐπειῶν.<br>θεῶν δὲ ἱερὰ ἐν Κυλλήνῃ Ἀσκληπιοῦ, τὸ δὲ Ἀφροδίτης ἐστί· τοῦ Ἑρμοῦ δὲ τὸ ἄγαλμα, ὃν οἱ ταύτῃ περισσῶς σέβουσιν, ὀρθόν ἐστιν αἰδοῖον ἐπὶ τοῦ βάθρου.", "st": "6.26"}, {"sp": "N", "t": "ἡ δὲ Ἠλεία χώρα τά τε ἄλλα ἐστὶν ἐς καρποὺς καὶ τὴν βύσσον οὐχ ἥκιστα ἐκτρέφειν ἀγαθή. τὴν μὲν δὴ κανναβίδα καὶ λίνον καὶ τὴν βύσσον σπείρουσιν ὅσοις ἡ γῆ τρέφειν ἐστὶν ἐπιτήδειος· οἱ μίτοι δέ, ἀφ’ ὧν τὰς ἐσθῆτας ποιοῦσιν οἱ Σῆρες, ἀπὸ οὐδενὸς φλοιοῦ, τρόπον δὲ ἕτερον γίνονται τοιόνδε. ἔστιν ἐν τῇ γῇ ζωύφιόν σφισιν, ὃν σῆρα καλοῦσιν Ἕλληνες, ὑπὸ δὲ αὐτῶν Σηρῶν ἄλλο πού τι καὶ οὐ σὴρ ὀνομάζεται·", "st": "6.26"}, {"sp": "N", "t": "μέγεθος μέν ἐστιν αὐτοῦ διπλάσιον ἢ κανθάρων ὁ μέγιστος, τὰ δὲ ἄλλα εἴκασται τοῖς ἀράχναις, οἳ ὑπὸ τοῖς δένδρεσιν ὑφαίνουσι, καὶ δὴ καὶ πόδας ἀριθμὸν ὀκτὼ κατὰ ταὐτὰ ἔχει τοῖς ἀράχναις. ταῦτα τὰ ζῷα τρέφουσιν οἱ Σῆρες οἴκους κατασκευασάμενοι χειμῶνός τε καὶ θέρους ὥρᾳ ἐπιτηδείους· τὸ δὲ ἔργον τῶν ζῴων κλῶσμα εὑρίσκεται λεπτὸν τοῖς ποσὶν αὐτῶν περιειλιγμένον.", "st": "6.26"}, {"sp": "N", "t": "τρέφουσι δὲ αὐτὰ ἐπὶ μὲν τέσσαρα ἔτη παρέχοντες τροφήν σφισιν ἔλυμον, πέμπτῳ δὲ—οὐ γὰρ πρόσω βιωσόμενα ἴσασι—κάλαμον διδόασιν ἐσθίειν χλωρόν· ἡ δέ ἐστιν ἡδίστη τροφὴ πασῶν τῷ ζῴῳ, καὶ ἐμφορηθὲν τοῦ καλάμου ῥήγνυταί τε ὑπὸ πλησμονῆς καὶ ἀποθανόντος οὕτω τὸ πολὺ τῆς ἁρπεδόνης εὑρίσκουσιν ἔνδον. γινώσκεται δὲ ἡ Σηρία νῆσος ἐν μυχῷ θαλάσσης κειμένη τῆς Ἐρυθρᾶς.", "st": "6.26"}, {"sp": "N", "t": "ἤκουσα δὲ καὶ ὡς οὐχ ἡ Ἐρυθρά, ποταμὸς δὲ ὃν Σῆρα ὀνομάζουσιν, οὗτός ἐστιν ὁ ποιῶν νῆσον αὐτήν, ὥσπερ καὶ Αἰγύπτου τὸ Δέλτα ὑπὸ τοῦ Νείλου καὶ οὐχ ὑπὸ μιᾶς περιέχεσθαι θαλάσσης· τοιαύτην ἑτέραν καὶ τὴν Σηρίαν νῆσον εἶναι. οὗτοι μὲν δὴ τοῦ Αἰθιόπων γένους αὐτοί τέ εἰσιν οἱ Σῆρες καὶ ὅσοι τὰς προσεχεῖς αὐτῇ νέμονται νήσους, Ἄβασαν καὶ Σακαίαν· οἱ δὲ αὐτοὺς οὐκ Αἰθίοπας, Σκύθας δὲ ἀναμεμιγμένους Ἰνδοῖς φασὶν εἶναι.", "st": "6.26"}, {"sp": "N", "t": "ταῦτα μὲν δὴ οὕτω λέγεται· ἀνδρὶ δὲ ἐς Ἀχαΐαν ἰόντι ἐξ Ἤλιδος ἑπτὰ καὶ πεντήκοντα στάδιοι καὶ ἑκατὸν ἐπὶ ποταμόν εἰσι Λάρισον, καὶ Ἠλείοις ὅροι πρὸς Ἀχαιοὺς τῆς χώρας ὁ ποταμός ἐστιν ἐφ’ ἡμῶν ὁ Λάρισος· τὰ δὲ ἔτι ἀρχαιότερα ἄκρα σφίσι πρὸς θαλάσσῃ ὅρος ἦν ὁ Ἄραξος.", "st": "6.26"}], []);})();
